            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RESET RUN", "REINICIAR PARTIDA", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW LESHY RUN", "PARTIDA NUEVA CON LESHY", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE LESHY RUN", "CONTINUAR PARTIDA CON LESHY", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW GRIMORA RUN", "PARTIDA NUEVA CON GRIMORA", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE GRIMORA RUN", "CONTINUAR PARTIDA CON GRIMORA", Language.Spanish);

