            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will allow you to see what cards are left in your deck.", "Esta opción permite ver qué cartas quedan en tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will disable all effects that might cause motion sickness and other visually jarring effects.", "Esta opción desactiva todos los efectos que puedan provocar mareos u otras molestias visuales.", Language.Spanish);
