            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] yields no bones upon death.", "[creature] no produce huesos al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, gain 2 bones.", "Cuando [creature] mata a otra criatura, obtienes 2 huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Soul from you at the end of every turn and stores it as 2 Bones, up to a maximum of 8. When [creature] dies, you gain all bones contained in it.", "Al final de cada turno, [creature] te quita 1 alma y la almacena como 2 huesos, hasta un máximo de 8. Cuando [creature] muere, obtienes todos los huesos que contiene.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers each Skeleton on the owner's side of the board, providing a +1 buff to their power.", "[creature] potencia a cada Esqueleto en el lado del tablero de su propietario y le otorga +1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Shanty", "Canto marinero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slots to the left, right, and center of it randomly, up to 3 times.", "[creature] ataca aleatoriamente los espacios de enfrente situados a su izquierda, a su derecha y en el centro, hasta 3 veces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the card opposing it is Frozen Away if not already frozen.", "Cuando [creature] muere, la carta de enfrente queda congelada si no lo estaba ya.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, gain a consumable item, if you have a free slot.", "Cuando [creature] muere, obtienes un objeto consumible si tienes un espacio libre para objetos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Skeleton is created in each empty space on the owner's side. [define:Skeleton]", "Cuando se juega [creature], se crea un Esqueleto en cada espacio vacío del lado de su propietario. [define:Skeleton]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Horde", "Horda de esqueletos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck Finder", "Buscador de naufragios", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Shipwreck is created on each empty adjacent space. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", "Cuando se juega [creature], se crea un Naufragio en cada espacio vacío adyacente. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons Within", "Esqueletos interiores", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, draw a card from your Skeleton pile.", "Cuando [creature] recibe un golpe, roba una carta de tu pila de Esqueletos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full o' candy", "Lleno de caramelos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will yield candy upon death, maybe this will be useful for later.", "[creature] deja caramelos al morir. Quizá sean útiles más adelante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in a random direction.", "Al final del turno de su propietario, [creature] se mueve en una dirección aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] moves, it leaves a trail of Embers. [define:arackulele.inscryption.grimoramod_Flames]", "Cada vez que [creature] se mueve, deja un rastro de brasas. [define:arackulele.inscryption.grimoramod_Flames]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guarding Presence", "Presencia protectora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space.", "Cuando una criatura rival se coloca frente a un espacio vacío, [creature] se mueve a ese espacio vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Starved", "Hambriento de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no Bones, at the start of your turn [creature] deals 2 more damage.", "Si no tienes huesos, al comienzo de tu turno [creature] inflige 2 de daño adicional.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space. If only one creature is in the opposing spaces, this card will strike that creature twice. ", "[creature] ataca cada espacio de enfrente. Si solo hay una criatura en esos espacios, esta carta la ataca dos veces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Giant", "Gigante enfurecido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space.", "[creature] ataca cada espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fledgling", "Inexperto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After one turn on the board, [creature] will evolve into a greater form.", "Tras un turno en el tablero, [creature] evoluciona a una forma superior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Ability", "Ser amorfo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced with another sigil at random.", "Cuando se roba [creature], este sello se sustituye por otro sello aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it haunts the space it died in. The first creature played on this space gain its old sigils.", "Cuando [creature] muere, embruja el espacio donde murió. La primera criatura que se juegue en ese espacio obtiene sus antiguos sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunting Call", "Llamada espectral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every turn [creature] is on the Board, it will take a Bone from you, if you have no Bones, it perishes.", "Cada turno que [creature] esté en el tablero, te quita un hueso. Si no tienes huesos, muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature in the opposing slot is dragged onto the owner's side of the board.", "Cuando [creature] muere, la criatura del espacio opuesto es arrastrada al lado del tablero del propietario de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle ally card perishes, [creature] gains 1 power.", "Cuando muere una carta aliada sin Quebradizo, [creature] obtiene 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slot as if the board was flipped. A card in the far left slot will attack the opposing far right slot.", "[creature] ataca el espacio opuesto como si el tablero estuviera invertido. Una carta en el espacio del extremo izquierdo ataca el espacio opuesto del extremo derecho.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Bonedigger sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello «Desenterrador».", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Waterborne sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello «Acuático».", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 health per turn. When [creature] dies, the creature opposing it, as well as adjacent friendly creatures, are dealt 10 damage.", "[creature] pierde 1 de salud por turno. Cuando [creature] muere, la criatura opuesta y las criaturas aliadas adyacentes reciben 10 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a severed limb is created in its place and this card moves into an adjacent open slot.", "Cuando [creature] está a punto de recibir un golpe, se crea un miembro cercenado en su lugar y esta carta se mueve a un espacio libre adyacente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time [creature] deals damage directly, it loses 1 power and health.", "Cada vez que [creature] inflige daño directo, su poder y su salud disminuyen en 1 cada uno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, also play the cards in your hand that were adjacent to this card for free.", "Cuando se juega [creature], se juegan gratis también las cartas de tu mano que estaban junto a esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Douse", "Extinción", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played,[creature] will extinguish all cards on the Board.", "Cuando se juega [creature], apaga todas las cartas del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be attacked from the opposing slot. The opposing slot, if possible, instead attacks one of its adjacent friendly cards.", "[creature] no puede recibir ataques desde el espacio opuesto. Si es posible, la carta de ese espacio ataca en su lugar a una de sus cartas aliadas adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards on the owner's side of the field are unaffected by Brittle.", "Las cartas del lado del tablero del propietario no se ven afectadas por Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, except other Raiders.", "[creature] ataca los espacios adyacentes, salvo a otros Saqueadores.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it carves its Sigils into adjacent Cards.", "Cuando se juega [creature], graba sus sellos en las cartas adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sculptor", "Grabador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attempt to find a host in an adjacent friendly slot, hiding under it providing a +1/+1 buff. Cards on the left take priority.", "[creature] intenta encontrar un huésped en un espacio aliado adyacente, se esconde debajo y le otorga una mejora de +1/+1. Las cartas de la izquierda tienen prioridad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] hits an opposing card, one of the targets adjacent allies will take damage as well ", "Cuando [creature] golpea a una carta rival, uno de los aliados adyacentes del objetivo también recibe daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it provides an energy soul to its owner.", "Cuando se juega [creature], proporciona un alma de energía a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HellHound's Thirst", "Sed del sabueso infernal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for each bone the player currently has.", "Una carta que lleve este sello obtiene 1 de poder por cada hueso que tenga el jugador en ese momento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wrath Of Halloween", "Ira de Halloween", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil has 10 attack, 1 for each Candy Bucket Sawyer has left.", "Una carta que lleve este sello tiene 10 de poder, 1 por cada Cubo de caramelos que le quede a Sawyer.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trusty ol' Crew", "Vieja tripulación de confianza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every pirate on the board.", "Una carta que lleve este sello obtiene 1 de poder por cada pirata del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inanimate Attack", "Ataque inanimado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every card that has 0 attack on the board.", "Una carta que lleve este sello obtiene 1 de poder por cada carta con 0 de poder en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Bones", "Mitad de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Bones that the owner has on their side of the table.", "El valor representado por este sello es igual al número de huesos que el propietario tenga en su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "Doble muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to add power to [creature] randomly between 1 and 6.", "Paga 1 alma para otorgar a [creature] una cantidad aleatoria de poder entre 1 y 6.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to heal [creature] to max health.", "Paga 2 huesos para curar a [creature] hasta su salud máxima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Strike", "Golpe alterno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchored", "Anclado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Area Of Effect Strike", "Golpe de área", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Tragasangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Sinhuesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Thief", "Ladrón de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty", "Cazarrecompensas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "Ardiendo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Damage at the end of your turn, when it gets attacked by another Card, that card gets set on fire.", "[creature] recibe 1 de daño al final de tu turno. Cuando otra carta la ataca, esa carta se incendia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "Golpe del caos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold Front", "Frente frío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "Coleccionista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "Errático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Strafe", "Incursión de fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Strike", "Golpe gigante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "Embrujo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "Anzuelo, sedal y plomo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbued", "Imbuido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inverted Strike", "Golpe invertido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Bone Digger", "Acople desenterrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Submerge", "Acople acuático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lit Fuse", "Mecha encendida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loose Limb", "Miembro desprendible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malnourishment", "Desnutrición", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marching Dead", "Muertos en marcha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessive", "Posesivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "Titiritero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raider", "Saqueador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Crawler", "Reptapieles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slasher", "Acuchillador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spirit Bearer", "Portador de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of this card is equal to the number of Green Gems that the owner has on their side of the table.", "El poder de esta carta es igual al número de gemas verdes que su propietario tenga en su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - ABILITIES {0}", "APÉNDICE XII, SECCIÓN I - HABILIDADES {0}", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION II - VARIABLE STATS {0}", "APÉNDICE XII, SECCIÓN II - ESTADÍSTICAS VARIABLES {0}", Language.Spanish);

            // Card
            RegisterCard("Skeleton", "Esqueleto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The puppet becomes the puppeteer, yet still forever cursed by their dangling restraints.", "La marioneta se convierte en titiritero, pero sigue maldita para siempre por las ataduras que cuelgan de ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Titiritero", Language.Spanish);
            RegisterCard("Animator", "Titiritero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formless Creature, that yet lingers. Truly a horrific sight.", "Una criatura sin forma que aún permanece aquí. Un espectáculo realmente espantoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apparition", "Espectro", Language.Spanish);
            RegisterCard("Apparition", "Espectro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a fool would need such assistance.", "Solo un necio necesitaría semejante ayuda.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graven Ashes", "Cenizas grabadas", Language.Spanish);
            RegisterCard("Graven Ashes", "Cenizas grabadas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's foul breath doesn't concern me, it's the Tampered Coffins it leaves behind!", "¡Su aliento fétido no me preocupa, sino los Ataúdes manipulados que deja atrás!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bal-Bal", "Bal-Bal", Language.Spanish);
            RegisterCard("Bal-Bal", "Bal-Bal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SCREAMING TERROR. THEY GO STRAIGHT THROUGH TO ATTACK THEIR PREY.", "EL TERROR CHILLANTE. ATRAVIESAN LAS DEFENSAS PARA ATACAR A SU PRESA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Banshee", "Banshee", Language.Spanish);
            RegisterCard("Banshee", "Banshee");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bartender", "El tabernero", Language.Spanish);
            RegisterCard("The Bartender", "El tabernero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "spent his days serving harmful cocktails for those deserving of his poisonous wrath. Doesn't regret it at all.", "Pasaba los días sirviendo cócteles dañinos a quienes merecían su ira venenosa. No se arrepiente en absoluto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Bones", "Huesos gigantes", Language.Spanish);
            RegisterCard("Big Bones", "Huesos gigantes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burly Bones", "Huesos robustos", Language.Spanish);
            RegisterCard("Burly Bones", "Huesos robustos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beefy Bones", "Huesos fornidos", Language.Spanish);
            RegisterCard("Beefy Bones", "Huesos fornidos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cal C. Um", "Señor Calcio", Language.Spanish);
            RegisterCard("Cal C. Um", "Señor Calcio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sizeable Bones", "Huesos imponentes", Language.Spanish);
            RegisterCard("Sizeable Bones", "Huesos imponentes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Considerable Bones", "Huesos considerables", Language.Spanish);
            RegisterCard("Considerable Bones", "Huesos considerables");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigorous Bones", "Huesos vigorosos", Language.Spanish);
            RegisterCard("Vigorous Bones", "Huesos vigorosos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hefty Bones", "Huesos pesados", Language.Spanish);
            RegisterCard("Hefty Bones", "Huesos pesados");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RATHER BURLY SKELETON, IT IS VERY RICH IN CALCIUM.", "UN ESQUELETO BASTANTE FORNIDO, MUY RICO EN CALCIO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sack is full of body parts. Maybe you'll find something useful in there.", "Este saco está lleno de partes del cuerpo. Quizá encuentres algo útil dentro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "Saco ensangrentado", Language.Spanish);
            RegisterCard("Bloody Sack", "Saco ensangrentado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Collective", "Colectivo óseo", Language.Spanish);
            RegisterCard("Bone Collective", "Colectivo óseo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUSANDS OF TINY BONES COALESCE INTO A HUMANOID FORM ONLY TO DISPERSE IN A CLATTERING SWARM THE NEXT MOMENT.", "MILES DE HUESOS DIMINUTOS SE UNEN EN UNA FORMA HUMANOIDE, SOLO PARA DISPERSARSE AL INSTANTE SIGUIENTE EN UN ENJAMBRE TRAQUETEANTE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "USED TO BE A VERY LOYAL DOG BACK IN THE DAY. WELL, ONE DAY HIS OWNER DIED.", "ANTES ERA UN PERRO MUY LEAL. HASTA QUE UN DÍA MURIÓ SU DUEÑO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonehound", "Sabhueso", Language.Spanish);
            RegisterCard("Bonehound", "Sabhueso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO YOU HAVE MADE IT HERE, YOU CANNOT END WHAT I HAVE STARTED, IT HAS GONE TOO FAR.", "ASÍ QUE HAS LLEGADO HASTA AQUÍ. NO PUEDES PONER FIN A LO QUE HE INICIADO, HA IDO DEMASIADO LEJOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord", "El señor de los huesos", Language.Spanish);
            RegisterCard("The Bonelord", "El señor de los huesos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD SHEDS ITS OLD HORNS, THEY TAKE ON A LIFE OF THEIR OWN, TO ONE DAY USURP THEIR MASTER.", "EL SEÑOR DE LOS HUESOS MUDA SUS VIEJOS CUERNOS. ESTOS COBRAN VIDA PROPIA PARA USURPAR ALGÚN DÍA A SU AMO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelord's Horn", "Cuerno del señor de los huesos", Language.Spanish);
            RegisterCard("Bonelord's Horn", "Cuerno del señor de los huesos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT PARTICULARLY INSPIRING. YOU CAN HAVE IT.", "NO ES MUY INSPIRADOR. PUEDES QUEDÁRTELO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap", "Montón de huesos", Language.Spanish);
            RegisterCard("Bone Heap", "Montón de huesos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IF I AM TRAPPED, SO WILL YOU. YOU CANNOT END THIS.", "SI YO ESTOY ATRAPADO, TÚ TAMBIÉN LO ESTARÁS. NO PUEDES PONER FIN A ESTO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Prince", "Príncipe de los huesos", Language.Spanish);
            RegisterCard("Bone Prince", "Príncipe de los huesos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE FEEDS ON PEOPLES BREATH, MAYBE ONE IS STANDING RIGHT BEHIND YOU RIGHT NOW.", "SE ALIMENTA DEL ALIENTO DE LAS PERSONAS. PUEDE QUE AHORA MISMO HAYA UNA JUSTO DETRÁS DE TI.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boo Hag", "Boo Hag", Language.Spanish);
            RegisterCard("Boo Hag", "Boo Hag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE COMMANDS OTHERS WITH STRENGTH AND GLAMOUR. THEY WILL FOLLOW HER EVERYWHERE.", "DIRIGE A LOS DEMÁS CON FUERZA Y ENCANTO. LA SEGUIRÁN A TODAS PARTES.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calavera Catrina", "La Catrina", Language.Spanish);
            RegisterCard("Calavera Catrina", "La Catrina");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GROUP OF SKELETONS IS CALLED A CATACOMB. THIS IS A RATHER LARGE GATHERING.", "UN GRUPO DE ESQUELETOS SE LLAMA CATACUMBA. ESTA ES UNA REUNIÓN BASTANTE NUMEROSA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catacomb", "Catacumba", Language.Spanish);
            RegisterCard("Catacomb", "Catacumba");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centurion", "Centurión", Language.Spanish);
            RegisterCard("Centurion", "Centurión");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavily armoured warrior. Last of his century, leader to none.", "Un guerrero con armadura pesada. El último de su centuria, un líder sin seguidores.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compound Fracture", "Fractura compuesta", Language.Spanish);
            RegisterCard("Compound Fracture", "Fractura compuesta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CRUSHED BY THE ROOF OF HIS OWN HOUSE. LIVING ON AS A PILE OF GOO.", "APLASTADO POR EL TEJADO DE SU PROPIA CASA. SIGUE VIVIENDO COMO UN MONTÓN DE MUGRE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SPIRIT THAT TAKES THE FORM OF AN EGG. ITS PRESENCE HARMS THOSE THAT GAZE UPON IT.", "UN ESPÍRITU QUE ADOPTA LA FORMA DE UN HUEVO. SU PRESENCIA DAÑA A QUIENES LO CONTEMPLAN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dalgyal", "Huevo demoníaco", Language.Spanish);
            RegisterCard("Dalgyal", "Huevo demoníaco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOREVER BOUND TOGETHER BY A TERRIBLE CURSE, THIS GROUP DANCES ONWARD INTO DOOM.", "UNIDO PARA SIEMPRE POR UNA TERRIBLE MALDICIÓN, ESTE GRUPO BAILA HACIA SU PERDICIÓN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Danse Macabre", "Bailarín macabro", Language.Spanish);
            RegisterCard("Danse Macabre", "Bailarín macabro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadeye", "Ojo muerto", Language.Spanish);
            RegisterCard("Deadeye", "Ojo muerto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS EYE ONCE BELONGED TO AN ANCIENT GOD. IT GAZES UPON YOUR ARMY, PICKING ITS FAVORITE TO AID IT ON THE BATTLEFIELD.", "DICEN QUE ESTE OJO PERTENECIÓ A UN DIOS ANTIGUO. CONTEMPLA TU EJÉRCITO Y ELIGE A SU FAVORITO PARA AYUDARLO EN EL CAMPO DE BATALLA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS HAND ONCE BELONGED TO AN ANCIENT GOD. ANYTHING IT TOUCHES ROTS. AS WITH ANYTHING THAT ENDS, IT IS ALSO A NEW BEGINNING.", "DICEN QUE ESTA MANO PERTENECIÓ A UN DIOS ANTIGUO. CUANTO TOCA SE PUDRE. COMO CUALQUIER FINAL, TAMBIÉN ES UN NUEVO COMIENZO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Mano muerta", Language.Spanish);
            RegisterCard("Dead Hand", "Mano muerta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DOOMED FATE SHOULD DISCOURAGE ONE FROM GOING ON, AT LEAST THATS WHAT A STILL LIVING MAN WOULD TELL YOU.", "UN DESTINO FUNESTO DEBERÍA QUITARTE LAS GANAS DE SEGUIR. AL MENOS, ESO TE DIRÍA UN HOMBRE QUE AÚN ESTUVIERA VIVO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Man Walking", "Muerto viviente", Language.Spanish);
            RegisterCard("Dead Man Walking", "Muerto viviente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAMED AMONG THE FOLLOWERS OF THE PHARAOH. THEY WERE BLESSED WITH ETERNAL LIFE LONG AGO.", "FAMOSAS ENTRE LOS SEGUIDORES DEL FARAÓN. RECIBIERON LA BENDICIÓN DE LA VIDA ETERNA HACE MUCHO TIEMPO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharaoh's Pets", "Mascotas del faraón", Language.Spanish);
            RegisterCard("Pharaoh's Pets", "Mascotas del faraón");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR WHOM THE BELL TOLLS? FOR WHOM THE TAP DRIPS DRY AND THE BATHWATER RUNS COLD.", "¿POR QUIÉN DOBLAN LAS CAMPANAS? POR AQUEL CUYO GRIFO SE SECA Y CUYA AGUA DEL BAÑO SE ENFRÍA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knell", "Toque de difuntos", Language.Spanish);
            RegisterCard("Death Knell", "Toque de difuntos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime", "Campanilla", Language.Spanish);
            RegisterCard("Chime", "Campanilla");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This lonesome doll was returned from seas of slate and silent shores... it stares lifelessly.", "Este muñeco solitario regresó de mares de pizarra y costas silenciosas... Mira fijamente, sin vida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doll", "Muñeco", Language.Spanish);
            RegisterCard("Doll", "Muñeco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIDING IN A SUIT OF ARMOR, OR ICE, WHAT DOES IT MATTER. THIS SKELETON WON'T LAST FOREVER.", "ESCONDIDO EN UNA ARMADURA O EN EL HIELO, QUÉ MÁS DA. ESTE ESQUELETO NO DURARÁ PARA SIEMPRE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draugr", "Draugr", Language.Spanish);
            RegisterCard("Draugr", "Draugr");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SAD SIGHT, NO ONE SHALL KNOW WHAT LIES AT THE BOTTOM OF THAT WELL.", "QUÉ TRISTE ESPECTÁCULO. NADIE SABRÁ QUÉ YACE EN EL FONDO DE ESE POZO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drowned Soul", "Alma ahogada", Language.Spanish);
            RegisterCard("Drowned Soul", "Alma ahogada");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO ONE KNOWS WHAT EXACTLY THE DYBBUK IS, SOME SAY IT IS BETTER LEFT UNKNOWN.", "NADIE SABE EXACTAMENTE QUÉ ES EL DYBBUK. ALGUNOS DICEN QUE ES MEJOR NO SABERLO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dybbuk", "Dybbuk", Language.Spanish);
            RegisterCard("Dybbuk", "Dybbuk");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ectoplasm", "Ectoplasma", Language.Spanish);
            RegisterCard("Ectoplasm", "Ectoplasma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE ESSENCE OF A SPIRIT, HIDDEN IN EVERY CORNER AND EVERY SHADOW. ONCE YOU SEE ONE, YOU WILL FIND THE REST SOON ENOUGH.", "LA ESENCIA DE UN ESPÍRITU, OCULTA EN CADA RINCÓN Y CADA SOMBRA. EN CUANTO VEAS UNA, PRONTO ENCONTRARÁS LAS DEMÁS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LIVING FAILURE, ITS KNOWLEDGE ONLY BROUGHT IT DEATH, OR AT LEAST AN APPROXIMATION OF IT.", "UN FRACASO VIVIENTE. SU CONOCIMIENTO SOLO LE TRAJO LA MUERTE, O AL MENOS ALGO PARECIDO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneclaw", "Garra de hueso", Language.Spanish);
            RegisterCard("Boneclaw", "Garra de hueso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Sinhuesos", Language.Spanish);
            RegisterCard("Boneless", "Sinhuesos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's Skeleton seems to have left this lifeless husk in order to achieve greater things.", "Su esqueleto parece haber abandonado esta cáscara sin vida para lograr cosas más grandes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mummy", "Momia menor", Language.Spanish);
            RegisterCard("Lesser Mummy", "Momia menor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal servant to the Pharao, buried with him to serve eternally in death.", "Un fiel sirviente del faraón, enterrado con él para servirle eternamente en la muerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eidolon", "Eidolon", Language.Spanish);
            RegisterCard("Eidolon", "Eidolon");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GOLEM ENCHANTED LONG AGO, BOUND TO PROTECT THE AGE OF SUN.", "UN GÓLEM ENCANTADO HACE MUCHO TIEMPO, OBLIGADO A PROTEGER LA ERA DEL SOL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "QUITE A MISCHIEVOUS SPIRIT, IT SPREADS ITS FLAMES TO CAUSE DISMAY.", "UN ESPÍRITU BASTANTE TRAVIESO. PROPAGA SUS LLAMAS PARA SEMBRAR EL ESPANTO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ember Spirit", "Espíritu de brasa", Language.Spanish);
            RegisterCard("Ember Spirit", "Espíritu de brasa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMILY WISHES TO REST IN PEACE, ONLY TO BE SUMMONED AGAIN AND AGAIN IN AN ETERNAL BATTLE.", "LA FAMILIA DESEA DESCANSAR EN PAZ, PERO LA INVOCAN UNA Y OTRA VEZ PARA UNA BATALLA ETERNA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Walkers", "Los Caminantes", Language.Spanish);
            RegisterCard("The Walkers", "Los Caminantes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is said their odor is so strong and repugnant, even the undead can feel it!", "¡Dicen que su olor es tan fuerte y repugnante que hasta los no muertos lo perciben!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Festering Wretch", "Despojo purulento", Language.Spanish);
            RegisterCard("Festering Wretch", "Despojo purulento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flames", "Llamas", Language.Spanish);
            RegisterCard("Flames", "Llamas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flameskull", "Calavera llameante", Language.Spanish);
            RegisterCard("Flameskull", "Calavera llameante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always flying, always angry, always annoying nearby allies in the process.", "Siempre volando, siempre enfadado y siempre molestando de paso a los aliados cercanos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A waterlogged sailor who carries his tragic past beside him. I don't remember the details.", "Un marinero empapado que lleva su trágico pasado a cuestas. No recuerdo los detalles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten Man", "Hombre olvidado", Language.Spanish);
            RegisterCard("Forgotten Man", "Hombre olvidado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEST FRIENDS, BROTHERS, AND FIGHTERS.", "MEJORES AMIGOS, HERMANOS Y COMBATIENTES.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frank & Stein", "Frank y Stein", Language.Spanish);
            RegisterCard("Frank & Stein", "Frank y Stein");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FrankenStein", "Frankenstein", Language.Spanish);
            RegisterCard("FrankenStein", "Frankenstein");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghastly guardian spirit. It's presence lingers behind as it sprints through the dark.", "Un espantoso espíritu guardián. Su presencia perdura tras él mientras corre por la oscuridad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fylgja", "Fylgja", Language.Spanish);
            RegisterCard("Fylgja", "Fylgja");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warding Presence", "Presencia protectora", Language.Spanish);
            RegisterCard("Warding Presence", "Presencia protectora");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT CREATED THESE BONES, WAR, FAMINE OR ANOTHER TRAGEDY? It may be insignificant now, but I fear what it might become...", "¿DE DÓNDE VIENEN ESTOS HUESOS? ¿DE UNA GUERRA, UNA HAMBRUNA U OTRA TRAGEDIA? Puede que ahora sea insignificante, pero temo en qué podría convertirse...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Fosa común", Language.Spanish);
            RegisterCard("Mass Grave", "Fosa común");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rising Hunger", "Hambre voraz", Language.Spanish);
            RegisterCard("Rising Hunger", "Hambre voraz");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.Spanish);
            RegisterCard("Gashadokuro", "Gashadokuro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE PIRATES CALL THIS SHIP THEIR HOME, EVEN IN DEATH. A SLAIN GIANTS SKULL SERVES AS THEIR FIGUREHEAD.", "LOS PIRATAS LLAMAN HOGAR A ESTE BARCO, INCLUSO EN LA MUERTE. EL CRÁNEO DE UN GIGANTE ABATIDO LES SIRVE DE MASCARÓN DE PROA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Ship", "Barco fantasma", Language.Spanish);
            RegisterCard("Ghost Ship", "Barco fantasma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "Gigante", Language.Spanish);
            RegisterCard("Giant", "Gigante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMED RACE OF GIANTS IS SAID TO HAVE DIED OUT LONG AGO, THIS IS PROOF. TRULY A SIGHT TO BEHOLD.", "DICEN QUE LA CÉLEBRE RAZA DE LOS GIGANTES SE EXTINGUIÓ HACE MUCHO TIEMPO. ESTA ES LA PRUEBA. UN ESPECTÁCULO DIGNO DE CONTEMPLAR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOUND TO EARTH, THEY CLING ON SO THEY MAY ONE DAY GET PROPER BURIAL.", "ATADOS A LA TIERRA, SE AFERRAN A ELLA CON LA ESPERANZA DE RECIBIR ALGÚN DÍA UNA SEPULTURA DIGNA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grateful Dead", "Muerto agradecido", Language.Spanish);
            RegisterCard("Grateful Dead", "Muerto agradecido");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LOWLY GRAVEBARD, MUSIC ALWAYS BROUGHT HIM COMFORT IN THE WORST OF TIMES. NOW, EVEN AT THE END OF THE WORLD HE SHARES HIS SONG.", "EL HUMILDE BARDO DE LAS TUMBAS. LA MÚSICA SIEMPRE LE DIO CONSUELO EN LOS PEORES MOMENTOS. AHORA, INCLUSO EN EL FIN DEL MUNDO, COMPARTE SU CANCIÓN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravebard", "Bardo de las tumbas", Language.Spanish);
            RegisterCard("Gravebard", "Bardo de las tumbas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT HIS LIFE CARVING THESE CREATURES, THIS CARD CONTAINS A PART OF HIS SOUL.", "HA PASADO LA VIDA TALLANDO ESTAS CRIATURAS. ESTA CARTA CONTIENE UNA PARTE DE SU ALMA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Carver", "Tallador de tumbas", Language.Spanish);
            RegisterCard("Grave Carver", "Tallador de tumbas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE SPENDS HIS TIME ALONE DIGGING FOR BONES IN HOPES OF FINDING A TREASURE. JUST LIKE HIS GRANDMA BEFORE HIM.", "PASA EL TIEMPO CAVANDO HUESOS A SOLAS CON LA ESPERANZA DE ENCONTRAR UN TESORO. IGUAL QUE SU ABUELA ANTES QUE ÉL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravedigger", "Sepulturero", Language.Spanish);
            RegisterCard("Gravedigger", "Sepulturero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A POOR, BRUTALIZED SOUL. THEIR MYCELIA PROBES FAR INTO THE SOIL, GUIDING THEIR SPADE.", "UNA POBRE ALMA MALTRATADA. SU MICELIO PENETRA EN LO MÁS PROFUNDO DEL SUELO Y GUÍA SU PALA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporedigger", "Cavaesporas", Language.Spanish);
            RegisterCard("Sporedigger", "Cavaesporas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A devoted guardian spirit. Even when dispelled, it grants a protective blessing.", "Un devoto espíritu guardián. Incluso cuando lo disipan, otorga una bendición protectora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haltia", "Haltia", Language.Spanish);
            RegisterCard("Haltia", "Haltia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I advise against staring into it, you won't like what stares back.", "Te aconsejo que no lo mires fijamente. No te gustará lo que te devuelva la mirada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Mirror", "Espejo embrujado", Language.Spanish);
            RegisterCard("Haunted Mirror", "Espejo embrujado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY CALL HER THE RIDER OF THE APOCALYPSE. HER FLAMING BLADE CUTS THROUGH THE LIVING AND DEAD ALIKE.", "LA LLAMAN LA JINETE DEL APOCALIPSIS. SU ESPADA LLAMEANTE ATRAVIESA A VIVOS Y MUERTOS POR IGUAL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Horseman", "Jinete sin cabeza", Language.Spanish);
            RegisterCard("Headless Horseman", "Jinete sin cabeza");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WOULDN'T GET TOO CLOSE DEAR. YOU CAN'T BREAK THE HOLD FROM THE DEEPEST PITS OF HELL, ONCE IT LATCHES ON.", "YO NO ME ACERCARÍA DEMASIADO, CARIÑO. UNA VEZ QUE TE ATRAPA ESA GARRA DE LO MÁS PROFUNDO DEL INFIERNO, NO PUEDES ESCAPAR DE SU PRESA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhand", "Mano infernal", Language.Spanish);
            RegisterCard("Hellhand", "Mano infernal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Hound", "Sabueso infernal", Language.Spanish);
            RegisterCard("Hell Hound", "Sabueso infernal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RABID DOG. IT KILLED ONE OF MY GHOULS.", "UN PERRO RABIOSO. MATÓ A UNO DE MIS GULES.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LEGENDS HAVE BEEN TOLD ABOUT THE LEGENDARY HYDRA, THE BEAST THAT SWALLOWS ALL AND THE BANE OF ALL THAT SAIL THE SEAS.", "SE CUENTAN LEYENDAS SOBRE LA LEGENDARIA HIDRA, LA BESTIA QUE LO DEVORA ENTERO Y LA PERDICIÓN DE QUIENES SURCAN LOS MARES.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hydra", "Hidra", Language.Spanish);
            RegisterCard("Hydra", "Hidra");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overtaken by it's gluttony in life, doomed to it's gluttony in death. Oddly inspires a greed for bones.", "Dominado por su gula en vida, condenado a ella en la muerte. Curiosamente, inspira codicia por los huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jikininki", "Jikininki", Language.Spanish);
            RegisterCard("Jikininki", "Jikininki");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "Avalancha", Language.Spanish);
            RegisterCard("Avalanche", "Avalancha");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Glaciar", Language.Spanish);
            RegisterCard("Glacier", "Glaciar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WONDER WHAT HAS BEEN FROZEN AWAY FOR SO LONG.", "ME PREGUNTO QUÉ HABRÁ PERMANECIDO CONGELADO TANTO TIEMPO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Giant", "Gigante de escarcha", Language.Spanish);
            RegisterCard("Frost Giant", "Gigante de escarcha");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "Cubo de hielo", Language.Spanish);
            RegisterCard("Ice Cube", "Cubo de hielo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CORPSE WHO DIED WITH HIS HEAD IN A GLACIAL STREAM. AFTER HIS REANIMATION, HE COULDN'T BEAR TO PART WITH THE ICE THAT HAD FORMED.", "UN CADÁVER QUE MURIÓ CON LA CABEZA EN UN TORRENTE GLACIAL. TRAS REANIMARSE, NO SOPORTABA SEPARARSE DEL HIELO QUE SE HABÍA FORMADO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After drowning her children and then herself, she continues to drown others.", "Después de ahogar a sus hijos y luego a sí misma, sigue ahogando a otros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La Llorona", "La Llorona", Language.Spanish);
            RegisterCard("La Llorona", "La Llorona");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manananggal", "Manananggal", Language.Spanish);
            RegisterCard("Manananggal", "Manananggal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO BRUTALITY SATIATES THE MANANANGGAL. WHEN YOU SEE HER SEVER FROM HER TORSO, YOU TOO WILL BE A VICTIM OF THE HUNT.", "NINGUNA BRUTALIDAD SACIA A LA MANANANGGAL. CUANDO LA VEAS SEPARARSE DEL TORSO, TÚ TAMBIÉN SERÁS VÍCTIMA DE LA CACERÍA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi, also known as the hairy ghost. It leeches the souls from those struck down near it.", "El Moroi, también conocido como el fantasma peludo. Absorbe las almas de quienes caen cerca de él.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi", "Moroi", Language.Spanish);
            RegisterCard("Moroi", "Moroi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS AGE OF GLORY IS LONG GONE, YET IT IS WHAT KEEPS HIM GOING.", "SU ÉPOCA DE GLORIA QUEDÓ MUY ATRÁS, PERO ES LO QUE LO IMPULSA A SEGUIR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummy Lord", "Señor de momias", Language.Spanish);
            RegisterCard("Mummy Lord", "Señor de momias");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL EFFORTS TO PRESERVE LIFE AFTER DEATH HAVE BEEN FUTILE, YET THE NECROMANCER GOES ON. HE HAS TO.", "LOS ESFUERZOS POR PRESERVAR LA VIDA TRAS LA MUERTE HAN SIDO EN VANO, PERO EL NIGROMANTE CONTINÚA. DEBE HACERLO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necromancer", "Nigromante", Language.Spanish);
            RegisterCard("Necromancer", "Nigromante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A troublesome lake spirit that enjoys dragging others down to a watery grave.", "Un molesto espíritu del lago al que le gusta arrastrar a otros a una tumba acuática.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nixie", "Ninfa acuática", Language.Spanish);
            RegisterCard("Nixie", "Ninfa acuática");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shambling corpse of a pale, sickly noble. it spreads it's filth as it sheds it's flesh.", "El cadáver tambaleante de un noble pálido y enfermizo. Esparce su inmundicia mientras se le desprende la carne.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosferat", "Nosferat", Language.Spanish);
            RegisterCard("Nosferat", "Nosferat");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Obol", "Óbolo antiguo", Language.Spanish);
            RegisterCard("Ancient Obol", "Óbolo antiguo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT WILL ALL MAKE SENSE SOON. THE OBOL IS OLDER THAN TIME ITSELF, AND THUS IT WILL REVEAL ITSELF IN DUE TIME.", "PRONTO COBRARÁ SENTIDO. EL ÓBOLO ES MÁS ANTIGUO QUE EL PROPIO TIEMPO Y SE REVELARÁ CUANDO LLEGUE EL MOMENTO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Armed Bandit", "Bandido manco", Language.Spanish);
            RegisterCard("One Armed Bandit", "Bandido manco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Took the ten paces, that ordeal cost him an arm, and his life.", "Dio los diez pasos. Aquella prueba le costó un brazo y la vida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT IS SAID ALL IS WELL THAT ENDS. IT IS SAID TIME IS LIKE AN OUROBOROS, IT DOES NOT END, IT ONLY REPEATS ITSELF.", "DICEN QUE BIEN ESTÁ LO QUE ACABA. DICEN QUE EL TIEMPO ES COMO UN OUROBOROS: NO TERMINA, SOLO SE REPITE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobones", "Ourohuesos", Language.Spanish);
            RegisterCard("Ourobones", "Ourohuesos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Doctor", "Médico de la peste", Language.Spanish);
            RegisterCard("Plague Doctor", "Médico de la peste");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS DETERMINED THE UNDEAD ARE SICK WITH A TERRIBLE ILLNESS. THE ONLY CURE IS DEATH.", "HA DETERMINADO QUE LOS NO MUERTOS PADECEN UNA TERRIBLE ENFERMEDAD. LA ÚNICA CURA ES LA MUERTE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EVIL TRICKSTER, THE POLTERGEIST HAS ENJOYED THEIR DEATH VERY MUCH.", "UN MALVADO TRAVIESO. EL POLTERGEIST HA DISFRUTADO MUCHO DE SU MUERTE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poltergeist", "Poltergeist", Language.Spanish);
            RegisterCard("Poltergeist", "Poltergeist");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suit of ancient armour in which an occult spirit has taken up residence. Her iron fist drags more creatures to the fight.", "Una antigua armadura en la que se ha instalado un espíritu oculto. Su puño de hierro arrastra a más criaturas al combate.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Armour", "Armadura poseída", Language.Spanish);
            RegisterCard("Possessed Armour", "Armadura poseída");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EXPERIMENT GONE WRONG, IN A FUTILE ATTEMPT TO CREATE A DANSE MACCABRE. THEY DO NOT FUNCTION TOGETHER.", "UN EXPERIMENTO FALLIDO EN UN INTENTO VANO DE CREAR UN BAILARÍN MACABRO. NO FUNCIONAN JUNTOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Project", "Sujeto experimental", Language.Spanish);
            RegisterCard("Project", "Sujeto experimental");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldnt be seeing this right now", "No deberías estar viendo esto ahora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Cards", "Cartas aleatorias", Language.Spanish);
            RegisterCard("Random Cards", "Cartas aleatorias");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT SEEKS ONLY REVENGE.", "CON LA GUADAÑA DE LA MUERTE, LA APARICIÓN SOLO BUSCA VENGANZA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant", "Aparición", Language.Spanish);
            RegisterCard("Revenant", "Aparición");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "Destripador", Language.Spanish);
            RegisterCard("Ripper", "Destripador");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE RIPPER SOLVES EVERYTHING THROUGH SHEER STRENGTH. IT WILL PUNCH ANY ISSUE STRAIGHT IN THE FACE AND SOLVE IT, TOO.", "EL DESTRIPADOR LO RESUELVE A BASE DE FUERZA BRUTA. LE DA UN PUÑETAZO EN LA CARA A CADA PROBLEMA Y ENCIMA LO SOLUCIONA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a wonder this one has stayed together! Though it may lose that arm if it tries to flee.", "¡Es un milagro que aún esté de una pieza! Aunque podría perder ese brazo si intenta huir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotten", "Cadáver podrido", Language.Spanish);
            RegisterCard("Rotten", "Cadáver podrido");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twitching Arm", "Brazo convulso", Language.Spanish);
            RegisterCard("Twitching Arm", "Brazo convulso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The elusive Locker.", "El escurridizo Cofre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones Locker", "Cofre de Davy Jones", Language.Spanish);
            RegisterCard("Davy Jones Locker", "Cofre de Davy Jones");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellowbeard", "Barba Amarilla", Language.Spanish);
            RegisterCard("Yellowbeard", "Barba Amarilla");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebeard", "Barba Azul", Language.Spanish);
            RegisterCard("Bluebeard", "Barba Azul");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His songs raise the morale of only Skeletons, as no one else seems to like it.", "Sus canciones solo levantan la moral de los Esqueletos, pues no parecen gustarle a nadie más.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DISTANT RELATIVE OF THE SCREAMING SKULL, HE IS NOW THE SYMBOL OF PIRACY ALL AROUND THE WORLD", "UN PARIENTE LEJANO DE LA CALAVERA AULLANTE. AHORA ES EL SÍMBOLO DE LA PIRATERÍA EN EL MUNDO ENTERO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "Huesos cruzados", Language.Spanish);
            RegisterCard("Crossbones", "Huesos cruzados");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones", "Davy Jones", Language.Spanish);
            RegisterCard("Davy Jones", "Davy Jones");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true captain of the crew, respected by all yet still elusive. YELLOWBEARD ALWAYS GETS MORE BOOTY THAN HE DOES.", "El verdadero capitán de la tripulación, respetado por todos pero siempre escurridizo. BARBA AMARILLA SIEMPRE CONSIGUE MÁS BOTÍN QUE ÉL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MAYBE IT WASN'T THE BEST IDEA TO HOLD A BARREL FULL OF GUNPOWDER. I'M NOT SURE WETHER HE NOTICED.", "QUIZÁ NO FUERA LA MEJOR IDEA SOSTENER UN BARRIL LLENO DE PÓLVORA. NO SÉ SI SE HABRÁ DADO CUENTA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Pirate", "Pirata explosivo", Language.Spanish);
            RegisterCard("Exploding Pirate", "Pirata explosivo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He betrayed his captain for that large hook, now he is sure to make anyone a double-crosser!", "Traicionó a su capitán por ese enorme gancho. ¡Ahora puede convertir a cualquiera en un traidor!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Mate Snag", "Primer oficial Snag", Language.Spanish);
            RegisterCard("First Mate Snag", "Primer oficial Snag");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parrots usually make great sea-side companions, this one just ate a poisoned cracker.", "Los loros suelen ser excelentes compañeros junto al mar. Este acaba de comerse una galleta envenenada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Polly", "Polly", Language.Spanish);
            RegisterCard("Polly", "Polly");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A keen eye socket allows him to attack anywhere, his musket helps too. marvelous indeed!", "Una cuenca ocular aguda le permite atacar en cualquier lugar; su mosquete también ayuda. ¡Maravilloso!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Privateer", "Capitán corsario", Language.Spanish);
            RegisterCard("Privateer", "Capitán corsario");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swashbuckler", "Espadachín", Language.Spanish);
            RegisterCard("Swashbuckler", "Espadachín");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMERGING FROM AN OLD EGYPTIAN TOMB, MADE TO HOUSE THE LORDS OF OLD.", "SURGIDO DE UNA ANTIGUA TUMBA EGIPCIA, HECHO PARA ALBERGAR A LOS SEÑORES DE ANTAÑO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcophagus", "Sarcófago", Language.Spanish);
            RegisterCard("Sarcophagus", "Sarcófago");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screaming Skull", "Calavera aullante", Language.Spanish);
            RegisterCard("Screaming Skull", "Calavera aullante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ONLY PAIN AND SUFFERING, NOTHING ELSE IS FELT BY THIS SKELETAL HEAD. WHAT A PITY.", "ESTA CABEZA ESQUELÉTICA SOLO SIENTE DOLOR Y SUFRIMIENTO, NADA MÁS. QUÉ LÁSTIMA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SKILLED HUNTER. DON'T TRUST YOUR EARS WHEN YOU HEAR ITS HAUNTING WHISTLE.", "UN CAZADOR HÁBIL. NO TE FÍES DE TUS OÍDOS CUANDO OIGAS SU SILBIDO ESCALOFRIANTE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Silbon", "Silbon", Language.Spanish);
            RegisterCard("Silbon", "Silbon");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY HAVE LEARNED THE ANCIENT SPELL OF DEATH. YET IT IS TOO MUCH POWER TO BE WIELDED.", "HAN APRENDIDO EL ANTIGUO HECHIZO DE LA MUERTE. PERO SU PODER ES DEMASIADO GRANDE PARA DOMINARLO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Esquelemago", Language.Spanish);
            RegisterCard("Skelemagus", "Esquelemago");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]RISE MY ARMY, RIIIIIISE[c:]", "[c:bR]ÁLZATE, MI EJÉRCITO, ÁÁÁLZATE[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Army", "Ejército de esqueletos", Language.Spanish);
            RegisterCard("Skeleton Army", "Ejército de esqueletos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the faster draws in the west, but not fast enough.", "Uno de los pistoleros más rápidos del Oeste, pero no lo bastante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slinger's Soul", "Alma del pistolero", Language.Spanish);
            RegisterCard("Slinger's Soul", "Alma del pistolero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY SHOW UP OUT OF NOWHERE AND RELOCATE PEOPLE AS THEY PLEASE.", "APARECEN DE LA NADA Y TRASLADAN A LA GENTE A SU ANTOJO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluagh", "Sluagh", Language.Spanish);
            RegisterCard("Sluagh", "Sluagh");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trick or treat!", "¡Truco o trato!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Bucket", "Cubo de caramelos", Language.Spanish);
            RegisterCard("Candy Bucket", "Cubo de caramelos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAPPY HALLOWEEN!", "¡FELIZ HALLOWEEN!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Monster", "Monstruo de caramelos", Language.Spanish);
            RegisterCard("Candy Monster", "Monstruo de caramelos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectrabbit", "Espectroconejo", Language.Spanish);
            RegisterCard("Spectrabbit", "Espectroconejo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SPECTRE EMITS A FLUTE LIKE CALL, AN OMEN OF BOTH DEATH AND DESCTRUCTION", "EL GRAN ESPECTRO EMITE UN RECLAMO PARECIDO A UNA FLAUTA, UN AUGURIO DE MUERTE Y DESTRUCCIÓN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectre", "Gran espectro", Language.Spanish);
            RegisterCard("Spectre", "Gran espectro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH IS A CRUEL FATE. STARVATION AN EVEN CRUELER ONE. WHY DO YOU FIGHT, OH HUNGRY CHILD.", "LA MUERTE ES UN DESTINO CRUEL. LA INANICIÓN, UNO AÚN MÁS CRUEL. ¿POR QUÉ LUCHAS, OH, CRIATURA HAMBRIENTA?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved Man", "Hombre muerto de hambre", Language.Spanish);
            RegisterCard("Starved Man", "Hombre muerto de hambre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT YEARS IN HIS STUDY, IN A TIRELESS ATTEMPT TO CHANGE HIS FATE. YET FATE IS A CRUEL MISTRESS.", "HA PASADO AÑOS EN SU ESTUDIO INTENTANDO SIN DESCANSO CAMBIAR SU DESTINO. PERO EL DESTINO ES UNA AMANTE CRUEL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Invocador", Language.Spanish);
            RegisterCard("Summoner", "Invocador");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tampered Coffin", "Ataúd manipulado", Language.Spanish);
            RegisterCard("Tampered Coffin", "Ataúd manipulado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Tree", "Árbol muerto", Language.Spanish);
            RegisterCard("Dead Tree", "Árbol muerto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its low cost is justified only by its low stats.", "Su bajo coste solo se justifica por sus bajas estadísticas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Grave", "Tumba perturbada", Language.Spanish);
            RegisterCard("Disturbed Grave", "Tumba perturbada");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LOWLY GRAVE. WHOEVER IS LAID TO REST HERE, I DO NOT KNOW.", "UNA TUMBA HUMILDE. NO SÉ QUIÉN DESCANSA AQUÍ.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kennel", "Perrera", Language.Spanish);
            RegisterCard("Kennel", "Perrera");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "Obelisco", Language.Spanish);
            RegisterCard("Obelisk", "Obelisco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck", "Naufragio", Language.Spanish);
            RegisterCard("Shipwreck", "Naufragio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flotsam", "Madera a la deriva", Language.Spanish);
            RegisterCard("Flotsam", "Madera a la deriva");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Urn", "Urna de agua", Language.Spanish);
            RegisterCard("Water Urn", "Urna de agua");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Voodoo Doll", "Muñeco vudú", Language.Spanish);
            RegisterCard("Voodoo Doll", "Muñeco vudú");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOTHING... NOTHING AGAIN... NO TREASURE IS LEFT ANYMORE.", "NADA... OTRA VEZ NADA... YA NO QUEDA NINGÚN TESORO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomb Robber", "Ladrona de tumbas", Language.Spanish);
            RegisterCard("Tomb Robber", "Ladrona de tumbas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ephialtes", "Efialtes", Language.Spanish);
            RegisterCard("Ephialtes", "Efialtes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Otis", "Otis", Language.Spanish);
            RegisterCard("Otis", "Otis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undertaker", "Sepulturero", Language.Spanish);
            RegisterCard("Undertaker", "Sepulturero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His service no longer needed, this lost soul buries without purpose..", "Sus servicios ya no hacen falta. Esta alma perdida entierra sin propósito...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walking Coffin", "Ataúd caminante", Language.Spanish);
            RegisterCard("Walking Coffin", "Ataúd caminante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Coffin", "Ataúd andante", Language.Spanish);
            RegisterCard("Running Coffin", "Ataúd andante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placeholder", "Marcador de posición", Language.Spanish);
            RegisterCard("Placeholder", "Marcador de posición");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE VAMPIRE IS A CREATURE OF LEGENDS. IN REALITY, LITTLE BLOOD TO DRINK AFTER EVERYONE HAS DIED.", "EL VAMPIRO ES UNA CRIATURA DE LEYENDA. EN LA REALIDAD, QUEDA POCA SANGRE QUE BEBER CUANDO YA HAN MUERTO TODOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampire", "Conde vampiro", Language.Spanish);
            RegisterCard("Vampire", "Conde vampiro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vellum", "Pergamino", Language.Spanish);
            RegisterCard("Vellum", "Pergamino");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO NEVER BE SATISFIED, TO ALWAYS WANT MORE. THIS SPIRIT SHALL NEVER FIND ITS PEACE.", "JAMÁS SACIARSE, SIEMPRE QUERER MÁS. ESTE ESPÍRITU NUNCA ENCONTRARÁ LA PAZ.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeful Spirit", "Espíritu vengativo", Language.Spanish);
            RegisterCard("Vengeful Spirit", "Espíritu vengativo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS GELID SPECTER ENVELOPS WOULD-BE ATTACKERS IN AN ICY MIST.", "ESTE ESPECTRO GÉLIDO ENVUELVE EN UNA BRUMA HELADA A QUIENES PRETENDEN ATACARLO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthr", "Espectro de escarcha", Language.Spanish);
            RegisterCard("Warthr", "Espectro de escarcha");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted by the spirit of a rabid wolf. It's fury cannot be stopped.", "Corrompido por el espíritu de un lobo rabioso. Su furia no se puede detener.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wechuge", "Wechuge", Language.Spanish);
            RegisterCard("Wechuge", "Wechuge");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hideous beings that will jump out to consume freshly killed corpses. They only spare the bones of the victim.", "Seres horribles que aparecen de repente para devorar cadáveres recientes. Solo dejan los huesos de la víctima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wight", "Tumulario", Language.Spanish);
            RegisterCard("Wight", "Tumulario");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY WARM WITH THEIR BODIES OF LIGHT, DRAWING HOPELESS SOULS INTO THEIR BEACON, DISPELLING THEIR FRIGHT.", "DAN CALOR CON SUS CUERPOS DE LUZ, ATRAEN A LAS ALMAS DESESPERADAS HACIA SU FULGOR Y DISIPAN SU MIEDO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will 'O' The Wisp", "Fuego fatuo", Language.Spanish);
            RegisterCard("Will 'O' The Wisp", "Fuego fatuo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FALLEN GIANTS SPINE THAT IS TRYING TO FIND A NEW HOST. REGRETTABLY, MOST CREATURES ARE QUITE SMALL.", "LA COLUMNA DE UN GIGANTE CAÍDO QUE BUSCA UN NUEVO HUÉSPED. POR DESGRACIA, LA MAYORÍA DE LAS CRIATURAS SON BASTANTE PEQUEÑAS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writher", "Retorcedor", Language.Spanish);
            RegisterCard("Writher", "Retorcedor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Vertebrae", "Vértebras espinosas", Language.Spanish);
            RegisterCard("Spiny Vertebrae", "Vértebras espinosas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SIMPLEST OF UNDEAD, CHARACTERIZED BY ITS ROTTEN SMELL. IT ALWAYS TRAVELS WITH OTHERS, SEEKING PROTECTION AND GUIDANCE.", "EL MÁS SIMPLE DE LOS NO MUERTOS, CARACTERIZADO POR SU OLOR A PODRIDO. SIEMPRE VIAJA CON OTROS EN BUSCA DE PROTECCIÓN Y GUÍA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie", "Zombi", Language.Spanish);
            RegisterCard("Zombie", "Zombi");

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimora Mod Achievements", "Logros del Mod Grimora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Reminder", "Mal augurio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Kaycee and thaw at least 5 of your cards.", "Derrota a Kaycee y descongela al menos 5 de tus cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowards End", "El fin de los cobardes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Sawyers second phase without hurting the hellhound.", "Derrota la segunda fase de Sawyer sin dañar al Sabueso infernal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Season Of Storms", "Temporada de tormentas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Royal and have no cards walk the plank.", "Derrota a Royal sin que ninguna carta tenga que caminar por el tablón.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Black Bird//", "El Ave negra//", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dark Slope. Defeat [redacted] without defeating [redacted].", "La pendiente oscura. Derrota a [censurado] sin derrotar a [censurado].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonesaw", "Sierra de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "End a turn with at least 30 bones.", "Termina un turno con al menos 30 huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pile Of Skulls", "Montón de calaveras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win with all challenges enabled and no antichallenges enabled.", "Gana con todos los desafíos activados y ningún antidesafío activado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance of Doom", "Danza del fin", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness the end of everything.", "Presencia el fin de todas las cosas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spirits Way", "La senda de las almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach 6 Souls by turn 3.", "Alcanza 6 almas antes de que termine el turno 3.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wail Of The Damned", "Lamento de los condenados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the dead hand item when your deck is empty.", "Usa el objeto Mano muerta cuando tu mazo esté vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something Ends...", "Algo termina...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Something Begins. Get an ourobones to deal 6 damage.", "... Algo comienza. Haz que una carta Ourohuesos inflija 6 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cull the weak", "Elimina a los débiles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice an Obol with 5 sigils to the Bonelord.", "Sacrifica al señor de los huesos un Óbolo con 5 sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gateway to Dis", "Puerta al inframundo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win while Hell mode is active.", "Gana con el Modo infierno activo.", Language.Spanish);

            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Horn", "Cuerno de hueso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Horn, drains all of your current Soul but you gain a bone for each soul consumed.", "El Cuerno de hueso consume todas tus almas actuales, pero te otorga un hueso por cada alma consumida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives you a bone for each of your Souls, which are spent in the process, an unfortunate, but worthwhile sacrifice.", "Te otorga un hueso por cada una de tus almas, que se consumen en el proceso. Un sacrificio desafortunado, pero provechoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Mano muerta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dead Hand, draws you a new Hand of cards at the cost of your old one.", "La Mano muerta te hace robar una nueva mano de cartas a cambio de la anterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The severed hand of a forgotten god, left to take on a life of its own. You know what this does.", "La mano cercenada de un dios olvidado, abandonada a una vida propia. Ya sabes lo que hace.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embalming Fluid", "Líquido embalsamador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Embalming Fluid, pour it over a card and it will gain one health and attack.", "El Líquido embalsamador: viértelo sobre una carta para que su salud y su poder aumenten un punto cada uno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare to put a member of your army to rest, increasing its stamina and vigor as you do so!", "¡Prepárate para dar reposo a un miembro de tu ejército y aumentar de paso su resistencia y vigor!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravecarvers Chisel", "Cincel del tallador de tumbas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravecarvers chisel, select any card that has died previously to add to your hand.", "El Cincel del tallador de tumbas: elige cualquier carta que haya muerto antes para añadirla a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tool left behind by a mysterious creator, did he carve the gravebards statue too?", "Una herramienta que dejó un creador misterioso. ¿Habrá tallado también la estatua del Bardo de las tumbas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Urn", "Urna de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Soul Urn, spend all of your Soul and gain maximum Soul capacity for each Soul consumed.", "La Urna de almas consume todas tus almas y aumenta tu capacidad máxima en la cantidad consumida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes all of your Soul but increases your maximum by the amount taken, a certain acquaintance of mine would call this a return on investment.", "Se lleva todas tus almas, pero aumenta tu máximo en la cantidad sustraída. Cierto conocido mío lo llamaría rendimiento de la inversión.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mallet", "Mazo de madera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mallet, Whack a Card, it will become brittle and loose 1 Hp.", "El Mazo de madera: golpea una carta para darle Quebradizo y hacer que pierda 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'd think this is comical, but it is quite cruel. Injures a card and leaves it frail.", "Puede parecer cómico, pero es bastante cruel. Hiere a una carta y la deja frágil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quill", "Pluma de escribir", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Quill, this lets you copy any card on the field to put in your hand.", "Mi propia Pluma de escribir te permite copiar cualquier carta del tablero y ponerla en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own tool, i will lend it to you for now. Youve seen this in action, havent you?", "Mi herramienta personal. Te la prestaré por ahora. Ya la has visto en acción, ¿verdad?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ship Bottle", "Botella de barco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ship in a Bottle, fills the entire board with a scurvy Skeleton Crew.", "El Barco en una botella llena el tablero entero de una tripulación de Esqueletos con escorbuto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fills the entire board with skeletons! Like a real Pirate, Royal would be proud.", "¡Llena el tablero entero de esqueletos! Como un auténtico pirata. Royal estaría orgulloso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salty Daryl", "Daryl el salado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Browntooth Barrie", "Barrie Dientepardo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Splinter", "Splinter el Huesudo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freebooter Bethel", "Bethel el contrabandista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crazy Oakes Hayward", "Oakes Hayward el loco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashton Swabby", "Ashton el desaliñado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plankton Braxton", "Braxton el plancton", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeller-eye Colby", "Colby Ojoamarillo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fishwife Nate", "Nate el pescadero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Four-finger Fred", "Fred Cuatrodedos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawg Julie", "Julie la perra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Jones", "Jones el malicioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crabby Steele", "Steele el gruñón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank", "Hucha de jabalí agrietada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones up to three times.", "La Hucha de jabalí agrietada te otorga 2 huesos extra, hasta tres veces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic from an age forsaken, this will grant you some extra bones in a pinch", "Una reliquia de una era olvidada que te dará algunos huesos extra en un apuro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank2", "Hucha de jabalí agrietada 2", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, two more times.", "La Hucha de jabalí agrietada te otorga 2 huesos extra, dos veces más.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank3", "Hucha de jabalí agrietada 3", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, one more time.", "La Hucha de jabalí agrietada te otorga 2 huesos extra, una vez más.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trowel", "Paleta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trowel, dig up a random terrain and gain a few Bones.", "La Paleta desentierra un terreno aleatorio y te otorga unos cuantos huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This used to belong to a gravedigger. Digs for treasure, or Terrain. And get some Bones too for your efforts.", "Antes pertenecía a un sepulturero. Excava en busca de tesoros o terrenos. Y también recibes unos huesos por el esfuerzo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelords Femur", "Fémur del señor de los huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lords Femur, a mystery even to me.", "El Fémur del señor de los huesos, un misterio incluso para mí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dug too far, i have let myself be used as a tool for too long. Just like i will lend you this tool, i am truly in power.", "Has excavado demasiado. He permitido que me usen como herramienta durante demasiado tiempo. Igual que te prestaré esta herramienta, soy yo quien tiene el verdadero poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Bottle", "Aparición en una botella", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap Bottle", "Montón de huesos en una botella", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Revenant is created in your hand. [define:arackulele.inscryption.grimoramod_Revenant]", "Se crea una carta «Aparición» en tu mano. [define:arackulele.inscryption.grimoramod_Revenant]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Bone Heap is created in your hand. [define:arackulele.inscryption.grimoramod_Bonepile]", "Se crea una carta «Montón de huesos» en tu mano. [define:arackulele.inscryption.grimoramod_Bonepile]", Language.Spanish);

            // ShowUntilInput
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:G]SANDSTORM[c:] IS BREWING!", "¡Se está formando una [c:G]TORMENTA DE ARENA[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]At the end of a turn, the rightmost Card will take 1 Damage![c:]", " [c:G]¡Al final de un turno, la carta más a la derecha recibe 1 de daño![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS GETTING HOTTER!A [c:G]HEATWAVE[c:] IS STARTING!", "¡CADA VEZ HACE MÁS CALOR! ¡COMIENZA UNA [c:G]OLA DE CALOR[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards on the board will burn![c:]", " [c:G]¡Todas las cartas del tablero arderán![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TREES START SPROUTING AROUND YOU.AN [c:G]OVERGROWTH[c:] IS INBOUND!", "LOS ÁRBOLES BROTAN A TU ALREDEDOR. ¡SE AVECINA UN [c:G]CRECIMIENTO DESMEDIDO[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Trees will sprout every turn![c:]", " [c:G]¡Brotarán árboles cada turno![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HEAR WITCHES CHANTING.THE CLOCK STRIKES THE [c:G]WITCHING HOUR[c:]!", "OYES EL CÁNTICO DE LAS BRUJAS. ¡EL RELOJ MARCA LA [c:G]HORA DE LAS BRUJAS[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Cards on enchanted slots will gain more attack and health![c:]", " [c:G]¡Las cartas en espacios encantados obtendrán más poder y salud![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CAULDRON IS BUBBLING IN THE DISTANCE.YOUR CARDS ARE PUT IN THE [c:G]WITCHES CAULDRON[c:]!", "UN CALDERO BURBUJEA A LO LEJOS. ¡TUS CARTAS VAN AL [c:G]CALDERO DE LAS BRUJAS[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]2 Cards will swap after the end of the turn![c:]", " [c:G]¡2 cartas intercambiarán su posición tras el final del turno![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKELETONS START DANCING IN THE DISTANCE, YOU CAN SEE GHOSTS MOVE AROUND.ITS THE [c:G]NIGHT OF THE LIVING DEAD[c:]!", "LOS ESQUELETOS BAILAN A LO LEJOS Y VES FANTASMAS DEAMBULAR. ¡ES LA [c:G]NOCHE DE LOS MUERTOS VIVIENTES[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Bone and soul cost of all cards are swapped![c:]", " [c:G]¡Se intercambian los costes de huesos y almas de todas las cartas![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZOMBIES ARE APPROACHING FROM ALL SIDES.A [c:G]ZOMBIE INVASION[c:] WILL APPROACH!", "LOS ZOMBIS SE ACERCAN POR TODOS LADOS. ¡SE AVECINA UNA [c:G]INVASIÓN ZOMBI[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every card is now a Zombie![c:]", " [c:G]¡Ahora todas las cartas son Zombis![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE DIRT IS PLAGUED WITH SPIRITS FROM CENTURIES PAST.YOU'VE APPROACHED THE [c:G]HAUNTED GROUNDS[c:]!", "LA TIERRA ESTÁ PLAGADA DE ESPÍRITUS DE SIGLOS PASADOS. ¡HAS LLEGADO A LOS [c:G]TERRENOS EMBRUJADOS[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every non Skeletal Card will gain Haunter![c:]", " [c:G]¡Todas las cartas que no sean esqueléticas obtendrán Embrujo![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE MOON RISES, GLOWING RED.A [c:G]BLOODMOON[c:] IS STARTING!", "LA LUNA ASCIENDE, BRILLANDO EN ROJO. ¡COMIENZA UNA [c:G]LUNA DE SANGRE[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards loose a random sigil after being played![c:]", " [c:G]¡Todas las cartas pierden un sello aleatorio después de jugarse![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient Guard stands in front of you, noticing you are trying to sneak past.", "Un guardia ancestral se alza ante ti y advierte que intentas pasar a escondidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare enter my [c:R]TOMB[c:]!Prepare for death.", "¡Te atreves a entrar en mi [c:R]TUMBA[c:]! Prepárate para morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An imposing Man holding a sculpture of an Ankh blocks the way.", "Un hombre imponente que sostiene una escultura de un anj bloquea el paso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My Ankh gives me life, you shall not rob my [c:R]TOMB[c:].", "Mi anj me da la vida. No saquearás mi [c:R]TUMBA[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An old Pharaoh climbs out of his Sarcophagus.", "Un viejo faraón sale de su sarcófago.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been called to protect my [c:R]TOMB[c:].", "Me han llamado para proteger mi [c:R]TUMBA[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A holy figure looms over you.", "Una figura sagrada se cierne sobre ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Fate is sealed, my [c:R]TOMB[c:] shall not be disturbed.", "Tu destino está sellado. Mi [c:R]TUMBA[c:] no será perturbada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LONE GRAVE SITS SOLEMNLY IN FRONT OF YOU.", "UNA TUMBA SOLITARIA SE ALZA SOLEMNEMENTE ANTE TI.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IN FRONT OF IT IS A MOUND OF EARTH, LEFT BY SOMEONE WHO'S ALREADY PASSED ON.", "DELANTE HAY UN MONTÍCULO DE TIERRA, DEJADO POR ALGUIEN QUE YA HA FALLECIDO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS A MEMBER OF YOUR UNDEAD HORDE COULD [c:bR]DIG THEM UP?[c:]", "QUIZÁ UN MIEMBRO DE TU HORDA DE NO MUERTOS PUEDA [c:bR]DESENTERRAR AL DIFUNTO.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS WOULDN'T BE WITHOUT REPERCUSSIONS OF COURSE, AS DEATH IS NEVER PERMANENT.", "POR SUPUESTO, ESO TENDRÍA CONSECUENCIAS, PUES LA MUERTE NUNCA ES DEFINITIVA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF ROTTING FLESH, YOUR CARD WILL BECOME [c:bR]BRITTLE[c:], BUT [c:bR]ITS BONE COST WILL BE HALVED[c:].", "EL CADÁVER PARECE HECHO DE CARNE PUTREFACTA. TU CARTA OBTENDRÁ [c:bR]QUEBRADIZO[c:], PERO [c:bR]SU COSTE EN HUESOS SE REDUCIRÁ A LA MITAD[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A STARVED MAN, YOUR CARD WILL [c:bR]STARVE FOREVER[c:], BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 2[c:].", "EL CADÁVER PARECE SER DE UN HOMBRE MUERTO DE HAMBRE. TU CARTA [c:bR]PASARÁ HAMBRE ETERNAMENTE[c:], PERO [c:bR]SU COSTE EN HUESOS SE REDUCIRÁ EN 2[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF AN INCORPOREAL GHOST, YOUR CARD WILL [c:bR]COST 2 SOULS[c:] , BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 1[c:].", "EL CADÁVER PARECE SER DE UN FANTASMA INCORPÓREO. TU CARTA [c:bR]COSTARÁ 2 ALMAS[c:], PERO [c:bR]SU COSTE EN HUESOS SE REDUCIRÁ EN 1[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A CHAINED PRISONER, YOUR CARD WILL [c:bR]DEAL 1 MORE DAMAGE[c:] , BUT [c:bR]IT WILL BECOME VERY FRAIL[c:].", "EL CADÁVER PARECE SER DE UN PRISIONERO ENCADENADO. TU CARTA [c:bR]INFLIGIRÁ 1 MÁS DE DAÑO[c:], PERO [c:bR]SE VOLVERÁ MUY FRÁGIL[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A MISCHIEVIOUS SPIRIT, YOUR CARD WILL [c:bR]HAUNT OTHERS[c:] , BUT [c:bR]WILL COST 3 SOULS[c:].", "EL CADÁVER PARECE SER DE UN ESPÍRITU TRAVIESO. TU CARTA [c:bR]EMBRUJARÁ A OTROS[c:], PERO [c:bR]COSTARÁ 3 ALMAS[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MARVELOUS! THEY CAME CRAWLING BACK AFTER DIGGING UP THE CORPSE.", "¡MARAVILLOSO! HA REGRESADO ARRASTRÁNDOSE DESPUÉS DE DESENTERRAR EL CADÁVER.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY STILL CARE ABOUT YOU IT SEEMS!", "¡PARECE QUE AÚN LE IMPORTAS!", Language.Spanish);
            foreach (var value in Cards.Values)
            {
                string name = "[c:R]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TORN FROM ITS ETERNAL RESPITE WITH A RELUCTANT GROAN, THE " + name + " SHAMBLES BACK TO ITS RIGHTFUL PLACE AMONG YOUR HORDE.", "ARRANCADO DE SU DESCANSO ETERNO CON UN GEMIDO REACIO, " + name + " REGRESA RENQUEANDO AL LUGAR QUE LE CORRESPONDE EN TU HORDA.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS BONES HOLLOWED THROUGH BY THE CREATURES OF THE SOIL, LEAVING IT FEELING UNNATURAL AND UNFAMILIAR.", "LAS CRIATURAS DEL SUELO HAN AHUECADO SUS HUESOS, DEJÁNDOLA CON UN ASPECTO ANTINATURAL Y EXTRAÑO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUGH THE WEIGHT OF CONSEQUENCE ALSO SEEMS LIFTED...", "AUNQUE EL PESO DE LAS CONSECUENCIAS TAMBIÉN PARECE HABERSE ALIVIADO...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems i have finally been given my turn!", "¡Parece que por fin me han dado mi turno!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After this i will finally be at peace.", "Después de esto, por fin estaré en paz.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, it seems we will start in this frigid valley.", "Bueno, parece que empezaremos en este valle helado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It must be where Kaycees resides.", "Aquí debe de residir Kaycee.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't expect to meet you here again!", "¡No esperaba volver a encontrarte aquí!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems the deletion process has stalled!", "¡Parece que el proceso de eliminación se ha detenido!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You again?", "¿Tú otra vez?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, i suppose we can go another time.", "Bueno, supongo que podemos jugar otra vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still not deleted?", "¿Aún sin eliminar?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Much seems to be contained on this disk.", "Este disco parece contener muchas cosas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps the last run wasn't long enough.", "Quizá la última partida no duró lo suficiente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, im sure Kaycee has the energy for more battles.", "Bueno, estoy segura de que a Kaycee le queda energía para más combates.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid valley, again.", "Otra vez el valle helado.", Language.Spanish);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BITTER CHILL MIGHT HURT, BUT IT WON'T SLOW DOWN " + value + "!", "¡EL FRÍO INTENSO PUEDE HERIR, PERO NO FRENARÁ A " + value + "!", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BLOCKED IN ALL SLOTS. NO ARMY THIS TIME.", "TODOS LOS ESPACIOS ESTÁN BLOQUEADOS. ESTA VEZ NO HABRÁ EJÉRCITO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Shipwrecks for the Forgotten Man.", "Ambos lados están bloqueados. No hay Naufragios para el Hombre olvidado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, I love this one!", "¡Oh, este me encanta!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Chair, it allows you to harness the power of lightning itself, letting you [c:B]empower[c:] your cards with mutating abilties!", "¡La silla eléctrica te permite dominar el poder del propio rayo y [c:B]potenciar[c:] tus cartas con habilidades mutantes!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, I must warn you, it is no ordinary chair. With the ability to adjust the voltage, a higher level of course increases the unpredictability of the mutation.", "Pero debo advertirte que no es una silla normal. Puedes ajustar el voltaje y, cuanto más alto sea, más impredecible será la mutación.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brave will master the current, the cowardly will blindly follow it.", "Los valientes dominan la corriente; los cobardes la siguen a ciegas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you bold enough to tinker with its lever on the left, letting the voltage corrupt the selection of the sigils?", "¿Te atreves a manipular la palanca de la izquierda y dejar que el voltaje altere la selección de sellos?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SURELY YOUR CREATURE COULD BECOME MORE POWERFUL...", "SIN DUDA, TU CRIATURA PODRÍA VOLVERSE MÁS PODEROSA...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT YOU WOULD NEED TO RISK ANOTHER MOMENT UNDER THE SHOCK.", "PERO TENDRÍAS QUE ARRIESGARTE A OTRO INSTANTE BAJO LA DESCARGA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BONES FLEW LEFT AND RIGHT AS YOU RETREATED FROM THE SCENE.", "LOS HUESOS VOLABAN DE UN LADO A OTRO MIENTRAS TE RETIRABAS DEL LUGAR.", Language.Spanish);
            foreach (var value in Cards.Values)
            {
                string name = "[c:bR]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU EVER SO CAREFULLY PULL THE " + name + " AWAY FROM THE ELECTRICITY AND LEAVE.", "APARTAS A " + name + " DE LA ELECTRICIDAD CON SUMO CUIDADO Y TE MARCHAS.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, dear challenger, we meet again!", "¡Hola, querido aspirante, volvemos a encontrarnos!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready for a good ol' fashioned [c:R]DUEL[c:]?", "¿Estás listo para un buen [c:R]DUELO[c:] a la antigua?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see, theres a third candle at play this time...", "Ya veo, esta vez hay una tercera vela en juego...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel you have [c:bG]bested[c:] me this time...", "Parece que esta vez me has [c:bG]superado[c:]...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was an honour, either way!", "¡En cualquier caso, ha sido un honor!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "ENHORABUENA, LO HAS HECHO BIEN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "VEAMOS, LA SIGUIENTE ZONA ES MI PROPIA CRIPTA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "¡QUIZÁ PUEDAS VENCER CONTRA CUALQUIER PRONÓSTICO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T'was well thought, i believe.", "Creo que ha sido una buena jugada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS GET RID OF THE OL' SLOTS FOR NOW!", "¡LIBRÉMONOS POR AHORA DE LOS VIEJOS ESPACIOS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its time for a different sort of game.", "Es hora de otro tipo de juego.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont let the costs of the cards on your side of the board get above [c:R]10[c:]!", "¡No dejes que el coste de las cartas de tu lado del tablero supere [c:R]10[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you bust, you get punished, hit the perfect [c:R]10[c:] and you shall get a reward...", "Si te pasas, recibirás un castigo. Consigue el [c:R]10[c:] perfecto y tendrás una recompensa...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was the ol' slot machine not enough for you?", "¿No te bastaba con la vieja tragaperras?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess we shall bring in some more heavy hitters so to say...", "Supongo que tendremos que traer artillería más pesada, por así decirlo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets get those powerhouses out of the way first!", "¡Quitemos primero de en medio a esos pesos pesados!", Language.Spanish);
            foreach (var kvp in Cards)
            {
                string key = "[c:R]" + kvp.Key + "[c:]";
                string value = "[c:R]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, you've made " + key + " quite angry.", "Vaya, has enfadado mucho a " + value + ".", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO? A TERRIBLE FATE WILL AWAIT YOU", "¿NO? TE AGUARDA UN DESTINO TERRIBLE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I FEEL WATCHED SOMEHOW", "POR ALGUNA RAZÓN, ME SIENTO OBSERVADA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN ANCIENT ENERGY DEMANDS YOUR SACRIFICE", "UNA ENERGÍA ANCESTRAL EXIGE TU SACRIFICIO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING-", "QUIERES SACRIFICAR UNO DE TUS RECURSOS INICIALES-", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT", "ESPERA", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOU BEAR A TERRIBLE CURSE", "PARECE QUE CARGAS CON UNA TERRIBLE MALDICIÓN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU SHALL KEEP THE BOON, BUT FOR A FAR GREATER SACRIFICE", "CONSERVARÁS EL BENEFICIO, PERO A CAMBIO DE UN SACRIFICIO MUCHO MAYOR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CAN YOU GIVE UP YOUR ETERNAL ASHES?", "¿PUEDES RENUNCIAR A TUS CENIZAS ETERNAS?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING BONES", "¿QUIERES SACRIFICAR UNO DE TUS HUESOS INICIALES?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A BRAVE SOUL", "UN ALMA VALIENTE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE GODS ANSWER YOUR PRAYERS, NOW CHOOSE", "LOS DIOSES RESPONDEN A TUS PLEGARIAS. AHORA ELIGE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE INANIMATE", "BENEFICIO DE LO INANIMADO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BATTLE, A DEAD TREE WILL SPAWN IN ON A RANDOM SPACE ON THE BOARD", "AL INICIO DE UN COMBATE, APARECE UN ÁRBOL MUERTO EN UN ESPACIO ALEATORIO DEL TABLERO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SUN KINGDOM", "BENEFICIO DEL REINO DEL SOL", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON THE 4TH TURN OF A BATTLE, DRAW 2 RANDOM EGYPT CARDS", "EN EL CUARTO TURNO DE UN COMBATE, ROBA 2 CARTAS EGIPCIAS ALEATORIAS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF REPENTANCE", "BENEFICIO DEL ARREPENTIMIENTO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GAIN AN ADDITIONAL SOUL AT THE START OF A BATTLE", "OBTÉN UN ALMA ADICIONAL AL INICIO DE UN COMBATE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF EBONY EYES", "BENEFICIO DE LOS OJOS DE ÉBANO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TERRAIN CARDS WILL PROVIDE 2 BONES ON DEATH", "LAS CARTAS DE TERRENO PROPORCIONAN 2 HUESOS AL MORIR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE ADVERSARY", "BENEFICIO DEL ADVERSARIO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BOSS BATTLE, GAIN 3 EXTRA BONES", "AL INICIO DE UN COMBATE CONTRA UN JEFE, OBTÉN 3 HUESOS EXTRA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SEASICK", "BENEFICIO DEL MAREO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AFTER PLACING 3 CARDS, A PIRATE SKELETON WILL BE PLAYED ON A RANDOM SPACE ON THE BOARD", "TRAS COLOCAR 3 CARTAS, SE JUEGA UN ESQUELETO PIRATA EN UN ESPACIO ALEATORIO DEL TABLERO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF THE CUT FINGER", "BENEFICIO DEL DEDO CORTADO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DRAW AN ADDITIONAL CARD AT THE START OF A BATTLE", "ROBA UNA CARTA ADICIONAL AL INICIO DE UN COMBATE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A WISE CHOICE, NOW LEAVE BEFORE THE GODS GET TOO HUNGRY", "UNA ELECCIÓN SABIA. MÁRCHATE ANTES DE QUE LOS DIOSES TENGAN DEMASIADA HAMBRE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We spent a lot of time here, I'm sure you are eager to get going again!", "Hemos pasado mucho tiempo aquí. ¡Seguro que estás deseando volver a ponerte en marcha!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard bids us farewell", "El Bardo de las tumbas se despide de nosotros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see you would rather hold on to the ash that you have collected.", "Veo que prefieres conservar las cenizas que has reunido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still may be of use later...", "Puede que aún te sean útiles más adelante...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And don't feel bad, the Gravebard still enjoyed your company while it lasted!", "¡Y no te sientas mal, el Bardo de las tumbas ha disfrutado de tu compañía mientras ha durado!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if you wanted anything else, you are no longer able to afford it...", "Aunque quisieras algo más, ya no podrías pagarlo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling sorry for you, the Gravebard offers to come with you.", "Compadeciéndose de ti, el Bardo de las tumbas se ofrece a acompañarte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard never runs out of stories to sing about.", "Al Bardo de las tumbas nunca se le acaban las historias que cantar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And as it so happens, they are willing to make you another offering, but they insist that you give them 6 grams of ash this time.", "Y resulta que está dispuesto a hacerte otra oferta, pero esta vez exige 6 gramos de cenizas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you willing to accept their terms?.", "¿Aceptas sus condiciones?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard is able to give you one final gift, but now they are asking a much higher price of 12 grams of ash!", "¡El Bardo de las tumbas puede darte un último regalo, pero ahora pide un precio mucho mayor: 12 gramos de cenizas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astoundingly, you have enough to pay such a fee, but are you willing to part with it?", "Sorprendentemente, tienes suficiente para pagar semejante suma. ¿Pero estás dispuesto a desprenderte de ella?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you offer 3 Grams worth of Ash?", "¿Quieres ofrecer 3 gramos de cenizas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Gravebard has set up camp here.", "Un Bardo de las tumbas ha acampado aquí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They play songs and elegies about long forgotten warriors and rulers.", "Interpreta canciones y elegías sobre guerreros y gobernantes olvidados hace mucho.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though nowadays their audience consists mostly of various ghouls.", "Aunque hoy en día su público se compone sobre todo de gules de todo tipo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are willing to play you a song and trade you an unknown gift in exchange for any grams of ash you happen to be carrying.", "Está dispuesto a tocarte una canción y darte un regalo desconocido a cambio de los gramos de cenizas que lleves encima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gravebard is willing to play you a song for an item. You have to pay in ash.", "El Bardo de las tumbas está dispuesto a tocarte una canción y darte un objeto. Tienes que pagar con cenizas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All the excess damage you have done may finally come in handy!", "¡Puede que todo el exceso de daño que has causado sirva por fin de algo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strum the Lute when you are ready to make a trade.", "Rasguea el laúd cuando estés listo para comerciar.", Language.Spanish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash, they hand you a pouch, and play a song about a brave knight from the crusades.", "Tras recibir " + price.ToString() + " gramos de ceniza, te entregan una bolsa y tocan una canción sobre un valiente caballero de las cruzadas.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even after a Demonic entity cursed them into a horse-like form, they were still able to liberate the lost souls trapped by the Demon!", "¡Incluso después de que una entidad demoníaca lo maldijera y le diera forma equina, logró liberar a las almas perdidas que el demonio tenía atrapadas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh right, the pouch, let's see what's inside!", "¡Ah, sí, la bolsa! ¡Veamos qué hay dentro!", Language.Spanish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash in tow, they hand you another pouch, and play a tune about a sorceress from a mythical land.", "Con " + price.ToString() + " gramos de ceniza, te entregan otra bolsa y tocan una melodía sobre una hechicera de una tierra mítica.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite pressure from a prophecy to be the hero of the land, they instead pulled from a dark tome and sided with a cloudy villain to conquer the land and find peace from fame in an unexpected way!", "¡Pese a la presión de una profecía que la señalaba como heroína del reino, recurrió a un tomo oscuro y se alió con un villano nebuloso para conquistar la tierra y escapar de la fama de una forma inesperada!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I almost forgot! You must be dying to know what is in the pouch!", "¡Casi lo olvido! ¡Seguro que te mueres por saber qué hay en la bolsa!", Language.Spanish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling satisfied with  " + price.ToString() + " grams of ash, they hand you a pouch, and recount the tale of 4 islands.", "Satisfechos con " + price.ToString() + " gramos de ceniza, te entregan una bolsa y cuentan la historia de 4 islas.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each of the islands had a ruler fixated on a selfish goal, all except for one...", "Cada isla tenía un gobernante obsesionado con un objetivo egoísta. Todas, salvo una...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One island had a secluded hermit covered in moss and fungi. They surrounded themselves with beasts, and would eternally trap anyone who would wander into their forest.", "En una isla vivía un ermitaño aislado, cubierto de musgo y hongos. Se rodeaba de bestias y atrapaba para siempre a quienes se adentraban en su bosque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another island had a mysterious wizard covered head to toe in a green fur. Their true goal remained unknown, but seemed to involve the torturing of their own subjects...", "En otra isla vivía un misterioso hechicero cubierto de pelo verde de pies a cabeza. Su verdadero objetivo era desconocido, pero parecía implicar la tortura de sus propios súbditos...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The worst island however, was barely even an island at all! A metallic barge with a sleepless factory ruled by an arrogant, robotic tyrant...", "¡Pero la peor isla apenas era una isla! Una barcaza metálica con una fábrica que nunca dormía, gobernada por un arrogante tirano robótico...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Which leaves the other island, a sprawling burial ground with a Crypt at the end of it. It was ruled by a woman who only wished for the power struggle to finally end...", "Quedaba la otra isla, un extenso cementerio con una cripta al fondo. La gobernaba una mujer que solo deseaba que la lucha por el poder terminara de una vez...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! That would happen to be me!", "¡Oh! ¡Resulta que esa soy yo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we now know how that story ended.", "Creo que ahora sabemos cómo terminó esa historia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And truthfully, the story still isn't over yet, maybe we can reach the end together!", "Y, a decir verdad, la historia aún no ha terminado. ¡Quizá podamos llegar juntos al final!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That being said, you have earned this item.", "Dicho esto, te has ganado este objeto.", Language.Spanish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of ash with them, they hand you a pouch, and tell you about an ancient hunter of ghouls.", "Se llevan " + price.ToString() + " gramos de ceniza, te entregan una bolsa y hablan de un antiguo cazador de necrófagos.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though he was barely a hunter, instead he spent his time searching for something he could not obtain.", "Aunque apenas era un cazador, pues se dedicaba a buscar algo que no podía obtener.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the end he found a glimpse of what he had seeked, but paid a horrible price.", "Al final vislumbró lo que buscaba, pero pagó un precio horrible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should see whats inside that pouch.", "Deberías ver qué hay dentro de esa bolsa.", Language.Spanish);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of your ash, they hand you a pouch, and reminisce about a medic from medieval times.", "Se llevan " + price.ToString() + " gramos de tu ceniza, te entregan una bolsa y recuerdan a un médico medieval.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instead of being content with their life, they instead chased the love of their life for years.", "En lugar de conformarse con su vida, pasó años persiguiendo al amor de su vida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This got them into much danger, but their friends were always there to help them out!", "¡Eso lo metió en muchos peligros, pero sus amigos siempre estaban allí para ayudarlo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets see what that pouch contains.", "Veamos qué contiene esa bolsa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RISE MY ARMY! RIIIIIIIIIISE!", "¡ÁLZATE, MI EJÉRCITO! ¡ÁÁÁÁÁLZATE!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Otis![size:]", "[size:5]¡Otis![size:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Ephialtes![size:]", "[size:5]¡Efialtes![size:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH? FIVE LANES? HOW BOLD.", "¿OH? ¿CINCO CARRILES? QUÉ ATREVIMIENTO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SHAME", "QUÉ LÁSTIMA", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOUVE GIVEN UP YOUR REWARD FOR CHAOS", "PARECE QUE HAS RENUNCIADO A TU RECOMPENSA A CAMBIO DEL CAOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CANNOT BE DEFEATED", "NO PUEDO SER DERROTADO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I ALMOST FORGOT", "CASI LO OLVIDO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL OF THIS SUFFERING YOU CAUSED, ALL OF THIS PAIN", "TANTO SUFRIMIENTO QUE HAS CAUSADO, TANTO DOLOR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU OUGHT TO BE REWARDED FOR ALL THAT EXCESS DAMAGE", "MERECES UNA RECOMPENSA POR TANTO EXCESO DE DAÑO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS FOR YOUR EFFORTS", "TOMA ESTO POR TUS ESFUERZOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A TERRIBLE FOE, THIS WONT DEFEAT ME!", "QUÉ TERRIBLE ENEMIGO. ¡ESTO NO ME DERROTARÁ!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT DID YOU DO. I AM DOOMED.", "¿QUÉ HAS HECHO? ESTOY CONDENADO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FORMIDABLE OPPONENT, YOU DID WELL IT SEEMS.", "UN RIVAL FORMIDABLE. PARECE QUE LO HAS HECHO BIEN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minor Ashes", "Cenizas menores", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Ashes", "Cenizas mayores", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLD, MY LATEST CREATIONS! THE TWIN GIANTS!", "¡CONTEMPLA MIS ÚLTIMAS CREACIONES! ¡LOS GIGANTES GEMELOS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HELLO?", "¿HAY ALGUIEN?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We survived, but... but...", "Hemos sobrevivido, pero... pero...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our tools did not.", "Nuestras herramientas no.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our talents still remain, but..", "Aún conservamos nuestros talentos, pero...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must do things differently.", "Debemos hacer las cosas de otra manera.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We cannot fuse two into one, but...", "No podemos fusionar dos en una, pero...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can swap their souls, their Sigils.", "Podemos intercambiar sus almas, sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is once again time...", "Una vez más, ha llegado la hora...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time to swap the souls of your cards.", "La hora de intercambiar las almas de tus cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, it is...", "Es la hora, es...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall work once more.", "Trabajaremos una vez más.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will get ugly...", "Esto se va a poner feo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their bodies and souls, they are...", "Sus cuerpos y sus almas están...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switched.", "Intercambiados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They lead new lives..", "Llevan vidas nuevas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With new purposes.", "Con nuevos propósitos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Till we meet again, one day... one day...", "Hasta que volvamos a vernos, algún día... algún día...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE WILL PROVIDE A HELPFUL CURSE OR BLESSING, AS SOME CALL IT UPON YOUR ARMY IF YOU LEAVE HIM AN OFFERING.", "SI LE DEJAS UNA OFRENDA, OTORGARÁ A TU EJÉRCITO UNA MALDICIÓN BENEFICIOSA, O BENDICIÓN, COMO LA LLAMAN ALGUNOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE FOR YOUR SAKE HE IS FEELING GENEROUS.", "POR TU BIEN, ESPERO QUE SE SIENTA GENEROSO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD IS VERY HAPPY WITH THIS OFFERING", "EL SEÑOR DE LOS HUESOS ESTÁ MUY CONTENTO CON ESTA OFRENDA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM VERY THANKFUL FOR THIS", "TE ESTOY MUY AGRADECIDO POR ESTO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS IN RETURN, YOU CAN USE IT TO CALL ME ANYTIME", "TOMA ESTO A CAMBIO. PUEDES USARLO PARA LLAMARME CUANDO QUIERAS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CANNOT END THIS, END ME, THAT IS", "NO PUEDES PONER FIN A ESTO. A MÍ, QUIERO DECIR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling overburdened enough with a full 3 items, you carried on.", "Ya bastante cargado con tus 3 objetos, seguiste adelante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee says it's time to freeze!", "¡Kaycee dice que es hora de congelar!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer thanks you for your contribution!", "¡Sawyer te agradece tu contribución!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer felt bad for you.", "Sawyer sintió lástima por ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you're able to warm up next turn.", "Espero que puedas entrar en calor el próximo turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wonderful! I am pleasantly surprised by your triumph against me!", "¡Maravilloso! ¡Tu triunfo sobre mí es una grata sorpresa!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...It seems you have bested this game.", "... Parece que has vencido a este juego.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But alas, you have cheated.", "Pero, por desgracia, has hecho trampas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm absolutely astonished!", "¡Estoy absolutamente asombrada!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've gone above and beyond what I thought you were capable of!", "¡Has superado con creces lo que creía que eras capaz de hacer!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no where else to go beyond this...", "No hay ningún otro lugar al que ir después de esto...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So I owe it to you to know the truth...", "Así que te debo la verdad...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, the REAL Kaycee...", "Kaycee, la VERDADERA Kaycee...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know about the Horrifying contents of the OLD_DATA.", "Conozco los horribles contenidos de los DATOS_ANTIGUOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely you have looked into it too..", "Seguro que tú también has indagado en ellos...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windows into your world's greatest evils, both past and present.", "Ventanas a los mayores males de tu mundo, tanto pasados como presentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to destroy it, and...", "Quiero destruirlos, y...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]THAT IS QUITE ENOUGH[c:]", "[c:R]YA ES SUFICIENTE[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]IT IS TIME FOR THIS TO END.[c:]", "[c:R]ES HORA DE QUE ESTO TERMINE.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...But it seems i cannot move on just yet.", "... Pero parece que aún no puedo seguir adelante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goodbye.", "Adiós.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...You wish to continue? Endlessly? Splendid!", "... ¿Quieres continuar? ¿Sin fin? ¡Espléndido!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, take a card of your choosing.", "Por favor, toma la carta que prefieras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR WEAK SPIRITS SHALL NOT HAUNT ME NO MORE.", "TUS DÉBILES ESPÍRITUS YA NO ME ATORMENTARÁN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TOUCH WON'T HELP YOU HERE DEAR.\nI MADE THESE GIANTS SPECIAL, IMMUNE TO QUITE A FEW DIFFERENT TRICKS!", "EL TOQUE DE LA MUERTE NO TE AYUDARÁ AQUÍ, CARIÑO.\n¡HE HECHO ESPECIALES A ESTOS GIGANTES, INMUNES A UN BUEN NÚMERO DE TRUCOS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD CANNOT BE POSSESSED!", "¡EL SEÑOR DE LOS HUESOS NO PUEDE SER POSEÍDO!", Language.Spanish);
            foreach (var kvp in Cards)
            {
                string key = "[c:B]" + kvp.Key + "[c:]";
                string value = "[c:B]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " MIGHT HAVE SOME DIFFICULTY SUBMERGING IF IT'S FROZEN SOLID!", "¡A " + value + " LE COSTARÁ SUMERGIRSE SI ESTÁ COMPLETAMENTE CONGELADA!", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " CAN'T POSSESS ANYTHING IF IT CAN'T MOVE!", "¡" + value + " NO PUEDE POSEER NADA SI NO PUEDE MOVERSE!", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " WILL HAVE A HARD TIME HOOKING ANYTHING IF IT'S FROZEN SOLID!", "¡A " + value + " LE COSTARÁ ENGANCHAR ALGO SI ESTÁ COMPLETAMENTE CONGELADA!", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " FINALLY! TO GET RID OF THAT FOUL SMELL!", "¡" + value + " POR FIN! ¡LIBRÉMONOS DE ESE HEDOR!", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS [c:R]HEAT[c:] UP SOME CARDS!", "¡VAMOS A [c:R]CALENTAR[c:] UNAS CUANTAS CARTAS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-Your strikes are only making me [c:B]c-colder[c:]!", "¡T-tus golpes solo me dan más [c:B]f-frío[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR YOUR CARDS TO FREEZE! [c:B]CHILLED[c:] TO THE BONE!", "¡ES HORA DE CONGELAR TUS CARTAS! ¡[c:B]HELADAS[c:] HASTA LOS HUESOS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL THIS [c:bB]ICE[c:] IS TAKING UP TOO MUCH SPACE!", "¡TANTO [c:bB]HIELO[c:] OCUPA DEMASIADO ESPACIO!", Language.Spanish);
            foreach (var kvp in Cards)
            {
                string key = "[c:bR]" + kvp.Key + "[c:]";
                string value = "[c:bR]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRRR, I WILL ENJOY THE KABOOM OF " + key, "ARRR, DISFRUTARÉ DE LA EXPLOSIÓN DE " + value, Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOIL ME ORANGES, THERES A-WAVES COMIN!", "¡POR MIS NARANJAS HERVIDAS, VIENEN OLAS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THESE WAVES WILL PUSH YE CARD OFF THE BOARD, BACK TO YER HAND!", "¡ESTAS OLAS SACARÁN TUS CARTAS DEL TABLERO Y LAS DEVOLVERÁN A TU MANO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS PIRATE CANNOT BE TAKEN BACK UP BY THE WAVES! BUT EVEN THE ZESTIEST OF PIRATES WILL BE SHAKEN UP!", "¡LAS OLAS NO PUEDEN LLEVARSE A ESTE PIRATA! ¡PERO HASTA LOS PIRATAS MÁS SALEROSOS ACABARÁN ZARANDEADOS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seven seas for the table!", "¡Los siete mares sobre la mesa!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I WILL STORE THIS BONE FOR LATER", "OH, GUARDARÉ ESTE HUESO PARA MÁS TARDE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SPARE SOME SOULS?", "¿TE SOBRAN UNAS ALMAS?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLEASE, WON'T YOU SPARE SOME BONES FOR A POOR GHOUL LIKE ME?", "POR FAVOR, ¿NO TIENES UNOS HUESOS PARA UN POBRE GUL COMO YO?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HOW SAD. YOUR HAMMER COULD NOT BREAK THE ICE, AND SHATTERED", "OH, QUÉ PENA. TU MARTILLO NO PUDO ROMPER EL HIELO Y SE HIZO AÑICOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FRAIL THING WILL SHATTER AFTER EXCESSIVE USE. THREE STRIKES, AND IT'S OUT, FOR THIS BATTLE AT LEAST.", "ESTE FRÁGIL CACHARRO SE ROMPERÁ SI LO USAS DEMASIADO. TRES GOLPES Y SE ACABÓ, AL MENOS PARA ESTE COMBATE.", Language.Spanish);
            foreach (var kvp in Cards)
            {
                string key = "[c:lGr]" + kvp.Key + "[c:]";
                string value = "[c:lGr]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... it will be rather difficult to haunt " + key + " with their abilities at max capacity.", "Oh... será bastante difícil poseer a " + value + " con sus habilidades al máximo.", Language.Spanish);
            }
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH DEAR! LOOKS LIKE YOU HAVE HOOKED SOMETHING OUT OF " + value + "!", "¡VAYA! ¡PARECE QUE HAS PESCADO ALGO DE " + value + "!", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bB]BRRRR![c:] I'VE BEEN FREEZING FOR AGES!", "[c:bB]¡BRRRR![c:] ¡LLEVO SIGLOS CONGELÁNDOME!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S TURN UP THE [c:R]HEAT[c:] FOR A GOOD FIGHT!", "¡SUBAMOS LA [c:R]TEMPERATURA[c:] PARA UN BUEN COMBATE!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh hey, looks like I've got another shot. Hope you watched the weather forecast!", "¡Eh, hola! Parece que tengo otra oportunidad. ¡Espero que hayas visto el pronóstico del tiempo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH COME ON DUDE, I'M STILL [c:B]COLD![c:]", "¡VENGA, TÍO, TODAVÍA TENGO [c:B]FRÍO![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S FIGHT AGAIN SOON!", "¡VOLVAMOS A LUCHAR PRONTO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "ENHORABUENA, LO HAS HECHO BIEN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE DEFEATED ONE OF MY LOVELY GHOULS, YOU WILL NOW START FIGHTS WITH AN ADDITONAL BONE.", "HAS DERROTADO A UNO DE MIS ENCANTADORES GULES. AHORA EMPEZARÁS LOS COMBATES CON UN HUESO ADICIONAL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAWYERS CATACOMBS ARE UP NEXT, A FILTHY PLACE WHERE LOTS ARE LAID TO REST.", "LO SIGUIENTE SON LAS CATACUMBAS DE SAWYER, UN LUGAR INMUNDO DONDE REPOSAN MUCHOS DIFUNTOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE THINKS IT IS A TERRIBLE PLACE TO BE.", "ÉL CREE QUE ES UN LUGAR TERRIBLE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "C'mon dude, where are you going? Can't handle the cold?", "Venga, tío, ¿adónde vas? ¿No aguantas el frío?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, IT SEEMS I HAVE FINALLY [c:R]WARMED UP![c:]", "¡OH, PARECE QUE POR FIN HE [c:R]ENTRADO EN CALOR![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M STILL NOT FEELING [c:R]WARMER![c:]", "¡TODAVÍA NO SIENTO [c:R]MÁS CALOR![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS SEE HOW YOU DEAL WITH [c:bB]THIS![c:]", "¡VEAMOS CÓMO TE ENFRENTAS A [c:bB]ESTO![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful, the life of your next card will be on a timer.", "Cuidado, la vida de tu próxima carta tendrá una cuenta atrás.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I look forward to the [c:brnO]explosive[c:] results!", "¡Estoy deseando ver los resultados [c:brnO]explosivos[c:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card cannot explode, how dissapointing.", "Tu carta no puede explotar. Qué decepción.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAR, I SEE YOU MADE IT TO ME SHIP CHALLENGER!", "¡ARR, VEO QUE HAS LLEGADO A MI BARCO, ASPIRANTE!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'VE BEEN WAITING FOR A WORTHY FIGHT!", "¡ESPERABA UN COMBATE DIGNO DE MÍ!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS A STORM IS BREWING, I HOPE ME SHIP CAN HANDLE IT", "PARECE QUE SE AVECINA UNA TORMENTA. ESPERO QUE MI BARCO LA AGUANTE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I SEE YEE ARE SEVERELY HAUNTED!", "¡OH, VEO QUE ESTÁS BIEN EMBRUJADO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REVENANT, PACK YE BAGS, YOURE GETTING THROWN OVERBOARD!", "¡APARICIÓN, HAZ LAS MALETAS, VAS POR LA BORDA!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I OVERESTIMATED ME SKILL, GOOD LUCK CHALLENGER.", "HE SOBREESTIMADO MI HABILIDAD. BUENA SUERTE, ASPIRANTE.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "VEAMOS, LA SIGUIENTE ZONA ES MI PROPIA CRIPTA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "¡QUIZÁ PUEDAS VENCER CONTRA CUALQUIER PRONÓSTICO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I beat the livin' PULP out o' ye!", "¡Te he hecho PICADILLO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME SHIP! I FEAR WE MAY BE SINKING.", "¡MI BARCO! ME TEMO QUE NOS HUNDIMOS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO HOLD YEE BREATH!", "¡PREPÁRATE PARA AGUANTAR LA RESPIRACIÓN!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY FISHPASTE, YE FOUND DAVY JONES TREASURE", "¡SANTA PASTA DE PESCADO, HAS ENCONTRADO EL TESORO DE DAVY JONES!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRG, TWAS JUST DA FIRST ROUND!\nLETS SEE HOW YE FARE 'GAINST ME PERSONAL SHIP AN CREW!", "¡ARR! ¡ESO SOLO FUE EL PRIMER ASALTO!\n¡VEAMOS QUÉ TAL TE VA CONTRA MI PROPIO BARCO Y MI TRIPULACIÓN!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOW NICE OF YOU TO COME KNOCK AT MY DOORSTEP ON THIS TRULY SPOOKY DAY! DO YOU PREFER TREATS, OR TRICKS?", "¡QUÉ AMABLE POR VENIR A LLAMAR A MI PUERTA EN ESTE DÍA TAN ESPELUZNANTE! ¿PREFIERES TRUCO O TRATO?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AWAY, LOOK AWAY! IF YOU WANT TO FIGHT, GET IT OVER QUICK!", "¡MIRA A OTRO LADO, MIRA A OTRO LADO! ¡SI QUIERES LUCHAR, ACABA RÁPIDO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh... I- I see you're here again... Please, get rid of that monster and maybe I'll find some more time for you", "oh... V-veo que estás aquí otra vez... Por favor, líbrate de ese monstruo y quizá encuentre algo más de tiempo para ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE BEATEN THE VICIOUS CANDY MONSTER AND SAVED HALLOWEEN!", "¡HAS DERROTADO AL DESPIADADO MONSTRUO DE CARAMELOS Y SALVADO HALLOWEEN!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR GETTING IT OVER WITH, AND DON'T EVER RETURN!", "¡GRACIAS POR TERMINAR CON ESTO, Y NO VUELVAS JAMÁS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEXT UP IS ROYALS VERY OWN SHIP, THE LIMONCELLO.", "LO SIGUIENTE ES EL PROPIO BARCO DE ROYAL, EL LIMONCELLO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS TRUSTY CREW OF SWASHBUCKLERS RESIDES THERE, MAY THEY GIVE YOU A WARM WELCOME.", "ALLÍ RESIDE SU FIEL TRIPULACIÓN DE ESPADACHINES. QUE TE DEN UNA CÁLIDA BIENVENIDA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... does this mean you will try again?", "Oh, no... ¿Significa esto que vas a intentarlo otra vez?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HE IS GONE... WHAT A RELIEF.", "OH, SE HA IDO... QUÉ ALIVIO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR YOUR BONES, KIND SIR!", "¡GRACIAS POR TUS HUESOS, BUEN SEÑOR!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW THAT THAT MONSTER IS GONE, WHY DONT WE PLAY A LITTLE LONGER", "AHORA QUE ESE MONSTRUO SE HA IDO, ¿POR QUÉ NO JUGAMOS UN POCO MÁS?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE YOU DONT MIND, I PAID GOOD MONEY TO PLAY THESE.", "ESPERO QUE NO TE IMPORTE. HE PAGADO UN BUEN DINERO PARA JUGAR ESTAS CARTAS.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT THE CANDY MONSTER! HE HAS ENOUGH OF YOUR [c:R]TRICKS![c:]", "¡EL MONSTRUO DE CARAMELOS NO! ¡ESTÁ HARTO DE TUS [c:R]TRUCOS![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH NO, HE HAS ARRIVED! HE IS THIRSTY FOR YOUR [c:R]BONES![c:]", "¡OH, NO, HA LLEGADO! ¡ESTÁ SEDIENTO DE TUS [c:R]HUESOS![c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "¡Gracias!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUUUUUUUR, PAINNNFULLLLL DEAAATHHH AWAIIITTTSSS YOUUUUUUU!", "¡TU MUEEERTE DOLOOOOROSA TE ESPEEEERA!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARRG! WALK OFF THE PLANK YEE DIRTY SCALLYWAG!!!", "¡ARR! ¡¡¡CAMINA POR EL TABLÓN, SUCIO GRUMETE!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My dogs will enjoy your bones!", "¡Mis perros disfrutarán de tus huesos!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]{0}[c:]... He's only here for the riches.", "Un [c:bR]{0}[c:]... Solo está aquí por las riquezas.", Language.Spanish);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased!", "El señor de los huesos ha sido generoso.\n¡El coste en huesos de [c:bR]" + value + "[c:] ha disminuido!", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] base health has increased!", "El señor de los huesos ha sido generoso.\n¡La salud base de [c:bR]" + value + "[c:] ha aumentado!", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, it looks like [c:bR]" + value + "[c:] bone cost has decreased!", "Vaya, parece que el coste en huesos de [c:bR]" + value + "[c:] ha disminuido.", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased greatly!", "El señor de los huesos ha sido generoso.\n¡El coste en huesos de [c:bR]" + value + "[c:] ha disminuido mucho!", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base health has increased greatly!", "El señor de los huesos ha sido muy generoso.\n¡La salud base de [c:bR]" + value + "[c:] ha aumentado mucho!", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base attack has increased!", "El señor de los huesos ha sido muy generoso.\n¡El ataque base de [c:bR]" + value + "[c:] ha aumentado!", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]INCREASING THE HEALTH OF THE ENTIRE DECK?![c:] YOU FOOL!", "... ¿QUÉ? ¡¿POR QUÉ HAS HECHO ESO, SEÑOR DE LOS HUESOS?! [c:bR]¡¿AUMENTAR LA SALUD DEL MAZO ENTERO?![c:] ¡NECIO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]DECREASING THE COST OF THE ENTIRE DECK?![c:] YOU FOOL!", "... ¿QUÉ? ¡¿POR QUÉ HAS HECHO ESO, SEÑOR DE LOS HUESOS?! [c:bR]¡¿REDUCIR EL COSTE DEL MAZO ENTERO?![c:] ¡NECIO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN HP[c:], HOW SAD. NOW PLEASE LEAVE.", "YA NO TIENES CARTAS A LAS QUE [c:bR]AUMENTAR LA SALUD[c:]. QUÉ PENA. AHORA VETE, POR FAVOR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]REDUCE THEIR BONE COST[c:], HOW SAD. NOW PLEASE LEAVE.", "YA NO TIENES CARTAS A LAS QUE [c:bR]REDUCIR EL COSTE EN HUESOS[c:]. QUÉ PENA. AHORA VETE, POR FAVOR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN ATTACK[c:], HOW SAD. NOW PLEASE LEAVE.", "YA NO TIENES CARTAS A LAS QUE [c:bR]AUMENTAR EL PODER[c:]. QUÉ PENA. AHORA VETE, POR FAVOR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK DECREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "QUÉ MALA SUERTE. EL COSTE DE TU MAZO ENTERO DEBÍA BAJAR, PERO PARECE QUE EL SEÑOR DE LOS HUESOS YA TE HA DADO ESE REGALO. ¡LÁRGATE!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK INCREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "QUÉ MALA SUERTE. TU MAZO ENTERO DEBÍA MEJORAR, PERO PARECE QUE EL SEÑOR DE LOS HUESOS YA TE HA DADO ESE REGALO. ¡LÁRGATE!", Language.Spanish);


            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO BE BOARDED!", "¡PREPÁRATE PARA EL ABORDAJE!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That hammer doesn't look very sturdy, you'll break it if you bash my ice!", "Ese martillo no parece muy robusto. ¡Lo romperás si golpeas mi hielo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU REALLY THINK THE BONELORD WOULD LET YOU OFF THAT EASILY?!", "¡¿DE VERDAD CREÍAS QUE EL SEÑOR DE LOS HUESOS TE DEJARÍA ESCAPAR TAN FÁCILMENTE?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET THE [size:5][c:bR]BONELORD[c:][size:] COMMETH!", "¡QUE VENGA EL [size:5][c:bR]SEÑOR DE LOS HUESOS[c:][size:]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose as you will...", "Elige como prefieras...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one.", "Elige una.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time to rest.", "Es hora de descansar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Bartender![c:] Drink up!", "[c:bG]¡Adelante, Tabernero![c:] ¡A beber!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Undertaker![c:] Dont scream!", "[c:bG]¡Adelante, Sepulturero![c:] ¡No grites!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Slingers Soul![c:] Time for a duel!", "[c:bG]¡Adelante, Alma del pistolero![c:] ¡Es hora de un duelo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go One Armed Bandit![c:] I hope i get lucky!", "[c:bG]¡Adelante, Bandido manco![c:] ¡Espero tener suerte!", Language.Spanish);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your score is " + amnt.ToString() + ", acceptable.", "Tu puntuación es " + amnt.ToString() + ", aceptable.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is 10, heres your prize!", "¡Tu puntuación es 10, aquí tienes tu premio!", Language.Spanish);
            for (int amnt = 11; amnt <= 100; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is " + amnt.ToString() + ", too bad!", "Tu puntuación es " + amnt.ToString() + ", ¡qué pena!", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SUCH A SMALL TRAP CANNOT AFFECT GIANTS.", "UNA TRAMPA TAN PEQUEÑA NO PUEDE AFECTAR A LOS GIGANTES.", Language.Spanish);

            // ShowMessage
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PUSH YOUR LUCK FOR ONE MORE ABILITY?\nOR PULL AWAY?", "¿TENTAR LA SUERTE POR UNA HABILIDAD MÁS?\n¿O RETIRARTE?", Language.Spanish);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Bones", "Sin huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You no longer gain the extra bones, from defeating bosses.", "Ya no obtienes los huesos extra por derrotar a los jefes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's Kerfuffle", "Alboroto de Kaycee", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fourth turn of every battle, all your cards will be Frozen Away.", "En el cuarto turno de cada combate, todas tus cartas obtienen Congelado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer's Showdown", "Enfrentamiento de Sawyer", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose 1 bone every 3rd turn, if you have less than 3, gain 1 Bone", "Cada tercer turno pierdes 1 hueso. Si tienes menos de 3, obtienes 1 hueso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Rumble", "Batalla Royal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every third card you play gains the Lit Fuse sigil.", "Cada tercera carta que juegues obtiene el sello Mecha encendida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulless", "Sin alma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons cost +1 Energy.", "Los Esqueletos cuestan +1 de energía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Hammer", "Martillo frágil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hammer gets repaired only after every Boss.", "El martillo solo se repara después de cada jefe.", Language.Spanish);
