    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "PARTIDA NUEVA CON MAGNIFICUS", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "PARTIDA NUEVA CON MAGNIFICUS", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "Ver mazo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "TORRE DE MAGIAS", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "MAZMORRA DE MUGRE", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "MAZMORRA DE LAVA", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "MAZMORRA DEL VACÍO", Language.Spanish);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "Desbloquea automáticamente todos los desafíos y mazos iniciales del Mod de Kaycee de Magnificus. Esto NO cambia tus puntos de desafío de Magnificus. Si cambias de opinión y decides desbloquear los desafíos de forma justa, tus puntos de desafío seguirán siendo los mismos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "Las cartas básicas de hechicero del acto 2 conservan sus estadísticas originales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "Usa los antiguos diseños de cartas planos en 2D en lugar de los nuevos modelos 3D.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "Añade salpicaduras de pintura al fondo de cada carta, como en el final original de Magnificus.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "Perspectiva en tercera persona para el juego de Magnificus. Desactívala si quieres la experiencia clásica en primera persona.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "Muestra una cuadrícula alrededor del jugador en el modo de tablero.", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Mox vacío", Language.Spanish);
            RegisterAbility("Blank Mox", "Mox vacío");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "Cuando se roba una carta que lleve este sello, se materializa en un cristal mox aleatorio. \n En otra carta, este sello hace que la carta genere un cristal mox aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "Mox indeciso", Language.Spanish);
            RegisterAbility("Undecided Mox", "Mox indeciso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "Cuando se juega una carta que lleve este sello, elige el tipo de mox que proporcionará.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "Corazón de rubí", Language.Spanish);
            RegisterAbility("Ruby Heart", "Corazón de rubí");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "Cuando muere una carta que lleve este sello, crea un Mox rubí en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Corazón de zafiro", Language.Spanish);
            RegisterAbility("Sapphire Heart", "Corazón de zafiro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "Cuando muere una carta que lleve este sello, crea un Mox zafiro en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "Médula ósea", Language.Spanish);
            RegisterAbility("Bone Marrow", "Médula ósea");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "Cuando muere una de tus cartas que no sea de gema, una carta que lleve este sello obtiene 1 de poder, hasta un máximo de 5.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "Estimulación", Language.Spanish);
            RegisterAbility("Stimulation", "Estimulación");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "Al final de cada turno, una carta que lleve este sello obtiene 1 de poder, hasta un máximo de 4.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "Estimulación de salud", Language.Spanish);
            RegisterAbility("Stimulation (Health)", "Estimulación de salud");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "Al final de cada turno, una carta que lleve este sello obtiene 2 de salud, hasta un máximo de 10.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "Robo mortal", Language.Spanish);
            RegisterAbility("Dead Draw", "Robo mortal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "Cuando muere una carta que no sea de gema, roba una carta de tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Corazón de esmeralda", Language.Spanish);
            RegisterAbility("Emerald Heart", "Corazón de esmeralda");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "Cuando muere una carta que lleve este sello, crea un Mox esmeralda en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Pegajoso", Language.Spanish);
            RegisterAbility("Gooey", "Pegajoso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "Cuando una carta que lleve este sello recibe un golpe, el atacante pierde 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "Gemnasia mental", Language.Spanish);
            RegisterAbility("Mental Gemnastics", "Gemnasia mental");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "Cuando se juega una carta que lleve este sello, roba de tu mazo tantas cartas como gemas haya en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "Saqueador", Language.Spanish);
            RegisterAbility("Loot", "Saqueador");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "Cuando una carta que lleve este sello inflige daño directo, roba de tu mazo tantas cartas como daño haya infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "Robo de vida", Language.Spanish);
            RegisterAbility("Life Steal", "Robo de vida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "Cuando una carta que lleve este sello inflige daño directo, su propietario recupera una cantidad de salud igual al daño infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "Golpe de retroceso", Language.Spanish);
            RegisterAbility("Knockback Hit", "Golpe de retroceso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "Cuando una carta que lleve este sello golpea a una carta rival, esta es empujada en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "Empalamiento", Language.Spanish);
            RegisterAbility("Impaled", "Empalamiento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "Cuando muere una carta que lleve este sello, crea una Lanza en su lugar. Una Lanza tiene Espinas afiladas, 0 de poder y 3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "Mox magno", Language.Spanish);
            RegisterAbility("Magnus Mox", "Mox magno");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "Mientras una carta que lleve este sello esté en el tablero, proporciona una gema naranja, una azul y una verde a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "Resurrección", Language.Spanish);
            RegisterAbility("Resurrection", "Resurrección");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "Cuando muere una carta que no sea de gema, la carta muerta vuelve a la vida, pero la carta que lleva este sello pierde 3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "Nuevas tiradas", Language.Spanish);
            RegisterAbility("Rerolls", "Nuevas tiradas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "Al final de cada turno, el poder base de una carta que lleve este sello se fija en un valor aleatorio entre 0 y 3.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "Trampa de acero", Language.Spanish);
            RegisterAbility("Steel Trap", "Trampa de acero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "Cuando muere una carta que lleve este sello, la carta opuesta también muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "Escudo de gemas", Language.Spanish);
            RegisterAbility("Gem Shield", "Escudo de gemas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "Cuando se juega una carta que lleve este sello, todas las gemas del tablero obtienen un escudo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "Trabajo de revestimiento", Language.Spanish);
            RegisterAbility("Plating Work", "Trabajo de revestimiento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "Mientras una carta que lleve este sello esté en el tablero, todas las gemas de tu lado del tablero obtienen el sello Espinas afiladas y 2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Titiritero", Language.Spanish);
            RegisterAbility("Animator", "Titiritero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "Mientras una carta que lleve este sello esté en el tablero, todas las cartas que no sean mox con 0 de poder obtienen 2 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Absorbedor de gemas", Language.Spanish);
            RegisterAbility("Gem Absorber", "Absorbedor de gemas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "Cuando se juega una carta que lleve este sello, todas las gemas de tu lado del tablero mueren. Por cada gema absorbida, esta carta obtiene 1 de poder y 2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Inmersión", Language.Spanish);
            RegisterAbility("Submerge", "Inmersión");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "Al final del turno, una carta que lleve este sello se sumerge. Cuando vuelve a la superficie, se convierte en una carta Tentáculo aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "Familiar", Language.Spanish);
            RegisterAbility("Familiar", "Familiar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "Una carta que lleve este sello muere si no hay cartas que no sean de gema en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "Desvanecimiento", Language.Spanish);
            RegisterAbility("Fading", "Desvanecimiento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "Una carta que lleve este sello muere al final del turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "Metamorfosis", Language.Spanish);
            RegisterAbility("Morph", "Metamorfosis");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "Cuando se juega una carta que lleve este sello, imita a la carta opuesta. Si no hay ninguna carta enfrente, muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "Multiplicación matricial", Language.Spanish);
            RegisterAbility("Multiplication", "Multiplicación matricial");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "Cuando se juega una carta que lleve este sello, roba otra copia de esta carta con un coste de gemas diferente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "Ciclo de mox", Language.Spanish);
            RegisterAbility("Mox Cycle", "Ciclo de mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "Al final de cada turno, todos los mox del tablero cambian cíclicamente a otros tipos de gema.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "Rastro de mox", Language.Spanish);
            RegisterAbility("Mox Strafe", "Rastro de mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "Al final del turno, esta carta se mueve en la dirección indicada en el sello y deja un mox atrás.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Purismo", Language.Spanish);
            RegisterAbility("Purist", "Purismo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "Cualquier carta directamente opuesta a esta pierde todos sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "Cervecería", Language.Spanish);
            RegisterAbility("Brewery", "Cervecería");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "Al final de cada turno, robas automáticamente una carta mox de tu mazo secundario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Prender fuego", Language.Spanish);
            RegisterAbility("Ignite", "Prender fuego");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "Cuando se juega una carta que lleve este sello, cada espacio rival vacío se llena de llamas mágicas. Una Llama mágica es una carta 0/1 con Molesto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "Proyección estelar", Language.Spanish);
            RegisterAbility("Projection", "Proyección estelar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "Cuando una carta que lleve este sello recibe un golpe, se mueve y deja atrás una proyección astral de sí misma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "Libro de hechizos", Language.Spanish);
            RegisterAbility("Spell Book", "Libro de hechizos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "Cuando se juega una carta que lleve este sello, roba una carta de hechizo aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "Erudito de hechizos", Language.Spanish);
            RegisterAbility("Scholar", "Erudito de hechizos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "Cuando se juega una carta que lleve este sello, roba al azar uno de los libros de Azurde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "Toque de Midas", Language.Spanish);
            RegisterAbility("Midas' Touch", "Toque de Midas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "Cuando una carta que lleve este sello ataca a otra carta, la carta atacada pierde todo su poder y se convierte en oro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "Cuerpo de oro", Language.Spanish);
            RegisterAbility("Made of Gold", "Cuerpo de oro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "Cuando muere una carta que lleve este sello, quien la mate obtiene 2 cristales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "Runas de invocación", Language.Spanish);
            RegisterAbility("Summon Runes", "Runas de invocación");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "Cuando se juega una carta que lleve este sello, invoca dos runas a su lado. Una Runa tiene 0 de poder, 1 de salud y Detonador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "Hechizo de salud", Language.Spanish);
            RegisterAbility("Spell of Health", "Hechizo de salud");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "Cuando se juega un hechizo que lleve este sello, todas las cartas de tu lado del tablero obtienen +2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "Hechizo de ataque", Language.Spanish);
            RegisterAbility("Spell of Attack", "Hechizo de ataque");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "Cuando se juega un hechizo que lleve este sello, todas las cartas de tu lado del tablero obtienen +1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "Hechizo de escarcha", Language.Spanish);
            RegisterAbility("Frost Spell", "Hechizo de escarcha");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "Cuando se juega un hechizo que lleve este sello, el poder de todas las cartas del rival se fija en 0, pero obtienen +2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "Hechizo de viento", Language.Spanish);
            RegisterAbility("Spell of Wind", "Hechizo de viento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "Cuando se juega un hechizo que lleve este sello, todas las cartas de tu lado del tablero obtienen Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "Alboroto horario", Language.Spanish);
            RegisterAbility("Ruckus", "Alboroto horario");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "Cuando se juega una carta que lleve este sello, todas las cartas del tablero se mueven en sentido horario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "Hechizo de agua", Language.Spanish);
            RegisterAbility("Spell of Water", "Hechizo de agua");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "Cuando se juega un hechizo que lleve este sello, se borran los sellos de todas las cartas del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "Hechizo de llama", Language.Spanish);
            RegisterAbility("Spell of Flame", "Hechizo de llama");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "Elige un lado del tablero. Todas las cartas de ese lado pierden 2 de salud sin morir y obtienen 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "Incendiar", Language.Spanish);
            RegisterAbility("Set Ablaze", "Incendiar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "Todas las cartas del lado opuesto pierden 2 de salud sin morir y obtienen 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "Hechizo de un solo uso", Language.Spanish);
            RegisterAbility("One Time Spell", "Hechizo de un solo uso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "Al terminar el turno, un hechizo que lleve este sello muere y se retira de tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Vasija de la codicia", Language.Spanish);
            RegisterAbility("Vase of Greed", "Vasija de la codicia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "Cuando se juega un hechizo que lleve este sello, descarta tu mano actual y después roba 4 cartas nuevas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Gnomificación", Language.Spanish);
            RegisterAbility("Gnomification", "Gnomificación");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "Elige un espacio donde invocar una carta Gnomo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Maldito", Language.Spanish);
            RegisterAbility("Cursed", "Maldito");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "Cuando se juega un hechizo que lleve este sello, muere inmediatamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "Inspiración", Language.Spanish);
            RegisterAbility("Inspiration", "Inspiración");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "Elige una carta para darle Aéreo + Saqueador durante 1 turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Cálculo infinitesimal", Language.Spanish);
            RegisterAbility("Calculus", "Cálculo infinitesimal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "Elige una carta para intercambiar sus estadísticas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Furia", Language.Spanish);
            RegisterAbility("Rage", "Furia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "Elige una carta para matarla. El rival de esa carta recibe un daño igual a la salud que tenía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Bola de fuego", Language.Spanish);
            RegisterAbility("Fireball", "Bola de fuego");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "Elige una carta para que reciba 2 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "Toque gélido", Language.Spanish);
            RegisterAbility("Cold to the Touch", "Toque gélido");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "Cuando una carta que lleve este sello ataca a otra carta, esta pierde 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "Congelado", Language.Spanish);
            RegisterAbility("Frozen", "Congelado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "Al final de cada turno, esta carta pierde su salud congelada. Cuando se agota toda la salud congelada, o si esta carta recibe un golpe, se descongela.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "Tracción potente", Language.Spanish);
            RegisterAbility("Strong Pull", "Tracción potente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "Todas las cartas rivales tenderán a golpear a esta carta en lugar de a otra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "Desplazamiento", Language.Spanish);
            RegisterAbility("Displacement", "Desplazamiento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "Cuando se roba una carta que lleve este sello, se añade otra copia de esta carta en una posición aleatoria de tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "Ajuste de cuentas de gemas", Language.Spanish);
            RegisterAbility("Gem Reckoning", "Ajuste de cuentas de gemas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "Al final de cada turno, si el propietario de esta carta no controla ninguna gema, se descarta la carta más a la izquierda de tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "Poder de mox", Language.Spanish);
            RegisterAbility("Mox Power", "Poder de mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "El valor representado por este sello es igual al número de cartas mox que el propietario tenga en su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "Salud de mox", Language.Spanish);
            RegisterAbility("Mox Health", "Salud de mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "El valor representado por este sello es igual al número de cartas mox que el propietario tenga en su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "Proximidad de la vela", Language.Spanish);
            RegisterAbility("Candle Proximity", "Proximidad de la vela");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "El valor representado por este sello depende de lo cerca que esté esta carta de la vela de la mesa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "Poder homicida", Language.Spanish);
            RegisterAbility("Murder Power", "Poder homicida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "El valor representado por este sello es igual al poder total en el lado rival del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "El valor representado por este sello es igual a la mitad del poder total de tu lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "Poder de hechizos", Language.Spanish);
            RegisterAbility("Spell Power", "Poder de hechizos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "El valor representado por este sello es igual al número total de hechizos jugados durante esta mazmorra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "El valor representado por este sello es igual al número total de hechizos jugados durante el combate.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "Poder de contrabatería", Language.Spanish);
            RegisterAbility("Counterbattery Power", "Poder de contrabatería");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "El valor representado por este sello es igual al daño que has recibido en este combate, dividido entre dos.", Language.Spanish);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, SpanishLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "mox", Language.Spanish);
            RegisterCard("Mox", "mox", "its a me moxio", "¡Soy yo, Moxio!");
            RegisterCard("Ruby Mox", "Mox rubí", "its a me moxio", "¡Soy yo, Moxio!");
            RegisterCard("Emerald Mox", "Mox esmeralda", "its a me moxio", "¡Soy yo, Moxio!");
            RegisterCard("Sapphire Mox", "Mox zafiro", "its a me moxio", "¡Soy yo, Moxio!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its a me moxio", "¡Soy yo, Moxio!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear", "Lanza", Language.Spanish);
            RegisterCard("Spear", "Lanza", "ayo", "ey");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ayo", "ey", Language.Spanish);
            RegisterCard("Mage Pupil", "Maga estudiante", "Though weak, it can always be useful in the right situation.", "Aunque débil, siempre puede ser útil en la situación adecuada.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though weak, it can always be useful in the right situation.", "Aunque débil, siempre puede ser útil en la situación adecuada.", Language.Spanish);
            RegisterCard("Junior Sage", "Sabio júnior", "Although simple, it can prove itself to be useful.", "Aunque simple, puede demostrar su utilidad.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although simple, it can prove itself to be useful.", "Aunque simple, puede demostrar su utilidad.", Language.Spanish);
            RegisterCard("Muscle Mage", "Mago musculoso", "An abomination of muscles, developed from drinking too many potions of the alchemist..", "Una abominación de músculos, desarrollada por beber demasiadas pociones del alquimista...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination of muscles, developed from drinking too many potions of the alchemist..", "Una abominación de músculos, desarrollada por beber demasiadas pociones del alquimista...", Language.Spanish);
            RegisterCard("Green Mage", "Mago verde", "It draws its power from the mana of the mox on the board.", "Obtiene su poder del maná de los mox del tablero.");
