            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imprisoned Tyrant", "Tirano encarcelado", Language.Spanish);
            RegisterCard("Imprisoned Tyrant", "Tirano encarcelado", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "Mago de matrices", Language.Spanish);
            RegisterCard("Multiplication mage", "Mago de matrices", "This cycle can go on forever..", "Este ciclo puede continuar para siempre...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "Este ciclo puede continuar para siempre...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "Mago invisible", Language.Spanish);
            RegisterCard("Invisible mage", "Mago invisible", "It drank the wrong potion and ended up invisible. How clumsy.", "Bebió la poción equivocada y acabó invisible. Qué torpe.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "Bebió la poción equivocada y acabó invisible. Qué torpe.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "Sabio de cristal", Language.Spanish);
            RegisterCard("Crystal Sage", "Sabio de cristal", "A young scholar, profoundly studying mana crystals.", "Un joven erudito que estudia a fondo los cristales de maná.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "Un joven erudito que estudia a fondo los cristales de maná.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "Guardián de las gemas", Language.Spanish);
            RegisterCard("Gem Guardian", "Guardián de las gemas", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "Lo contrario del Detonador de gemas: este busca proteger a todos los mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "Lo contrario del Detonador de gemas: este busca proteger a todos los mox.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "Asesino con gemas", Language.Spanish);
            RegisterCard("Gembound Ripper", "Asesino con gemas", "It is unstable, but such is the price for unending power.", "Es inestable, pero ese es el precio de un poder sin fin.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "Es inestable, pero ese es el precio de un poder sin fin.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Devorador de gemas", Language.Spanish);
            RegisterCard("Gem Absorber", "Devorador de gemas", "It seeks out to consume all mana within Mox to grow stronger.", "Busca consumir todo el maná de los mox para hacerse más fuerte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "Busca consumir todo el maná de los mox para hacerse más fuerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Esquelemago", Language.Spanish);
            RegisterCard("Skelemagus", "Esquelemago", "Great power for a few, fleeting moments..", "Un gran poder durante unos pocos y fugaces instantes...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "Un gran poder durante unos pocos y fugaces instantes...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "Sabio esquelético", Language.Spanish);
            RegisterCard("Skelesage", "Sabio esquelético", "One of my own Junior Sages, lost and revived.", "Uno de mis propios Sabios júnior, perdido y revivido.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "Uno de mis propios Sabios júnior, perdido y revivido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "Erudito inquieto", Language.Spanish);
            RegisterCard("Erratic Scholar", "Erudito inquieto", "A panicked scholar.. Always running from its problems..", "Un erudito en pánico... Siempre huyendo de sus problemas...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "Un erudito en pánico... Siempre huyendo de sus problemas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "Mago de mox", Language.Spanish);
            RegisterCard("Mox Mage", "Mago de mox", "A Mox disguised as a mage.. It's not going to fool anyone.", "Un mox disfrazado de mago... No va a engañar a nadie.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "Un mox disfrazado de mago... No va a engañar a nadie.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "Transmutador áureo", Language.Spanish);
            RegisterCard("Aurumtact", "Transmutador áureo", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Un erudito anciano, maldito por su codicia, que sepulta en oro puro todo lo que toca.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Un erudito anciano, maldito por su codicia, que sepulta en oro puro todo lo que toca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "Mox encadenado", Language.Spanish);
            RegisterCard("Chained Mox", "Mox encadenado", "A collection of 3 moxen, tangled together, combining their mana energy.", "Un conjunto de 3 mox enredados entre sí que combinan su energía de maná.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "Un conjunto de 3 mox enredados entre sí que combinan su energía de maná.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "Maux", Language.Spanish);
            RegisterCard("Maux", "Maux", "In all my years, I have NEVER seen an imitation cruder than this.", "En todos mis años, NUNCA he visto una imitación más burda.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "En todos mis años, NUNCA he visto una imitación más burda.", Language.Spanish);
            RegisterCard("Stim Mage", "Mago estimulado", "It strives to grow stronger, disregarding its own wellbeing..", "Se esfuerza por hacerse más fuerte sin preocuparse por su propio bienestar...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "Se esfuerza por hacerse más fuerte sin preocuparse por su propio bienestar...", Language.Spanish);
            RegisterCard("Gourmage", "Gourmaga", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Una maga glotona que devora los cadáveres de tus caídos para hacerse más fuerte... Asqueroso.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Una maga glotona que devora los cadáveres de tus caídos para hacerse más fuerte... Asqueroso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "Mago zoquete", Language.Spanish);
            RegisterCard("Dunce", "Mago zoquete", "This one can never seem to hit its target..", "Este nunca parece dar en el blanco...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "Este nunca parece dar en el blanco...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "Grootslang", Language.Spanish);
            RegisterCard("Grootslang", "Grootslang", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "El simple roce de sus colmillos basta para matar a cualquier criatura, sin importar su tamaño.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "El simple roce de sus colmillos basta para matar a cualquier criatura, sin importar su tamaño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "Ratón de biblioteca", Language.Spanish);
            RegisterCard("Bookworm", "Ratón de biblioteca", "A rare kind of insect that absorbs knowledge out of books.", "Un tipo raro de insecto que absorbe el conocimiento de los libros.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "Un tipo raro de insecto que absorbe el conocimiento de los libros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Alquimista", Language.Spanish);
            RegisterCard("Alchemist", "Alquimista", "A supporting one. It brews potions to empower your cards.", "Una unidad de apoyo. Prepara pociones para potenciar tus cartas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "Una unidad de apoyo. Prepara pociones para potenciar tus cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "Mago de las campanas", Language.Spanish);
            RegisterCard("Chime Mage", "Mago de las campanas", "Its chime can prove to be quite annoying..", "Su tintineo puede resultar bastante molesto...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "Su tintineo puede resultar bastante molesto...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "Resucitado", Language.Spanish);
            RegisterCard("Revivor", "Resucitado", "It brings a mage back from the dead, at the cost of its own health.", "Devuelve a un mago de entre los muertos a costa de su propia salud.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "Devuelve a un mago de entre los muertos a costa de su propia salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "Mago de las runas", Language.Spanish);
            RegisterCard("Rune Mage", "Mago de las runas", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Cuando lo invocan, conjura runas explosivas a su lado. No es buena idea, debo decir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Cuando lo invocan, conjura runas explosivas a su lado. No es buena idea, debo decir.", Language.Spanish);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "Así que llega.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "Así que llega.", Language.Spanish);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "Preví su llegada.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "Preví su llegada.", Language.Spanish);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "Por fin está aquí.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "Por fin está aquí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "Sabio francotirador", Language.Spanish);
            RegisterCard("Sniper Sage", "Sabio francotirador", "A mage whose training allows it to cast spells from afar.", "Un mago cuyo entrenamiento le permite lanzar hechizos desde lejos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "Un mago cuyo entrenamiento le permite lanzar hechizos desde lejos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "Runa", Language.Spanish);
            RegisterCard("Rune", "Runa", "This is the last call, for alcohol.", "Esta es la última ronda de alcohol.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Esta es la última ronda de alcohol.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "Llama mágica", Language.Spanish);
            RegisterCard("Flame", "Llama mágica", "This is the last call, for alcohol.", "Esta es la última ronda de alcohol.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Esta es la última ronda de alcohol.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "Conejo", Language.Spanish);
            RegisterCard("Rabbit", "Conejo", "This is the last call, for alcohol.", "Esta es la última ronda de alcohol.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Esta es la última ronda de alcohol.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "Última ronda de priva.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "Última ronda de cerveza.", Language.Spanish);
            RegisterCard("Master Goranj", "Maestro Verdanja", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "El imponente Maestro Verdanja. No solo lanza magia temible, también posee una postura firme.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "El imponente Maestro Verdanja. No solo lanza magia temible, también posee una postura firme.", Language.Spanish);
            RegisterCard("Master Bleene", "Maestro Azurde", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "El abnegado Maestro Azurde. Te ayudará en los momentos de mayor necesidad... A costa de su propia capacidad para defenderse. Admirable.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "El abnegado Maestro Azurde. Te ayudará en los momentos de mayor necesidad... A costa de su propia capacidad para defenderse. Admirable.", Language.Spanish);
            RegisterCard("Master Orlu", "Maestra Naranzul", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "La gran Maestra Naranzul surca el cielo con alas pálidas, ataca desde arriba y atrae cartas desde abajo...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "La gran Maestra Naranzul surca el cielo con alas pálidas, ataca desde arriba y atrae cartas desde abajo...", Language.Spanish);
            RegisterCard("Master Magnus", "Maestro supremo", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Me llamo... ¡Shake-Zula! ¡El rey del micro! ¡El de la vieja escuela! ¿Quieres un viaje? Te lo traigo yo...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Me llamo... ¡Shake-Zula! ¡El rey del micro! ¡El de la vieja escuela! ¿Quieres un viaje? Te lo traigo yo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "Maestro supremo", Language.Spanish);
            RegisterCard("Master Magnus", "Maestro supremo", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, sí, estoy en lo más alto, te sacudo como un poli. ¡Meatwad, te toca con tu toc toc!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Frylock, sí, estoy en lo más alto, te sacudo como un poli. ¡Meatwad, te toca con tu toc toc!", Language.Spanish);
            RegisterCard("Master Magnus", "Maestro supremo", "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad consigue la pasta, ya ves. Meatwad conquista a las chicas, colega. ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "Meatwad consigue la pasta, ya ves. Meatwad conquista a las chicas, colega. ", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "Fénix", Language.Spanish);
            RegisterCard("Phoenix", "Fénix", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Un ave majestuosa que, según se dice, fue cómplice de la Maestra Naranzul...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Un ave majestuosa que, según se dice, fue cómplice de la Maestra Naranzul...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "Sabueso de Azurde", Language.Spanish);
            RegisterCard("Bleenehound", "Sabueso de Azurde", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Un canino leal que, según se dice, fue el fiel compañero del Maestro Azurde.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Un canino leal que, según se dice, fue el fiel compañero del Maestro Azurde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemy 101", "Introducción a la alquimia", Language.Spanish);
