    public class CustomSideDeckMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for CustomSideDeck Mod");
            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How the mod should handle side deck card backs for side decks that don't add their own custom card back. If enabled, automatically generates a unique card back based on the side deck's main card's portrait. Otherwise, the default squirrel back will be used.", "Determina cómo gestiona el mod los reversos de los mazos secundarios que no incluyen uno personalizado. Si se activa, genera automáticamente un reverso único a partir del retrato de la carta principal del mazo secundario. De lo contrario, se usa el reverso de ardilla predeterminado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether to automatically add an Aqua version of all custom side decks. Buggy, not recommended.", "Añade automáticamente una versión acuática de todos los mazos secundarios personalizados. Tiene errores; no se recomienda.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether or not Aquasquirrels and custom side decks marked as `CSDIsAqua` should be shown as options even when the Squirrel Fish challenge isn't on.", "Muestra como opciones las acuardillas y los mazos secundarios personalizados marcados como `CSDIsAqua` incluso cuando el desafío Peces ardilla está desactivado.", Language.Spanish);

            // ShowText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Side Deck", "Elegir mazo secundario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Configure Side Deck", "Configurar mazo secundario", Language.Spanish);
            for (int point = 0; point <= 100; point++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>" + point.ToString() + "</color> Challenge Points", "MAZO SECUNDARIO ACTUAL: <color=#eef4c6>" + point.ToString() + "</color> " + (point == 1 ? "punto de desafío" : "puntos de desafío"), Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>+" + point.ToString() + "</color> Challenge Points", "MAZO SECUNDARIO ACTUAL: <color=#eef4c6>+" + point.ToString() + "</color> " + (point == 1 ? "punto de desafío" : "puntos de desafío"), Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Challenge Points: <color=#eef4c6>" + point.ToString() + "</color>", "Total de puntos de desafío: <color=#eef4c6>" + point.ToString() + "</color>", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\nContains {0} cards", "\nContiene {0} cartas", Language.Spanish); // todo

        }
    }

    public class PackManagementMod
    {

        public static Dictionary<string, string> EncountersTitle = new();
        public static Dictionary<string, KeyValuePair<string, string>> EncountersDescription = new();

        public static void RegisterEncounter(string en, string zh, string endes, string zhdes)
        {
            EncountersTitle.Add(en, zh);
            EncountersDescription.Add(en, new KeyValuePair<string, string>(endes, zhdes));
        }
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PackManagement Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Card Packs", "Elegir paquetes de cartas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Encounter Packs", "Elegir paquetes de encuentros", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Active Packs", "Elegir paquetes activos", Language.Spanish);

            // Packs
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Beastly Card Expansion Pack", "Inscryption: expansión de cartas bestiales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "La colección original de cartas de la cabaña de Leshy. Con lobos, mantis y alguna que otra cucaracha.", Language.Spanish);
            RegisterEncounter("Inscryption: Beastly Card Expansion Pack", "Inscryption: expansión de cartas bestiales", "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "La colección original de cartas de la cabaña de Leshy. Con lobos, mantis y alguna que otra cucaracha.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Techno Card Expansion Pack", "Inscryption: expansión de cartas tecnológicas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of robotic cards, exclusively using the energy mechanic.", "La colección original de cartas robóticas, que usa exclusivamente la mecánica de energía.", Language.Spanish);
            RegisterEncounter("Inscryption: Techno Card Expansion Pack", "Inscryption: expansión de cartas tecnológicas", "The original set of robotic cards, exclusively using the energy mechanic.", "La colección original de cartas robóticas, que usa exclusivamente la mecánica de energía.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Undead Card Expansion Pack", "Inscryption: expansión de cartas no muertas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrimoraMod", "Mod Grimora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Impulsadas por los huesos de los muertos, estas cartas regresan de la tumba para luchar por ti.", Language.Spanish);
            RegisterEncounter("Inscryption: Undead Card Expansion Pack", "Inscryption: expansión de cartas no muertas", "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Impulsadas por los huesos de los muertos, estas cartas regresan de la tumba para luchar por ti.");
            RegisterEncounter("GrimoraMod", "Mod Grimora", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Magickal Card Expansion Pack", "Inscryption: expansión de cartas mágicas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Domina el poder de los mox para invocar aprendices y librar los duelos más honorables.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels. (Magnificus Mod Cards)", "Domina el poder de los mox para invocar aprendices y librar los duelos más honorables. (Cartas del Mod Magnificus)", Language.Spanish);
            RegisterEncounter("Inscryption: Magickal Card Expansion Pack", "Inscryption: expansión de cartas mágicas", "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Domina el poder de los mox para invocar aprendices y librar los duelos más honorables.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miscellaneous Community Cards", "Cartas variadas de la comunidad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unusual, unsorted, and unruly cards that have been added by mods but not properly sorted into packs.", "Cartas inusuales, sin clasificar y rebeldes, añadidas por mods sin estar bien organizadas en paquetes.", Language.Spanish);
            RegisterEncounter("Miscellaneous Community Cards", "Cartas variadas de la comunidad", "The unusual, unsorted, and unruly cards that have been added by mods but not properly sorted into packs.", "Cartas inusuales, sin clasificar y rebeldes, añadidas por mods sin estar bien organizadas en paquetes.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Beastly Encounters", "Inscryption: encuentros bestiales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of [summary] that Leshy has carefully curated for the ideal gaming experience.", "La selección original que Leshy ha preparado cuidadosamente para una experiencia de juego ideal: [summary].", Language.Spanish);
            RegisterEncounter("Inscryption: Beastly Encounters", "Inscryption: encuentros bestiales", "The original set of [summary] that Leshy has carefully curated for the ideal gaming experience.", "La selección original que Leshy ha preparado cuidadosamente para una experiencia de juego ideal: [summary].");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unsorted Regions and Encounters", "Regiones y encuentros sin clasificar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These [summary] have been added by mods but not properly sorted into packs.", "Estos contenidos se han añadido mediante mods, pero no están bien organizados en paquetes: [summary].", Language.Spanish);
            RegisterEncounter("Unsorted Regions and Encounters", "Regiones y encuentros sin clasificar", "These [summary] have been added by mods but not properly sorted into packs.", "Estos contenidos se han añadido mediante mods, pero no están bien organizados en paquetes: [summary].");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eri Card Expansion", "Expansión de cartas de Eri", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From the [randomcard] to the [randomcard], this pack contains [count] wild animals that feel right at home in the wild world of Inscryption.", "Desde «[randomcard]» hasta «[randomcard]», este paquete contiene [count] animales salvajes que se sienten como en casa en el mundo salvaje de Inscryption.", Language.Spanish); // todo
            RegisterEncounter("Eri Card Expansion", "Expansión de cartas de Eri", "From the [randomcard] to the [randomcard], this pack contains [count] wild animals that feel right at home in the wild world of Inscryption.", "Desde «[randomcard]» hasta «[randomcard]», este paquete contiene [count] animales salvajes que se sienten como en casa en el mundo salvaje de Inscryption.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ara's Card Expansion", "Expansión de cartas de Ara", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This expansion contains [count] cards that offer a unique twist on Inscryption's core gameplay. Cards like [randomcard] and [randomcard] will give a little additional spice to your next run.", "Esta expansión contiene [count] cartas que dan un giro original a las mecánicas fundamentales de Inscryption. Cartas como «[randomcard]» y «[randomcard]» le darán un poco de sabor a tu próxima partida.", Language.Spanish); // todo
            RegisterEncounter("Ara's Card Expansion", "Expansión de cartas de Ara", "This expansion contains [count] cards that offer a unique twist on Inscryption's core gameplay. Cards like [randomcard] and [randomcard] will give a little additional spice to your next run.", "Esta expansión contiene [count] cartas que dan un giro original a las mecánicas fundamentales de Inscryption. Cartas como «[randomcard]» y «[randomcard]» le darán un poco de sabor a tu próxima partida.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hallownest Expansion", "Expansión de Hallownest", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large expansion containing [count] creatures from Hollow Knight. Up from peaceful Crossroads, down into the Abyss.", "Una gran expansión con [count] criaturas de Hollow Knight. Desde los tranquilos Cruces Olvidados hasta las profundidades del Abismo.", Language.Spanish); // todo
            RegisterEncounter("Hallownest Expansion", "Expansión de Hallownest", "A large expansion containing [count] creatures from Hollow Knight. Up from peaceful Crossroads, down into the Abyss.", "Una gran expansión con [count] criaturas de Hollow Knight. Desde los tranquilos Cruces Olvidados hasta las profundidades del Abismo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitty's Regions", "Regiones de Bitty", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitty's Regions adds [summary].", "Novedades de Regiones de Bitty: [summary].", Language.Spanish);
            RegisterEncounter("Bitty's Regions", "Regiones de Bitty", "Bitty's Regions adds [summary].", "Novedades de Regiones de Bitty: [summary].");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Region Expansion", "Expansión de la región del vacío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This region expansion from Void adds [summary].", "Novedades de esta expansión de regiones creada por Void: [summary].", Language.Spanish);
            RegisterEncounter("Void Region Expansion", "Expansión de la región del vacío", "This region expansion from Void adds [summary].", "Novedades de esta expansión de regiones creada por Void: [summary].");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eri's Card Pack Encounters", "Encuentros del paquete de cartas de Eri", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This expansion adds [summary] featuring cards from Eri's Card Expansion.", "Esta expansión añade contenido con cartas de la Expansión de cartas de Eri: [summary].", Language.Spanish);
            RegisterEncounter("Eri's Card Pack Encounters", "Encuentros del paquete de cartas de Eri", "This expansion adds [summary] featuring cards from Eri's Card Expansion.", "Esta expansión añade contenido con cartas de la Expansión de cartas de Eri: [summary].");
            RegisterEncounter("Original Undead Card", "Cartas no muertas originales", "The cards for the Undead Tribe are in the original game.(ACT2)", "Las cartas de la tribu de los no muertos del juego original. (ACTO 2)"); // UndeadTempleINKCM
            RegisterEncounter("NonOriginal Undead Card", "Paquete de cartas no muertas NonOriginal", "The expansion cards for the Undead Tribe are not in the original game.", "Las cartas de expansión de la tribu de los no muertos que no están en el juego original."); // UndeadTempleINKCM
            RegisterEncounter("Wilderness Legend", "Leyenda salvaje", "Add some simple cards based on the original imprint.", "Añade algunas cartas sencillas basadas en los sellos originales."); // WildernessLegend
            RegisterEncounter("DLC_Fairy_Tale", "DLC Leyendas salvajes: cuentos de hadas", "Added some cards based on myths, legends, and fictional elements.", "Añade algunas cartas basadas en mitos, leyendas y elementos ficticios."); // WildernessLegend
            RegisterEncounter("P03KCM", "P03KCM", "", "");
            RegisterEncounter("Kaycee's P03 Expansion Pack #1", "Paquete de expansión P03 de Kaycee n.º 1", "The first expansion pack from the developers of 'P03 in Kaycees Mod' adds [count] new cards across all four regions of Botopia.", "El primer paquete de expansión de los creadores de «P03 en el Mod de Kaycee» añade [count] cartas nuevas repartidas por las cuatro regiones de Botopía.");  // P03KCM
            RegisterEncounter("Kaycee's P03 Expansion Pack #2", "Paquete de expansión P03 de Kaycee n.º 2", "The second official expansion pack, with [count] firey new cards that command an explosive reaction!", "¡El segundo paquete de expansión oficial trae [count] cartas nuevas y ardientes que provocarán una reacción explosiva!");  // P03KCM
            RegisterEncounter("Inscryption: Rogue Bots of Botopia", "Inscryption: Robots rebeldes de Botopía", "Botopia has become overrun with rogue bots! These [count] encounters have been rebalanced for Kaycee's Mod.", "¡Botopía está infestada de robots rebeldes! Estos [count] encuentros se han reequilibrado para el Mod de Kaycee.");  // P03KCM
            RegisterEncounter("Kaycee's P03 Encounter Expansion #1", "Expansión de encuentros P03 de Kaycee n.º 1", "[count] additional encounters that feature cards from the first official P03 expansion pack.", "[count] encuentros adicionales con cartas del primer paquete de expansión oficial de P03.");  // P03KCM
            RegisterEncounter("Kaycee's P03 Encounter Expansion #2", "Expansión de encuentros P03 de Kaycee n.º 2", "[count] additional encounters that feature cards from the second official P03 expansion pack.", "[count] encuentros adicionales con cartas del segundo paquete de expansión oficial de P03.");  // P03KCM
            RegisterEncounter("Kaycee's P03 Expansion Pack #3", "Paquete de expansión P03 de Kaycee n.º 3", "They said it would never happen, but it's here! The third official expansion pack breaks all of the rules, with [count] new cards that bring bones, blood, and gems to Botopia!", "¡Decían que nunca ocurriría, pero aquí está! ¡El tercer paquete de expansión oficial rompe todas las reglas con [count] cartas nuevas que traen huesos, sangre y gemas a Botopía!");  // P03KCM EXP3
            RegisterEncounter("Kaycee's P03 Encounter Expansion #3", "Expansión de encuentros P03 de Kaycee n.º 3", "[count] additional encounters that feature cards from the third official P03 expansion pack.", "[count] encuentros adicionales con cartas del tercer paquete de expansión oficial de P03.");  // P03KCM EXP3
            RegisterEncounter("Aga's Magnificus Expansion", "Expansión de Magnificus de Aga", "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "Una expansión no oficial del Mod Magnificus con [count] magos únicos y llenos de color");  // AgasMagnificusExpansion
            RegisterEncounter("Smughtro's MagMod Expansion", "Expansión MagMod de Smughtro", "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "Añade al Mod Magnificus 19 cartas comunes, 7 cartas raras, 7 hechizos y 6 cartas de ficha.");  // MagModExpansion
            RegisterEncounter("Revenant Mod Card Pack", "Paquete de cartas del mod Revenant", "This card pack consists of mainly cards that return to the player in a variety of ways.", "Este paquete se compone principalmente de cartas que vuelven al jugador de diversas maneras.");  // RevenantMod
