    public class MagicExpansionMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagicExpansion Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry Witch", "Bruja iracunda", Language.Spanish);
            MagnificusMod.RegisterCard("Angry Witch", "Bruja iracunda", "The witch in charge of anger will ignite flames in the opposite battlefield.", "La bruja que domina la ira prende fuego al campo enemigo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "La bruja que domina la ira prende fuego al campo enemigo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "Bruja soberbia", Language.Spanish);
            MagnificusMod.RegisterCard("Arrogant Witch", "Bruja soberbia", "The witch who mastered the power of arrogance appeared with the demon.", "La bruja que domina el poder de la soberbia aparece acompañada de un demonio.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "La bruja que domina el poder de la soberbia aparece acompañada de un demonio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "Mago del café", Language.Spanish);
            MagnificusMod.RegisterCard("Coffee Mage", "Mago del café", "Mages who love coffee use gems to regulate their breath.", "Los magos amantes del café usan gemas para regular la respiración.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "Los magos amantes del café usan gemas para regular la respiración.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "Pollo mágico gracioso", Language.Spanish);
            MagnificusMod.RegisterCard("Funny MagiChiking", "Pollo mágico gracioso", "A smelly Rooster who has learned magic.", "Un gallo apestoso que ha aprendido magia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "Un gallo apestoso que ha aprendido magia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "Bruja glotona", Language.Spanish);
            MagnificusMod.RegisterCard("Gluttonous Witch", "Bruja glotona", "The witch in charge of gluttony committed a terrible sin.", "La bruja que domina la gula ha cometido un pecado terrible.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "La bruja que domina la gula ha cometido un pecado terrible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "Bruja codiciosa", Language.Spanish);
            MagnificusMod.RegisterCard("Greedy Witch", "Bruja codiciosa", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "La bruja que domina el poder de la codicia, por desgracia, solo nos aporta valor después de morir.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "La bruja que domina el poder de la codicia, por desgracia, solo nos aporta valor después de morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "Bruja ávida de saber", Language.Spanish);
            MagnificusMod.RegisterCard("Inquisitive Witch", "Bruja ávida de saber", "Nothing is more powerful than her curiosity.", "Nada es más poderoso que su curiosidad.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "Nada es más poderoso que su curiosidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "Bruja envidiosa", Language.Spanish);
            MagnificusMod.RegisterCard("Jealous Witch", "Bruja envidiosa", "The witch in charge of jealousy has powerful magic and power.", "La bruja que domina la envidia posee una magia y una fuerza formidables.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "La bruja que domina la envidia posee una magia y una fuerza formidables.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "Bruja perezosa", Language.Spanish);
            MagnificusMod.RegisterCard("Lazy Witch", "Bruja perezosa", "The witch in charge of the power of laziness is really a lazy guy.", "La bruja que domina el poder de la pereza es una auténtica holgazana.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "La bruja que domina el poder de la pereza es una auténtica holgazana.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "Bruja lujuriosa", Language.Spanish);
            MagnificusMod.RegisterCard("Lust Witch", "Bruja lujuriosa", "The witch in charge of lust, don't look into her eyes.", "La bruja que domina la lujuria… No la mires a los ojos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "La bruja que domina la lujuria… No la mires a los ojos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "Ciervo de nueve colores", Language.Spanish);
            MagnificusMod.RegisterCard("Nine Color Deer", "Ciervo de nueve colores", "The colorful nine color deer has precious value.", "El vistoso ciervo de nueve colores tiene un valor incalculable.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "El vistoso ciervo de nueve colores tiene un valor incalculable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "Pollo mágico apestoso", Language.Spanish);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "Pollo mágico apestoso", "Hatched by magic eggs.", "Nacido de un huevo mágico.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "Nacido de un huevo mágico.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "Maníaco de las bombas", Language.Spanish);
            MagnificusMod.RegisterCard("Bomb Maniac", "Maníaco de las bombas", "Even if it detonates itself, it never surrenders to others.", "Aunque tenga que hacerse estallar, jamás se rendirá.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "Aunque tenga que hacerse estallar, jamás se rendirá.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "Conde Conejo", Language.Spanish);
            MagnificusMod.RegisterCard("Earl Bunny", "Conde Conejo", "The versatile Earl Bunny, not everyone can comprehend this art.", "El polifacético Conde Conejo… No cualquiera comprende este arte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "El polifacético Conde Conejo… No cualquiera comprende este arte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "Dragón chino", Language.Spanish);
            MagnificusMod.RegisterCard("Chinese Loong", "Dragón chino", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Cuando el dragón se sumerge en el abismo, trae paz a los cuatro mares; cuando alza el vuelo, protege todas las cosas. Su viaje de miles de leguas anuncia la buena fortuna allá donde pasa.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Cuando el dragón se sumerge en el abismo, trae paz a los cuatro mares; cuando alza el vuelo, protege todas las cosas. Su viaje de miles de leguas anuncia la buena fortuna allá donde pasa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Mago del queso", Language.Spanish);
            MagnificusMod.RegisterCard("Cheese Wizard", "Mago del queso", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Un hechicero de buen humor y experto cocinero cuyo queso posee poderes mágicos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Un hechicero de buen humor y experto cocinero cuyo queso posee poderes mágicos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "Gólem de escarcha", Language.Spanish);
            MagnificusMod.RegisterCard("Frost Golem", "Gólem de escarcha", "Once on the field, there is a strong sense of oppression.", "En cuanto entra en el tablero, su presencia resulta abrumadora.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "En cuanto entra en el tablero, su presencia resulta abrumadora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Mago del béisbol", Language.Spanish);
            MagnificusMod.RegisterCard("Baseball Mage", "Mago del béisbol", "His soul is bound under sportswear and can never be liberated.", "Su alma está prisionera de la ropa deportiva y jamás podrá liberarse.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "Su alma está prisionera de la ropa deportiva y jamás podrá liberarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "Mago de asalto", Language.Spanish);
            MagnificusMod.RegisterCard("Raid Mage", "Mago de asalto", "You will understand how terrifying it is for a robber to master magic.", "Comprenderás lo aterrador que puede ser un bandido que domina la magia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "Comprenderás lo aterrador que puede ser un bandido que domina la magia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "Tortuga de jade", Language.Spanish);
            MagnificusMod.RegisterCard("Jade Turtle", "Tortuga de jade", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Una tortuga cubierta de esmeraldas de pies a cabeza… No puedo evitar asombrarme de que exista una pintura así.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Una tortuga cubierta de esmeraldas de pies a cabeza… No puedo evitar asombrarme de que exista una pintura así.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "Queso mágico", Language.Spanish);
            MagnificusMod.RegisterCard("Magic Cheese", "Queso mágico", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "Cuco escarlata", Language.Spanish);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "Cuco escarlata", "The success or failure of the angry magic bird often depends on its face.", "Con esta ave mágica enfadada, tu éxito o fracaso suele depender de su humor.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "Con esta ave mágica enfadada, tu éxito o fracaso suele depender de su humor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "Aprendiz lancero", Language.Spanish);
            MagnificusMod.RegisterCard("Spear Apprentice", "Aprendiz lancero", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Los aprendices de los magos lanceros… Los más sabios siempre se guardan un plan de reserva.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Los aprendices de los magos lanceros… Los más sabios siempre se guardan un plan de reserva.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "El Ojo de la oscuridad", Language.Spanish);
            MagnificusMod.RegisterCard("The Eye of Darkness", "El Ojo de la oscuridad", "This precious pearl was once the devil's eye.", "Esta perla preciosa fue en su día el ojo del diablo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "Esta perla preciosa fue en su día el ojo del diablo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "Hechizo del bosque", Language.Spanish);
            MagnificusMod.RegisterCard("Forest Spell", "Hechizo del bosque", "The forest spell obtained from Leshy can provide the most primitive defense.", "El hechizo del bosque obtenido de Leshy ofrece la forma más primitiva de defensa.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "El hechizo del bosque obtenido de Leshy ofrece la forma más primitiva de defensa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "Escudo mox", Language.Spanish);
            MagnificusMod.RegisterCard("MoxShield", "Escudo mox", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "La mera presencia de este escudo mágico engastado con gemas siempre transmite seguridad.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "La mera presencia de este escudo mágico engastado con gemas siempre transmite seguridad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "Tormenta nebular", Language.Spanish);
            MagnificusMod.RegisterCard("Nebula Storm", "Tormenta nebular", "This cruel storm can directly take away an enemy.", "Esta tormenta despiadada puede llevarse a un enemigo de inmediato.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "Esta tormenta despiadada puede llevarse a un enemigo de inmediato.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "Contrato de alma", Language.Spanish);
            MagnificusMod.RegisterCard("Soul Contract", "Contrato de alma", "Perhaps you need more card assistance, and a soul contract is a great choice.", "Quizá necesites la ayuda de más cartas. Un contrato de alma sería una gran elección.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "Quizá necesites la ayuda de más cartas. Un contrato de alma sería una gran elección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "Muro de los lamentos", Language.Spanish);
            MagnificusMod.RegisterCard("Wailing Wall", "Muro de los lamentos", "Such perseverance even moves the thorny walls to weep.", "Semejante perseverancia conmueve hasta a los muros de espinas y los hace llorar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "Semejante perseverancia conmueve hasta a los muros de espinas y los hace llorar.", Language.Spanish);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "Hora del café", Language.Spanish);
            MagnificusMod.RegisterAbility("Coffee Time", "Hora del café");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "La primera vez que [creature] recibe daño, obtiene 2 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "Muerte de la soberbia", Language.Spanish);
            MagnificusMod.RegisterAbility("Death of Arrogance", "Muerte de la soberbia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "Cuando [creature] muere, las cartas adyacentes obtienen 2 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "Muerte de la codicia", Language.Spanish);
            MagnificusMod.RegisterAbility("Death of Greed", "Muerte de la codicia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "Cuando [creature] muere, las cartas adyacentes obtienen 3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "Creación divina", Language.Spanish);
            MagnificusMod.RegisterAbility("God Made", "Creación divina");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "Cuando se juega [creature], se crea un Homúnculo en cada espacio vacío adyacente. El Homúnculo tiene: 1 de poder, 1 de salud, Familiar.", Language.Spanish);
            MagnificusMod.RegisterAbility("Fir Caller", "Llamada de los abetos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "Cuando [creature] muere, los espacios vacíos del lado de su propietario se llenan de Grandes abetos. El Gran abeto tiene: 0 de poder, 3 de salud, Salto poderoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "Sabor persistente", Language.Spanish);
            MagnificusMod.RegisterAbility("Lingering Taste", "Sabor persistente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "Cuando [creature] muere, las cartas adyacentes obtienen 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "Amor al queso", Language.Spanish);
            MagnificusMod.RegisterAbility("Love of Cheese", "Amor al queso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "Cuando se juega [creature], roba una carta Queso mágico. El Queso mágico tiene: 0 de poder, 2 de salud, Sabor persistente.", Language.Spanish);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "Expansión mágica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "¡Llegan las cartas del mundo fantástico! ¡Se añadirá más contenido en el futuro!", Language.Spanish);
        }
    }
