            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee", "Kaycee", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal", "Royal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Training Dummy", "Muñeco de entrenamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "Goo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pike Mage", "Mago lancero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonely Wizard", "Hechicero solitario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspector", "Inspectora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Melter", "Fundidora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dredger", "Dragador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prospector", "Buscador de oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angler", "Pescador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapper", "Trampero", Language.Spanish);

            // ShowUntilInput
            Dictionary<GemType, string> gemTypesEn = new Dictionary<GemType, string>
            {
                { GemType.Orange, "Naranja" },
                { GemType.Blue, "Azul" },
                { GemType.Green, "Verde" },
            };
            Dictionary<GemType, string> gemTypes = new Dictionary<GemType, string>
            {
                { GemType.Orange, "naranja" },
                { GemType.Blue, "azul" },
                { GemType.Green, "verde" },
            };
            foreach (var gemType in gemTypes.Keys)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have the two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "[c:] Gems needed to play that. Gain Gems by playing Mox cards.", "No tienes las dos gemas de color " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "[c:] necesarias para jugar esa carta. Juega cartas Mox para obtener gemas.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gem skeptic sigil prevents you from playing that gem.", "El sello Escéptico de gemas te impide jugar esa gema.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play that until you're 3 off dying.", "Solo puedes jugarla cuando estés a 3 de daño o menos de perder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You want to play that? Start losing.", "¿Quieres jugarla? Empieza a perder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play it, genius.", "No puedes jugarla, genio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot play that card with the scales in this state.", "No puedes jugar esa carta con la balanza en este estado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play that one.", "Esa no puedes jugarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid that one's forbidden, dear.", "Me temo que esa está prohibida, cariño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't allow you to play that card.", "No te permitiré jugar esa carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play a gem card while a creature with the Gem Skeptic sigil is on your side of the board!", "¡No puedes jugar cartas de gema mientras haya una criatura con el sello Escéptico de gemas en tu lado del tablero!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card cannot be played unless you are three or less damage from losing!", "¡Solo puedes jugar esta carta cuando estés a tres de daño o menos de perder!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card cannot be played.", "Esta carta no se puede jugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides...", "Bloqueado por ambos lados…", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absorber", "Absorbedor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a creature adjacent to [creature] is struck, [creature] will gain health equal to the amount of damage dealt.", "Si se golpea a una criatura adyacente a [creature], [creature] obtiene tanta salud como daño se haya infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack unless forced to attack by another effect.", "[creature] solo ataca si otro efecto la obliga a hacerlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Bearer", "Portador de abalorios", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it grants it's owner a random item.", "Cuando se juega [creature], su propietario obtiene un objeto aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] pulls out a random item.", "[creature] saca un objeto aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbait", "Cebo de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to return [creature] to your hand.", "Paga 1 de sangre para devolver [creature] a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonefed", "Alimentado con huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to heal [creature] for up to 3 health.", "Paga 2 huesos para que [creature] recupere hasta 3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Strike", "Golpe óseo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to deal 1 damage to the creature opposing [creature].", "Paga 2 huesos para infligir 1 de daño a la criatura que está frente a [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broodfeast", "Festín de cría", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 blood to create a copy of [creature] in your hand.", "Una vez por turno, paga 1 de sangre para crear una copia de [creature] en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnivore", "Carnívoro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 blood to increase the power of [creature] by 3.", "Paga 2 de sangre para aumentar en 3 el poder de [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Causality", "Causalidad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 currency to trigger a random effect.", "Paga 1 unidad de moneda para activar un efecto aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The universe seems in harmony already... nothing changes.", "El universo ya parece estar en armonía… Nada cambia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing happened...", "No ha pasado nada…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing? Huh, that's disappointing.", "¿Nada? Vaya, qué decepción.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power buff, lucky you...", "Una mejora de poder, qué suerte tienes…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health buff, could be a lot better...", "Una mejora de salud, podría haber sido mucho mejor…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dealt me a blow...", "Me has asestado un golpe…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dealt one direct damage!", "¡Has infligido un punto de daño directo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess playing a perfect game is no match for pay to win mechanics.", "Parece que ni una partida perfecta puede competir con las mecánicas de pagar para ganar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadbeat", "Sin fuerzas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a creature on the same side of the board. That creature will perish.", "Elige una criatura del mismo lado del tablero. Esa criatura morirá.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck Drain", "Drenaje del mazo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Up to 3 times per turn, pay 1 blood to draw a random card from your deck.", "Hasta 3 veces por turno, paga 1 de sangre para robar una carta aleatoria de tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dredge", "Dragado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to search your deck for any card, and add it to your hand.", "Paga 4 huesos para buscar cualquier carta en tu mazo y añadirla a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape", "Huida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have a green gem, return [creature] to your hand.", "Si tienes una gema verde, devuelve [creature] a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eternal Gallop", "Galope eterno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move [creature] in the direction inscribed on the sigil.", "Mueve [creature] en la dirección indicada por el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exalted Rune", "Runa exaltada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to create a 'Mox Pillar' in your hand. A mox pillar is defined as: 0 power, 4 health, Mox Sigil, Mighty Leap.", "Paga 1 de sangre para crear un «Pilar mox» en tu mano. Un Pilar mox tiene: 0 de poder, 4 de salud, sello mox, Salto poderoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fair Trade", "Trato justo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 pelt to remove an opponent's creature from the board, and add it to your hand.", "Paga 1 piel para retirar una criatura rival del tablero y añadirla a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fetch", "A buscar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to make [creature] move in the direction inscribed in the sigil.", "Paga 1 hueso para mover [creature] en la dirección indicada por el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flip", "Cara o cruz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "50/50 chance to either kill [creature] or give it +1 power and health.", "Probabilidad de 50/50 de matar a [creature] o darle +1 de poder y salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorge", "Atiborrarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] has less than 10 health, pay 1 blood to grant it +3 health.", "Si [creature] tiene menos de 10 de salud, paga 1 de sangre para darle +3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You spent the last of your foils!.", "¡Has gastado tu último foil!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 0 foil remaining.", "Te quedan 0 foils.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 1 foil remaining.", "Te queda 1 foil.", Language.Spanish);
            for (int currency = 2; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have " + currency + " foils remaining.", "Te quedan " + currency + " " + (currency == 1 ? "foil" : "foils") + ".", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough teeth.", "No tienes suficientes dientes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need more teeth to use that ability.", "Necesitas más dientes para usar esa habilidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot pay the cost", "No puedes pagar el coste", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you deaf? Get more Robobucks.", "¿Estás sordo? Consigue más robopavos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not running a charity, get more money.", "Esto no es una organización benéfica. Consigue más dinero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No robobucks, no sigil.", "Sin robopavos, no hay sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No dice.", "Ni hablar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.", "Mmm.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough teeth to pay the cost.", "No tienes suficientes dientes para pagar el coste.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll need to perform better in battle if you wish to use that ability.", "Si quieres usar esa habilidad, tendrás que hacerlo mejor en combate.", Language.Spanish);
            for (int currency = 0; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You require more foils to use this ability! You have " + currency + " foils.", "¡Necesitas más foils para usar esta habilidad! Tienes " + currency + " " + (currency == 1 ? "foil" : "foils") + ".", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh.", "Uf.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need more Robobucks to use that sigil, and I don't give credit.", "Necesitas más robopavos para usar ese sello, y no fío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back when you're a little... mmm... richer.", "Vuelve cuando seas un poco… mmm… más rico.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky Eater", "Comensal exigente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to draw bones equal to the health of the sacrificed creature.", "Paga 1 de sangre para obtener tantos huesos como salud tenía la criatura sacrificada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Punching Bag", "Saco de boxeo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, choose any creature. That creature will strike this card for 1 damage. Afterwards, this card regains 1 health.", "Una vez por turno, elige cualquier criatura. Esa criatura golpea esta carta y le inflige 1 de daño. Después, esta carta recupera 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remove", "Eliminar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill [creature].", "Mata a [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharpen", "Afilado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have an orange mox gem, sacrifice it to give [creature] +1 attack power.", "Si tienes una gema mox naranja, sacrifícala para dar +1 de poder a [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] sacrifices an orange gem to sharpen it's attack!", "¡[creature] sacrifica una gema naranja para afilar su ataque!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spellsword", "Espada hechizada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All gems on the same side of the board as[creature] gain 2 power, attack, and perish.", "Todas las gemas del mismo lado del tablero que [creature] obtienen 2 de poder, atacan y después mueren.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trained Flier", "Volador experto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grant [creature] the effect of the Airborne sigil until next upkeep. If the card already has Airborne, this will remove it's effect until next upkeep.", "Otorga a [creature] el efecto del sello Aéreo hasta el próximo inicio de turno. Si la carta ya tiene Aéreo, se elimina su efecto hasta el próximo inicio de turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trained Swimmer", "Nadador experto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature will gain the effect of the Waterborne sigil for one turn.", "La criatura obtiene el efecto del sello Acuático durante un turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade Subroutine", "Subrutina de mejora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] destroys another bot, this gains 1 point. When activated, the owner is presented with a choice of three sigils to permanently augment the card. Selecting a sigil spends points, and the more points accumulated when the sigil is activated, the higher quality the presented sigils will be.", "Cuando [creature] destruye otro robot, obtiene 1 punto. Al activarse, su propietario elige uno de tres sellos para mejorar la carta de forma permanente. Elegir un sello consume puntos; cuantos más puntos se hayan acumulado al activarlo, mayor será la calidad de los sellos ofrecidos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aculeate Grip", "Agarre espinoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played on the same side of the board as [creature], [creature] will move towards them as far as possible, dealing them one damage and increasing it's own health by 1.", "Cuando se juega una criatura del mismo lado del tablero que [creature], [creature] se acerca a ella tanto como sea posible, le inflige un punto de daño y obtiene 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allure", "Atracción", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the round, [creature] will draw opposing creatures in front of itself.", "Al inicio del turno del jugador, [creature] atrae a las criaturas rivales frente a ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annihilation", "Aniquilación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all creatures on the board are dealt 10 damage.", "Cuando [creature] muere, todas las criaturas del tablero reciben 10 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Guardian", "Guardián de hormigas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal damage equal to it's attack power to any card which strikes a friendly ant.", "[creature] inflige daño igual a su poder a cualquier carta que golpee a una hormiga aliada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antimagic", "Antimagia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any mox gems played while [creature] is on the board will immediately perish. [creature] will move to the position of the destroyed gem, gain 1 health, and immediately attack.", "Mientras [creature] esté en el tablero, cualquier gema mox que se juegue muere de inmediato. [creature] se mueve al lugar de la gema destruida, obtiene 1 de salud y ataca de inmediato.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] destroys the played gem!", "¡[creature] destruye la gema jugada!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armortify", "Blindaje", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains the armored sigil.", "Cuando [creature] ataca a una criatura rival y la mata, obtiene el sello Acorazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artistic License", "Licencia artística", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creature opposing it loses all sigils.", "Cuando se juega [creature], la criatura de enfrente pierde todos sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trying to plunder me sigils? Yer a sour spoilsport!", "¿Quieres saquearme los sellos? ¡Maldito aguafiestas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite your artistry, the soul of the moon is impervious...", "Pese a tu arte, el alma de la luna sigue siendo invulnerable…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backup", "Refuerzos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, the first card in it's owner's hand is played in it's place.", "Cuando [creature] muere en combate, la primera carta de la mano de su propietario se juega en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls in backup.", "[creature] pide refuerzos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandage Weaver", "Tejedor de vendas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn,[creature] will heal the cards to it's left and right for 1 health.", "Al final del turno, [creature] hace que las cartas a su izquierda y derecha recuperen 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bastion", "Bastión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] recieves damage, it only takes half the damage it normally would, rounded up.", "Cuando [creature] recibe daño, solo sufre la mitad, redondeada hacia arriba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batch Delete", "Borrado en lote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature and it perishes, any creatures on the board which share the same cost as the target perish also.", "Cuando [creature] golpea a una criatura y la mata, también mueren todas las criaturas del tablero que tengan el mismo coste que la víctima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shreds any other cards with the same cost as it's victim...", "[creature] destroza las demás cartas con el mismo coste que su víctima…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bejeweled", "Engastado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the field, lining up three gems of the same colour will remove those gems from the field. Any creatures which opposed those gems will be removed as well, and the opponent will take damage directly equal to their combined attack power. ", "Mientras [creature] esté en el tablero, alinear tres gemas del mismo color las retira del tablero. También se retiran las criaturas que estén frente a esas gemas y el rival recibe daño directo igual a la suma de su poder. ", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bewilder", "Desconcierto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose any creature. Swap that creatures power and health.", "Cuando se juega [creature], su propietario puede elegir cualquier criatura. Intercambia el poder y la salud de esa criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bifurcated When Gempowered", "Bifurcación con gema", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If its owner has an Orange Gem, [creature] will strike each opposing space to the left and right of the space across from it.", "Si su propietario tiene una gema naranja, [creature] ataca los espacios rivales a la izquierda y a la derecha del espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bisection", "Bisección", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, two copies of the victim are created in the owner's hand with zero power and halved health.", "Cuando [creature] mata a otra criatura, se crean dos copias de la víctima en la mano del propietario de la carta que tiene este sello, con poder igual a cero y la mitad de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleach", "Lejía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent creatures lose all sigils.", "Cuando se juega [creature], todas las criaturas rivales pierden todos sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated", "Hinchado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is worth blood equal to its health when sacrificed.", "Cuando se sacrifica [creature], proporciona tanto de sangre como salud tenga.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Artist", "Artista de la sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every three cards which perish by combat while [creature] is on the board, [creature] will give it's owner a deathcard constructed from the cost, stats, and sigils of those creatures.", "Mientras [creature] esté en el tablero, por cada tres cartas que mueran en combate, [creature] da a su propietario una carta de muerte creada a partir de su coste, estadísticas y sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] constructs a deathcard from previous creatures deaths...", "[creature] crea una carta de muerte a partir de las criaturas que han muerto antes…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it transforms to or from it's alternate form instead of perishing.", "Cuando se sacrifica [creature], cambia a su forma alternativa o vuelve de ella en lugar de morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Dependent", "Dependiente de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not strike another creature during the attack phase, it will perish at the start of the owner's next turn.", "Si [creature] no golpea a otra criatura durante la fase de ataque, muere al inicio del próximo turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood From Stone", "Sangre de piedra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may sacrifice terrain cards in order to play [creature].", "Puedes sacrificar cartas de terreno para jugar [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Gusher", "Chorro de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card, as well as creatures to the left and right of this card, gain 1 health.", "Cuando [creature] ataca a una criatura rival y la mata, esta carta y las criaturas a su izquierda y derecha obtienen 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Tragasangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] deals damage to a creature, it gains 1 Health for each damage dealt.", "Cuando [creature] inflige daño a una criatura, obtiene 1 de salud por cada punto de daño infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes the blood of its prey!", "¡[creature] bebe la sangre de su presa!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Magic", "Magia de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the field, its owner may sacrifice any gems, even if those gems normally cannot be sacrificed.", "Mientras [creature] esté en el tablero, su propietario puede sacrificar cualquier gema, incluso las que normalmente no se pueden sacrificar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodrunner", "Corredor de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, it will move in the direction inscribed in the sigil.", "Cuando [creature] inflige daño a una criatura, se mueve en la dirección indicada por el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Inspiration", "Inspiración azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a blue gem will gain a random sigil when played.", "Mientras [creature] esté en el tablero, todas las criaturas aliadas cuyo coste incluya una gema azul obtienen un sello aleatorio al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers the Blue Gem cost creature with a random sigil!", "¡[creature] otorga un sello aleatorio a la criatura con coste de gema azul!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombjuration", "Bombocación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose an empty slot on either side of the board. A magic bomb is created in the chosen slot.", "Cuando se juega [creature], su propietario puede elegir un espacio vacío de cualquiera de los dos lados del tablero. Se crea una Bomba mágica en el espacio elegido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombs Away", "Bombas fuera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Payload is created in the opposing slot. [define:SigilNevernamed Payload]", "Cuando se juega [creature], se crea una Carga útil en el espacio de enfrente. [define:SigilNevernamed Payload]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] drops a payload into the opposing slot!", "¡[creature] lanza una carga útil al espacio de enfrente!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Dependent", "Dependiente de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the user has 0 Bones, [creature] will perish.", "Si quien la usa tiene 0 huesos, [creature] muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Duke", "Duque de los huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 3 Bones are awarded instead of 1.", "Cuando [creature] muere, se obtienen 3 huesos en lugar de 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelust", "Ansia de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it generates 3 bones for its owner.", "Cuando [creature] mata a otra criatura, genera 3 huesos para su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Spurs", "Espolones óseos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it generates a bone for it's owner.", "Cuando [creature] recibe un golpe, genera un hueso para su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target the least powerful opposing card when it attacks.", "Al atacar, [creature] elige como objetivo la carta rival con menos poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "Ardiendo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] takes 1 damage. Also, when [creature] is struck, the striker gains this sigil.", "Al final del turno de su propietario, [creature] recibe 1 de daño. Además, cuando [creature] recibe un golpe, quien la golpeó obtiene este sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzz Off", "Zumba lejos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave a mayfly in it's old place. A mayfly is defined as 1 power, 1 health, airborne, brittle.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada por el sello y deja una Efímera en su lugar anterior. Una Efímera tiene: 1 de poder, 1 de salud, Aéreo, Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Call To Arms", "Llamada a las armas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creatures to it's left and right will immediately attack.", "Cuando se juega [creature], las criaturas a su izquierda y derecha atacan de inmediato.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Shedder", "Sembrador de cartas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave a card in it's wake.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada por el sello y deja una carta a su paso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caustic", "Cáustico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's killer perishes as well.", "Cuando [creature] muere, también muere quien la mató.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Center Strike", "Golpe central", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack all opponent slots except for those in the leftmost and rightmost lanes.", "[creature] ataca todos los espacios rivales salvo los de los carriles de los extremos izquierdo y derecho.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "Golpe del caos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random strike modifier sigil.", "Cuando se roba [creature], este sello se sustituye por un sello aleatorio que modifica los golpes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheater", "Tramposo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, the opponent is dealt 1 damage.", "Cuando [creature] ataca a una criatura rival y la mata, el rival recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Maker", "Creador de circuitos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a conduit card is created to its left and right.", "Cuando se juega [creature], se crea una carta de conducto a su izquierda y a su derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Claw", "Garra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will lose all attack power if it is not directly adjacent to a card bearing the clawed sigil.", "[creature] pierde todo su poder si no está directamente adyacente a una carta con el sello Con garras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed", "Con garras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, claws are created to the left and right. Any creatures in those spaces will be killed.", "Cuando se juega [creature], se crean Garras a su izquierda y derecha. Se mata a cualquier criatura que ocupe esos espacios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawing Hand", "Mano con garras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to the number of cards in the owner's hand.", "Cuando [creature] recibe un golpe, quien la golpeó recibe tanto daño como cartas tenga en la mano el propietario de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleaving", "Hendir", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes another creature, that creature will be cut in half. Half of the creature will move to the right, while the other half remains in place.", "Cuando [creature] golpea a otra criatura, esta se corta por la mitad. Una mitad se mueve a la derecha y la otra permanece en su sitio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cleaves it's target in half!", "¡[creature] parte su objetivo por la mitad!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coastguard", "Guardacostas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerges during the opponent's turn. When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space while submerged.", "Se sumerge durante el turno rival. Cuando se coloca una criatura rival frente a un espacio vacío, [creature] se mueve a ese espacio sin salir del agua.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collateral Damage", "Daños colaterales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if [creature] is on the board, the nearest creature to this card will be dealt ten damage.", "Al final del turno de su propietario, si [creature] está en el tablero, la criatura más cercana a esta carta recibe diez de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "Coleccionista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscribed on the sigil. Creatures in the way will be returned to the owner's hand.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada por el sello. Las criaturas que encuentre en el camino vuelven a la mano del propietario de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Commander", "Comandante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the creatures to it's left and right will attack the striker.", "Cuando [creature] recibe un golpe, las criaturas a su izquierda y derecha atacan a quien la golpeó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Strike When Powered", "Doble golpe al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it will strike the opposing space an additional time when it attacks.", "Si [creature] está dentro de un circuito, golpea el espacio de enfrente una vez más al atacar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift When Powered", "Regalo al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit when it perishes, a random card is created in your hand.", "Si [creature] está dentro de un circuito cuando muere, se crea una carta aleatoria en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morsel When Powered", "Bocado al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] is sacrificed while inside a completed circuit, ⁣it adds its stat values to the card it was sacrificed for.", "Cuando se sacrifica [creature] dentro de un circuito completo, ⁣sus estadísticas se añaden a la carta por la que se ha sacrificado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omnipotent When Powered", "Omnipotencia al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it will strike every opposing space containing a card when it attacks. [creature] will strike directly if no creatures oppose it, or if it is not in a circuit.", "Si [creature] está dentro de un circuito, ataca cada espacio rival que contenga una carta. [creature] ataca normalmente si ninguna criatura rival puede interceptarla o si no está dentro de un circuito.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered Quills", "Púas al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck while inside a completed circuit, the striker is dealt 2 damage.", "Cuando [creature] recibe un golpe dentro de un circuito completo, quien la golpeó recibe 2 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Print When Powered", "Impresión al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is inside a completed circuit, a gem will be created in its owners hand at the start of their turn.", "Si [creature] está dentro de un circuito completo, se crea una gema en la mano de su propietario al inicio de su turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] prints a mox gem for its owner!", "¡[creature] imprime una gema mox para su propietario!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repulsive When Powered", "Repulsión al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a conduit, if another creature would strike it, it does not.", "Mientras [creature] esté dentro de un circuito, las otras criaturas que fueran a golpearla no lo hacen.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scavenge When Powered", "Carroñeo al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is inside a completed circuit, opposing creatures also grant Bones upon death.", "Mientras [creature] esté dentro de un circuito completo, las criaturas rivales también otorgan huesos al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Damage When Powered", "Salpicadura al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a conduit when it strikes a slot, creatures to the left and right of the struck slot will be dealt 1 damage.", "Cuando [creature] golpea un espacio mientras está dentro de un circuito, las criaturas a la izquierda y derecha del espacio golpeado reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulate When Powered", "Estimular al potenciarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is inside a completed circuit, it gains 2 health at the start of its owners turn.", "Mientras [creature] esté dentro de un circuito completo, obtiene 2 de salud al inicio del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] stimulates its health!", "¡[creature] estimula su salud!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Billowing Bond", "Vínculo aéreo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures within a bond completed by [creature] gain the power of flight at the start of each turn.", "Las criaturas dentro de un vínculo completado por [creature] obtienen la capacidad de volar al inicio de cada turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Conduit", "Conducto ancestral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] perishes, a Gem Skeleton will be created in it's place.", "Cuando una criatura dentro de un circuito completado por [creature] muere, se crea un Esqueleto de gema en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls forth a Gem Skeleton with the old magics!", "¡[creature] invoca un Esqueleto de gema con la magia antigua!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Conduit", "Conducto de esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains a green gem.", "Si [creature] forma parte de un circuito completo, su propietario obtiene una gema verde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner a green gem!", "¡[creature] completa un circuito y otorga una gema verde a su propietario!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants a green gem!", "¡[creature] ya no completa un circuito ni otorga una gema verde!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Friendship Bond", "Vínculo de amistad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a bond completed by [creature] spawn Squirrels at the end of the owner's turn.", "Los espacios vacíos dentro de un vínculo completado por [creature] generan Ardillas al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Conduit", "Conducto sepulcral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the end of the owner's turn, [creature] will generate one bone for each creature contained within the circuit it completes.", "Completa un circuito. Al final del turno de su propietario, [creature] genera un hueso por cada criatura dentro del circuito que completa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] grants a bone for every creature in it's circuit.", "[creature] otorga un hueso por cada criatura de su circuito.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gun Conduit", "Conducto artillero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the slot opposing a card in a circuit completed by [creature], the moved creature is dealt 1 damage.", "Cuando una criatura se mueve al espacio frente a una carta de un circuito completado por [creature], la criatura que se ha movido recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes a free shot!", "¡[creature] dispara gratis!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Conduit", "Conducto ardiente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] is struck, the striker gains the Burning Sigil. Also, creatures within this card's circuit do not take damage from the Burning sigil.", "Cuando una criatura dentro de un circuito completado por [creature] recibe un golpe, quien la golpeó obtiene el sello Ardiendo. Además, las criaturas del circuito de esta carta no reciben daño del sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot Conduit", "Conducto de botín", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the start of the owner's turn, [creature] will draw 1 card to the owners hand for every empty space in the circuit it completes.", "Completa un circuito. Al inicio del turno de su propietario, [creature] hace que su propietario robe 1 carta por cada espacio vacío del circuito que completa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] draws a card for every empty space in it's circuit!", "¡[creature] hace robar una carta por cada espacio vacío de su circuito!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malfunctioning Conduit", "Conducto averiado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the end of its owner's turn, random cards from its owners hand will be played in random spaces inside of the circuit completed by [creature]. Those cards gain the Burning Sigil.", "Completa un circuito. Al final del turno de su propietario, se juegan cartas aleatorias de su mano en espacios aleatorios del circuito completado por [creature]. Esas cartas obtienen el sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] draws cards into it's circuit!", "¡[creature] atrae cartas a su circuito!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meaningless Bond", "Vínculo sin efecto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may complete a bond, but provides no additional effect.", "[creature] puede completar un vínculo, pero no proporciona ningún efecto adicional.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nano Conduit", "Nanoconducto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn, creatures within a circuit completed by [creature] gain the Armored sigil.", "Al final del turno de su propietario, las criaturas dentro de un circuito completado por [creature] obtienen el sello Acorazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shields all creatures in its circuit!", "¡[creature] protege con un escudo a todas las criaturas de su circuito!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Conduit", "Conducto de rubí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains an orange gem.", "Si [creature] forma parte de un circuito completo, su propietario obtiene una gema naranja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner an orange gem!", "¡[creature] completa un circuito y otorga una gema naranja a su propietario!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants an orange gem!", "¡[creature] ya no completa un circuito ni otorga una gema naranja!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Conduit", "Conducto de zafiro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains a blue gem.", "Si [creature] forma parte de un circuito completo, su propietario obtiene una gema azul.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner a blue gem!", "¡[creature] completa un circuito y otorga una gema azul a su propietario!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants a blue gem!", "¡[creature] ya no completa un circuito ni otorga una gema azul!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stim Conduit", "Conducto estimulante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn, creatures within a circuit completed by [creature] gain 1 Health.", "Al final del turno de su propietario, las criaturas dentro de un circuito completado por [creature] obtienen 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] increases the health of every creature in it's circuit!", "¡[creature] aumenta la salud de cada criatura de su circuito!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tender Bond", "Vínculo tierno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures within a bond completed by [creature] heal to full health at the start of the owner's turn.", "Las criaturas dentro de un vínculo completado por [creature] recuperan toda su salud al inicio del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Conduit", "Conducto espinoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] is struck, the striker is then dealt a single damage point.", "Cuando una criatura dentro de un circuito completado por [creature] recibe un golpe, quien la golpeó recibe un punto de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Confusion", "Confusión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played opposite an opponents creature, swap that creatures power and health.", "Cuando se juega [creature] frente a una criatura rival, se intercambian el poder y la salud de esa criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card opposing [creature] is confused!", "¡La carta que está frente a [creature] está confundida!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copier", "Copiador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a copy of it's murderer is created in your hand.", "Cuando [creature] muere, se crea en tu mano una copia de quien la mató.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coward", "Cobarde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is targeted, it will leap out of the way.", "Cuando [creature] se convierte en objetivo, se aparta de un salto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Strike Left", "Golpe desviado a la izquierda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack the space to the left of it's intended target.", "[creature] ataca el espacio a la izquierda del objetivo previsto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Strike Right", "Golpe desviado a la derecha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack the space to the right of it's intended target.", "[creature] ataca el espacio a la derecha del objetivo previsto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "Huesos cruzados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it grants 2 bones to it's owner.", "Cuando se juega [creature], otorga 2 huesos a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crunchy", "Crujiente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it generates one bone for its owner.", "Cuando se sacrifica [creature], genera un hueso para su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cute", "Adorable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that strike [creature] feel guilty, and will skip their next strike.", "Las criaturas que golpean a [creature] se sienten culpables y se saltan su siguiente golpe.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Data Breach", "Filtración de datos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner must draw a card from their deck and immediately discard it. The opponent is dealt damage equal to the drawn creatures attack power.", "Cuando [creature] muere, su propietario debe robar una carta de su mazo y descartarla de inmediato. El rival recibe daño igual al poder de la criatura robada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadringer", "Campanero fúnebre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, it gains +1 power each time the bell is rung, if it has less than 5 power.", "Mientras [creature] esté viva y en el tablero, si tiene menos de 5 de poder obtiene +1 de poder cada vez que suena la campana.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] powers up!", "¡[creature] se potencia!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Snatch", "Arrebato mortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card from your deck.", "Cuando [creature] muere, roba una carta de tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decked Out", "Bien equipado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a card from a random temple's side deck is created in your hand.", "Cuando [creature] recibe un golpe, se crea en tu mano una carta del mazo secundario de un templo aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "Profanador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner must draw a card from their deck and immediately discard it.", "Cuando [creature] muere, su propietario debe robar una carta de su mazo y descartarla de inmediato.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate", "Desesperado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it deals one point of damage to the opponent.", "Cuando [creature] muere, inflige un punto de daño al rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals a free point of damage as it perishes.", "[creature] inflige gratis un punto de daño al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deus Hoof", "Dios ungulado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All friendly hooved creatures gain +1 Power and Health while [creature] is on the board. Also, all hooved creatures will attack anything that strikes [creature].", "Todas las criaturas aliadas de la tribu de Ungulados obtienen +1 de poder y salud mientras [creature] esté en el tablero. Además, todas las criaturas de la tribu de Ungulados atacan a quien golpee a [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dexter Strike", "Golpe diestro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will also strike the slot to the right of the opposing slot when it attacks.", "Al atacar, [creature] también golpea el espacio a la derecha del espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diagonal Strike", "Golpe diagonal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it will strike either to the left or right of its original target, prioritising striking slots containing creatures. If both or neither slots adjacent to the target contain creatures, [creature] will attack to the left or right at random.", "Cuando [creature] ataca, golpea a la izquierda o derecha de su objetivo original y da prioridad a los espacios con criaturas. Si ambos espacios adyacentes al objetivo tienen criaturas o ambos están vacíos, [creature] ataca a la izquierda o derecha al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disembowel", "Destripamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, an amount of guts equal to its remaining health are created in its owners hand.", "Cuando se sacrifica [creature], se crean en la mano de su propietario tantas cartas Entrañas como salud le quede.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s guts explode into your hands.", "Las entrañas de [creature] explotan en tus manos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Distraction", "Distracción", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a distraction is left in its place and [creature] moves to the right.", "Cuando [creature] vaya a recibir un golpe, se deja una distracción en su lugar y [creature] se mueve a la derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diver", "Buceador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can strike the opposing card even while it is submerged.", "[creature] puede golpear la carta de enfrente aunque esta esté sumergida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next card drawn while [creature] is alive and on the board will be duplicated.", "Se duplica la siguiente carta que se robe mientras [creature] esté viva y en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divisibility Strike", "Golpe de divisibilidad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] will alternate between striking all odd indexed opponent slots, and all even indexed opponent slots.", "Al final del turno de su propietario, [creature] alterna su modo de ataque entre todos los espacios rivales de índice impar y todos los de índice par.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Docile", "Dócil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will wait a set number of turns in between being allowed to attack.", "[creature] debe esperar un número fijo de turnos entre los ataques permitidos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doomed", "Condenado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will perish.", "Al final del turno, [creature] muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Tap", "Golpe coordinado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly creature strikes an opponent creature, [creature] will also attack that opponent creature.", "Cuando una criatura aliada golpea a una criatura rival, [creature] también ataca a esa criatura rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] aids its comrades in battle!", "¡[creature] ayuda a sus camaradas en combate!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Downdraft", "Corriente descendente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant the power of flight to creatures to it's left and right.", "[creature] otorga la capacidad de volar a las criaturas a su izquierda y derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw", "Robo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its owner draws cards equal to the number inscribed on this sigil.", "Cuando se juega [creature], su propietario roba tantas cartas como indique el número del sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dripping", "Goteante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave part of it's own body in it's wake.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada por el sello y deja parte de su cuerpo a su paso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drop", "Despliegue inicial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If[creature] is drawn as part of your opening hand, it will be automatically played on a random board space for free.", "Si se roba [creature] como parte de tu mano inicial, se juega automáticamente gratis en un espacio aleatorio del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search your deck for any card and create a duplicate of it in your hand.", "Cuando se juega [creature], puedes buscar cualquier carta en tu mazo y crear un duplicado en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Duppelgang", "Dúo de dobles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw copies of cards adjacent to it from your deck to your hand.", "Cuando se juega [creature], roba de tu mazo copias de las cartas adyacentes y añádelas a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eager", "Ansioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain +2 power for the duration of it's first turn on the board.", "[creature] obtiene +2 de poder durante su primer turno en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easy Pickings", "Presas fáciles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all other creatures on the board with 1 health will perish.", "Cuando se juega [creature], mueren todas las demás criaturas del tablero con 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emancipation", "Emancipación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, copies of any bottled cards the owner possesses are created in the owner's hand.", "Cuando se juega [creature], se crean en la mano de su propietario copias de todas las cartas embotelladas que posea.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Core", "Núcleo de esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, an Emerald Vessel is created in its place.", "Cuando [creature] muere, se crea un Recept. esmeralda en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Corazón de esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, an Emerald Mox is created in its place.", "Cuando [creature] muere, se crea un Mox esmeralda en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanting", "Encantamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures you control gain one of its other sigils, at random.", "Cuando se juega [creature], todas las criaturas que controlas obtienen uno de sus otros sellos al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endangered", "En peligro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] has a one in four chance to perish.", "Al final del turno, [creature] tiene una probabilidad entre cuatro de morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy Lines", "Líneas enemigas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it will target all opponent slots that it is NOT directly opposing.", "Cuando [creature] ataca, elige como objetivo todos los espacios rivales que NO estén directamente enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Dependent", "Dependiente de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the user has 0 Energy, [creature] will perish.", "Si quien la usa tiene 0 de energía, [creature] muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged", "Enfurecido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it gains 1 attack power.", "Cuando [creature] recibe un golpe, obtiene 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entangle", "Enredo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its killer has their power reduced by half and rounded down for one turn.", "Cuando [creature] muere, el poder de quien la mató se reduce a la mitad y se redondea hacia abajo durante un turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "Errático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. It will not move if the target slot is obstructed. Direction has a 50/50 chance to change after moving.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada por el sello. No se mueve si el espacio de destino está bloqueado. Tras moverse, tiene una probabilidad de 50/50 de cambiar de dirección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esprit De Corps", "Espíritu de cuerpo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, creatures in the leftmost and rightmost slots on the same side of the board gain 1 power.", "Mientras [creature] esté en el tablero, las criaturas de los espacios de los extremos izquierdo y derecho del mismo lado obtienen 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While[creature] is alive and on the board, its owner may not take fatal damage.", "Mientras [creature] esté viva y en el tablero, su propietario no puede recibir daño letal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even Strike", "Golpe par", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opposing spaces in even indexed columns when it attacks. Column index is counted from the left, starting at 1.", "Al atacar, [creature] golpea todos los espacios rivales de las columnas con índice par. Las columnas se cuentan desde la izquierda, empezando por 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exceptional Sacrifice", "Sacrificio excepcional", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as 6 Blood rather than 1 Blood when sacrificed. Does not pair well with many lives.", "Cuando se sacrifica [creature], cuenta como 6 de sangre en lugar de 1. No combina bien con Muchas vidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstarved Beast", "Bestia sedienta de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may search their graveyard for a card, and add that card to their hand.", "Cuando se juega [creature], su propietario puede buscar una carta en su cementerio y añadirla a su mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Corpse", "Cadáver explosivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all empty spaces on the board are filled with it's innards.", "Cuando [creature] muere, todos los espacios vacíos del tablero se llenan de sus entrañas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Expulsion", "Expulsión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] takes damage, it regurgitates it's contents into the adjacent space to the right.", "Cuando [creature] recibe daño, regurgita su contenido en el espacio adyacente de la derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exsanguination", "Desangramiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, friendly creatures have their blood cost reduced by 1.", "Mientras [creature] esté en el tablero, el coste de sangre de las criaturas aliadas se reduce en 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye For Battle", "Ojo para el combate", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will lose all attack power if it is not directly opposing an opponent's creature.", "[creature] pierde todo su poder si no está directamente frente a una criatura rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Face To Face", "Cara a cara", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it morphs to mimic the current opponent.", "Cuando se roba [creature], se transforma para imitar al rival actual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fan Tailed", "Cola de abanico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all friendly creatures on the board take flight.", "Cuando se juega [creature], todas las criaturas aliadas del tablero alzan el vuelo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fatal Flank", "Flanco fatal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes to combat, it creates a specific creature in all empty adjacent slots.", "Cuando [creature] muere en combate, crea una criatura específica en todos los espacios vacíos adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearsome", "Temible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot occupied by another creature, that creature will move to make way for it if there is room to do so.", "Cuando [creature] elige a una criatura como objetivo de ataque, el objetivo huye a un espacio vacío adyacente si hay alguno disponible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "File Explorer", "Explorador de archivos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, choose two creatures from random selection of your deck. These creatures will define this cards power and health at random. If this card dies, the creatures used to define its stats perish as well.", "Cuando se juega [creature], elige dos criaturas de una selección aleatoria de tu mazo. Estas determinan al azar el poder y la salud de esta carta. Si la carta muere, también mueren las criaturas usadas para determinar sus estadísticas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filter Feeder", "Filtrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature perishes adjacent to [creature], the card will gain either 1 power or 1 health.", "Cuando muere una criatura adyacente a [creature], esta carta obtiene 1 de poder o 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebomb", "Bomba incendiaria", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, creatures adjacent to it and opposing it take 2 damage and gain the Burning sigil.", "Cuando [creature] muere, las criaturas adyacentes y la de enfrente reciben 2 de daño y obtienen el sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] explodes, spraying fire everywhere!", "¡[creature] explota y esparce fuego por todas partes!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire In The Hole", "Cuidado, que explota", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's owner may choose an opponent slot. The creature in that slot will take ten damage.", "Cuando [creature] muere, su propietario puede elegir un espacio rival. La criatura de ese espacio recibe diez de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Resistant", "Resistente al fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not take damage from the Burning sigil.", "[creature] no recibe daño del sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flank Blast", "Explosión lateral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, adjacent friendly creatures are dealt 10 damage.", "Cuando [creature] muere, las criaturas aliadas adyacentes reciben 10 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flea Ridden", "Infestado de pulgas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes to combat, it creates a Flea in all empty adjacent slots. A Flea is defined as 0 Power, 1 Health, Eager, Frail", "Cuando [creature] muere en combate, crea una Pulga en cada espacio adyacente vacío. Una Pulga tiene 0 de poder, 1 de salud, Ansioso y Frágil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flighty", "Voluble", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move to a random available space.", "Al final del turno, [creature] se mueve a un espacio disponible aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil Record", "Registro fósil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, terrain cards will award 3 additional bones when destroyed.", "Mientras [creature] esté en el tablero, las cartas de terreno otorgan 3 huesos adicionales al ser destruidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail", "Frágil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it will perish.", "Cuando [creature] recibe un golpe, muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Sacrifice", "Sacrificio frágil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, the creature it was sacrificed for gains the Frail Sigil.", "Cuando se sacrifica [creature], la criatura para la que se sacrificó obtiene el sello Frágil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freefall", "Caída libre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all airborne creatures require exactly 1 less of their respective cost to be played.", "Mientras [creature] esté en el tablero, jugar cualquier criatura con Aéreo cuesta exactamente 1 recurso menos de su tipo correspondiente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Friend Finder", "Buscador de amigos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random friend is created in the slots to it's left and right.", "Cuando se juega [creature], se crea un amigo aleatorio en cada uno de los espacios a su izquierda y a su derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fringe Strike", "Golpe en los extremos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the leftmost and rightmost opponent lanes.", "[creature] siempre ataca los carriles rivales situados más a la izquierda y más a la derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frog Friend", "Amigo de las ranas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil. You may search your deck for any 'frog' or 'toad' creatures, and play them in [creature]'s old space.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Puedes buscar en tu mazo las criaturas «rana» o «sapo» que quieras y jugarlas en el espacio que ocupaba [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dependant", "Dependencia de esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no green mox gems, it will perish.", "Si el propietario de [creature] no controla ninguna gema mox verde, esta muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires an emerald mox to exist and perishes.", "[creature] necesita un mox esmeralda para existir y muere si no lo tiene.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Dependant", "Dependencia de rubí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no orange mox gems, it will perish.", "Si el propietario de [creature] no controla ninguna gema mox naranja, esta muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires a ruby mox to exist and perishes.", "[creature] necesita un mox rubí para existir y muere si no lo tiene.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Dependant", "Dependencia de zafiro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no blue mox gems, it will perish.", "Si el propietario de [creature] no controla ninguna gema mox azul, esta muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires a sapphire mox to exist and perishes.", "[creature] necesita un mox zafiro para existir y muere si no lo tiene.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shedder", "Desprendimiento de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil and drop a random Gem in its old place.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello y deja una gema aleatoria en el espacio que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Skeptic", "Escéptico de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, its owner may not play any mox gems.", "Mientras [creature] esté en el tablero, su propietario no puede jugar gemas mox.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "Gigante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, any strikes against its owner will target it instead.", "Mientras [creature] esté en el tablero, todos los ataques dirigidos a su propietario apuntan a ella en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift Bearer", "Portador de regalos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a random creature is created in your hand.", "Cuando [creature] muere, se crea una criatura aleatoria en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glitterheart", "Corazón centelleante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, playing a mox gem will increase its health by 1.", "Mientras [creature] esté en el tablero, jugar una gema mox aumenta su salud en 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is bolstered by the played gem.", "La gema jugada fortalece a [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Globetrotter", "Trotamundos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscribed on the sigil. If obstructed, it will move to the other side of the board and begin to circle back.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Si encuentra un obstáculo, pasa al otro lado del tablero y empieza a dar la vuelta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Black Goat is created in its owners hand.", "Cuando se juega [creature], se crea una Cabra negra en la mano de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Digger", "Buscador de oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 currency, up to five times per battle.", "Al final del turno de su propietario, [creature] genera 1 unidad de moneda, hasta cinco veces por batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Rush", "Fiebre del oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent cards on the board perish, and are replaced by Gold Nuggets.", "Cuando se juega [creature], todas las cartas rivales del tablero mueren y son sustituidas por pepitas de oro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Pegajoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker loses 1 power.", "Cuando [creature] recibe un golpe, quien la golpeó pierde 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrape that gunk off the hull, lads! Full steam ahead!", "¡Raspad esa porquería del casco, muchachos! ¡A toda máquina!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No amount of ooze can slow the motion of a celestial body...", "Ninguna cantidad de cieno puede frenar el movimiento de un cuerpo celeste...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graveyard Shift", "Turno de cementerio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it leaves something else in it's old space. Unlike Frozen Away, this new creature will retain the sigils and buffs of the original.", "Cuando [creature] muere en combate, deja algo distinto en el espacio que ocupaba. A diferencia de Congelado, la nueva criatura conserva los sellos y las mejoras de la original.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity", "Gravedad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose any opponent creature, and move it to any open space on their side of the board.", "Cuando se juega [creature], su propietario puede elegir una criatura rival y moverla a cualquier espacio libre de su propio lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Inspiration", "Inspiración verde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a green gem gain +2 health.", "Mientras [creature] esté en el tablero, todas las criaturas aliadas que cuestan una gema verde obtienen +2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gut Spewer", "Escupeentrañas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its innards are created in your hand.", "Cuando se juega [creature], sus entrañas se crean en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "Precursor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly creatures perishes, [creature] will move to fill it's empty space.", "Cuando una criatura aliada muere, [creature] se mueve para ocupar su espacio vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harts Within", "Ciervos interiores", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a random creature from the hooved tribe is created in your hand.", "Cuando [creature] recibe un golpe, se crea en tu mano una criatura aleatoria de la tribu de ungulados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "Embrujo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies to combat, it haunts the space it died in. Creatures that enter this space absorb its old sigils.", "Cuando [creature] muere en combate, su espíritu permanece en el espacio donde murió. Las criaturas que entren en ese espacio absorben sus antiguos sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] leaves its sigils behind in the ethereal plane!", "¡[creature] deja sus sellos en el plano etéreo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature]s owner may choose a creature they control. That creature gains 1 health.", "Al final del turno del propietario de [creature], este puede elegir una criatura que controle. Esa criatura obtiene 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healshield", "Escudo curativo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not take damage during a turn, it will gain Armor at the start of its owner's next turn.", "Si [creature] no recibe daño durante un turno, obtiene Armadura al comienzo del siguiente turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herald", "Heraldo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] attacks an opposing creature and it perishes, creatures to the left and right of this card gain 1 power.", "Cuando [creature] ataca a una criatura enfrente y esta muere, las criaturas a izquierda y derecha de esta carta obtienen 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Powered", "Alta potencia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owners turn, [creature] will consume 1 energy.", "Al comienzo del turno de su propietario, [creature] consume 1 de energía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Home Run", "Jonrón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will remember the lane in which it was played, and will always attack that lane.", "[creature] recuerda el carril en el que se jugó y siempre ataca ese carril.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "Anzuelo, sedal y plomo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, the opposing creature will be pulled into it's old space.", "Cuando [creature] muere en combate, la criatura enfrente es arrastrada al espacio que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypermorphic", "Hipermórfico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] will transform into a random card of the same type and quality.", "Al final de cada turno, [creature] se transforma en una carta aleatoria del mismo tipo y calidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "Ignición", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature gains the Burning sigil.", "Cuando [creature] golpea a una criatura, esta obtiene el sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immaculate Form", "Forma inmaculada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, the gems cost of all friendly creatures is reduced by 2 gems.", "Mientras [creature] esté en el tablero, el coste en gemas de todas las criaturas aliadas se reduce en 2 gemas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immaterial", "Inmaterial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any attacks made against [creature] during the opponents turn will pass straight through, and hit the creature's owner directly.", "Durante el turno rival, los ataques contra [creature] la atraviesan y golpean directamente a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immortal Coil", "Espiral inmortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, any friendly creatures that die to combat will return to the owner's hand, though slightly weakened.", "Mientras [creature] esté viva en el tablero, las criaturas aliadas que mueran en combate regresan a la mano de su propietario, ligeramente debilitadas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incontinent", "Incontinente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a mess is created in its place and a card bearing this sigil moves to the right.", "Cuando [creature] está a punto de recibir un golpe, se crea un desastre en su lugar y una carta que lleve este sello se mueve a la derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiring Sacrifice", "Sacrificio inspirador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it grants its sigils to the creature it was sacrificed for.", "Cuando se sacrifica [creature], esta otorga sus sellos a la criatura para la que se sacrificó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instant Effect", "Efecto inmediato", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After resolving on the board, [creature] will immediately perish.", "Tras resolverse en el tablero, [creature] muere inmediatamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killing Joke", "Broma mortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost an orange gem will either gain +1 power or -1 power when played.", "Mientras [creature] esté en el tablero, las criaturas aliadas que cuestan una gema naranja obtienen +1 o -1 de poder al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] randomly modifies the power of the Orange Gem cost card!", "¡[creature] modifica aleatoriamente el poder de la carta que cuesta una gema naranja!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kin Bearer", "Portador de parentesco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a random creature of the same tribe is created in your hand.", "Cuando [creature] muere, se crea en tu mano una criatura aleatoria de la misma tribu.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindred", "Parentesco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, random common creatures of the same tribe will be played for free to its left and right.", "Cuando se juega [creature], se juegan gratis a su izquierda y a su derecha criaturas comunes aleatorias de la misma tribu.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "L33p Leaver", "Dejador de S4lt4B0t", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscrybed in the sigil and drop a L33pB0t in its old place.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello y deja un S4lt4B0t en el espacio que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Landscaper", "Paisajista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] is played, any terrain cards on the board are removed and added to it's owner's hand.", "Cuando se juega [creature], todas las cartas de terreno del tablero se retiran y se añaden a la mano de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lash Out", "Ataque de ira", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will attack a random opposing slot.", "Al final del turno de su propietario, [creature] ataca un espacio rival aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Latch", "Acople aéreo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the airborne sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Latch", "Acople molesto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the annoying sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Molesto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Latch", "Acople ardiente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the burning sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burrower Latch", "Acople excavador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the burrower sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Excavador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Latch", "Acople frágil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the frail sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Frágil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporarily Gemified", "Gemificado temporalmente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has been temporarily gemified until the end of battle.", "[creature] ha sido gemificada temporalmente hasta el final de la batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Latch", "Acople de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] perishes, its owner chooses a creature to become gemified.", "Cuando [creature] muere, su propietario elige una criatura para gemificarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter Latch", "Acople de embrujo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the haunter sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Embrujo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Null Latch", "Acople nulo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the null conduit sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Conducto nulo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overclocked Latch", "Acople sobrepotenciado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain 1 power, and the overclocked sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga 1 de poder y el sello Sobrepotenciado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Latch", "Acople de francotirador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sniper sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Francotirador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Latch", "Acople veloz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sprinter sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Velocista.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalwart Latch", "Acople firme", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the stalwart sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Firme.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Totem Latch", "Acople de tótem", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sigil on their current totem.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello de su tótem actual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne Latch", "Acople acuático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the waterborne sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Acuático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaper", "Saltador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, leaping over single card obstructions.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello, saltando los obstáculos de una sola carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it creates a number of cards in the owner's hand equal to it's remaining HP, then perishes.", "Cuando [creature] recibe un golpe, crea en la mano de su propietario tantas cartas como puntos de salud le queden y luego muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lockdown", "Bloqueo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing creature loses attack power equal to the power of this card and gains the Stalwart sigil.", "Cuando se juega [creature], la criatura enfrente pierde tanto poder como el de esta carta y obtiene el sello Firme.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] locks the opposing creature in place!", "¡[creature] inmoviliza a la criatura enfrente!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "Soledad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "[creature] obtiene +1 de poder por cada espacio adyacente vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lurk", "Acecho sumergido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerges during the opponent's turn. When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Se sumerge durante el turno rival. Cuando una criatura se mueve al espacio frente a [creature], recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magitech", "Magitecnia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, playing a mox gem will provide it's owner with an energy cell.", "Mientras [creature] esté viva en el tablero, jugar una gema mox proporciona una celda de energía a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] channels electrical power through your gems!", "¡[creature] canaliza electricidad a través de tus gemas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malware", "Programa malicioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may not play [creature] unless you are three or less damage away from losing the game.", "Solo puedes jugar [creature] si te separan de la derrota tres puntos de daño o menos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marcescent", "Marcescente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains it's attack power.", "Cuando [creature] ataca a una criatura enfrente y esta muere, esta carta obtiene su poder de ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mason", "Albañil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random obelisk is created in your hand.", "Cuando se juega [creature], se crea un obelisco aleatorio en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mauler", "Derribador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal overkill damage directly to the opponent.", "[creature] inflige el daño excedente directamente al rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medicinal", "Medicinal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it heals all friendly creatures by 2 and removes all negative sigils from friendly creatures.", "Cuando se juega [creature], cura 2 de salud a todas las criaturas aliadas y les quita todos los sellos negativos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirrific", "Acople especular", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's owner chooses a creature to gain the Mirror rorriM ability.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga la habilidad Espej0 ojeps3.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mockery", "Burla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is played opposite an opponent's creature, it's stats change to mimic that creature's stats.", "Si [creature] se juega frente a una criatura rival, sus estadísticas pasan a ser iguales a las de esa criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph Mover", "Movimiento cambiante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random movement related sigil.", "Cuando se roba [creature], este sello se sustituye por un sello de movimiento aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Motivator", "Motivador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature gains 1 power.", "Cuando [creature] golpea a una criatura, esta obtiene 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moxcraft", "Moxcraft", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a random mox is created in your hand.", "Cuando [creature] recibe un golpe, se crea un mox aleatorio en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Max", "Mox máximo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be played unless two cards which grant its respective mox cost colour are present on the owners side of the board.", "Solo se puede jugar [creature] si hay dos cartas que proporcionen el color de mox requerido por su coste en el lado del tablero de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moxwarp", "Distorsión mox", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, any enemy attack that enters a sapphire mox will be returned out of all ruby mox, and vice versa.", "Mientras [creature] esté viva en el tablero, cualquier ataque enemigo que entre en un mox zafiro saldrá reflejado de todos los mox rubí, y viceversa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystery Mox", "Mox misterioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random gem-granting sigil.", "Cuando se roba [creature], este sello se sustituye por un sello aleatorio que proporciona gemas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature Of The Beast", "Naturaleza de la bestia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a completely random creature is created in the owner's hand.", "Cuando [creature] muere, se crea en la mano de su propietario una criatura completamente aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obedient", "Obediente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to an empty space on the same side of the board, chosen by it's owner.", "Al final del turno de su propietario, [creature] se mueve a un espacio vacío del mismo lado del tablero, elegido por su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Odd Strike", "Golpe impar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opposing spaces in odd indexed columns when it attacks. Column index is counted from the left, starting at 1.", "Cuando ataca, [creature] golpea todos los espacios opuestos de las columnas impares. Las columnas se cuentan desde la izquierda, empezando por 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omni Guardian", "Guardián universal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all friendly creatures on the board gain armour.", "Cuando se juega [creature], todas las criaturas aliadas del tablero obtienen armadura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives the Armored sigil to all friendly creatures.", "[creature] otorga el sello Acorazado a todas las criaturas aliadas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crusher", "Triturador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a terrain card.", "[creature] obtiene 2 de poder cuando tiene enfrente una carta de terreno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerly Departed", "Ciervo difunto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Hooved tribe.", "[creature] obtiene 2 de poder cuando tiene enfrente una criatura de la tribu de ungulados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dog Gone", "Perro desaparecido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Canine tribe.", "[creature] obtiene 2 de poder cuando tiene enfrente una criatura de la tribu canina.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fowl Play", "Juego de plumas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Avian tribe.", "[creature] obtiene 2 de poder cuando tiene enfrente una criatura de la tribu aviar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insectivore", "Insectívoro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Insect tribe.", "[creature] obtiene 2 de poder cuando tiene enfrente una criatura de la tribu de insectos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snakebite", "Mordedura de serpiente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Reptile tribe.", "[creature] obtiene 2 de poder cuando tiene enfrente una criatura de la tribu de reptiles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Inspiration", "Inspiración naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While[creature] is on the board, all friendly cards which cost an orange gem gain +1 power.", "Mientras [creature] esté en el tablero, todas las cartas aliadas que cuestan una gema naranja obtienen +1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Organ Thief", "Ladrón de órganos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it's remains are created in your hand.", "Cuando [creature] mata a otra criatura, los restos de esta se crean en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osteoklepty", "Osteoclepsia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it steals all of the opponents bones for it's owner.", "Cuando se juega [creature], roba todos los huesos del rival para su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other Side", "La otra orilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, any friendly creatures that die in combat will be returned to the owner's hand as skeletons.", "Mientras [creature] esté en el tablero, las criaturas aliadas que mueran en combate regresan a la mano de su propietario como esqueletos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Presence", "Presencia dolorosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On upkeep, all creatures adjacent to [creature] vertically, horizontally, or diagonally take 1 damage.", "Al comienzo del turno del propietario de [creature], todas las criaturas adyacentes a ella en vertical, horizontal o diagonal reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralytic", "Paralizante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature loses 1 power.", "Cuando [creature] golpea a una criatura, esta pierde 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parthenogenesis", "Partenogénesis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies to combat, a larval form is left in it's old space that evolves into an exact clone after 1 turn.", "Cuando [creature] muere en combate, deja en el espacio que ocupaba una larva que evoluciona en un clon idéntico tras 1 turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect Form", "Forma perfecta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, the gems cost of all friendly creatures is reduced by 1 gem.", "Mientras [creature] esté en el tablero, el coste en gemas de todas las criaturas aliadas se reduce en 1 gema.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantasmic", "Fantasmal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move in the direction inscribed in the sigil, phasing past obstacles and wrapping around to the other side of the board if movement is impossible.", "Al final del turno, [creature] se mueve en la dirección indicada en el sello, atraviesa obstáculos y pasa al otro lado del tablero si no puede moverse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piercing", "Perforación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a slot which has a creature queued behind it, the queued creature will take 1 damage.", "Cuando [creature] golpea un espacio tras el que hay una criatura en espera, esa criatura recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pinnacle Strike", "Golpe supremo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opponent spaces when it attacks.", "Cuando ataca, [creature] golpea todos los espacios rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Point Nemo", "Punto Nemo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures on the board gain the Waterborne sigil.", "Cuando se juega [creature], todas las criaturas del tablero obtienen el sello Acuático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potent", "Sacrificio potente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, the creature it was sacrificed for gains a random sigil.", "Cuando se sacrifica [creature], la criatura para la que se sacrificó obtiene un sello aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preemptive Strike", "Golpe preventivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack once when first played.", "[creature] ataca una vez al jugarse por primera vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] makes a free attack!", "¡[creature] realiza un ataque gratuito!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Propagation", "Propagación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, a creature is created on the board to the left or right of this card.", "Cuando [creature] ataca a una criatura enfrente y esta muere, se crea una criatura en el tablero a la izquierda o a la derecha de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prophecy", "Profecía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may look at three cards from your deck and choose them in order. The next three cards you draw will be the cards you were shown, in the order that you chose them.", "Cuando se juega [creature], puedes mirar tres cartas de tu mazo y elegirlas en orden. Las próximas tres cartas que robes serán las que se te mostraron, en el orden elegido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will allow you to choose from three cards. These three cards will be the next three cards you draw from your deck, in the order you choose them here.", "Te permitiré elegir entre tres cartas. Serán las próximas tres cartas que robes de tu mazo, en el orden que elijas aquí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose three creatures, and alter your next draws.", "Elige tres criaturas y cambia tus próximos robos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know how this goes.", "Ya sabes cómo funciona.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose from three cards. These three cards will be the next three cards you draw from your deck, in the order you chose them.", "Elige entre tres cartas. Serán las próximas tres cartas que robes de tu mazo, en el orden elegido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose your next three draws.", "Elige tus próximos tres robos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmmm... your new prophecy overwrites the old, it would seem.", "Mmm... parece que tu nueva profecía sustituye a la anterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your new prophecy overwrites the old!", "¡Tu nueva profecía sustituye a la anterior!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... very well", "Mmm... muy bien", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough cards left for a prophecy.", "No te quedan suficientes cartas para una profecía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough cards left to make a new prophecy!", "¡No te quedan suficientes cartas para una nueva profecía!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pure Heart", "Corazón puro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Pinnacle Mox is created in its place.", "Cuando [creature] muere, se crea un Mox de la cima en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pushover", "Blanco fácil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is opposed by an enemy creature, the card will perish.", "Si [creature] tiene enfrente una criatura enemiga, la carta muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put Sentry Here", "Centinela aquí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Sentry Drone is created to its left and right.", "Cuando se juega [creature], se crea un Dron centinela a su izquierda y otro a su derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quad Strike", "Golpe cuádruple", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space to the left and right of the spaces across from it as well as striking the space in front of it an additional time.", "[creature] golpea los espacios rivales a izquierda y derecha del que tiene enfrente y golpea una vez adicional el espacio frente a ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quickdraw", "Desenfunde rápido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will automatically play itself from your deck onto a random space at the start of each battle.", "Al comienzo de cada batalla, [creature] se juega automáticamente desde tu mazo en un espacio aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ranger", "Explorador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose an opponent creature. That creature will take 10 damage.", "Cuando se juega [creature], su propietario puede elegir una criatura rival. Esa criatura recibe 10 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ravenous", "Voraz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills a creature, it will gain an additional strike against the opposing space until the end of combat.", "Cuando [creature] mata a una criatura, obtiene un golpe adicional contra el espacio de enfrente hasta el final de la batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "Recarga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner regains 1 energy. Does not affect the current energy maximum.", "Cuando se juega [creature], su propietario recupera 1 de energía. Esto no afecta al máximo de energía actual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recycle", "Reciclaje", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, when any friendly creature perishes by combat a special card will be created in the owners hand. The card created depends on the temple of the friendly card which perishesd.", "Mientras [creature] esté en el tablero, cuando una criatura aliada muere en combate se crea una carta especial en la mano de su propietario. La carta creada depende del templo de la carta aliada que murió.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflective", "Reflectante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is opposed by a creature, it gains power equal to the opposing creatures power.", "Cuando [creature] tiene enfrente una criatura, obtiene una bonificación de poder igual al poder de la criatura enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regenerator", "Regenerador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, [creature] will heal 1 health.", "Al comienzo del turno de su propietario, [creature] recupera 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] regenerates one health!", "¡[creature] regenera un punto de salud!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rememberance", "Recuerdo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may search their graveyard for a card. This sigil is replaced by that cards sigils.", "Cuando se juega [creature], su propietario puede buscar una carta en su cementerio. Este sello se sustituye por los sellos de esa carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remote Controlled", "Control remoto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Remote Controller is created in the owner's hand. When the remote controller is struck, [creature] will attack the striker.", "Cuando se juega [creature], se crea un Mando a distancia en la mano de su propietario. Cuando el mando recibe un golpe, [creature] ataca a quien lo golpeó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reroute", "Desvío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will swap places with a random creature on the same side of the board.", "Al final del turno, [creature] intercambia su lugar con una criatura aleatoria del mismo lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resilient", "Resistente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All damage taken by [creature] is reduced to 1.", "Todo el daño que recibe [creature] se reduce a 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retreat", "Retirada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it will move to a random empty space on the same side of the board.", "Cuando [creature] recibe un golpe, se mueve a un espacio vacío aleatorio del mismo lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return Strike", "Contragolpe", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it attacks in retaliation.", "Cuando [creature] recibe un golpe, contraataca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revolve", "Rotación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards on the board are moved one space clockwise.", "Cuando se juega [creature], todas las cartas del tablero se mueven un espacio en sentido horario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "Destripador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will move to and destroy any free, 1 health, non-terrain creatures played, and becomes stronger for each one consumed.", "[creature] se mueve hacia las criaturas aliadas jugadas que no sean terreno y que sean gratuitas y tengan 1 de salud máxima, o sean cabras, y las destruye. Se fortalece por cada criatura consumida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rock Eater", "Devorador de rocas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Terrain card is played on the same side of the board as [creature], it will be consumed, granting it's stats and sigils to the card.", "Cuando se juega una carta de terreno en el mismo lado del tablero que [creature], esta la devora y obtiene sus estadísticas y sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Core", "Núcleo rubí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Ruby Vessel is created in its place.", "Cuando [creature] muere, se crea un Receptáculo rubí en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Strike", "Golpe en carrera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] will move in the direction inscribed on the sigil, striking the space opposing it's destination as it does so.", "Después de atacar, [creature] se mueve en la dirección indicada en el sello y golpea el espacio frente a su destino durante el movimiento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rupture", "Ruptura", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, half of that damage, rounded down, is also dealt to that creature's owner.", "Cuando [creature] inflige daño a una criatura, la mitad de ese daño, redondeada hacia abajo, también se inflige al propietario de esa criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sanguine", "Sanguinario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is sacrificed, [creature] gains 1 power until the end of combat.", "Cuando se sacrifica una criatura, [creature] obtiene 1 de poder hasta el final de la batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Core", "Núcleo zafiro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Sapphire Vessel is created in its place.", "Cuando [creature] muere, se crea un Receptáculo zafiro en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Corazón de zafiro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Sapphire Mox is created in its place.", "Cuando [creature] muere, se crea un Mox zafiro en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Savage Ritual", "Ritual salvaje", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it attacks once before dying.", "Cuando se sacrifica [creature], esta ataca una vez antes de morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentriple", "Centinela triple", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they, as well as any creatures to their left or right, are dealt 1 damage.", "Cuando una criatura se mueve al espacio frente a [creature], ella y las criaturas a su izquierda y derecha reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Bones", "Huesos afilados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to half the number of bones its owner has, rounded down.", "Cuando [creature] recibe un golpe, quien la golpeó recibe daño igual a la mitad de los huesos del propietario de la carta, redondeada hacia abajo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharper Quills", "Púas más afiladas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt 2 damage.", "Cuando [creature] recibe un golpe, quien la golpeó recibe 2 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharpest Quills", "Púas afiladísimas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt 3 damage.", "Cuando [creature] recibe un golpe, quien la golpeó recibe 3 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Shot", "Disparo afilado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it gains +2 power and attacks once before dying.", "Cuando [creature] muere, obtiene +2 de poder y ataca una vez antes de morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Mimic", "Imitación de sello", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is played opposite an opponent's creature, this sigil is replaced by copies of that creatures sigils.", "Si [creature] se juega frente a una criatura rival, este sello se sustituye por copias de los sellos de esa criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will also strike the slot to the left of the opposing slot when it attacks.", "Cuando ataca, [creature] golpea también el espacio a la izquierda del que tiene enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siphon", "Sifón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures to the left of [creature] lose all attack power. That attack power is instead added to this card's power.", "Las criaturas a la izquierda de [creature] pierden todo su poder de ataque. Ese poder se añade al poder de esta carta en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Animator", "Titiritero de pieles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, all pelts gain it's attack power.", "Mientras [creature] esté viva en el tablero, todas las pieles obtienen su poder de ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Swarm", "Enjambre de calaveras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, all Skeletons will strike twice when attacking.", "Mientras [creature] esté viva en el tablero, todos los esqueletos golpean dos veces al atacar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimeball", "Bola de slime", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it permanently stains the opposing slot with slime. Any creatures in a slimy slot without made of stone lose 1 power.", "Cuando se juega [creature], cubre permanentemente de slime el espacio de enfrente. Las criaturas en un espacio viscoso que no tengan Hecho de piedra pierden 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snapshot", "Instantánea", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the entire board reverts to the state it was in when [creature] was placed.", "Cuando [creature] muere, todo el tablero vuelve al estado en que estaba cuando se colocó [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snare", "Lazo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played opposite a creature, that creature is ensnared and stored within the bearer, being released when the bearer perishes.", "Cuando [creature] se juega frente a una criatura, esta queda atrapada dentro de la carta portadora y es liberada cuando la portadora muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snip", "Tijeretazo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creature opposing it is removed from the board without triggering on-death effects.", "Cuando se juega [creature], la criatura que tiene enfrente se retira del tablero sin activar efectos de muerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cuts it's opponent in half.", "[creature] corta a su rival por la mitad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soak", "Absorción", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any damage taken by [creature] is reduced by 1. Taking damage decrements the timer rendered on this sigil. When the timer rendered on this sigil reaches 0, the bearer will attack with power equal to it's health, then perish.", "El daño que recibe [creature] se reduce en 1. Recibir daño disminuye el contador mostrado en este sello. Cuando el contador llega a 0, la carta portadora ataca con un poder igual a su salud y luego muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiders Web", "Telaraña", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When any opponent card moves, with the exception of entering the board for the first time,[creature] will strike them for one damage.", "Cuando una carta rival se mueve, salvo al entrar en el tablero por primera vez, [creature] le inflige un punto de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Damage", "Daño de área", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a slot, creatures to the left and right of the struck slot will be dealt 1 damage.", "Cuando [creature] golpea un espacio, las criaturas a izquierda y derecha del espacio golpeado reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Zone", "Zona de impacto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the creatures to it's left or right are also dealt 1 damage.", "Cuando [creature] recibe un golpe, las criaturas a su izquierda o derecha también reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The damage dealt to [creature] splashes out to its comrades.", "El daño infligido a [creature] salpica a sus compañeros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Split Detonation", "Detonación diagonal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, diagonally adjacent enemy creatures are dealt 10 damage.", "Cuando [creature] muere, las criaturas enemigas adyacentes en diagonal reciben 10 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Split Sentry", "Centinela dividido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], any creatures to their left or right are dealt 1 damage.", "Cuando una criatura se mueve al espacio frente a [creature], las criaturas a su izquierda o derecha reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spurred", "Espoleado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power while the slot opposing it is occupied.", "[creature] obtiene 1 de poder mientras el espacio de enfrente esté ocupado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Dependent", "Dependencia de ardillas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no Squirrels, [creature] will perish. If this card is a squirrel, it cannot support itself.", "Si el propietario de [creature] no controla Ardillas, [creature] muere. Si esta carta es una Ardilla, no puede sostenerse a sí misma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel King", "Rey de las ardillas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature, a squirrel is created in the owner's hand.", "Cuando [creature] ataca a una criatura enfrente, se crea una Ardilla en la mano de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalwart", "Firme", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is moved from the space it was placed in, it will immediately move back, shunting any card which may have moved there in the meantime out of the way.", "Si [creature] se mueve del espacio en que se colocó, vuelve a él inmediatamente y aparta cualquier carta que lo haya ocupado entretanto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Trail", "Rastro pegajoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] enters a space on the board, it permantently marks that space with its slime. Any creatures that enter that space without the Made of Stone sigil lose 1 power.", "Cuando [creature] entra en un espacio del tablero, lo marca permanentemente con su slime. Toda criatura que entre en ese espacio sin el sello Hecho de piedra pierde 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sturdy", "Robusto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All damage taken by [creature] is reduced by 1.", "Todo el daño que recibe [creature] se reduce en 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Subaquatic Spines", "Espinas subacuáticas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will submerge during the opponent's turn. While submerged, opposing creatures attack it's owner directly, and will take 1 damage after attacking.", "[creature] se sumerge durante el turno rival. Mientras está sumergida, las criaturas rivales atacan directamente a su propietario y reciben 1 de daño después de atacar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Invocador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose from a selection of random cards to add to their hand.", "Cuando se juega [creature], su propietario puede elegir una carta de una selección aleatoria y añadirla a su mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supercharge", "Sobrecarga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it refreshes it's owner's energy to the current maximum.", "Cuando se juega [creature], restaura la energía de su propietario hasta el máximo actual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] restores it's owner's energy.", "[creature] restaura la energía de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surging Quills", "Púas crecientes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to the amount of times this has been struck.", "Cuando [creature] recibe un golpe, quien la golpeó recibe tanto daño como veces ha sido golpeada esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweeping Strike Left", "Barrido a la izquierda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the leftmost opponent creature. Overkill damage travels to the right instead of to the backlane.", "[creature] siempre ataca a la criatura rival situada más a la izquierda. El daño excedente se desplaza a la derecha en lugar de a la fila posterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweeping Strike Right", "Barrido a la derecha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the rightmost opponent creature. Overkill damage travels to the left instead of to the backlane.", "[creature] siempre ataca a la criatura rival situada más a la derecha. El daño excedente se desplaza a la izquierda en lugar de a la fila posterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switch Strike", "Golpe alterno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn [creature] will alternate between striking to the left or right of the opposing slot when it attacks, in addition to striking the opposing slot.", "Al final del turno de su propietario, [creature] alterna entre izquierda y derecha el lado de su golpe adicional. Al atacar, también golpea el espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swooping Strike", "Golpe en picado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space a second time when attacking. Also, [creature]'s first strike each turn will occur directly, over opponent creatures.", "Cuando ataca, [creature] golpea una segunda vez el espacio de enfrente. Además, el primer golpe de [creature] en cada turno es directo y pasa por encima de las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathic", "Telepático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures will stike the most powerful opponent card when they attack.", "Mientras [creature] esté en el tablero, todas las criaturas aliadas golpean la carta rival más poderosa al atacar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tempting Target", "Objetivo tentador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If an opponent creature would strike a space adjacent to [creature], it will instead strike [creature].", "Si una criatura rival fuera a golpear un espacio adyacente a [creature], golpea a [creature] en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Termatriarch", "Termatriarca", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] and a different card bearing the Termite King sigil are alive and on the board, a termite will be created in your hand at the start of your turn.", "Mientras [creature] y otra carta con el sello Rey de las termitas estén vivas en el tablero, se crea una termita en tu mano al comienzo de tu turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Termite King", "Rey de las termitas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] and a different card bearing the Termatriarch sigil are alive and on the board, a termite will be created in your hand at the start of your turn.", "Mientras [creature] y otra carta con el sello Termatriarca estén vivas en el tablero, se crea una termita en tu mano al comienzo de tu turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TestSigil", "Sello de prueba", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will most likely fuck shit up.", "[creature] probablemente lo joderá todo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thief", "Ladrón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant an amount of currency when it kills another creature.", "[creature] proporciona cierta cantidad de moneda cuando mata a otra criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Travel", "Viaje en el tiempo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is played, the opponent is obligated to skip their next turn.", "Cuando se juega [creature], el rival debe saltarse su próximo turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll pass my next turn.", "Me saltaré mi próximo turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your opponent must skip their next turn!", "¡Tu rival debe saltarse su próximo turno!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh. Fine. I'll pass.", "Uf. Está bien. Paso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fair enough dear, I'll pass.", "Es justo, cariño. Paso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Puller", "Sacadientes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will add one damage to the scales in the owner's favour, regardless of it's attack power or obstruction.", "Al final del turno de su propietario, [creature] añade un punto de daño a la balanza a favor de su propietario, independientemente de su poder de ataque o de cualquier obstáculo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic", "Tóxico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck but does not perish, the striker perishes. Does not affect Made of Stone cards.", "Cuando [creature] recibe un golpe y no muere, quien la golpeó muere. No afecta a las cartas con Hecho de piedra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s toxicity kills instantly!", "¡La toxicidad de [creature] mata al instante!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traitor", "Traidor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will move onto the opponent's side of the board if unobstructed.", "Cuando se juega [creature], se mueve al lado rival del tablero si el camino está libre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trajectile Quills", "Púas proyectil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, an opponent creature of the owner's choosing is dealt 1 damage.", "Cuando [creature] recibe un golpe, una criatura rival elegida por el propietario de la carta recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trampler", "Pisoteador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. Cards in the way will be killed, and grant +1 attack power to the sigil bearer.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Las cartas en su camino mueren y otorgan +1 de poder de ataque a la carta portadora del sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transformer", "Transformador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will transform to or from it's alternate form.", "Al final del turno, [creature] cambia entre su forma actual y su forma alternativa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmogrification", "Transfiguración", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature will be changed into another form.", "Cuando [creature] golpea a una criatura, esta adopta otra forma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapjaw", "Mandíbula trampa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack to the left and the right of the opposing space if those slots are obstructed. If those slots are not obstructed, the strikes will be transferred to the directly opposing space.", "[creature] ataca los espacios a izquierda y derecha del espacio de enfrente si están ocupados. Si no lo están, los golpes se transfieren al espacio directamente enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trifling Sacrifice", "Sacrificio modesto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as 2 Blood rather than 1 Blood when sacrificed.", "Cuando se sacrifica [creature], cuenta como 2 de sangre en lugar de 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trio", "Trío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created to the left and right.", "Cuando se juega [creature], se crea una copia a su izquierda y otra a su derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triple Strike", "Golpe triple", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space two extra times when attacking.", "Cuando ataca, [creature] golpea dos veces más el espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trophy Hunter", "Cazador de trofeos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target the most powerful opposing card when it attacks.", "Cuando ataca, [creature] apunta a la carta rival más poderosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuck And Roll", "Voltereta defensiva", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of combat, [creature] will move to the free space opposed by the least amount of attack power, taking into account queued creatures, flight, and Touch of Death.", "Al comienzo del turno del propietario de [creature], esta se mueve al espacio libre expuesto al menor poder de ataque, teniendo en cuenta las criaturas en espera, el vuelo y el Toque de la muerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tug", "Tirón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will draw the queued opposing creature into the main opposing space, if possible.", "Cuando se juega [creature], arrastra, si es posible, a la criatura rival en espera al espacio principal de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Bond", "Vínculo gemelo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created adjacent, killing other creatures to make room if there is none. These cards share a health pool, and when either card dies, it's twin will die as well.", "Cuando se juega [creature], se crea una copia adyacente; si no hay espacio, se mata a otras criaturas para hacer sitio. Ambas cartas comparten la salud y, cuando una muere, su gemela también muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twister", "Torbellino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When struck, [creature] will transform to or from it's alternate form.", "Cuando [creature] recibe un golpe, cambia entre su forma actual y su forma alternativa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unbalanced Leadership", "Liderazgo desequilibrado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature directly to the left of [creature] gains 2 power.", "La criatura situada justo a la izquierda de [creature] obtiene 2 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under Pressure", "Bajo presión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, 2 damage is dealt to the opponent creature. Also, when [creature] perishes, any adjacent creatures with this sigil also take ten damage.", "Cuando [creature] muere, la criatura enfrente recibe 2 de daño. Además, cuando [creature] muere, todas las criaturas adyacentes con este sello reciben diez de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] pops, dealing 2 damage to the opposing creature!", "¡[creature] estalla e inflige 2 de daño a la criatura enfrente!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfocused Strike", "Golpe errático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target a random space when it attacks.", "Cuando ataca, [creature] apunta a un espacio aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unhammerable", "Inmune al martillo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be killed using the hammer.", "[creature] no puede morir por el martillo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlucky", "Desafortunado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, cards played by the opponent have a chance to have debuffed stats, or lose a random sigil.", "Mientras [creature] esté viva en el tablero, las cartas jugadas por el rival tienen cierta probabilidad de ver reducidas sus estadísticas o perder un sello aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unspeakable", "Indecible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card you control resolves on the board without being played from your hand, you may choose to play [creature] from your hand or deck instead.", "Cuando una carta que controlas se resuelve en el tablero sin haber sido jugada desde tu mano, puedes elegir jugar [creature] desde tu mano o mazo en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unstable Gems", "Gemas inestables", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a mox gem will gain the brittle sigil when played.", "Mientras [creature] esté en el tablero, todas las criaturas aliadas que cuestan una gema mox obtienen el sello Quebradizo al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] renders the gem cost creature unstable!", "¡[creature] vuelve inestable a la criatura que cuesta una gema!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valuable", "Valioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant an amount of currency when it perishes.", "[creature] proporciona cierta cantidad de moneda cuando muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampiric", "Vampírico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains 1 health.", "Cuando [creature] ataca a una criatura enfrente y esta muere, esta carta obtiene 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Venator", "Venador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it will transform to or from it's alternate form.", "Cuando [creature] mata a otra criatura, cambia entre su forma actual y su forma alternativa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vessel Shedder", "Dejador de receptáculos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil and drop an Empty Vessel in its old place.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello y deja un Receptáculo vacío en el espacio que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Visceral", "Visceral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, any leftover blood that is not used for the sacrifice will be converted into bones.", "Cuando se sacrifica [creature], la sangre sobrante que no se use para el sacrificio se convierte en huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Viva La Revolution", "Viva la revolución", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owners turn, [creature] will revolve all creatures on the board clockwise. Also, [creature] will not attack it's original owner.", "Al comienzo del turno de su propietario, [creature] hace girar en sentido horario a todas las criaturas del tablero. Además, [creature] no ataca a su propietario original.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterbird", "Ave acuática", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] strikes a slot containing a submerged creature, that creature will re-emerge and [creature] will attack it instead of attacking directly.", "Si [creature] golpea un espacio que contiene una criatura sumergida, esta emerge y [creature] la ataca en lugar de atacar directamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wavering Strike", "Golpe oscilante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will alternate between striking to the left or right of where it would otherwise attack at the end of each turn.", "Al final del turno de su propietario, [creature] cambia el lado de sus ataques: estos apuntan alternativamente a la izquierda o a la derecha del espacio que atacaría normalmente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaver", "Tejedor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil and leave a Web in it's old space. [creature] can move back over webs it has placed.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello y deja una Telaraña en el espacio que ocupaba. [creature] puede volver a moverse sobre las telarañas que haya colocado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures in the insect tribe will not attack [creature].", "Las criaturas de la tribu de insectos no atacan a [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weird Latch", "Acople extraño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random latch sigil.", "Cuando se roba [creature], este sello se sustituye por un sello de Acople aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wild Shape", "Forma salvaje", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it transforms based on what gem colours its owner controls.", "Cuando se juega [creature], se transforma según los colores de las gemas que controle su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] transforms based on its owner's gems...", "[creature] se transforma según las gemas de su propietario...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wimpy", "Debilucho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, it will always deal 1 less damage than it should.", "Cuando [creature] inflige daño a una criatura, siempre inflige 1 menos de lo que debería.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wing Clipper", "Cortaalas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent creatures with the Airborne sigil lose the Airborne sigil.", "Cuando se juega [creature], todas las criaturas rivales con el sello Aéreo pierden ese sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] grounds all its opponents!", "¡[creature] hace aterrizar a todos sus rivales!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wingrider", "Jinete alado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a friendly airborne creature is played while [creature] is in the owner's hand, this card will be played adjacent to it.", "Si se juega una criatura aliada con Aéreo mientras [creature] está en la mano de su propietario, esta carta se juega junto a ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodsie Lord", "Señor del bosque", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Enchanted Pines are created on every empty space. An enchanted pine is defined as 0 power, 3 health.", "Cuando se juega [creature], se crean Pinos encantados en todos los espacios vacíos. Un Pino encantado tiene 0 de poder y 3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wriggle", "Retorcerse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played it deals 1 damage to all opponent creatures.", "Cuando se juega [creature], inflige 1 de daño a todas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writhe", "Retorcimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will attack all opposing spaces for 1 damage.", "Cuando [creature] muere, ataca todos los espacios rivales e inflige 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ye filthy dog! Now one o' me maties needs to swab the poop deck!", "¡Perro asqueroso! ¡Ahora uno de mis marineros tendrá que fregar la cubierta de popa!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1d4", "1d4", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil starts at 2, and will become a random number between 1 and 4 at the start of each subsequent turn.", "El valor representado por este sello empieza en 2 y pasa a ser un número aleatorio entre 1 y 4 al comienzo de cada turno posterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power starts at 2, and will become a random number between 1 and 4 at the start of each subsequent turn.", "El poder de [creature] empieza en 2 y pasa a ser un número aleatorio entre 1 y 4 al comienzo de cada turno posterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambitious", "Ambicioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to highest power number present on the board, regardless of whether the card bearing it is friend or foe. Updates at the start of both the player and opponent turn.", "El valor representado por este sello es igual al mayor poder del tablero, tanto si pertenece a una carta aliada como enemiga. Se actualiza al comienzo del turno del jugador y del rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the power of the creature with the highest attack power on the board. Recalculates each turn.", "El poder de [creature] es igual al de la criatura con mayor poder de ataque del tablero. Se recalcula cada turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Plus Two", "Hormigas más dos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of ants on the board, plus two.", "El valor representado por este sello es igual al número de hormigas aliadas en el tablero, más dos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of friendly ants on the board, plus two.", "El poder de [creature] es igual al número de hormigas aliadas en el tablero, más dos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Birds of a Feather", "Aves del mismo plumaje", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of avian tribe creatures on the board, including opponent creatures.", "El valor representado por este sello es igual al número de criaturas de la tribu aviar en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of avian tribe creatures on the board, including opponent creatures.", "El poder de [creature] es igual al número de criaturas de la tribu aviar en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood and Bone", "Sangre y huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the bone cost of the opposing card, or double the blood cost of the opposing card.", "El valor representado por este sello es igual al coste en huesos de la carta de enfrente más el doble de su coste en sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the bone cost of the opposing creature plus twice the blood cost of the opposing creature.", "El poder de [creature] es igual al coste en huesos de la criatura enfrente más el doble de su coste en sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boned", "Osificado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of bones the owner possessed when the bearer was placed. Does not fluctuate with bone count changes post placement.", "El valor representado por este sello es igual al número de huesos que tenía el propietario al colocar la carta portadora. No cambia si la cantidad de huesos varía después de colocarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to the number of bones the owner possessed when it was placed. Does not fluctuate with bone count changes post placement.", "La salud de [creature] es igual al número de huesos que tenía su propietario al colocarla. No cambia si la cantidad de huesos varía después de colocarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Dance", "Baile del cangrejo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of crustacean tribe creatures on the board, including opponent creatures.", "El valor representado por este sello es igual al número de criaturas de la tribu de crustáceos en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of crustacean tribe creatures on the board, including opponent creatures.", "El poder de [creature] es igual al número de criaturas de la tribu de crustáceos en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage Dice", "Dado de daño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil starts at 3, and will become a random number between 1 and 6 at the start of each subsequent turn.", "El valor representado por este sello empieza en 3 y pasa a ser un número aleatorio entre 1 y 6 al comienzo de cada turno posterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power starts at 3, and will become a random number between 1 and 6 at the start of each subsequent turn.", "El poder de [creature] empieza en 3 y pasa a ser un número aleatorio entre 1 y 6 al comienzo de cada turno posterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage Scaling", "Escala de daño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to five minus the amount of damage until you lose the game.", "El valor representado por este sello es igual a cinco menos el daño que te falta para perder la partida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to five minus the amount of damage until you lose the game.", "El poder de [creature] es igual a cinco menos el daño que te falta para perder la partida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Director Of The Board", "Presidente del tablero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards on the board, including opponent cards.", "El valor representado por este sello es igual al número de cartas del tablero, incluidas las cartas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the total number of cards on the board, including opponent creatures.", "El poder de [creature] es igual al número total de cartas del tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawn Out", "Fuerza del robo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards you have drawn this turn while it's bearer is on the board.", "El valor representado por este sello es igual al número de cartas que has robado este turno mientras la carta portadora estaba en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of cards you have drawn this turn while it is on the board.", "El poder de [creature] es igual al número de cartas que has robado este turno mientras estaba en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fabled", "Legendario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of rare creatures on the board.", "El valor representado por este sello es igual al doble del número de criaturas raras del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to twice the number of rare creatures on the board.", "El poder de [creature] es igual al doble del número de criaturas raras del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firepower", "Potencia de fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of creatures on the board with the Burning sigil.", "El valor representado por este sello es igual al número de criaturas del tablero con el sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of creatures on the board with the Burning sigil.", "El poder de [creature] es igual al número de criaturas del tablero con el sello Ardiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Follow The Leader", "Sigue al líder", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the attack power of the first card in your hand.", "El valor representado por este sello es igual al poder de ataque de la primera carta de tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the attack power of the first card in your hand.", "El poder de [creature] es igual al poder de ataque de la primera carta de tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greenhorn", "Novato verde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of Green gems on the owner's side of the board when the bearer was played.", "El valor representado por este sello es igual al doble del número de gemas verdes del lado del tablero del propietario cuando se jugó la carta portadora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to twice the number of Green gems on it's owner's side of the board when it was played.", "La salud de [creature] es igual al doble del número de gemas verdes del lado del tablero de su propietario cuando se jugó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Half Charged", "Media carga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the player's current energy, rounded up.", "El valor representado por este sello es igual a la mitad de la energía actual del jugador, redondeada hacia arriba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to half your current energy, rounded up.", "El poder de [creature] es igual a la mitad de tu energía actual, redondeada hacia arriba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand On Heart", "Mano en el corazón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards in your hand.", "El valor representado por este sello es igual al número de cartas en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to the number of cards in your hand.", "La salud de [creature] es igual al número de cartas en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health Damage", "Daño vital", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to it's bearer's current health.", "El valor representado por este sello es igual a la salud actual de la carta portadora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to its health.", "El poder de [creature] es igual a su salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herding Beast", "Bestia de rebaño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of hooved tribe creatures on the board, including opponent creatures.", "El valor representado por este sello es igual al número de criaturas de la tribu de ungulados en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of hooved tribe creatures on the board, including opponent creatures.", "El poder de [creature] es igual al número de criaturas de la tribu de ungulados en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lithophile", "Litófilo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of terrain cards on the board.", "El valor representado por este sello es igual al número de cartas de terreno del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of terrain cards on the board.", "El poder de [creature] es igual al número de cartas de terreno del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magicke Power", "Poder mágico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of sigils this card has removed with the Bleach Sigil or Artistic License Sigil.", "El valor representado por este sello es igual al número de sellos que esta carta ha eliminado con Lejía o Licencia artística.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of sigils it has removed with the Bleach Sigil or Artistic License Sigil.", "El poder de [creature] es igual al número de sellos que ha eliminado con Lejía o Licencia artística.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Squirrels", "Medias ardillas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the number of Squirrels remaining in your side deck. ", "El valor representado por este sello es igual a la mitad de las Ardillas que quedan en tu mazo secundario. ", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to half the number of Squirrels remaining in your side deck.", "El poder de [creature] es igual a la mitad de las Ardillas que quedan en tu mazo secundario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Hunter", "Cazador de manada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of canine tribe creatures on the board, including opponent creatures.", "El valor representado por este sello es igual al número de criaturas de la tribu canina en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of canine tribe creatures on the board, including opponent creatures.", "El poder de [creature] es igual al número de criaturas de la tribu canina en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Power", "Poder de los objetos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of items the owner holds.", "El valor representado por este sello es igual al número de objetos que tiene el propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of items it's owner holds.", "El poder de [creature] es igual al número de objetos que tiene su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Power Plus", "Poder de los objetos superior", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of items the owner holds.", "El valor representado por este sello es igual al doble del número de objetos que tiene el propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to twice the number of items it's owner holds.", "El poder de [creature] es igual al doble del número de objetos que tiene su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sanguine Bond", "Vínculo sanguíneo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of sacrifices made on the turn when the bearer was placed.", "El valor representado por este sello es igual al número de sacrificios realizados durante el turno en que se colocó la carta portadora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of sacrifices made on the turn when it was placed.", "El poder de [creature] es igual al número de sacrificios realizados durante el turno en que se colocó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sin Eater", "Devorador de pecados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of sigils present on the creatures that were sacrificed to play it's bearer.", "El valor representado por este sello es igual al número de sellos de las criaturas sacrificadas para jugar la carta portadora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the amount of sigils present on the creatures that were sacrificed to play it.", "El poder de [creature] es igual al número de sellos de las criaturas sacrificadas para jugarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved", "Hambriento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to seven minus the number of cards left in your deck.", "El valor representado por este sello es igual a siete menos el número de cartas que quedan en tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to seven minus the number of cards left in your deck.", "El poder de [creature] es igual a siete menos el número de cartas que quedan en tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strength In Numbers", "La unión hace la fuerza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of creatures bearing this sigil on the board, including opponent creatures.", "El valor representado por este sello es igual al número de criaturas del tablero que llevan este sello, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of creatures bearing the same special damage stat on the board, including opponent creatures.", "El poder de [creature] es igual al número de criaturas del tablero con la misma estadística especial de daño, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Vitality", "Vitalidad de los objetos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to double the number of items the owner holds.", "El valor representado por este sello es igual al doble del número de objetos que tiene el propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to twice the number of items it's owner holds.", "La salud de [creature] es igual al doble del número de objetos que tiene su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "World Wide Web", "Red mundial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of arachnid tribe creatures on the board, including opponent creatures.", "El valor representado por este sello es igual al número de criaturas de la tribu de arácnidos en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of arachnid tribe creatures on the board, including opponent creatures.", "El poder de [creature] es igual al número de criaturas de la tribu de arácnidos en el tablero, incluidas las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abstain", "Abstinencia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dupeglitch", "Fallo de duplicación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinister Strike", "Golpe a la izquierda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bully", "Matón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legion", "Legión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodborn", "Nacido de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divination", "Adivinación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhume", "Exhumación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eternal", "Eterno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goated", "Cabruno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healer", "Sanador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] is played, the opponent is obligated to skip their next turn.", "Tras jugarse [creature], el rival debe saltarse su próximo turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, random creatures of the same tribe will be played for free to its left and right.", "Cuando se juega [creature], se juegan gratis a su izquierda y a su derecha criaturas aleatorias de la misma tribu.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, [creature] will draw opposing creatures in front of itself.", "Al comienzo del turno de su propietario, [creature] atrae a las criaturas rivales frente a ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Afterlife", "Más allá", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a spectral copy of it is created in your hand. This copy lacks the Afterlife sigil, is free, and is both Immaterial and Doomed. ", "Cuando [creature] muere, se crea una copia espectral en tu mano. La copia carece del sello Más allá, es gratuita y tiene Inmaterial y Condenado. ", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Resistant", "Resistente a explosiones", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] would take 10 or more damage from a single source, it takes 1 damage instead.", "Si [creature] fuera a recibir 10 o más de daño de una sola fuente, recibe 1 de daño en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lanky", "Larguirucho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage directly to the opponent, it will always deal 1 less damage than it should.", "Cuando [creature] inflige daño directamente al rival, siempre inflige 1 menos de lo que debería.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peer Pressure", "Presión de grupo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent occupied space.", "[creature] obtiene +1 de poder por cada espacio adyacente ocupado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy", "Saludable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice [creature] to increase the health of a creature of your choosing by 4.", "Sacrifica [creature] para aumentar en 4 la salud de una criatura que elijas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micromachine", "Micromáquina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vagrant Spirit", "Espíritu errante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endoskeleton", "Endoesqueleto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletal Beast", "Bestia esquelética", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buttress", "Contrafuerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil a number of times equal to how many times it damaged another creature this turn.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello tantas veces como haya infligido daño a otra criatura durante este turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not strike another creature during its turn, it will perish at the start of the owner's next turn.", "Si [creature] no golpea a otra criatura durante su turno, muere al comienzo del siguiente turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unnatural Contraption", "Artefacto antinatural", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unnatural Cadaver", "Cadáver antinatural", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrot On A Stick", "Zanahoria en un palo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind Controller", "Controlador mental", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycology", "Micología", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, opposing creatures are drawn into its slot. If two creatures are drawn into the same slot this way, they become merged.", "Cuando [creature] muere en combate, las criaturas rivales son atraídas a su espacio. Si dos criaturas son atraídas así al mismo espacio, se fusionan.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutate", "Mutación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] destroys another creatre, this gains 1 point. When activated, the owner is presented with a choice of three sigils to augment the card til the end of battle. Selecting a sigil spends points, and the more points accumulated when the sigil is activated, the higher quality the presented sigils will be.", "Cuando [creature] destruye otra criatura, este sello obtiene 1 punto. Al activarlo, su propietario elige uno de tres sellos propuestos para mejorar la carta hasta el final de la batalla. La elección cuesta puntos; cuantos más haya acumulados al activarlo, mayor será la calidad de los sellos ofrecidos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raise Undead", "Alzar a los no muertos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw 3 skeletons from your side deck to your hand.", "Cuando se juega [creature], roba 3 esqueletos de tu mazo secundario y añádelos a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Growth Factor", "Factor de crecimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature is played opposing [creature], this card gains health equal to that creature's health.", "Cuando otra criatura se juega frente a [creature], esta carta obtiene tanta salud como la de esa criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shuffle", "Mezcla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, every card on the board is shuffled into a random space.", "Cuando se juega [creature], todas las cartas del tablero se mezclan y se reparten en espacios aleatorios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambidextrous", "Ambidiestro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, you draw an additional card at the start of your turn.", "Mientras [creature] esté en el tablero, robas una carta adicional al comienzo de tu turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Dependant", "Dependencia de circuito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is not within a completed circuit, it will perish.", "Si [creature] no está dentro de un circuito completo, muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rapid", "Rápido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move as far as possible in the direction inscribed in the sigil.", "Al final del turno de su propietario, [creature] se mueve lo más lejos posible en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resistance", "Resistencia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a completed circuit, it adds 1 power to the conduits making up the circuit.", "Mientras [creature] esté dentro de un circuito completo, añade 1 de poder a los conductos que lo forman.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dig Deep", "Cavar hondo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 bone. This number increases by 1 when [creature] kills another creature.", "Al final del turno de su propietario, [creature] genera 1 hueso. Esta cantidad aumenta en 1 cuando [creature] mata a otra criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Startled", "Sobresaltado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], this card will transform to or from it's alternate form.", "Cuando una criatura se mueve al espacio frente a [creature], esta carta cambia entre su forma actual y su forma alternativa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflexive", "Reflejo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When its owner is dealt damage directly, [creature] will transform to or from it's alternate form.", "Cuando su propietario recibe daño directo, [creature] cambia entre su forma actual y su forma alternativa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talons", "Garras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, choose any card on the board. You may move it to any open space on the same side of the board.", "Cuando se juega [creature], elige cualquier carta del tablero. Puedes moverla a cualquier espacio libre del mismo lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycobeast", "Micobestia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycodaver", "Micocadáver", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Endoskeleton", "Endoesqueleto esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Endoskeleton", "Endoesqueleto rubí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Endoskeleton", "Endoesqueleto zafiro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may add to a bond, but provides no additional effect.", "[creature] puede contribuir a un vínculo, pero no aporta ningún efecto adicional.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that are a part of a bond containing [creature] will gain flight at the start of each turn.", "Las criaturas que forman parte de un vínculo que incluye a [creature] obtienen vuelo al comienzo de cada turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that are a part of a bond containing [creature] will heal equal to the number of cards in the bond at the start of the owners turn.", "Al comienzo del turno del propietario, las criaturas que forman parte de un vínculo que incluye a [creature] recuperan tanta salud como cartas haya en el vínculo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed bond, fill all empty spaces on the same side of the board with squirrels at the end of turn.", "Si [creature] forma parte de un vínculo completo, al final del turno todos los espacios vacíos del mismo lado del tablero se llenan de ardillas.", Language.Spanish);
        }
    }
    public class AllTheSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AllTheSigils Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Puddle", "Charco de ácido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A puddle of Acid, dangerous to the touch", "Un charco de ácido, peligroso al tacto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jackalope", "Liebrílope", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jacka", "Jacka", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abundance", "Abundancia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant one tooth per instance of Abundance when killed.", "Cuando se mata a [creature], proporciona un diente por cada instancia de Abundancia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acidic Trail", "Rastro ácido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, and deal 1 damage to the opposing creature if it is able to move.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello y, si puede moverse, inflige 1 de daño a la criatura enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Brittle", "Acople activado de Quebradizo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy will allow the owner to give a creature Brittle.", "Al activarse por 1 de energía, el propietario puede otorgar Quebradizo a una criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Explode On Death", "Acople activado de Detonador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy will allow the owner to give a creature Explode On Death.", "Al activarse por 2 de energía, el propietario puede otorgar Detonador a una criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Nano Shield", "Acople activado de Acorazado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy / 2 bones will allow the owner to give a creature Nano Shield.", "Al activarse por 1 de energía / 2 huesos, el propietario puede otorgar Acorazado a una criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Reach", "Acople activado de Salto poderoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 2 energy will allow the owner to give a creature Reach.", "Al activarse por 2 de energía, el propietario puede otorgar Salto poderoso a una criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Agile", "Ágil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, it will move out of the way.", "Cuando [creature] está a punto de recibir un golpe, se aparta para esquivarlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Card jumped out of the way to save itself...", "La carta saltó a un lado para salvarse...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trail they leave behind, hurts.", "El rastro que dejan detrás duele.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All seeing", "Omnividente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all talking cards on your side of the board get +2 health.", "Mientras [creature] esté en el tablero, todas las cartas parlantes de tu lado del tablero obtienen +2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Scratch", "Arañazo alterno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack a space adjacent to the attacked slot, the adjacent slot that it will attack will change between left or right at the end of each opponent's turn.", "Cuando [creature] ataca, también golpea un espacio adyacente al atacado. Ese espacio adyacente alterna entre izquierda y derecha al final de cada turno rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambush", "Emboscada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Cuando una criatura se mueve al espacio frente a [creature], recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antler Bearer", "Portador de astas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is killed, gain three random hooved tribe cards.", "Cuando se mata a [creature], obtienes tres cartas aleatorias de la tribu de ungulados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The herd sticks together.", "El rebaño permanece unido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shielded", "Protegido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is dealt damage, the damage dealt is halved, rounded down.", "Cuando [creature] recibe daño, este se reduce a la mitad y se redondea hacia abajo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asleep", "Dormido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has 0 attack for as long as it has this sigil, at the start of the player's turn this sigil will be removed from [creature].", "[creature] tiene 0 de ataque mientras tenga este sello. Al comienzo del turno del jugador, este sello se elimina de [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bait", "Cebo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is played and there is no card opposite of [creature], the opposing creature will move to that spot.", "Cuando se juega una criatura rival y no hay ninguna carta frente a [creature], esa criatura se mueve a ese espacio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noble Sacrifice", "Sacrificio noble", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is counted as 2 blood rather than 1 blood when sacrificed.", "Cuando se sacrifica [creature], cuenta como 2 de sangre en lugar de 1 de sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blight", "Azote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it subtracts its stat values to the card it was sacrificed for.", "Cuando se sacrifica [creature], sus estadísticas se restan de las de la carta para la que se sacrificó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Strike", "Golpe aleatorio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike at opponent slots randomly when it attacks.", "Cuando ataca, [creature] golpea espacios rivales al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blinding Strike", "Golpe cegador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Random Strikes Sigil.", "Cuando [creature] inflige daño a otra criatura, esta obtiene el sello Golpe aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They strike widly...", "Sus golpes van en todas direcciones...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Growth", "Crecimiento sanguíneo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, the amount of blood it is counted as when sacrificed will increase.", "Cuando [creature] ataca, aumenta la cantidad de sangre por la que cuenta al sacrificarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is power in the blood.", "Hay poder en la sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BloodGuzzler", "Bebedor de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals damage, it gains 1 Health for each damage dealt.", "Cuando [creature] inflige daño, obtiene 1 de salud por cada punto de daño infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain life from the blood.", "Obtén vida de la sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood shifter", "Cambiaformas sanguíneo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another card, it will turn into that card.", "Cuando [creature] mata a otra carta, se transforma en esa carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bodyguard", "Guardaespaldas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will redirect the initial attack of a card to it, if the attack was targeting a card in an adjacent space.", "Si el primer ataque de una carta apunta a una carta en un espacio adyacente, se redirige hacia [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A protector, till the very end.", "Un protector hasta el final.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier", "Bombardero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 10 damage to a random creature during the end phase of the owner's turn.", "Al final del turno de su propietario, [creature] inflige 10 de daño a una criatura aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bond", "Vínculo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any creatures adjacent to [creature] will gain either +1 attack or +1 health, depending on which stat it is closest to.", "[creature] obtiene +1 de poder si tiene una carta justo a su izquierda y +1 de salud si tiene una carta justo a su derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives no bones! Any bones gained from sigils or death will be negated.", "¡[creature] no da huesos! Se anulan todos los huesos obtenidos por sellos o por su muerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature has no bones!", "¡Esa criatura no tiene huesos!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Picker", "Recogehuesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] kills a creature, it will generate 1 Bone.", "Cuando [creature] mata a una criatura, genera 1 hueso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shard", "Astilla de hueso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will generate 1 bone when hit, if it lives through the attack.", "Cuando [creature] recibe un golpe, genera 1 hueso si sobrevive al ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A splinter of bone.", "Una astilla de hueso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box", "Caja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get removed from your deck on death, and a new creature contained within will be added to it.", "Cuando [creature] muere, se retira de tu mazo y se añade a él una nueva criatura contenida en ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken", "Roto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is permanently removed from your deck if it dies.", "Si [creature] muere, se elimina de tu mazo de forma permanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is on fire, and will gain 1 power and loose 1 health each upkeep. Blocked by Fire Resistance.", "[creature] está ardiendo: al comienzo del turno de su propietario obtiene 1 de poder y pierde 1 de salud. Resistente al fuego impide este efecto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rampages while on fire.", "Se desata mientras arde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the towner's turn, [creature] will move in the direction inscribed in the sigil, and drop an acid puddle in their old space.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello y deja un Charco de ácido en el espacio que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as a Chicken.", "[creature] cuenta como una Gallina.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choreography", "Coreografía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On activation [creature] will cycle through: don't move, move left and move right. At the end of the owner's turn [creature] will move in the chosen way.", "Al activarse, [creature] alterna entre quedarse quieta, moverse a la izquierda y moverse a la derecha. Al final del turno de su propietario, [creature] se mueve según la opción elegida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coin Finder", "Buscador de monedas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will grant the owner 1 foil.", "Al final del turno de su propietario, [creature] le proporciona 1 unidad de moneda.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tooth for your thoughts?", "¿Un diente por tus pensamientos?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Consumer", "Consumidor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it gains 2 health.", "Cuando [creature] mata a otra criatura, obtiene 2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly", "Cobarde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack a card with a power 2 higher than its own.", "[creature] no ataca a una carta cuyo poder supere al suyo en más de 2.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadly Waters", "Aguas mortales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will kill cards that attacked over it while it was face-down. Does not affect cards that have Airborne or Made of Stone.", "[creature] mata a las cartas que atacaron por encima de ella mientras estaba boca abajo. No afecta a las cartas con Aéreo o Hecho de piedra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathburst", "Explosión mortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 1 damage to each oppsing space to the left, right, and center of it.", "Cuando [creature] muere, inflige 1 de daño a cada criatura en el espacio de enfrente y en los espacios a izquierda y derecha de este.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the Start of its owner's turn [creature] will lose -1 attack and will gain +1 health.", "Al comienzo del turno de su propietario, [creature] pierde 1 de ataque y obtiene +1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperation", "Desesperación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is damaged to 1 health, it will gain 3 power.", "Cuando el daño reduce a [creature] a 1 de salud, obtiene 3 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When so close to death, it strikes out.", "Tan cerca de la muerte, arremete.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disease Absorbtion", "Absorción de enfermedades", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, [creature] will take all negative sigils onto itself.", "Cuando se juega [creature], absorbe los sellos negativos de las demás cartas del mismo lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How Noble.", "Qué nobleza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dive (Bones)", "Inmersión de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to cause this card to flip face down at the end of the owner's turn.", "Paga 2 huesos para poner esta carta boca abajo al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dive (Energy)", "Inmersión de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to cause this card to flip face down at the end of the owner's turn.", "Paga 2 de energía para poner esta carta boca abajo al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multi-Strike", "Golpe múltiple", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a card multiple times, if it lives through the first attack. Will not trigger -on attack- or -on damage- effects with the extra strikes.", "[creature] golpea una carta varias veces si esta sobrevive al primer ataque. Los golpes adicionales no activan efectos de ataque ni de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double scratch", "Doble arañazo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it attacks twice and the space right and left of the attacked slot.", "Cuando [creature] ataca, golpea dos veces y también golpea los espacios a derecha e izquierda del atacado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Blood", "Robo de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing blood is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta aleatoria que cuesta sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Bone", "Robo de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing bone is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta aleatoria que cuesta huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Card", "Robo de carta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a card relating to it's ice cube parameter (default Stoat) is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta relacionada con su parámetro Cubo de hielo, por defecto un Armiño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Jackalope", "Robo de Liebrílope", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Jackalope is created in your hand.", "Cuando se juega [creature], se crea un Liebrílope en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Strafe", "Robo en movimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] moves, a random card with a movement sigil is created in your hand.", "Cuando [creature] se mueve, se crea en tu mano una carta aleatoria con un sello de movimiento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Cost", "Robo por coste", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card that has the same cost type as [creature] is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta aleatoria con el mismo tipo de coste que [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Energy", "Robo de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing energy is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta aleatoria que cuesta energía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Mox", "Robo mox", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing mox is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta aleatoria que cuesta mox.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Support call", "Llamada de apoyo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a card from your sidedeck is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta de tu mazo secundario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drunk", "Ebrio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a random one of the opposing spaces to the left and right of the space across from it.", "[creature] golpea al azar uno de los espacios rivales a izquierda o derecha del que tiene enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dwarf", "Enano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it will loose one unit of cost, as well as 1 power and 2 health (can't go below 1 health). A unit is defined as: 1 blood, 3 bones, 3 energy, or all mox.", "Cuando se roba [creature], pierde una unidad de coste, 1 de poder y 2 de salud, sin bajar de 1 de salud. Una unidad equivale a 1 de sangre, 3 huesos, 3 de energía o todos los mox requeridos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dying", "Moribundo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will die after X number of turns.", "[creature] muere después de X turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To The Slaughter", "Al matadero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] will eat a random Chicken gaining the same amount of attack as the eaten chicken's health, and gaining the same amount of health as the eaten chicken's attack.", "Al final de cada turno, [creature] se come una Gallina aleatoria y obtiene tanto ataque como salud tenía la gallina y tanta salud como ataque tenía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric", "Guía eléctrica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] decalres an attack, they will deal half the damage to cards adjacent to the target.", "Cuando [creature] declara un ataque, inflige la mitad del daño a las cartas adyacentes al objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enforcer", "Ejecutor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will cause adjacent creatures to attack.", "Al comienzo del turno de su propietario, [creature] hace que las criaturas adyacentes ataquen.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enrage", "Líder sobreacelerado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will empower adjacent allies, increasing their strenght by 2. However, if they perish while empowered, they are permamently removed from your deck.", "[creature] potencia a los aliados adyacentes y aumenta su poder en 2. Si mueren mientras están potenciados, se eliminan de tu mazo de forma permanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entomophage", "Entomófago", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 2 additional damage to cards of the insect tribe.", "[creature] inflige 2 de daño adicional a las cartas de la tribu de insectos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are a good source of protine I hear.", "He oído que son una buena fuente de proteínas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar will help with attacking when it's adjacent allies attack a card.", "Un familiar ayuda a atacar cuando sus aliados adyacentes atacan una carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearful", "Temeroso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck without it resulting in death, it will be returned to its owner's hand.", "Cuando [creature] recibe un golpe sin morir, regresa a la mano de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charge", "Carga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 bones to choose an enemy creature that [creature] will strike.", "Paga 3 huesos para elegir una criatura enemiga a la que [creature] golpeará.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "Incendiario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature will gain the Burning Sigil. The Burning Sigil is define as: Each upkeep, this creature gains 1 strength but looses 1 health.", "Cuando [creature] inflige daño a otra criatura, esta obtiene el sello Ardiendo. Al comienzo del turno de su propietario, una criatura con Ardiendo obtiene 1 de poder pero pierde 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves a deadly mark", "Incluso cuando termina la batalla, deja una marca mortal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lure", "Señuelo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause facedown cards to become face up when attacking.", "Al atacar, [creature] hace que las cartas boca abajo se pongan boca arriba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Submerge are brought back to the surface", "Las criaturas sumergidas vuelven a la superficie.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature], a targeted card is moved to the owner's side of the board.", "Cuando se coloca [creature], su propietario elige una carta rival y la mueve a su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone lord 5", "Señor de los huesos 5", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 5 bones are rewarded instead of 1.", "Cuando [creature] muere, se otorgan 5 huesos en lugar de 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frightened", "Asustado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], [creature] will move away from that card to a random free adjacent spot, while prioritizing slots without any opposing creatures.", "Cuando una criatura se mueve al espacio frente a [creature], [creature] se aleja a un espacio adyacente libre aleatorio, priorizando los espacios sin criaturas enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frightful", "Aterrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause opposing creatures to move out of the way when it attacks.", "Al atacar, [creature] hace que las criaturas enfrente se aparten.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it will gain one unit blood of cost, as well as one attack and two health.", "Cuando se roba [creature], su coste aumenta una unidad de sangre y obtiene un punto de ataque y dos de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a large creature you have there", "¡Qué criatura tan grande tienes ahí!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grazing", "Pastoreo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 1 health if there is no opposing creature.", "Al final del turno de su propietario, [creature] recupera 1 de salud si no tiene una criatura enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 1 Health at the end of it's owner's turn.", "Esta criatura recupera 1 de salud al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gripper", "Agarrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, and try to move the opposing creature with it if it can.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello e intenta mover con ella a la criatura enfrente si puede.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trail they leave behind, hurts.", "El rastro que dejan detrás duele.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haste", "Prisa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack as soon as it gets played on the board if played not during combat.", "[creature] ataca en cuanto se juega en el tablero, siempre que no se juegue durante el combate.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasteful", "Impaciente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack as soon as it gets played on the board. It will not attack during normal combat. It will attack at the start of the owner's turn.", "[creature] ataca en cuanto se juega en el tablero. No ataca durante el combate normal, sino al comienzo del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herd", "Rebaño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will summon a copy of itself each upkeep, up to three times.", "Al comienzo del turno de su propietario, [creature] invoca una copia de sí misma en un espacio vacío aleatorio del mismo lado, hasta tres veces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hermit", "Ermitaño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be placed on any terrain card. If it is their sigils and stats will be combined, and a name combination will be created.", "[creature] puede colocarse sobre cualquier carta de terreno. En ese caso, se combinan sus sellos y estadísticas y se fusionan sus nombres.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Tide", "Marea alta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, it will grant the waterborne sigil of cards that are played after it on it's side of the board. Does not affect cards that are Airborne.", "Mientras [creature] esté en el tablero, otorga el sello Acuático a las cartas que se jueguen después en su lado del tablero. No afecta a las cartas con Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waters rise.", "Las aguas suben.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homing", "Persecución", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the opposing slot is empty, and there is a creature in a neighbouring lane, [creature] will attack that creature instead of attacking the opposing slot.", "Si el espacio de enfrente está vacío y hay una criatura en un carril vecino, [creature] ataca a esa criatura en lugar del espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoodini", "Houdini", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will swap places with the opposing creature.", "Cuando se juega [creature], intercambia su lugar con la criatura enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Host", "Nido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is the host of other creatures. It will give you such creature when struck.", "[creature] alberga a otras criaturas. Cuando recibe un golpe, te da una de ellas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause the opponant to skip their turn when played.", "Cuando se juega [creature], el rival se salta su próximo turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time tic away", "La arena del tiempo se agota.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhaustion", "Agotamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The attack of [creature] will be decreased by the same amount as its lost health.", "El ataque de [creature] se reduce en una cantidad igual a la salud que ha perdido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hyped", "Entusiasmado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack at the start of the owner's turn in addition to during normal combat.", "[creature] ataca al comienzo del turno de su propietario además de durante el combate normal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbuing", "Imbución", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get specific buffs depending on which tribe is most promenent in the sacrifices that were used to summon it.", "[creature] obtiene mejoras específicas según la tribu más representada entre los sacrificios usados para invocarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inaccurate", "Impreciso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a random one of the opposing spaces to the left and right of the spaces across from it as well as the space in front of it.", "[creature] golpea al azar uno de los espacios enfrente o a izquierda y derecha de este.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Timer", "Vieja guardia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the Start of its owner's turn [creature] will gain +1 attack and will take 1 damage.", "Al comienzo del turno de su propietario, [creature] obtiene +1 de ataque y recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Injured", "Herido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is hurt and will lose 1 health each time it declares an attack due to the strain of the injuries.", "[creature] está herida y pierde 1 de salud cada vez que declara un ataque por el esfuerzo de sus heridas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instant", "Instantáneo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will perish immediately after its played.", "[creature] muere inmediatamente después de jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launcher", "Lanzador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will create another creature on a random empty space on the owner's side of the table.", "Al final del turno de su propietario, [creature] crea otra criatura en un espacio vacío aleatorio del lado del tablero de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lead (Bones)", "Guía de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to move this card one slot in the direction inscribed on the sigil.", "Paga 2 huesos para mover esta carta un espacio en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "one can lead  a horse to water...", "Se puede llevar un caballo al agua...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lead (Energy)", "Guía de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to move this card one slot in the direction inscribed on the sigil.", "Paga 2 de energía para mover esta carta un espacio en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leech", "Sanguijuela", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it will heal 1 Health for each damage dealt to a card.", "Cuando [creature] inflige daño a una carta, recupera 1 de salud por cada punto de daño infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigor from blood!", "¡Vigor de la sangre!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left scratch", "Arañazo izquierdo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack the space on the left of the attacked slot.", "Cuando [creature] ataca, también golpea el espacio a la izquierda del atacado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Gambler", "Apostador de vida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 2 damage to the owner in exchange for a 0 to 6 increase in stats. Failing to pay this cost will result in death.", "Al final del turno de su propietario, [creature] obtiene de 0 a 5 puntos repartidos al azar entre ataque y salud y después inflige 2 de daño al jugador. Este daño puede hacerte perder la partida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your blood, their strength!", "¡Tu sangre, su fuerza!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Linguist", "Lingüista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all talking cards on your side of the board get +1 attack.", "Mientras [creature] esté en el tablero, todas las cartas parlantes de tu lado del tablero obtienen +1 de ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Low Tide", "Marea baja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, it will negate the waterborne sigil of cards that are played after it on it's side of the board.", "Mientras [creature] esté en el tablero, anula el sello Acuático de las cartas que se jueguen después en su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lullaby", "Nana", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all opposing creatures gain the asleep sigil.", "Cuando [creature] muere, todas las criaturas rivales obtienen el sello Dormido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maneuver", "Maniobra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will strafe in the direction inscribed on the sigil if there is a creature in the opposing slot from it. Else it will strafe in the opposite direction inscribed on the sigil.", "Al comienzo del turno de su propietario, [creature] se mueve en la dirección indicada en el sello si hay una criatura en el espacio de enfrente. De lo contrario, se mueve en la dirección opuesta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It runs", "Corre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medic", "Médico militar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will try heal 1 damage to a friendly card for each instance of Medic.", "Al comienzo del turno de su propietario, [creature] elige al azar otra carta aliada e intenta curarle 1 de salud por cada instancia de Médico militar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A good patching", "Una buena cura", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medical Aid", "Ayuda médica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, choose a hurt creature on the owner's side to heal for 1.", "Al final del turno rival, elige una criatura herida del lado del propietario y cúrale 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas", "Don de Midas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] kills a creature, it will generate 1 Foil for each instance of Midas the card has.", "Cuando [creature] mata a una criatura, genera 1 unidad de moneda por cada instancia de Don de Midas que tenga.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bounty, paid in full.", "Una recompensa pagada por completo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mount", "Soporte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards may be played on top of [creature]. If they are their sigils and stats will be combined, and a name combination will be created.", "Se pueden jugar cartas sobre [creature]. En ese caso, se combinan sus sellos y estadísticas y se fusionan sus nombres.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power from Movement", "Poder del movimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will gain 1 power and 1 health if it moved last round.", "Al comienzo del turno de su propietario, [creature] obtiene 1 de poder y 1 de salud si se movió en la ronda anterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each move, it grows", "Crece con cada movimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurse", "Enfermera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, [creature] will heal any adjacent friendly cards.", "Al final del turno rival, [creature] cura a las cartas aliadas adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nutritious", "Nutritivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it adds 1 power and 2 health to the card it was sacrificed for.", "Cuando se sacrifica [creature], añade 1 de poder y 2 de salud a la carta para la que se sacrificó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature is so full of nutrients, the creature you play comes in stronger!", "¡Esa criatura es tan nutritiva que la criatura que juegas llega más fuerte!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 1", "Don de huesos 1", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 1 bone is rewarded.", "Cuando se juega [creature], se otorga 1 hueso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opportunist", "Oportunista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 1 power for each instance of Opportunist, when the opposing slot is empty.", "Cuando el espacio de enfrente está vacío, [creature] obtiene 1 de poder por cada instancia de Oportunista.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It takes it's chance when it gets it.", "Aprovecha la oportunidad cuando se presenta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralysis", "Parálisis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only attack every other turn. Some effects from sigils may bypass this.", "[creature] solo ataca en turnos alternos. Algunos efectos de sellos pueden eludir esta restricción.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shocking event.", "Un suceso impactante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite", "Parásito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be placed on top of any card. If it is their sigils and stats will be combined, and a name combination will be created.", "[creature] puede colocarse sobre cualquier carta. En ese caso, se combinan sus sellos y estadísticas y se fusionan sus nombres.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pathetic Sacrifice", "Sacrificio lamentable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is so pathetic, it is not a worthy or noble sacrifice. [creature] is meant to stay on the board, and thus can't be targeted by the hammer.", "[creature] es demasiado lamentable para ser sacrificada. [creature] debe permanecer en el tablero y por tanto no puede ser objetivo del martillo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is not a noble, or worthy sacrifice", "Ese sacrificio no es noble ni digno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky", "Exigente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannnot be summoned by using any free cards as sacrifice.", "[creature] no puede invocarse usando cartas gratuitas como sacrificio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pierce", "Perforación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks the card in queue behind it's initial target first when declaring an attack.", "Cuando declara un ataque, [creature] golpea primero la carta en espera detrás de su objetivo inicial.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My creatures!", "¡Mis criaturas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poisonous", "Venenoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature that killed it perishes as well.", "Cuando [creature] muere, también muere la criatura que la mató.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacking something poisonous, isn't that smart.", "Atacar algo venenoso no es muy inteligente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessor", "Poseedor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will grant a random friendly card that is on the board it's base power and health.", "Cuando [creature] muere, otorga su poder y salud base a otra carta aliada aleatoria del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It passes it's strength onto those who remain", "Transmite su fuerza a quienes quedan", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerful Possessor", "Poseedor poderoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will grant a random friendly card that is on the board it's base plus modified power and base plus modified health.", "Cuando [creature] muere, otorga su poder y salud base con sus modificadores a otra carta aliada aleatoria del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Predator", "Depredador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 1 power for each instance of Predator, when the opposing slot has a card.", "Cuando el espacio de enfrente contiene una carta, [creature] obtiene 1 de poder por cada instancia de Depredador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prideful", "Orgulloso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack a card with a power 2 lower than its own.", "[creature] no ataca a una carta cuyo poder sea inferior al suyo en más de 2.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature's pride will be it's downfall.", "El orgullo de una criatura será su perdición.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "Protector", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attacks on adjacent allies to hit directly.", "Los ataques contra los aliados adyacentes a [creature] golpean directamente a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They protect their allies, but who protects you?", "Protegen a sus aliados, pero ¿quién te protege a ti?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppets gift", "Regalo de la marioneta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is on the board any cards with brittle won't die because of brittle.", "Mientras [creature] esté en el tablero, las cartas con Quebradizo no mueren por ese sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Superior Sacrifice", "Sacrificio superior", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is counted as 4 blood rather than 1 blood when sacrificed.", "Cuando se sacrifica [creature], cuenta como 4 de sangre en lugar de 1 de sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ram", "Carnero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will try to ram the card infront of it when played, or every upkeep till it succeeds once. It will send the rammed target to the queue if on my side, or back to the hand if on your side. Does not work during combat.", "Al jugarse [creature] y luego al comienzo del turno de su propietario hasta que lo consiga una vez, intenta embestir a la carta enfrente. Si la carta portadora está en tu lado, el objetivo vuelve a la fila de espera; si la carta portadora está en el lado rival, vuelve a la mano. No funciona durante el combate.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moving creatures around? How Rude!", "¿Mover criaturas? ¡Qué mala educación!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Strafe", "Carrera aleatoria", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is drawn, it will gain a random strafe sigil.", "Cuando se roba [creature], obtiene un sello de movimiento aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How will it move?", "¿Cómo se moverá?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recoil", "Retroceso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will take 1 damage each time they attack.", "[creature] recibe 1 de daño cada vez que ataca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The strength causes the creature pain.", "La fuerza causa dolor a la criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 1", "Regeneración 1", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 1 health.", "Al final del turno de su propietario, [creature] recupera 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 1 Health at the end of it's owner's turn.", "Esta criatura recupera 1 de salud al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 2", "Regeneración 2", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 2 health.", "Al final del turno de su propietario, [creature] recupera 2 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 2 Health at the end of it's owner's turn.", "Esta criatura recupera 2 de salud al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 3", "Regeneración 3", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 3 health.", "Al final del turno de su propietario, [creature] recupera 3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 3 Health at the end of it's owner's turn.", "Esta criatura recupera 3 de salud al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen", "Regeneración completa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen to full health.", "Al final del turno de su propietario, [creature] recupera toda su salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal to full Health at the end of it's owner's turn.", "Esta criatura recupera toda su salud al final del turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repellant", "Repelente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature that killed it gets pushed into the back row.", "Cuando [creature] muere, la criatura que la mató es empujada a la fila trasera.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resistant", "Resistente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only ever take 1 damage from most things. Some effects might bypass this.", "[creature] normalmente solo recibe 1 de daño de la mayoría de las fuentes. Algunos efectos pueden eludir esta protección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hardy creature that one is.", "Esa sí que es una criatura resistente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resourceful", "Rico en recursos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, instead of dying, it loses a random sigil. Resourceful will only remove itself when there are no other sigils on the card.", "Cuando se sacrifica [creature], no muere, sino que pierde un sello aleatorio. Rico en recursos solo se elimina a sí mismo cuando la carta no tiene otros sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retaliate", "Represalia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike those who strike their adjacent allies.", "[creature] golpea a quienes atacan a sus aliados adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right scratch", "Arañazo derecho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack the space on the right of the attacked slot.", "Cuando [creature] ataca, también golpea el espacio a la derecha del atacado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rushing march", "Marcha apresurada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil, however if it hits a card whilst moving, [creature] will stop and the card it hit will perish.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Si [creature] encuentra una carta al moverse, se detiene y la carta encontrada muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Schooling", "Banco de peces", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant creatures with the waterborn 1 power.", "[creature] otorga 1 de poder a las criaturas con el sello Acuático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waterborn stick together.", "Las criaturas acuáticas permanecen unidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a targeted card cut in two.", "Cuando se juega [creature], una carta objetivo se corta en dos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My card!", "¡Mi carta!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shapeshifter", "Cambiaformas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is ever changing. It will change its form once it's struck.", "[creature] cambia constantemente. Cambia de forma cuando recibe un golpe.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short", "Pequeño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not be blocked by an opposing creature bearing the airborn sigil.", "[creature] no puede ser bloqueada por una criatura enfrente con el sello Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sickness", "Enfermedad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will loose 1 attack each time it declares an attack.", "[creature] pierde 1 de ataque cada vez que declara un ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature's strength leaves it as it strikes.", "La fuerza abandona a la criatura al golpear.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone lord 6", "Señor de los huesos 6", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 6 bones are rewarded instead of 1.", "Cuando [creature] muere, se otorgan 6 huesos en lugar de 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluggish", "Lento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack during normal combat. It will instead attack after the Opponent's cards attack.", "[creature] no ataca durante el combate normal. En su lugar, ataca después de que lo hagan las cartas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bit slow there eh?", "Un poco lento, ¿eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Song of sleep", "Canción de sueño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a creature moves into the space opposing [creature], that creature will obtain the asleep sigil.", "Si una criatura se mueve al espacio frente a [creature], obtiene el sello Dormido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawner", "Generador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil and will create another creature in its old space.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello y crea otra criatura en el espacio que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stampede", "Estampida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause adjacent creatures to attack when played on the board if played not during combat.", "Cuando [creature] se coloca en el tablero fuera del combate, hace que las criaturas adyacentes ataquen.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power in Numbers", "La unión hace la fuerza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky", "Pegajoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the card opposing [creature] moves, [creature] will try to move with it", "Si la carta frente a [creature] se mueve, [creature] intenta moverse con ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocity", "Velocidad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. If it is able to move, it will gain 1 power and 1 health.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Si puede moverse, obtiene 1 de poder y 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Wind", "Viento fuerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is on the board, negate the airbone sigil of all cards that are played after it.", "Mientras [creature] esté en el tablero, anula el sello Aéreo de todas las cartas que se jueguen después.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Wind forces a landing.", "El viento obliga a aterrizar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerged Ambush", "Emboscada sumergida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 1 damage to cards that attacked over it while it was face-down. Does not affect cards that are Airborne.", "[creature] inflige 1 de daño a las cartas que atacaron por encima de ella mientras estaba boca abajo. No afecta a las cartas con Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strikes from the water.", "Golpea desde el agua.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swallower", "Devorador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] attacks, it will destroy the card it attacks if it has less health than it and heal to full health.", "Cuando [creature] inflige daño a una carta que sobrevive con menos salud que ella, la destruye y recupera toda su salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gone in one gulp.", "Desapareció de un solo bocado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sympathetic", "Compasivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only attack if the opposing creature has more or equal health to it.", "[creature] solo ataca si la criatura enfrente tiene tanta o más salud que ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take-Off (Bones)", "Despegue de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to give this card Airborne till the start of owner's next turn.", "Paga 2 huesos para dar Aéreo a esta carta hasta el comienzo del siguiente turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spread your wings and fly.", "Extiende tus alas y vuela.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take-Off (Energy)", "Despegue de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to give this card Airborne till the start of the owner's next turn.", "Paga 2 de energía para dar Aéreo a esta carta hasta el comienzo del siguiente turno de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrified", "Aterrorizado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], [creature] will move away from that card to a random free adjacent spot while pushing any creatures in it's way, while prioritizing slots without any opposing creatures.", "Cuando una criatura se mueve al espacio frente a [creature], [creature] se aleja a un espacio adyacente libre aleatorio, empujando a las criaturas de su camino y priorizando los espacios sin criaturas enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thick Shell", "Caparazón grueso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, [creature] takes 1 less damage.", "Cuando [creature] es atacada, recibe 1 menos de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick shell on that creature protected it from one damage!", "¡El caparazón grueso de esa criatura la protegió de un punto de daño!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will try to steal a random default sigil from a card in the opposing lane when played, or at the start of the owner's turn until it does.", "Al jugarse y luego al comienzo del turno de su propietario hasta conseguirlo, [creature] intenta robar un sello básico aleatorio de una carta del carril de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If only I could steal the moon...", "Si tan solo pudiera robar la luna...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone prince 3", "Príncipe de los huesos 3", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 3 bones are rewarded instead of 1.", "Cuando [creature] muere, se otorgan 3 huesos en lugar de 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 3", "Don de huesos 3", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 3 bones are rewarded.", "Cuando se juega [creature], se otorgan 3 huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Bargain", "Trato de dientes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will put 1 point of damage of it's opponent's side of the scale. When it perishes, it will put 2 damage on the owner's side of the scale.", "Cuando se juega [creature], añade 1 de daño al lado rival de la balanza. Cuando muere, añade 2 de daño al lado de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deal with a devil I see...", "Un trato con el diablo, por lo que veo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toothpuller", "Sacadientes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will add one point of damage to the opponent's scale.", "Al final del turno de su propietario, [creature] añade un punto de daño a la balanza rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That Hurts", "Eso duele", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Shard", "Astilla de diente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will generate 1 foil when hit, if it lives through the attack.", "Cuando [creature] recibe un golpe, genera 1 unidad de moneda si sobrevive al ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A splinter of gold.", "Una astilla de oro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin", "Toxina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 power and 1 health.", "Cuando [creature] inflige daño a otra criatura, esta pierde 1 de poder y 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All things can be worn down, and in different ways.", "Todo puede desgastarse de distintas formas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Deadly)", "Toxina letal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Dying Sigil. The Dying Sigil is defined as: [creature] will die after 2 number of turns.", "Cuando [creature] inflige daño a otra criatura, esta obtiene el sello Moribundo. Moribundo significa que [creature] muere después de 2 turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves a deadly mark", "Incluso cuando termina la batalla, deja una marca mortal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Sickening)", "Toxina enfermiza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Sickness Sigil. The Sickness Sigil is defined as: When ever a creature bearing this sigil declares an attack, they will loose one attack.", "Cuando [creature] inflige daño a otra criatura, esta obtiene el sello Enfermedad. Enfermedad significa que una criatura con este sello pierde un punto de ataque cada vez que declara un ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves sickness spreads in what it fights.", "Incluso después de la batalla, la enfermedad se extiende entre sus rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Strength)", "Toxina de poder", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 power.", "Cuando [creature] inflige daño a otra criatura, esta pierde 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, strength leaves it's target", "Incluso después de la batalla, el objetivo pierde fuerza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Vigor)", "Toxina de vigor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 health.", "Cuando [creature] inflige daño a otra criatura, esta pierde 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trample", "Arrollar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals overkill damage to a card, the overkill damage will be sent to the owner.", "Cuando [creature] inflige daño excedente a una carta, ese daño pasa al propietario de esa carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stampede can not be stopped.", "Una estampida no se puede detener.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Enemy Only)", "Transformación en gallina (solo enemigos)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform a random creature on the board on the opponent's side into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "Al final de cada turno, [creature] transforma en Gallina a una criatura aleatoria del lado rival del tablero. Una Gallina tiene 1 de ataque y 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Loose Cannon)", "Transformación en gallina (impredecible)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform a random creature on the board into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "Al final de cada turno, [creature] transforma en Gallina a una criatura aleatoria del tablero. Una Gallina tiene 1 de ataque y 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Opposing)", "Transformación en gallina (enfrente)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played opposing [creature] it will turn into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "Cuando una criatura se juega o se mueve al espacio frente a [creature], se transforma en Gallina. Una Gallina tiene 1 de ataque y 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transient", "Efímero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will return to your hand.", "Al final del turno de su propietario, [creature] regresa a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature blinks back into the owner's hand at the end of their turn.", "La criatura vuelve a la mano de su propietario al final de su turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribal Ally", "Aliado tribal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A card of the same tribe is created in your hand. No tribe counts as a tribe of tribeless.", "Cuando se juega [creature], se crea en tu mano una carta de la misma tribu. No tener tribu cuenta como una tribu propia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It calls for it's kin.", "Llama a los suyos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribal Tutor", "Búsqueda tribal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search your deck for a card of the same tribe and take it into your hand. No tribe counts as a tribe of tribeless.", "Cuando se juega [creature], puedes buscar en tu mazo una carta de la misma tribu y llevarla a tu mano. No tener tribu cuenta como una tribu propia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribe Attack", "Ataque tribal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all other cards on your side of the board of the same tribe will gain +1 attack.", "Mientras [creature] esté en el tablero, todas las demás cartas de la misma tribu de tu lado obtienen +1 de ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribe Health", "Salud tribal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all other cards on your side of the board of the same tribe will gain +1 health.", "Mientras [creature] esté en el tablero, todas las demás cartas de la misma tribu de tu lado obtienen +1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turbulent Waters", "Aguas turbulentas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will force other creatures with waterborne to resurface and take 1 damage at the start of the owner's turn.", "Al comienzo del turno de su propietario, [creature] obliga a las demás criaturas con Acuático a emerger y recibir 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waters be rough.", "Las aguas están revueltas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone prince 2", "Príncipe de los huesos 2", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 2 bones are rewarded instead of 1.", "Cuando [creature] muere, se otorgan 2 huesos en lugar de 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 2", "Don de huesos 2", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 2 bones are rewarded.", "Cuando se juega [creature], se otorgan 2 huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Underdog", "Desfavorecido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can only be played when you are losing.", "[creature] solo puede jugarse cuando vas perdiendo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious", "Feroz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is attacked, it gains 1 power.", "Cuando [creature] es atacada, obtiene 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hit just makes it angry.", "Un golpe solo consigue enfadarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warper", "Desplazador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move to the right, jumping over any creatures in its path, if it encounters the edge of the board, it will loop over to the other side.", "Al final del turno de su propietario, [creature] se mueve a la derecha y salta sobre las criaturas de su camino. Si llega al borde del tablero, pasa al otro lado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wild hunger", "Hambre salvaje", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil, however if it hits a card whilst moving, [creature] will stop, the card it hit will perish and [creature] will gain 1+/1+.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Si [creature] encuentra una carta, la mata y obtiene +1 de ataque y +1 de salud; si el espacio queda libre, [creature] se mueve a él.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withering", "Marchitamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will perish at the end of the opponant's turn.", "[creature] muere al final del turno rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zapper", "Electrocutador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature will gain the Paralysis Sigil. The Paralysis sigil is defined as: A card bearing this sigil will only attack every other turn.", "Cuando [creature] inflige daño a otra criatura, esta obtiene el sello Parálisis. Una carta con Parálisis solo ataca en turnos alternos.", Language.Spanish);
        }
    }
    public class BittysSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysSigils Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Eggs for you.", "Ambos lados están bloqueados. No hay huevos para ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No empty spaces. No firs for you.", "No hay espacios vacíos. No hay abetos para ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive Squirrel Reproduction", "Reproducción explosiva de ardillas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, fill your side deck with squirrels.", "Cuando se juega [creature], llena tu mazo secundario de Ardillas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hauler", "Transportador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Adjacent friendly creatures will be pulled in the same direction.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Las criaturas aliadas adyacentes son arrastradas en la misma dirección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Swap", "Intercambio de corazones", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards on the board swap their power and health.", "Cuando se juega [creature], todas las cartas del tablero intercambian su poder y su salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutual Hire", "Contratación mutua", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created in the opposing space.", "Cuando se juega [creature], se crea una copia en el espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charged Barrage", "Andanada cargada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 life to increase the power of all cards on your side of the board by 1.", "Paga 4 de vida para aumentar en 1 el poder de todas las cartas de tu lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health Roll", "Tirada de salud", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to set the health of [creature] randomly between 1 and 6.", "Paga 1 de energía para fijar aleatoriamente la salud de [creature] entre 1 y 6.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Roll", "Tirada de sello", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Life to add a random sigil to [creature].", "Paga 4 de vida para añadir un sello aleatorio a [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wildlife Camera", "Cámara de fauna", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another card, a copy of the killed card is created in your hand.", "Cuando [creature] mata a otra carta, se crea en tu mano una copia de la carta que mató.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dusty Quill", "Pluma polvorienta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a creature dies while [creature] is on the board, a corpse is raised in it's place. Corpses are defined as: 0/1.", "Cada vez que muere una criatura mientras [creature] está en el tablero, se alza un cadáver en su lugar. Los cadáveres tienen 0/1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleached Brush", "Pincel blanqueado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing card will lose all its sigils.", "Cuando se juega [creature], la carta enfrente pierde todos sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Soul", "Alma fuerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve sigils from another card.", "[creature] no puede recibir sellos de otra carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Soul", "Alma débil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have its sigils transferred to another card.", "Los sellos de [creature] no pueden transferirse a otra carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nonexistent Soul", "Alma inexistente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have sigils transferred to, or from this card.", "No se pueden transferir sellos a [creature] ni desde esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia", "Pirofobia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not be buffed at campsites.", "[creature] no puede recibir mejoras en las hogueras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia (Attack)", "Pirofobia (poder)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve power buffs from campsites.", "[creature] no puede recibir mejoras de poder en las hogueras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia (Health)", "Pirofobia (salud)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve health buffs from campsites.", "[creature] no puede recibir mejoras de salud en las hogueras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repulsion", "Repulsión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not attack.", "[creature] no puede atacar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Mushrooms", "Hongos misteriosos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, if there is a card on either side of [creature], they are fused together.", "Al final del turno, las cartas a izquierda o derecha de [creature] se fusionan con ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move the opposing card and itself in the direction inscribed in the sigil.", "Al final del turno de su propietario, [creature] se mueve junto con la carta enfrente en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counter Attack", "Contraataque", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, the striker is then dealt damage equal to this card's attack.", "Cuando [creature] recibe un golpe, quien la golpeó recibe después daño igual al ataque de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Counter", "Contraataque espejo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, the striker is then dealt damage equal to the striker's attack.", "Cuando [creature] recibe un golpe, quien la golpeó recibe después daño igual a su propio ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter", "Desplazamiento del tablero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. All cards will shift in the same direction, looping to the other edge of the board.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Todas las cartas se desplazan en la misma dirección y vuelven por el borde opuesto del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter (Owner)", "Desplazamiento del tablero (aliados)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Friendly cards will shift in the same direction, looping to the other edge of the board.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Las cartas aliadas se desplazan en la misma dirección y vuelven por el borde opuesto del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter (Opposing)", "Desplazamiento del tablero (rivales)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. The opposing cards will shift in the same direction, looping to the other edge of the board.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Las cartas rivales se desplazan en la misma dirección y vuelven por el borde opuesto del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathbell", "Toque de difuntos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the battle phase, [creature] perishes.", "Al comienzo de la fase de combate de su propietario, [creature] muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clockwise", "Sentido horario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, move all cards on the board clockwise.", "Cuando se juega [creature], mueve todas las cartas del tablero en sentido horario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stubborn", "Terco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have its stats swapped.", "Las estadísticas de [creature] no pueden intercambiarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] is on the board, move all cards on the board clockwise.", "Al final de cada turno en que [creature] esté en el tablero, mueve todas las cartas del tablero en sentido horario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting", "Fugaz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn [creature] will be discarded from your hand.", "Al final del turno, [creature] se descarta de tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Link", "Vínculo de alma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all other allied cards bearing this sigil perish as well.", "Cuando [creature] muere, todas las demás cartas aliadas que lleven este sello también mueren.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Draw", "Robo vacío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, discard the oldest card in your hand, draw a card.", "Cuando se juega [creature], descarta la carta más antigua de tu mano y roba una carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Barrage", "Andanada vacía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards take 1 damage.", "Cuando se juega [creature], todas las cartas reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Phobic", "Miedo a las gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls a Mox card, [creature] perishes.", "Si el propietario de [creature] controla una carta mox, [creature] muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foolhardy", "Temerario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve modifications from any source.", "[creature] no puede recibir modificaciones de ninguna fuente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jumper", "Saltador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move itself to the first empty space in the direction inscribed in the sigil.", "Al final del turno de su propietario, [creature] se mueve al primer espacio vacío en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super Sprinter", "Supervelocista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move itself as far as possible in the direction inscribed in the sigil.", "Al final del turno de su propietario, [creature] se mueve lo más lejos posible en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eggist", "Arte de los huevos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on each empty adjacent space.", "Cuando se juega [creature], se crea un Huevo en cada espacio adyacente vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fir Caller", "Llamada de los abetos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Fir is created in each of the owner's spaces.", "Cuando se juega [creature], se crea un Gran abeto en cada espacio vacío del lado de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flipper", "Inversor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] swaps its stats.", "Al final del turno de su propietario, [creature] intercambia sus estadísticas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting Draw", "Robo fugaz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw 1 card with Fleeting.", "Cuando se juega [creature], roba 1 carta con Fugaz.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outcast", "Paria", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] is shuffled into the deck.", "Al final del turno, [creature] se baraja dentro del mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Repeater", "Repetidor vacío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all On Play sigils on that card are activated.", "Cuando [creature] muere, se activan todos los sellos de esa carta que se activan al jugarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replenish", "Reposición", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, draw a card.", "Cuando se roba [creature], roba una carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Target Swap", "Intercambio dirigido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Target a Card: the card's stats are swapped.", "Cuando se juega [creature], elige una carta como objetivo: sus estadísticas se intercambian.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Growth", "Crecimiento sacrificial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it will grow into a more powerful form.", "Cuando se sacrifica [creature], crece hasta adoptar una forma más poderosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Transformer", "Transformación rubí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls a Ruby Mox, [creature] will be transformed; otherwise [creature] will transform into its base form.", "Si el propietario de [creature] controla un mox rubí, [creature] se transforma; de lo contrario, [creature] vuelve a su forma base.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gemify", "Gemificación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains buffs based on moxes in play on the owner's side. Orange is 1 Power. Green is 2 Health. Blue is lower Cost.", "[creature] obtiene mejoras según los mox en juego del lado de su propietario. Naranja: 1 de poder. Verde: 2 de salud. Azul: coste reducido.", Language.Spanish);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpse", "Cadáver", Language.Spanish);
