            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros only grows stronger from death.", "el Ouroboros solo se vuelve más fuerte con la muerte.", Language.Spanish);
