            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what glittering wool,", "qué lana tan brillante,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "attached to such a rare creature.", "en una criatura tan rara.", Language.Spanish);
