            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will not be able to take it with your caravan.", "No podrás llevártela con tu caravana.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "Ah...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't be seeing your [v:0] again,", "No volverás a ver tu carta [v:0],", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It has taken too much damage.", "Ha recibido demasiado daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "Ah...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you permanently kill your [v:0] on purpose?", "¿Has matado definitivamente a tu carta [v:0] a propósito?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shame...", "Qué pena...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha! There be my first mate!", "¡Ja! ¡Ahí está mi primer oficial!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argh! There be snakes on me ship as well!", "¡Arrr! ¡También hay serpientes en mi barco!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha!", "¡Ja!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I should hire ye to get rid of the rest of them!", "¡Debería contratarte para librarme del resto!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha! It's dead!", "¡Ja! ¡Ya no vive!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what?", "¿qué?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirates?", "¿Piratas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll allow it.", "Lo permitiré.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what?", "¿qué?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cheating?", "¿hacer trampas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how dissapointing...", "qué decepción...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the game will be soured from a pitifully easy ascent.", "la partida quedará arruinada por un ascenso lastimosamente fácil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cheater...", "tramposo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you no shame?", "¿No tienes vergüenza?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To cheat so blatantly...", "Hacer trampas tan descaradamente...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you should be dead.", "deberías estar muerto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and yet...", "y sin embargo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how dissapointing...", "qué decepción...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't tolerate this for much longer...", "No toleraré esto por mucho más tiempo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enough of this.", "Ya basta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yer not dead?", "¿No estás muerto?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah...", "ah...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "back to normal then?", "¿volvemos a la normalidad, entonces?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll admit, I had gotten used to the changes...", "Lo admito, me había acostumbrado a los cambios...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Cards?", "¿Cartas debilitadas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is hard to explain...", "Esto es difícil de explicar...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps they are sick? Yes.", "¿Quizá están enfermas? Sí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crippling disease afflicted your meager troupe of creatures.", "Una enfermedad debilitante había afectado a tu escasa comitiva de criaturas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne Cards?", "¿Cartas acuáticas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is hard to explain...", "Esto es difícil de explicar...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a mutation? Yes.", "¿Una mutación, quizá? Sí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your caravan of creatures had a startling mutation,", "tu caravana de criaturas había sufrido una mutación sorprendente,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They could only survive in the water.", "Solo podían sobrevivir en el agua.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralyzed Cards?", "¿Cartas paralizadas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "Mmm...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your group of creatures were fatigued from the long journey,", "tu grupo de criaturas estaba fatigado por el largo viaje,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but there would be a long way to go yet.", "pero aún quedaba un largo camino por recorrer.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Souled Cards?", "¿Cartas de alma débil?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "Mmm...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will not be able to extract their souls into new creatures,", "no podrás extraer sus almas para transferirlas a nuevas criaturas,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For better or worse...", "para bien o para mal...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lives of past challengers weighed down on you...", "Las vidas de anteriores aspirantes pesaban sobre ti...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "¿Eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How to explain this...", "Cómo explicar esto...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You were running low on supplies that day...", "Aquel día te quedaban pocas provisiones...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll have fewer [c:G][v:0]s[c:] to work with.", "Tendrás menos [c:G][v:0][c:] a tu disposición.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "¿Eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abundance of [c:G][v:0]s[c:]...", "Una abundancia de [c:G][v:0][c:]...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Must be mating season...", "Debe de ser la época de apareamiento...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "¿Eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environmental effects?", "¿Efectos ambientales?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how interesting...", "qué interesante...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In order to proceed,", "Para avanzar,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you had to slog through the wetter parts of the swamp.", "tuviste que avanzar con dificultad por las zonas más húmedas del pantano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick[c:G][c:G]mud[c:] stuck to your boots, and hindered your movements...", "El espeso [c:G][c:G]lodo[c:] se pegaba a tus botas y dificultaba tus movimientos...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid air was not the only obstacle in your way,", "el aire gélido no era el único obstáculo en tu camino,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the harsh ice and unforgiving snow also stood in your path.", "el duro hielo y la nieve implacable también se interponían en tu camino.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "before long you found yourself in...", "pronto te encontraste en medio de...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a [c:B]hailstorm.[c:]", "una [c:B]granizada.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You found yourself cornered against a sheer rock wall,", "te viste sin salida ante una pared de roca escarpada,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the [c:G]cliffside.[c:]", "el [c:G]acantilado.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Against the cold stone, there would be less space to fight.", "Frente a la fría piedra, habría menos espacio para luchar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mycologists had left one of their experiments behind,", "los micólogos habían dejado atrás uno de sus experimentos,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "unbeknownst to them, it began to fester and grow.", "sin que lo supieran, había empezado a infectarse y crecer.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "even the creatures fighting you would not be safe from the [c:G]fungal mass.[c:]", "ni siquiera las criaturas que luchaban contra ti estarían a salvo de la [c:G]masa fúngica.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stumbled across one of the Prospector's Camps.", "Te encontraste con uno de los campamentos del Buscador de oro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The camp was filled with prospecting tools.", "El campamento estaba lleno de herramientas de prospección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "pickaxes, headlamps...", "picos, linternas frontales...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and [c:bR]dynamite.[c:]", "y [c:bR]dinamita.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across one of the Angler's Ponds.", "Te encontraste con uno de los estanques del Pescador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the area stank of rotting fish", "la zona apestaba a pescado podrido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emanating from the nearby abandoned buckets of [c:dB]bait.[c:]", "el olor venía de unos cubos de [c:dB]cebo[c:] abandonados cerca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across one of the Trapper's Hunting Grounds.", "Llegaste a uno de los cotos de caza del Trampero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the stench of blood hung in the air...", "el olor a sangre flotaba en el aire...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you noticed the numerous [c:G]traps[c:] lying in wait.", "notaste las numerosas [c:G]trampas[c:] que acechaban.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came upon a strange [c:bR]totem.[c:]", "Te encontraste con un extraño [c:bR]tótem.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious energy swirled around it,", "una energía misteriosa giraba a su alrededor,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the creatures nearby seem more agressive than usual...", "las criaturas cercanas parecían más agresivas de lo habitual...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "Ah...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a [c:bR]Blood Moon.[c:]", "una [c:bR]Luna de sangre.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Er...", "Eh...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You...", "Tú...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...What?", "... ¿Qué?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am at a loss for words.", "Me he quedado sin palabras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wind was howling around you.", "El viento aullaba a tu alrededor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuck in the middle of a blizzard,", "en medio de una ventisca que te impedía escapar,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You heard rumbling from the mountains above.", "oíste un estruendo desde las montañas de arriba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here it comes...", "Ahí viene...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an [c:B]avalanche.[c:]", "una [c:B]avalancha.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stumble across a strange black stone.", "Te encuentras con una extraña piedra negra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone tablet sits in front of it, clearly made for sacrifices.", "Ante ella hay una losa de piedra, claramente destinada a los sacrificios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a certain creature may cause a reaction?", "¿Quizá una criatura concreta podría provocar una reacción?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk trembles in delight.", "El obelisco tiembla de alegría.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A goat is truly a worthy sacrifice.", "Una cabra es un sacrificio verdaderamente digno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't be seeing it again.", "No volverás a verla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk rumbles with anger.", "El obelisco retumba de ira.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pelt is a truly pitiful sacrifice.", "Una piel es un sacrificio verdaderamente lamentable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...That is not a proper sacrifice.", "... Ese no es un sacrificio adecuado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop this.", "Basta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You...", "Tú...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is bloodshed without meaning.", "Esto es un derramamiento de sangre sin sentido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[v:0]...", "[v:0]...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm?", "¿Mmm?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this?", "¿Qué es esto?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh heh heh...", "Je, je, je...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ye walked into th' pirate's cove!", "¡Has entrado en la guarida de los piratas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Me crew will get rid of ye quick!", "¡Mi tripulación acabará contigo enseguida!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You carve through the thick underbrush and foilage.", "Te abres paso entre la espesa maleza y el follaje.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees blotting out the sun...", "Los árboles tapan el sol...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you travel, you hear the woods start to creak around you.", "Mientras avanzas, oyes que el bosque empieza a crujir a tu alrededor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should know better than to walk in the darkness...", "Deberías saber que no conviene caminar en la oscuridad...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As your caravan of creatures travels, you hear a rushing sound.", "Mientras avanza tu caravana de criaturas, oyes un rugido de agua.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You climb to a higher place as water flows around you.", "Subes a un lugar más alto mientras el agua fluye a tu alrededor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are caught in a [c:B]flood.[c:]", "Te atrapa una [c:B]inundación.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the terrain and flying creatures will be able to avoid the waters.", "Solo los terrenos y las criaturas voladoras podrán evitar las aguas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As your caravan of creatures moves across a clearing, the winds blow stronger.", "Mientras tu caravana de criaturas cruza un claro, el viento sopla con más fuerza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong breeze greets your face, and you grasp onto the surroundings for dear life.", "Una fuerte ráfaga te golpea la cara y te aferras a lo que te rodea para salvar la vida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creatures are blown [c:G]airborne.[c:]", "Tus criaturas salen despedidas [c:G]por los aires.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only burrowing and submerged creatures will be able to avoid the gusts.", "Solo las criaturas excavadoras y las sumergidas podrán evitar las ráfagas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Breeze blows...", "La brisa sopla...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You come across a pile of corpses.", "Te encuentras con un montón de cadáveres.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange energy swirls around them as you approach.", "Una extraña energía gira a su alrededor cuando te acercas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then...", "Entonces...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]The dead walk.[c:]", "[c:R]Los muertos caminan.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]The dead walk.[c:]", "[c:R]Los muertos caminan.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across an overgrown glade.", "Llegaste a un claro cubierto de vegetación.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees seemed taller, and stronger than usual.", "Los árboles parecían más altos y fuertes de lo habitual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creatures grew faster as well.", "Tus criaturas también crecían más rápido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#25C102>Flash Growth.</color>", "<color=#25C102>Crecimiento fulminante.</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "¿Eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're decreasing the number of vessels you have?", "¿Estás reduciendo la cantidad de receptáculos que tienes?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely a player as bad as you needs the extra chump blockers?", "¿Un jugador tan malo como tú no necesita más bloqueadores prescindibles?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "Ya verás.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "¿Eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're increasing the number of vessels you have?", "¿Estás aumentando la cantidad de receptáculos que tienes?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes sense.", "Tiene sentido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After all, a player as bad as you needs the extra chump blockers.", "Al fin y al cabo, un jugador tan malo como tú necesita más bloqueadores prescindibles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[v:0] vessels...", "[v:0] receptáculos...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "¿Oh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You couldn't even stick to the changes?", "¿Ni siquiera has podido mantener los cambios?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pathetic.", "Patético.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "¿Oh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My own Ourobot?", "¿Mi propio Ourobot?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must be masochistic if you thought this was a good idea.", "Debes de ser masoquista si pensaste que era una buena idea.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your funeral.", "Tú verás.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There it goes.", "Ahí se va.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just made it stronger.", "Acabas de hacerlo más fuerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Of course, you knew that already.", "Claro, eso ya lo sabías.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not worried.", "No me preocupa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll come back to crush you later.", "Volverá más tarde para aplastarte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "¿Eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaker starting cards?", "¿Cartas iniciales más débiles?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As if one health will make a difference.", "Como si un punto de salud fuera a marcar la diferencia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "¿Eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Were my environments not good enough for you?", "¿Mis entornos no eran lo bastante buenos para ti?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine.", "Está bien.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm...", "Mmm...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have found a...", "Has encontrado un...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Robot scrapyard.", "Desguace de robots.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's broken down robots everywhere.", "Hay robots averiados por todas partes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every robot in this area dies twice.", "Cada robot de esta zona muere dos veces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's the scrapyard again.", "Otra vez el desguace.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know the drill.", "Ya sabes cómo va.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eugh", "Puaj", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is one of [c:O]HIS.[c:]", "Esto es una de [c:O]SUS cosas.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your... transformer bots will be more effective here.", "Tus... robots transformadores serán más eficaces aquí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll transform when played.", "Se transformarán al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "Ya verás.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your transformer bots will be more effective here.", "Tus robots transformadores serán más eficaces aquí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll tranform when played.", "Se transformarán al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "Ah...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A favorite of mine.", "Uno de mis favoritos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each of your turns all cards will be moved clockwise.", "Al comienzo de cada uno de tus turnos, todas las cartas se moverán en sentido horario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you've seen it before.", "Seguro que ya lo has visto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each of your turns all cards will be moved clockwise.", "Al comienzo de cada uno de tus turnos, todas las cartas se moverán en sentido horario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've seen it before.", "Ya lo has visto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "Ah...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your <color=#25C102>G</color>[c:O]E[c:][c:B]M[c:]s will be more useful.", "Tus <color=#25C102>g</color>[c:O]e[c:][c:B]mas[c:] serán más útiles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More useful than [c:R]he[c:] ever was able to make them...", "Más útiles de lo que [c:R]él[c:] jamás consiguió que fueran...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...As long as you keep that one alive.", "... Siempre que mantengas con vida a esa cosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your <color=#25C102>G</color>[c:O]E[c:][c:B]M[c:]s will be more useful.", "Tus <color=#25C102>g</color>[c:O]e[c:][c:B]mas[c:] serán más útiles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...As long as you keep that one alive.", "... Siempre que mantengas con vida a esa cosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh", "Je", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one will be quite...", "Este será bastante...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocking.", "Electrizante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You find yourself in an electrical storm.", "Te encuentras en medio de una tormenta eléctrica.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, it will take 1 damage.", "Cuando se juega una carta, recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it survives, it'll be stronger for a bit.", "Si sobrevive, será más fuerte durante un tiempo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you'll find this one quite...", "Creo que este te resultará bastante...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocking.", "Electrizante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Parrot", "Loro no muerto", Language.Spanish);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascender's Bane", "Perdición del escalador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You start with a useless card in the deck.", "Empiezas con una carta inútil en el mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Champions", "Campeones", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opponent cards have a chance to become a champion.", "Las cartas rivales pueden convertirse en campeones.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environmental Effects", "Efectos ambientales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each battle, a random environmental effect may activate.", "Al comienzo de cada batalla, puede activarse un efecto ambiental aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Famine", "Hambruna", Language.Spanish);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The side deck has " + amnt.ToString() + " more cards.", "El mazo secundario tiene " + amnt.ToString() + " " + (amnt == 1 ? "carta más" : "cartas más") + ".", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The side deck has " + amnt.ToString() + " less cards.", "El mazo secundario tiene " + amnt.ToString() + " " + (amnt == 1 ? "carta menos" : "cartas menos") + ".", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runaway Side Deck", "Mazo secundario fugitivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Side Deck cards have the Fleeting sigil.", "Las cartas de tu mazo secundario tienen el sello Fugaz.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Golden Fleece", "El Vellocino de oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Golden Ram appears randomly throughout the run.", "Un Carnero Dorado aparece aleatoriamente durante la partida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder Bosses", "Jefes más duros", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bosses' main cards are more powerful, and bosses are more agressive.", "Las cartas principales de los jefes son más poderosas y los jefes son más agresivos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Pirate", "Pirata auténtico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirates invade Bosses. The Final Boss Challenge is harder.", "Los piratas invaden los combates contra jefes. El desafío del jefe final es más difícil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Extra Lives", "Vidas extra", Language.Spanish);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The scales will reset once they hit 0, up to " + amnt.ToString() + " times for each candle.", "La balanza se reinicia al llegar a 0, hasta " + amnt.ToString() + " " + (amnt == 1 ? "vez" : "veces") + " por vela.", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botched Experiments", "Experimentos fallidos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mycologists have a chance to make mistakes while fusing cards.", "Los micólogos pueden cometer errores al fusionar cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Fecundity", "Fecundidad original", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reverts the Fecundity Nerf.", "Revierte el debilitamiento de Fecundidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mulligan", "Nueva mano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may redraw your hand at the start of each battle.", "Puedes volver a robar tu mano al comienzo de cada batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reverse Scales", "Balanza invertida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start all battles with 1 damage on the opponent's side of the scale.", "Empieza todas las batallas con 1 de daño en el lado rival de la balanza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocked Starters", "Inicio conmocionado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in starting deck attack every other turn.", "Las cartas del mazo inicial solo atacan en turnos alternos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprintmaggedon", "Sprintmagedón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards get a random Sprinter sigil when drawn.", "Todas las cartas obtienen un sello de Velocista aleatorio al robarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traveling Ouroboros", "Ouroboros viajero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A traveling Ouroboros appears throughout the run.", "Un Ouroboros viajero aparece durante la partida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfair Hand", "Mano injusta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your starting hand is randomly drawn.", "Tu mano inicial se roba al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive Noise", "Ruido explosivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card dies, a loud boom will play. All cards explode on death.", "Cuando una carta muere, suena una fuerte explosión. Todas las cartas explotan al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aquatic Starters", "Inicio acuático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in starting deck have the Waterborne sigil.", "Las cartas del mazo inicial tienen el sello Acuático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unspirited Starters", "Inicio sin espíritu", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in the starting deck may not have their sigils transferred.", "Los sellos de las cartas del mazo inicial no pueden transferirse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Starters", "Inicio debilitado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in the starting deck have 1 less health.", "Las cartas del mazo inicial tienen 1 de salud menos.", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Champion", "Campeón azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will cause all other non-Terrain cards on the same side to gain flight, as long as the champion is alive.", "Mientras este campeón esté vivo, todas las demás cartas que no sean terreno del mismo lado obtienen vuelo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bright Red Champion", "Campeón rojo brillante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, this champion will heal all other non-terrain creatures on the opponent's side by 1.", "Al comienzo de cada turno, este campeón cura 1 de salud a todas las demás criaturas que no sean terreno del lado rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyan Champion", "Campeón cian", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will deal 1 damage to every other creature on the board.", "Cuando este campeón muere, inflige 1 de daño a todas las demás criaturas del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive", "Explosivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature]; the other card, adjacent cards, and opposing cards will all be dealt 10 damage.", "Se pueden colocar otras cartas sobre [creature]; la carta colocada, las adyacentes y las de enfrente reciben todas 10 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a copy of it is created in the opponent's hand.", "Cuando [creature] muere, se crea una copia en la mano del rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragile", "Frágil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] perishes, it is permanently removed from your deck.", "Si [creature] muere, se elimina de tu mazo de forma permanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Champion", "Campeón verde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will deal 1 damage directly to you, after it destroys another creature.", "Tras destruir otra criatura, este campeón inflige 1 de daño directamente a su rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Light Blue Champion", "Campeón azul claro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will deal 3 damage to creatures to the left and right of it as well as the opposing creature.", "Cuando este campeón muere, inflige 3 de daño a las criaturas a su izquierda y derecha y a la criatura enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Light Green Champion", "Campeón verde claro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will prevent all damage from the first strike dealt to it. Damage from effects like sigils will not be prevented.", "Este campeón evita todo el daño del primer golpe que recibe. El daño de efectos como los sellos no se evita.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magenta Champion", "Campeón magenta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, this champion will attack for 1 damage in a random space on your side.", "Al comienzo de cada turno, este campeón ataca un espacio aleatorio de tu lado e inflige 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muddy", "Ola de lodo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature], but will be unable to attack for one turn and will gain Muddy. If [creature] is sacrificed, the sacrificing creature will be unable to attack for one turn.", "Se pueden colocar otras cartas sobre [creature], pero no pueden atacar durante un turno y obtienen Ola de lodo. Si se sacrifica [creature], la criatura para la que se sacrificó no puede atacar durante un turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Slab", "Losa sacrificial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature]; the other card will die.", "Se pueden colocar otras cartas sobre [creature]; la carta colocada muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Champion", "Campeón naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will steal 2 golden teeth from you if it damages you directly.", "Si este campeón te inflige daño directo, te roba 2 dientes de oro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not attack every other turn.", "[creature] solo puede atacar en turnos alternos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purple Champion", "Campeón morado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time you play a card, if the space opposing this champion is empty, that card will move to that space.", "Cada vez que juegas una carta, si el espacio frente a este campeón está vacío, esa carta se mueve a ese espacio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seaworthy", "Navegable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature], any Waterborne sigils on the card will be negated.", "Se pueden colocar otras cartas sobre [creature]; cualquier sello Acuático de la carta queda anulado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Champion", "Campeón rojo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion starts with 2 additional Health.", "Este campeón empieza con 2 de salud adicional.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter", "Refugio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adjacent cards are sheltered from environmental effects.", "Las cartas adyacentes están protegidas de los efectos ambientales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalancher", "Portador de avalanchas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Creatures in the way will be killed. If [creature] is at the right most side of the board, it dies.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Las criaturas en su camino mueren. Si [creature] está en el extremo derecho del tablero, muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Creatures in the way will be killed.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Las criaturas en su camino mueren.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to the right, jumping over any creatures in its path. If it encounters the edge of the board, it will loop over to the other side.", "Al final del turno de su propietario, [creature] se mueve a la derecha y salta sobre las criaturas de su camino. Si llega al borde del tablero, pasa al otro lado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Champion", "Campeón blanco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will create a Boulder in its space. [define:Boulder]", "Cuando este campeón muere, crea un Peñasco en su espacio. [define:Boulder]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellow Champion", "Campeón amarillo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion starts with 1 additional Power.", "Este campeón empieza con 1 de poder adicional.", Language.Spanish);

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slot Spawner", "Generador de espacios", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, spawns a slot. Used for testing.", "Al jugarse, esta carta crea un espacio. Se usa para pruebas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, converts the slot into a Raft.", "Al jugarse, esta carta convierte el espacio en una Balsa.", Language.Spanish);
            // Boon
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Angler's Pond", "Entorno: estanque del Pescador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Bait Buckets.", "El rival empieza la batalla con Cubos de cebo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Blizzard", "Entorno: ventisca", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, if there is not an Avalanche present on the board, one will be created on the left-most side of the board.", "Al comienzo de cada turno, si no hay una Avalancha en el tablero, se crea una en el extremo izquierdo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Blood Moon", "Entorno: Luna de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Dire Wolf Pups.", "El rival empieza la batalla con Lobeznos gigantes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Breeze", "Entorno: brisa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, all creatures gain or lose Airborne. Terrain, and creatures with Waterborne or Burrower are ignored.", "Al comienzo de cada turno, todas las criaturas obtienen o pierden Aéreo. Se ignoran los terrenos y las criaturas con Acuático o Excavador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Carrot Patch", "Entorno: campo de zanahorias", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Rabbits.", "El rival empieza la batalla con Conejos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Cliffside", "Entorno: acantilado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the battle, the leftmost lane will be blocked with Cliffs.", "Al comienzo de la batalla, el carril situado más a la izquierda queda bloqueado por acantilados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Factory", "Entorno: fábrica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Upkeep, all cards are rotated clockwise.", "En el mantenimiento, todas las cartas giran en sentido horario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Dark Forest", "Entorno: bosque oscuro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Trees. All of the opponent's terrain have +1 power.", "El rival empieza la batalla con Árboles. Todos sus terrenos obtienen +1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Prospector's Camp", "Entorno: campamento del Buscador de oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will start the battle with Dynamite on some of your spaces.", "Empiezas la batalla con Dinamita en algunos de tus espacios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Electrical Storm", "Entorno: tormenta eléctrica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, it takes 1 damage and gains 1 power.", "Cuando se juega una carta, recibe 1 de daño y obtiene 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Flash Growth", "Entorno: crecimiento fulminante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, any sigils that activate at the start of the turn are activated.", "Cuando se juega una carta, se activan sus sellos que se activan al comienzo del turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Flood", "Entorno: inundación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a creature is played, it gains Waterborne. Terrain, and creatures with Airborne are ignored.", "Cada vez que se juega una criatura, obtiene Acuático. Se ignoran los terrenos y las criaturas con Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Gem Sanctuary", "Entorno: santuario de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All gems have +1 power.", "Todas las gemas obtienen +1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Graveyard", "Entorno: cementerio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature dies, it dies again.", "Cuando una criatura muere, muere otra vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Hail Storm", "Entorno: granizada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, all of the turn owner's non-terrain cards take 1 damage.", "Al comienzo de cada turno, todas las cartas que no sean terreno del propietario del turno reciben 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Pirate's Hollow", "Entorno: cala de los piratas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with a Minicello.", "El rival empieza la batalla con un Minicello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Mud Swamp", "Entorno: pantano lodoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will start the battle with Mud on some of your spaces.", "Empiezas la batalla con Lodo en algunos de tus espacios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Fungal Field", "Entorno: campo de hongos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Mushrooms.", "El rival empieza la batalla con Hongos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Obelisk", "Entorno: obelisco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with an Obelisk.", "El rival empieza la batalla con un Obelisco.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Cursed Totem", "Entorno: tótem maldito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Cursed Totems.", "El rival empieza la batalla con Tótems malditos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Trapper's Hunting Grounds", "Entorno: coto de caza del Trampero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Steel Traps.", "El rival empieza la batalla con Trampas de acero.", Language.Spanish);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascender's Bane", "Perdición del escalador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A reminder of past challengers.", "Un recuerdo de anteriores aspirantes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "Avalancha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A monsterous mound of snow.", "Un montón monstruoso de nieve.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cliff", "Acantilado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A solid wall of rock.", "Una sólida pared de roca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clover", "Trébol", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal member of Royal's crew.", "Un miembro leal de la tripulación de Royal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite", "Dinamita", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A box of dynamite.", "Una caja de dinamita.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chrysomallos", "Chrysomallos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mystical, glittering being.", "Un ser místico y reluciente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "Cubo de hielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice.", "Un bloque de hielo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minicello", "Minicello", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A miniture version of a famous pirate's ship.", "Una versión en miniatura del barco de un famoso pirata.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mud", "Lodo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mushrooms", "Hongos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of strange mushrooms. They attract anything nearby.", "Un conjunto de extraños hongos. Atraen todo lo que hay cerca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "Obelisco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tall mysterious stone.", "Una piedra alta y misteriosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Altar", "Altar de sacrificios", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flat mysterious stone.", "Una piedra plana y misteriosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raft", "Balsa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dry patch in the flood.", "Una zona seca en la inundación.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter", "Refugio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter from the storm.", "Un refugio de la tormenta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Totem", "Tótem maldito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A totem surrounded in mysterious energy.", "Un tótem rodeado de una energía misteriosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Ouroboros.", "Mi propio Ouroboros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wooden Board", "Tabla de madera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A regular wooden board.", "Una tabla de madera normal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Firstmate", "Topo, primer oficial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobot", "Ourobot", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living {0}", "Versión viviente de {0}", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a mutation?", "¿Quizá una mutación?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raft Slot", "Espacio de balsa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prevents creatures on this slot from submerging into the water.", "Impide que las criaturas de este espacio se sumerjan.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muddy Slot", "Espacio lodoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played on this slot, it cannot attack for one turn.", "Cuando se juega una criatura en este espacio, no puede atacar durante un turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hail Slot", "Espacio de granizo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, a creature in this slot takes 1 damage.", "Al comienzo del turno de su propietario, una criatura en este espacio recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flooded Slot", "Espacio inundado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it gets submerged in the water unless it is flying.", "Cuando se juega una criatura en este espacio, se sumerge salvo que vuele.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windy Slot", "Espacio ventoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, a creature in this slot will alternate between flying and not flying. This effect is ignored if the creature naturally flies, submerges, or burrows.", "Al comienzo del turno de su propietario, una criatura en este espacio alterna entre volar y no volar. El efecto se ignora si vuela, se sumerge o excava por naturaleza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Slot", "Espacio lúgubre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature dies in this slot, it dies again.", "Cuando una criatura muere en este espacio, muere otra vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Growth Slot", "Espacio de crecimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, instantly evolve it if it has an evolve related sigil. If it does not have Fledgling, it instead gains Fledgling.", "Cuando se juega una criatura en este espacio, haz que evolucione de inmediato si tiene un sello relacionado con la evolución. Si no tiene Inexperto, obtiene Inexperto en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overclocking Slot", "Espacio de sobrepotenciación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it takes 1 damage and gains 1 attack.", "Cuando se juega una criatura en este espacio, recibe 1 de daño y obtiene 1 de ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite Slot", "Espacio de dinamita", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it takes 10 damage and explodes. The dynamite is removed.", "Cuando se juega una criatura en este espacio, recibe 10 de daño y explota. La dinamita se elimina.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk Tablet", "Losa del obelisco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it is sacrificed.", "Cuando se juega una criatura en este espacio, es sacrificada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is truly a worthy sacrifice.", "Este es un sacrificio verdaderamente digno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a thing... does not bleed.", "Una cosa así... no sangra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk does not react.", "El obelisco no reacciona.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, something greater.", "Quizá algo más grande.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick [c:G]mud[c:] stuck to your boots, and hindered your movements...", "El espeso [c:G]lodo[c:] se pegaba a tus botas y dificultaba tus movimientos...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The glade glowed with unnatural light.", "El claro brillaba con una luz sobrenatural.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the area stank of rotting fish,", "la zona apestaba a pescado podrido,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps they are sick?", "¿Quizá están enfermas?", Language.Spanish);
        }
    }
    public class NewSpellCardToolkitMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NewSpellCardToolkit Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attack Up", "Ataque aumentado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Increases the target's attack for the rest of the battle.", "Aumenta el ataque del objetivo durante el resto de la batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attack Down", "Ataque reducido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decreases the target's attack for the rest of the battle.", "Reduce el ataque del objetivo durante el resto de la batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cataclysm", "Cataclismo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all other cards on the boards perish as well.", "Cuando [creature] muere, todas las demás cartas del tablero también mueren.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Damage", "Daño directo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals damage directly to a target.", "Inflige daño directamente a un objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Heal", "Curación directa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heals the target. This can heal the target beyond its original max health.", "Cura al objetivo. Su salud puede superar así el máximo original.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Twice", "Robo doble", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, draw two more cards and add them to your deck.", "Cuando [creature] muere, roba dos cartas adicionales y añádelas a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Control", "Tomar el control", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes control of the targeted creature.", "Toma el control de la criatura objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Sigils", "Otorgar sellos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's sigils to the target.", "Otorga al objetivo los sellos de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Stats", "Otorgar estadísticas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's stats to the target.", "Otorga al objetivo las estadísticas de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Stats and Sigils", "Otorgar estadísticas y sellos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's stats and sigils to the target.", "Otorga al objetivo las estadísticas y los sellos de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Global)", "Hechizo (global)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played anywhere on the board, it will cause an immediate effect and then disappear.", "Cuando esta carta se juega en cualquier lugar del tablero, produce un efecto inmediato y después desaparece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLOBAL SPELL.", "HECHIZO GLOBAL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Global, Instant)", "Hechizo (global, instantáneo)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will cause an immediate effect and then disappear.", "Cuando se juega esta carta, produce un efecto inmediato y después desaparece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INSTA-GLOBAL SPELL.", "HECHIZO GLOBAL INSTANTÁNEO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Targeted)", "Hechizo (dirigido)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will target and affect a chosen space on the board and then disappear.", "Cuando se juega esta carta, apunta a un espacio elegido del tablero, lo afecta y después desaparece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TARGETED SPELL.", "HECHIZO DIRIGIDO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Global)", "Orden (global)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played anywhere on the board, it will cause an immediate effect and then disappear.", "Cuando esta carta se juega en cualquier lugar del tablero, produce un efecto inmediato y después desaparece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLOBAL COMMAND.", "ORDEN GLOBAL.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Global, Instant)", "Orden (global, instantánea)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will cause an immediate effect and then disappear.", "Cuando se juega esta carta, produce un efecto inmediato y después desaparece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INSTA-GLOBAL COMMAND.", "ORDEN GLOBAL INSTANTÁNEA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Targeted)", "Orden (dirigida)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will target and affect a chosen space on the board and then disappear.", "Cuando se juega esta carta, apunta a un espacio elegido del tablero, lo afecta y después desaparece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TARGETED COMMAND.", "ORDEN DIRIGIDA.", Language.Spanish);

        }
    }
    public class P03SigilariumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for P03Sigilarium Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urch1n Cell", "Celda Urch1n", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Urch1n Cell", "Celda Urch1n");
            P03InKayceesModMod.RegisterCardPart("Urch1n", "Urch1n");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charge!", "¡Carga!", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Charge!", "¡Carga!");
            P03InKayceesModMod.RegisterCardPart("Charge!", "¡Carga!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade!", "¡Mejora!", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Upgrade!", "¡Mejora!");
            P03InKayceesModMod.RegisterCardPart("Upgrade!", "¡Mejora!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zap!", "¡Descarga!", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Zap!", "¡Descarga!");
            P03InKayceesModMod.RegisterCardPart("Zap!", "¡Descarga!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast!", "¡Explosión!", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Blast!", "¡Explosión!");
            P03InKayceesModMod.RegisterCardPart("Blast!", "¡Explosión!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defend!", "¡Defensa!", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Defend!", "¡Defensa!");
            P03InKayceesModMod.RegisterCardPart("Defend!", "¡Defensa!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Junk", "Chatarra", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Junk", "Chatarra");
            P03InKayceesModMod.RegisterCardPart("Junk", "Chatarra");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "S4LM0N", "S4LM0N", Language.Spanish);
            P03InKayceesModMod.RegisterCard("S4LM0N", "S4LM0N");
            P03InKayceesModMod.RegisterCardPart("S4LM0N", "S4LM0N");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seed", "Semilla", Language.Spanish);
            P03InKayceesModMod.RegisterCard("Seed", "Semilla");
            P03InKayceesModMod.RegisterCardPart("Seed", "Semilla");

            // Ability

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - Additional Mechanics {0}", "APÉNDICE XII, SUBSECCIÓN I - Mecánicas adicionales {0}", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield Absorption", "Absorción de escudos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures lose their shields. This creature gains 1 attack for each shield lost this way.", "Cuando se juega [creature], todas las criaturas pierden sus escudos. Esta criatura obtiene 1 de ataque por cada escudo perdido así.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rapid Recycle", "Reciclaje rápido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to choose another card you control to die and immediately respawn. You may only activate this ability once per turn.", "Paga 1 de energía para elegir otra carta que controles: muere y reaparece inmediatamente. Esta habilidad solo puede activarse una vez por turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supercharge", "Sobrecarga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: friendly cards gain 1 power until the end of the turn. This ability can only be activated once per turn.", "Gasta una unidad de combustible: las cartas aliadas obtienen 1 de poder hasta el final del turno. Esta habilidad solo puede activarse una vez por turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copy and Paste", "Copiar y pegar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The controller of [creature] chooses two cards they control. The second card's sigils are replaced with the sigils of the first.", "Quien controla [creature] elige dos cartas que controle. Los sellos de la segunda se sustituyen por los de la primera.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card to copy sigils from", "Elige una carta de la que copiar los sellos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card to paste sigils onto", "Elige una carta en la que pegar los sellos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannon Fire", "Fuego de cañón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: Create a Blast! card in hand. Blast! is defined as a spell that costs 2 energy and sets the target on fire. This ability can only be activated once per turn.", "Gasta una unidad de combustible: crea una carta «¡Explosión!» en tu mano. «¡Explosión!» es un hechizo que cuesta 2 de energía y prende fuego al objetivo. Esta habilidad solo puede activarse una vez por turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: Create a Blast! card in hand. Blast! is defined as a command that costs 2 energy and sets the target on fire. This ability can only be activated once per turn.", "Gasta una unidad de combustible: crea una carta «¡Explosión!» en tu mano. «¡Explosión!» es una orden que cuesta 2 de energía y prende fuego al objetivo. Esta habilidad solo puede activarse una vez por turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge Reserves", "Recarga de reservas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to create a Charge in your hand. Charge is defined as a spell that refills 1 Energy when played.", "Paga 2 de energía para crear una carta «¡Carga!» en tu mano. «¡Carga!» es un hechizo que recupera 1 de energía al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to create a Charge in your hand. Charge is defined as a command that refills 1 Energy when played.", "Paga 2 de energía para crear una carta «¡Carga!» en tu mano. «¡Carga!» es una orden que recupera 1 de energía al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Holo Weaver", "Tejedor holográfico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, create a Defend! card in hand. Defend! is defined as a spell that costs 2 energy and gives the target a shield.", "Una vez por turno, crea una carta «¡Defensa!» en tu mano. «¡Defensa!» es un hechizo que cuesta 2 de energía y da un escudo al objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, create a Defend! card in hand. Defend! is defined as a command that costs 2 energy and gives the target a shield.", "Una vez por turno, crea una carta «¡Defensa!» en tu mano. «¡Defensa!» es una orden que cuesta 2 de energía y da un escudo al objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Future Sight", "Visión del futuro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look at the top card of your deck. You can play it.", "Mira la carta superior de tu mazo. Puedes jugarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil Fuel", "Combustible fósil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Provides an additional energy cell.", "Proporciona una celda de energía adicional.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dispenser", "Dispensador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a random item.", "Obtén un objeto aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overcharge", "Sobrecarga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Energy to increase the Power of this card by 1.", "Paga 4 de energía para aumentar en 1 el poder de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enrage", "Líder sobreacelerado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Energy equal to the Power of this card plus 2 to increase the Power of this card by 1.", "Paga tanta energía como el poder de esta carta más 2 para aumentar su poder en 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drive", "Conducción", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: move in the direction inscribed in this sigil. This ability can only be activated once per turn.", "Gasta una unidad de combustible: mueve esta carta en la dirección indicada en este sello. Esta habilidad solo puede activarse una vez por turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad", "Cruceta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to an adjacent empty lane.", "Mueve esta carta a un carril adyacente vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad Left", "Cruceta izquierda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to the lane to the left, if it is empty.", "Mueve esta carta al carril de la izquierda si está vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad Right", "Cruceta derecha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to the lane to the right, if it is empty.", "Mueve esta carta al carril de la derecha si está vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Inmersión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: submerge during the opponent's turn. While submerged, opposing creatures attack its owner directly.", "Gasta una unidad de combustible: esta carta se sumerge durante el turno rival. Mientras está sumergida, las criaturas enfrente atacan directamente a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tow Hook", "Gancho de remolque", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: tow an opposing creature to your side of the board until end of turn. Creatures being towed cannot be hammered. This ability can only be activated once per turn.", "Gasta una unidad de combustible: remolca una criatura rival a tu lado del tablero hasta el final del turno. Las criaturas remolcadas no pueden ser golpeadas con el martillo. Esta habilidad solo puede activarse una vez por turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Button Pusher", "Pulsador de botones", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all activated sigils and sigils that trigger on play or on death are activated.", "Cuando se juega [creature], se activan todos los sellos activables y los que se activan al jugar una carta o al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Control", "Control parasitario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opposing cards are moved to your side of the board.", "Cuando se juega [creature], todas las cartas rivales se mueven a tu lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Power", "Poder energético", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of times the player has spent energy this turn.", "El valor representado por este sello es igual al número de veces que el jugador ha gastado energía este turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Holo Trap", "Trampa holográfica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the creature opposing it perishes as well. A Vessel is created in your hand.", "Cuando una carta que lleve este sello muere, también muere la criatura enfrente. Se crea un Receptáculo en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Lord", "Señor de lo Quebradizo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, cards with Brittle have Unkillable.", "Mientras [creature] esté viva, las cartas con Quebradizo tienen Inmatable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buck Wild", "Embiste salvaje", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, this card will charge into the opposing slot, killing anything in its way.", "Cuando esta carta recibe daño, carga hacia el espacio de enfrente y mata todo lo que encuentre en su camino.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (1)", "Espacio en llamas (1)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts one turn.", "¡Este espacio está en llamas! Inflige un punto de daño a la carta que lo ocupa al final del turno. El efecto dura un turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (2)", "Espacio en llamas (2)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts two turns.", "¡Este espacio está en llamas! Inflige un punto de daño a la carta que lo ocupa al final del turno. El efecto dura dos turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (3)", "Espacio en llamas (3)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts three turns.", "¡Este espacio está en llamas! Inflige un punto de daño a la carta que lo ocupa al final del turno. El efecto dura tres turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (4)", "Espacio en llamas (4)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts four turns.", "¡Este espacio está en llamas! Inflige un punto de daño a la carta que lo ocupa al final del turno. El efecto dura cuatro turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burnt Out", "Última llamarada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it sets the land on fire for three turns.", "Cuando [creature] muere, prende fuego al espacio que ocupa durante tres turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "on fire", "en llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catch Fire", "Prender fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target is set on fire.", "Cuando [creature] apunta a un espacio, este prende fuego.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transforms When Unpowered", "Transformación sin alimentación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is NOT within a circuit at the beginning of the turn, it will transform back into its original form.", "Si [creature] NO está dentro de un circuito al comienzo del turno, vuelve a su forma original.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne When Unpowered", "Acuático sin alimentación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is NOT within a circuit it submerges itself during its opponent's turn. While submerged, opposing creatures attack its owner directly.", "Si [creature] NO está dentro de un circuito, se sumerge durante el turno de su rival. Mientras está sumergida, las criaturas enfrente atacan directamente a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short Circuit", "Cortocircuito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, create a Zap! in your hand. Zap! is defined as a spell that costs 2 energy and deals 1 damage to any target.", "Si [creature] está dentro de un circuito al comienzo del turno, crea una carta «¡Descarga!» en tu mano. «¡Descarga!» es un hechizo que cuesta 2 de energía e inflige 1 de daño a cualquier objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, create a Zap! in your hand. Zap! is defined as a command that costs 2 energy and deals 1 damage to any target.", "Si [creature] está dentro de un circuito al comienzo del turno, crea una carta «¡Descarga!» en tu mano. «¡Descarga!» es una orden que cuesta 2 de energía e inflige 1 de daño a cualquier objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transforms When Powered", "Transformación con alimentación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, it will transform into a stronger form.", "Si [creature] está dentro de un circuito al comienzo del turno, se transforma en una forma más poderosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explodonate When Powered", "Cereza explosiva alimentada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it detonates itself and deals 10 damage to all five adjacent spaces.", "Si [creature] está dentro de un circuito, detona e inflige 10 de daño a los cinco espacios adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics When Powered", "Gemnasia mental alimentada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, if it is within a circuit, its owner draw cards equal to the number of Mox Cards on their side of the game board.", "Cuando se juega [creature], si está dentro de un circuito, su propietario roba tantas cartas como cartas mox haya en su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trap When Powered", "Trampa alimentada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes while in a circuit, the creature opposing it perishes as well. A Vessel is created in your hand.", "Cuando una carta que lleve este sello muere dentro de un circuito, también muere la criatura enfrente. Se crea un Receptáculo en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unkillable When Powered", "Inmatable con alimentación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit when it perishes, a copy of it is created in your hand.", "Si [creature] está dentro de un circuito cuando muere, se crea una copia en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splice Conduit", "Conducto de empalme", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] completes a circuit, all cards within that circuit are moved towards it, splicing with it if possible.", "Si [creature] completa un circuito, todas las cartas dentro de él se mueven hacia ella y se empalman con ella si es posible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Conduit", "Conducto apestoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Stinky.", "Las cartas dentro de un circuito completado por [creature] tienen Apestoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Conduit", "Conducto aéreo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Airborne.", "Las cartas dentro de un circuito completado por [creature] tienen Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Conduit", "Conducto de gas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Fire Strike and Burnt Out.", "Las cartas dentro de un circuito completado por [creature] tienen Golpe de fuego y Última llamarada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bedazzling Conduit", "Conducto deslumbrante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] are Gemified.", "Las cartas dentro de un circuito completado por [creature] están gemificadas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Static Electricity", "Electricidad estática", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause all friendly cards to behave as if they are part of a completed conduit.", "[creature] hace que todas las cartas aliadas se comporten como si formaran parte de un circuito completo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Generator", "Generador de gas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it has fuel, [creature] will cause all friendly cards to behave as if they are part of a completed conduit.", "Mientras tenga combustible, [creature] hace que todas las cartas aliadas se comporten como si formaran parte de un circuito completo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Protector", "Protector conducto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is within a completed circuit, damage that would be dealt to the conduits is dealt to this creature instead.", "Cuando [creature] está dentro de un circuito completo, el daño destinado a los conductos se inflige a esta criatura en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Byte", "Byte muerto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, take 1 damage.", "Cuando una carta que lleve este sello muere, recibes 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Sprinter", "Doble carrera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil will move in the direction inscribed in the sigil twice.", "Al final del turno de su propietario, una carta que lleve este sello se mueve dos veces en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Summoner", "Invocador de Quebradizo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random brittle card is created in your hand.", "Cuando se juega [creature], se crea en tu mano una carta aleatoria con Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iterate", "Iteración", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it with a different cost is created in your hand.", "Cuando se juega [creature], se crea en tu mano una copia con un coste distinto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tinkerer", "Manitas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create three spell cards selected at random.", "Cuando se juega [creature], crea tres cartas de hechizo elegidas al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create three command cards selected at random.", "Cuando se juega [creature], crea tres cartas de orden elegidas al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phasers Ready", "Fáseres listos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create two Zap! cards in hand. Zap! is defined as a spell that costs 2 energy and deals 1 damage to any target.", "Cuando se juega [creature], crea dos cartas «¡Descarga!» en tu mano. «¡Descarga!» es un hechizo que cuesta 2 de energía e inflige 1 de daño a cualquier objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create two Zap! cards in hand. Zap! is defined as a command that costs 2 energy and deals 1 damage to any target.", "Cuando se juega [creature], crea dos cartas «¡Descarga!» en tu mano. «¡Descarga!» es una orden que cuesta 2 de energía e inflige 1 de daño a cualquier objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combat Research", "Investigación de combate", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, create a Forced Upgrade card in hand. Forced Upgrade is defined as a spell that costs 2 energy and caused any target to upgrade to a new version.", "Cuando [creature] inflige daño, crea una carta Mejora forzada en tu mano. Mejora forzada es un hechizo que cuesta 2 de energía y mejora cualquier objetivo a una nueva versión.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, create a Forced Upgrade card in hand. Forced Upgrade is defined as a command that costs 2 energy and caused any target to upgrade to a new version.", "Cuando [creature] inflige daño, crea una carta Mejora forzada en tu mano. Mejora forzada es una orden que cuesta 2 de energía y mejora cualquier objetivo a una nueva versión.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric", "Guía eléctrica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] declares an attack, it will deal half the damage to cards adjacent to the target.", "Cuando [creature] declara un ataque, inflige la mitad del daño a las cartas adyacentes al objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Buff", "Mejora de mox verde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it gains two health for each Green Mox its owner controls.", "Cuando se juega [creature], obtiene dos de salud por cada mox verde que controle su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Blessing", "Bendición de esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] provides +2 Health to all creatures you control.", "[creature] proporciona +2 de salud a todas las criaturas que controlas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Shard", "Fragmento de esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, an Emerald Mox is created in its place and a card bearing this sigil moves to the right.", "Cuando [creature] está a punto de recibir un golpe, se crea un mox esmeralda en su lugar y una carta que lleve este sello se mueve a la derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armor Giver", "Otorgador de armadura", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] enters, all opposing cards gain Nano Armor.", "Cuando [creature] entra en juego, todas las cartas rivales obtienen Acorazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Siphon", "Sifón de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card you own dies in combat, [creature] creates a Charge in your hand. Charge is a spell that refills 1 Energy when played.", "Cada vez que otra carta que posees muere en combate, [creature] crea una carta «¡Carga!» en tu mano. «¡Carga!» es un hechizo que recupera 1 de energía al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card you own dies in combat, [creature] creates a Charge in your hand. Charge is a command that refills 1 Energy when played.", "Cada vez que otra carta que posees muere en combate, [creature] crea una carta «¡Carga!» en tu mano. «¡Carga!» es una orden que recupera 1 de energía al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explodonate", "Cereza explosiva", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it explodes and deals 10 damage to all five adjacent slots.", "Cuando [creature] muere, explota e inflige 10 de daño a los cinco espacios adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Strike", "Golpe de fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it sets the target space on fire for three turns.", "Cuando [creature] ataca, prende fuego al espacio objetivo durante tres turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Strike When Fueled", "Golpe de fuego con combustible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, if it is fueled, it consumes one fuel to set the target space on fire for three turns.", "Cuando [creature] ataca y tiene combustible, consume una unidad para prender fuego al espacio objetivo durante tres turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Stoker", "Avivador de llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on board, all fires you start will be stronger, causing them to last one turn longer.", "Mientras [creature] esté en el tablero, todos los fuegos que enciendas son más fuertes y duran un turno más.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fling", "Lanzamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, if one or more cards was sacrificed to play it, [creature] deals damage to a card of the player's choice equal to the total attack value of all sacrificed cards.", "Cuando se juega [creature], si se sacrificaron una o más cartas para jugarla, [creature] inflige a una carta elegida por el jugador daño igual a la suma del ataque de todas las cartas sacrificadas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade", "Mejora forzada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target is immediately upgraded to a stronger version of itself.", "Cuando [creature] apunta a un espacio, el objetivo se mejora de inmediato a una versión más poderosa de sí mismo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Donation", "Donación de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards can be sacrificed to pay blood costs even if they normally could not.", "Mientras [creature] esté viva, todas las cartas aliadas pueden sacrificarse para pagar costes de sangre, aunque normalmente no pudieran hacerlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Giver", "Don de piedra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards are Made of Stone", "Mientras [creature] esté viva, todas las cartas aliadas tienen Hecho de piedra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dust Giver", "Don de polvo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards have Magic Dust.", "Mientras [creature] esté viva, todas las cartas aliadas tienen Polvo mágico.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Roller", "Rodillo de carbón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards which have fuel are Stinky.", "Mientras [creature] esté viva, todas las cartas aliadas con combustible tienen Apestoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Ignition", "Ignición de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly gems have +1 Power, Flame Strike, Brittle, and Burnt Out.", "Mientras [creature] esté viva, todas las gemas aliadas obtienen +1 de poder, Golpe de fuego, Quebradizo y Última llamarada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Strike", "Golpe con combustible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes one fuel to attack and can only attack if it has fuel.", "[creature] consume una unidad de combustible para atacar y solo puede atacar si tiene combustible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card carries an external fuel source which powers one or more of its sigils. When a card's fuel tank empties, those sigils cease to function.", "Esta carta lleva una fuente externa de combustible que alimenta uno o más de sus sellos. Cuando el depósito se vacía, esos sellos dejan de funcionar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel", "Combustible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Shield", "Escudo de combustible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] has fuel, it takes damage by losing fuel instead of health.", "Mientras [creature] tenga combustible, al recibir daño pierde combustible en lugar de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Siphon", "Sifón de combustible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] deals damage directly to the opponent, it gains that much fuel.", "Cada vez que [creature] inflige daño directo al rival, obtiene esa misma cantidad de combustible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Blood", "Lleno de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can be sacrificed to pay blood costs.", "[creature] puede sacrificarse para pagar costes de sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Oil", "Lleno de aceite", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it adds 3 health to each card on either side and across from it.", "Cuando [creature] muere, añade 3 de salud a cada carta a sus lados y enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully Loaded", "Carga completa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves a permanent +1 attack bonus in the lane it occupied.", "Cuando [creature] muere, deja una bonificación permanente de +1 de ataque en el carril que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot has its power increased by one.", "La carta de este espacio obtiene un punto de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defend", "Defensa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target gains Nano Armor.", "Cuando [creature] apunta a un espacio, el objetivo obtiene Acorazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Gift", "Regalo de mox azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, if you control an Blue Mox, gain a random card.", "Cuando [creature] muere, si controlas un mox azul, obtén una carta aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Looter", "Saqueador de mox azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage directly, if you control a Blue Mox, draw a card for each damage dealt.", "Cuando [creature] inflige daño directo, si controlas un mox azul, roba una carta por cada punto de daño infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist With Blue", "Purismo azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the owner of [creature] controls a Blue Mox, cards opposing [creature] have their sigils removed.", "Si el propietario de [creature] controla un mox azul, las cartas frente a [creature] pierden sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Without Green", "Molesto sin verde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing [creature] gains 1 power unless the owner of [creature] also controls a Green Mox.", "La criatura frente a [creature] obtiene 1 de poder, salvo que el propietario de [creature] también controle un mox verde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Gift", "Regalo de mox verde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, if you control a Green Mox, gain a random card.", "Cuando [creature] muere, si controlas un mox verde, obtén una carta aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Without Orange", "Quebradizo sin naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] will perish if its owner does not control an Orange Mox.", "Después de atacar, [creature] muere si su propietario no controla un mox naranja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Airborne", "Aéreo con mox naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you control an Orange Mox, [creature] will ignore opposing cards and strike an opponent directly.", "Si controlas un mox naranja, [creature] ignora las cartas enfrente y golpea directamente a un rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Printer", "Impresora de mox naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you control an Orange Mox, [creature] will draw a card from your side deck at the start of every turn.", "Si controlas un mox naranja, [creature] roba una carta de tu mazo secundario al comienzo de cada turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Strike", "Golpe de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks once for each gem provider its owner controls.", "[creature] ataca una vez por cada proveedor de gemas que controle su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Power", "Poder esmeralda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of green gems its owner controls.", "El valor representado por este sello es igual al número de gemas verdes que controle su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopper", "Saltador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] moves to an empty space of its owner's choosing.", "Al final de cada turno, [creature] se mueve a un espacio vacío elegido por su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kraken Transformer", "Transformación de kraken", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of your turn, [creature] will transform to, or from, Kraken mode.", "Al comienzo de tu turno, [creature] cambia al modo kraken o vuelve a su forma anterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Latch", "Acople molesto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Annoying sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Molesto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Latch", "Acople de muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will die at the end of the turn. When [creature] perishes, its owner chooses a creature to gain this sigil. This will repeat.", "[creature] muere al final del turno. Cuando [creature] muere, su propietario elige una criatura que obtiene este sello. El proceso se repite.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Latch", "Acople del primer sello", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the first sigil this card has.", "Cuando [creature] muere, su propietario elige una criatura que obtiene el primer sello de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Latch", "Acople aéreo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Airborne sigil.", "Cuando [creature] muere, su propietario elige una criatura para que obtenga el sello Aéreo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Latch", "Acople de conducto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Null Conduit sigil.", "Cuando [creature] muere, su propietario elige una criatura que recibe el sello Conducto nulo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rampage Latch", "Acople desenfrenado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Rampager sigil. The target will immediately rampage once when the latch is applied.", "Cuando [creature] muere, su propietario elige una criatura que recibe el sello Desenfrenado. El objetivo embiste una vez al recibir el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Latch", "Acople apestoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Stinky sigil.", "Cuando [creature] muere, su propietario elige una criatura que recibe el sello Apestoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swapper Latch", "Acople intercambiador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Swapper sigil. The target will immediately swap stats once when the latch is applied.", "Cuando [creature] muere, su propietario elige una criatura que recibe el sello Intercambiador. El objetivo intercambia sus estadísticas una vez al recibir el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lootbox", "Caja de botín", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] kills a card, a random card is created in your hand.", "Cada vez que [creature] mata una carta, se crea una carta aleatoria en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Synchronized Fate", "Destinos unidos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, you lose the game.", "Cuando [creature] muere, pierdes la partida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Dust", "Polvo mágico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves one of its gems behind on the board. Any future cards in that space will provide those gems.", "Cuando [creature] muere, deja una de sus gemas en el tablero. Las cartas colocadas después en ese espacio proporcionarán esa gema.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Slot", "Espacio de Mox azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide a Blue Mox.", "La carta de este espacio proporciona un Mox azul.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Slot", "Espacio de Mox naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide an Orange Mox.", "La carta de este espacio proporciona un Mox naranja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Slot", "Espacio de Mox verde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide a Green Mox.", "La carta de este espacio proporciona un Mox verde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Mox Slot", "Espacio de Gran mox", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide all three moxen.", "La carta de este espacio proporciona los tres tipos de mox.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miner", "Minero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] buries itself during its opponent's turn. While buried, opposing creatures attack its owner directly. When it comes back up, it creates a card in its owner's hand.", "[creature] se entierra durante el turno de su oponente. Mientras está enterrada, las criaturas de enfrente atacan directamente a su propietario. Al volver a salir, crea una carta en la mano de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rubber Stamp", "Sello de goma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever you play [creature], it becomes a copy of another creature of your choosing. If this creature has other abilities, those abilities will be transferred (up to the maximum of 4).", "Cuando juegas [creature], se convierte en una copia de otra criatura de tu elección. Si esta carta tiene otras habilidades, se transfieren a la copia, hasta un máximo de 4.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launch Missile", "Lanzamisiles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can skip its attack this turn to launch a missile that lands on the next turn, splashing damage to adjacent spaces. Use carefully - ammo is limited.", "[creature] puede renunciar a su ataque este turno para lanzar un misil que caerá en el siguiente turno e infligirá daño a los espacios adyacentes. Úsalo con cuidado: la munición es limitada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launch Self", "Autolanzamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can sacrifice itself to launch a missile that lands on the next turn, splashing damage to adjacent spaces.", "[creature] puede sacrificarse para lanzar un misil que caerá en el siguiente turno e infligirá daño a los espacios adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flammable", "Inflamable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it detonates and sets adjacent spaces on fire for three turns.", "Cuando [creature] muere, explota e incendia los espacios adyacentes durante tres turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arsonist", "Pirómano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it sets all spaces on the board on fire for four turns.", "Cuando se juega [creature], incendia todos los espacios del tablero durante cuatro turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refueler", "Reabastecedor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it has fuel, [creature] will attempt to move beside any creatures you play that also use fuel. Each turn, [creature] will refuel adjacent creatures.", "Mientras tenga combustible, [creature] intentará moverse junto a las criaturas que juegues y que también usen combustible. Cada turno [creature] reabastece a las criaturas adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Second Chance", "Segunda oportunidad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly non-Brittle creature dies, if [creature] is on the battlefield, a 1/1 skeleton will be created in its place.", "Cuando muere una criatura aliada sin Quebradizo y [creature] está en el campo de batalla, se crea un esqueleto 1/1 en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonus Energy Conduit", "Conducto de energía adicional", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, it provides a reserve of energy equal to the player's current maximum energy.", "Si [creature] forma parte de un circuito completo, proporciona una reserva de energía igual a la energía máxima actual del jugador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclocked", "Sobrepotenciación esquelética", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it permanently becomes an Exeskeleton with the same abilities. If [creature] has Unkillable, it will be unaffected.", "Cuando [creature] muere, se convierte permanentemente en un Exeesqueleto con las mismas habilidades. Si [creature] tiene Inmatable, no se ve afectada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overheat", "Sobrecalentamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the scales are in your favor, [creature] loses 1 power. When the scales aren't in your favor, [creature] gains 1 power.", "Cuando la balanza está a tu favor, [creature] pierde 1 de poder. Cuando no está a tu favor, [creature] obtiene 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power Drain", "Drenaje de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes all of its owner's available energy each turn.", "Cada turno, [creature] consume toda la energía disponible de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Purismo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards opposing [creature] have their sigils removed.", "Las cartas frente a [creature] pierden sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This handles actually removing abilities. You should never see this ability on a card!!!", "Este efecto elimina realmente las habilidades. ¡Nunca deberías ver esta habilidad en una carta!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunter", "Cazarrecompensas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When drawn, [creature] will turn into a random bounty hunter.", "Cuando se roba [creature], se convierte en un cazarrecompensas aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nerf This!", "¡Nerfea esto!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it gains a randomly selected negative ability.", "Cuando se roba [creature], obtiene una habilidad negativa elegida al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apotheosis", "Apoteosis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it gains a randomly selected rare ability.", "Cuando se roba [creature], obtiene una habilidad rara elegida al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "Recarga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, one energy will be refilled (up to the player's maximum energy)", "Cuando se juega [creature], se recupera un punto de energía, hasta la energía máxima del jugador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alarm Clock", "Despertador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature that this sigil is pointing to will gain +1 attack. The clock will turn at the beginning of the player's turn.", "La criatura a la que apunta este sello obtiene +1 de ataque. El reloj gira al comienzo del turno del jugador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Blessing", "Bendición del rubí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] provides +1 Attack to all creatures you control.", "[creature] otorga +1 de ataque a todas las criaturas que controlas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Warrior", "Guerrero de Mox naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it attacks all enemy cards opposite Orange Mox providers its owner controls.", "Cuando se juega [creature], ataca a todas las cartas enemigas situadas frente a proveedores de Mox naranja que controle su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burst", "Estallido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] explode, dealing 10 damage to each adjacent card.", "Las cartas sacrificadas para pagar [creature] explotan e infligen 10 de daño a cada carta adyacente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Consumer", "Devoragemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all gem vessels on its owner's side of the board are sacrificed.", "Cuando se juega [creature], se sacrifican todos los receptáculos de gemas del lado de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emergence Latch", "Acople de emersión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When cards sacrificed to pay for [creature] die, their owner chooses a card to gain their first sigil.", "Cuando mueren las cartas sacrificadas para pagar [creature], su propietario elige una carta que recibe su primer sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Macabre Growth", "Crecimiento macabro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains the attack and health of all cards sacrificed to play it.", "[creature] obtiene el ataque y la salud de todas las cartas sacrificadas para jugarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shatter", "Añicos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] drop 4 bones instead of 1 when they die.", "Las cartas sacrificadas para pagar [creature] dejan 4 huesos en lugar de 1 al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts Sacrifice", "Sacrificio de entrañas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] slime the opposing slot when they die. Cards in slimed slots have one less power.", "Cuando mueren las cartas sacrificadas para pagar [creature], cubren de limo el espacio de enfrente. Las cartas en espacios viscosos tienen un punto de poder menos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Charger", "Cargador de Mox azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it creates a Charge in your hand for each Blue Mox its owner controls. Charge is a spell that refills 1 Energy when played.", "Cuando se juega [creature], crea una carta «¡Carga!» en tu mano por cada Mox azul que controle su propietario. «¡Carga!» es un hechizo que recupera 1 de energía al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it creates a Charge in your hand for each Blue Mox its owner controls. Charge is a command that refills 1 Energy when played.", "Cuando se juega [creature], crea una carta «¡Carga!» en tu mano por cada Mox azul que controle su propietario. «¡Carga!» es un comando que recupera 1 de energía al jugarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Blessing", "Bendición del zafiro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] reduces the cost of all cards in your hand by 1.", "[creature] reduce en 1 el coste de todas las cartas de tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Dumper", "Volcador de chatarra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, a broken bot is played on the opposing space.", "Cuando se juega una carta que lleva este sello, se juega un Bot roto en el espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Salvage", "Recuperación de chatarra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, add the total cost of all cards sacrificed to play it, then create a Charge! for each energy, create a Zap! for each gem, create an Upgrade! for each blood, and create a Defend! for each bone.", "Cuando se juega [creature], suma el coste de todas las cartas sacrificadas para jugarla: crea una «¡Carga!» por cada energía, una «¡Descarga!» por cada gema, una «¡Mejora!» por cada sangre y una «¡Defensa!» por cada hueso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bulldoze", "Allanamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to cause this card to move in the direction inscribed in the sigil. Creatures that are in the way will be pushed in the same direction.", "Paga 1 de energía para mover esta carta en la dirección indicada por el sello. Las criaturas que estén en su camino serán empujadas en la misma dirección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shred", "Trituración", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shred a card from your hand to get +1 Attack (until end of turn). The shredded card behaves as if it died. Unkillable cards and cards Made of Stone cannot be shredded.", "Tritura una carta de tu mano para obtener +1 de ataque hasta el final del turno. La carta triturada se comporta como si hubiera muerto. Las cartas con Inmatable o Hecho de piedra no pueden triturarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Power", "Poder del mazo secundario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards its owner has drawn from the side deck.", "El valor representado por este sello equivale al número de cartas que su propietario ha robado del mazo secundario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimed Slot", "Espacio viscoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will have its attack reduced by one.", "El ataque de la carta en este espacio se reduce en uno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phase Through", "Atravesar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its controller's turn, [creature] moves one space in the direction indicated, moving through other cards if necessary until it finds an empty space.", "Al final del turno de quien la controla, [creature] se mueve un espacio en la dirección indicada y atraviesa otras cartas si hace falta hasta encontrar un espacio vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Heart", "Corazón solar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, its heart stays behind and provides conduit power to the slot.", "Cuando [creature] muere, su corazón permanece y proporciona energía de conducto al espacio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Powered", "Alimentación solar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card slot stays powered at all times, even if it is not in a completed circuit.", "Este espacio de carta permanece siempre alimentado, aunque no forme parte de un circuito completo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overwhelming Entrance", "Entrada arrolladora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opposing creatures are tossed into new slots. Non-conduit terrain is not affected.", "Cuando se juega [creature], todas las criaturas rivales son arrojadas a otros espacios. El terreno que no sea un conducto no se ve afectado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Familiar", "Invocar familiar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it plays a techbeast in an empty adjacent slot.", "Cuando se juega [creature], juega una tecnobestia en un espacio adyacente vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zip of Death", "Velocidad mortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take 2 damage.", "Recibe 2 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Target Required", "Objetivo necesario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can only attack lanes that have cards in them.", "[creature] solo puede atacar carriles que contengan cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Controlled", "Controlado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is under control of its opponent. At the end of the turn, it will return to its owner. While being controlled, it cannot be hammered.", "[creature] está bajo el control de su oponente. Al final del turno vuelve con su propietario. Mientras está controlada, no se puede golpear con el martillo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Bola de fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its turn, [creature] chooses a card slot to set on fire for three turns.", "Al final de su turno, [creature] elige un espacio de carta y lo incendia durante tres turnos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimeball", "Bola de slime", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its turn, [creature] will choose one slot to become slimed. Cards in a slimed slot lose one power.", "Al final de su turno, [creature] elige un espacio para cubrirlo de limo. Las cartas en un espacio viscoso pierden un punto de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Vandal", "Vándalo de limo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it slimes all slots on the board. Cards in slimed slots lose one power.", "Cuando se juega [creature], cubre de limo todos los espacios del tablero. Las cartas en espacios viscosos pierden un punto de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Guts", "Lleno de entrañas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it slimes the opposing slot.", "Cuando [creature] muere, cubre de limo el espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seed Sprinter", "Velocista sembrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its controller's turn, [creature] moves one space in the direction indicated (if it can) and plants a seed in its previous space.", "Al final del turno de quien la controla, [creature] se mueve un espacio en la dirección indicada, si puede, y planta una semilla en su espacio anterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vessel Heart", "Corazón de receptáculo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, a vessel is created in its place.", "Cuando muere una carta que lleva este sello, se crea un receptáculo en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zap", "Descarga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals damage directly to the target.", "Inflige daño directamente al objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urchin Spawn Conduit", "Conducto generador de erizos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Urchin Cells at the end of the owner's turn.", "Al final del turno del propietario, aparecen células de erizo en los espacios vacíos de un circuito completado por [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to set the power of [creature] randomly between 1 and 6.", "Paga 2 de energía para fijar el poder de [creature] en un valor aleatorio entre 1 y 6.", Language.Spanish);
        }
    }
    public class P03InKayceesModMod
    {
        public static Dictionary<string, string> Consumables = new();
        public static Dictionary<string, string> Mods = new();
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, string> CardParts = new();

        public static void RegisterConsumable(string en, string zh)
        {
            Consumables.Add(en, zh);
        }

        public static void RegisterMod(string en, string zh)
        {
            Mods.Add(en, zh);
        }
        public static void RegisterCard(string en, string zh)
        {
            Cards[en] = zh;
        }
        public static void RegisterCardPart(string en, string zh)
        {
            CardParts[en] = zh;
        }
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for P03InKayceesMod Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW P03 RUN", "PARTIDA NUEVA CON P03", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE P03 RUN", "CONTINUAR PARTIDA CON P03", Language.Spanish);

            // Ability: Base
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "Doble muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head Shot", "Tiro a la cabeza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is immune to the effects of Touch of Death, Stinky, and fire.", "[creature] es inmune a los efectos de Toque de la muerte, Apestoso y el fuego.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no Gem Vessels, [creature] perishes.", "Si el propietario de [creature] no controla ningún receptáculo de gemas, [creature] muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mine Cryptocurrency", "Minar criptomonedas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When part of a conduit, [creature] will generate cryptocurrency.", "Cuando forma parte de un conducto, [creature] genera criptomonedas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stamp Paperwork", "Sellar documentos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to stamp this paperwork as properly filed and ready for further processing.", "Paga 1 de energía para sellar estos documentos como correctamente archivados y listos para su posterior tramitación.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Strike", "Golpe poderoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks all cards in all lanes opposing it, or attacks just the center opposing lane if there are no cards it can attack.", "[creature] ataca a todas las cartas de todos los carriles de enfrente. Si no hay cartas a las que pueda atacar, solo ataca el carril central de enfrente.", Language.Spanish);
            // Ability: Multiverse
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Bomb Latch", "Acople bomba multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Multiverse Detonator sigil.", "Cuando [creature] muere, su propietario elige una criatura de cualquier universo que recibe el sello Detonador multiversal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Brittle Latch", "Acople quebradizo multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Brittle sigil.", "Cuando [creature] muere, su propietario elige una criatura de cualquier universo que recibe el sello Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Detonator", "Detonador multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all adjacent cards in all universes are dealt 10 damage", "Cuando [creature] muere, todas las cartas adyacentes de todos los universos reciben 10 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Full of Oil", "Lleno de aceite multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it adds 3 health to the creature on either side and across from it in every universe.", "Cuando [creature] muere, las criaturas a ambos lados y frente a ella en cada universo obtienen 3 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Fully Loaded", "Carga completa multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves a permanent +1 attack bonus in the lane it occupied in every universe.", "Cuando [creature] muere, deja una bonificación permanente de +1 de ataque en el carril que ocupaba en cada universo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Guardian", "Guardián multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space in any universe, [creature] will move to that empty space.", "Cuando se coloca una criatura rival frente a un espacio vacío en cualquier universo, [creature] se mueve a ese espacio vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Burrower", "Excavador multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an empty space would be struck, [creature] will cross universes to move to that space to receive the strike instead.", "Cuando un espacio vacío vaya a recibir un golpe, [creature] cruzará universos y se moverá a ese espacio para recibirlo en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Null Conduit", "Conducto nulo multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuits completed by [creature] are completed in every universe.", "Los circuitos completados por [creature] se completan en todos los universos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Mighty Leap", "Salto poderoso multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will leap across universes to block attacks that occur in this lane in any universe.", "[creature] salta entre universos para bloquear los ataques en este carril en cualquier universo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Sentry", "Centinela multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature] in any universe, they are dealt 1 damage.", "Cuando una criatura se mueve al espacio frente a [creature] en cualquier universo, recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Shield Latch", "Acople de escudo multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Nano Armor sigil.", "Cuando [creature] muere, su propietario elige una criatura de cualquier universo que recibe el sello Acorazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Sprinter", "Velocista multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to the next universe.", "Al final del turno de su propietario, [creature] se mueve al siguiente universo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Strike", "Golpe multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space in every universe other than its own.", "[creature] golpea cada espacio de enfrente en todos los universos salvo el suyo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Great Mox", "Gran mox multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Green, Orange, and Blue Gem is provided to the owner's side in every universe.", "Cuando se juega [creature], se proporciona una gema verde, una naranja y una azul al lado de su propietario en cada universo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Hoarder", "Acaparador multiversal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search the multiverse for a card that has perished that is capable of traversing the multiverse.", "Cuando se juega [creature], puedes buscar en el multiverso una carta que haya muerto y pueda atravesar los universos.", Language.Spanish);


