            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The second official expansion pack, with [count] firey new cards that command an explosive reaction!", "¡El segundo paquete de expansión oficial trae [count] cartas nuevas y ardientes que provocarán una reacción explosiva!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Rogue Bots of Botopia", "Inscryption: Robots rebeldes de Botopía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has become overrun with rogue bots! These [count] encounters have been rebalanced for Kaycee's Mod.", "¡Botopía está infestada de robots rebeldes! Estos [count] encuentros se han reequilibrado para el Mod de Kaycee.", Language.Spanish);
