    public class DeathcardChallengesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for DeathcardChallenges Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathcards", "Cartas de muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may find past challengers' deathcards during your run", "Puedes encontrar cartas de muerte de aspirantes anteriores durante tu partida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathcard Creation", "Creación de carta de muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will create a deathcard if you lose", "Crearás una carta de muerte si pierdes", Language.Spanish);

        }
    }
