            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you lay the spikeweed as a trap for those who dare approach it?", "¿Colocarás la Hierba de pinchos como trampa para quienes se atrevan a acercarse?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anybody who attempts to trample it will meet a sharp fate.", "Quien intente pisotearla se encontrará con un destino punzante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artichoke", "Alcachofa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This drone has seen some warfare", "Este dron ha vivido la guerra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beeshooter", "Lanzaabejas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "According to all known laws of aviation, there is no way a bee should be able to fly", "Según todas las leyes conocidas de la aviación, una abeja no debería poder volar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puffshroom", "Seta soplona", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It might not be very powerful, but it can get you out of a pinch", "Puede que no sea muy poderoso, pero puede sacarte de un apuro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seashroom", "Seta marina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a little mushroom, sitting on the water", "Una pequeña seta posada sobre el agua, sin más", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredyshroom", "Seta miedosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some may consider this one a coward for its tactics", "Algunos lo considerarían un cobarde por sus tácticas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fume", "Vaho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fumeshroom", "Seta humosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its fumes can hit many foes", "Sus vapores pueden alcanzar a muchos enemigos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporeshroom", "Seta de esporas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put divide and conquer into practice", "Pon en práctica el divide y vencerás", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sunflower", "Girasol", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These can power entire infantries", "Pueden proporcionar energía a ejércitos enteros", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Sunflower", "Girasol gemelo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly a great powerplant", "Una auténtica central vegetal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SunShroom", "Seta solar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "allow the sunshroom some time to reach its full potential", "Dale tiempo a la Seta solar para alcanzar todo su potencial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ToadStool", "Seta sapo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A frogish fungus, how curious", "Un hongo parecido a una rana, qué curioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun bean", "Frijol solar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will you invest in the sun bean?", "¿Invertirás en el Frijol solar?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wallnut", "Nuez", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an iconic line of defence", "Una línea de defensa emblemática", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tallnut", "Nuez alta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Near nothing can get past this one", "Casi nada puede pasar por encima", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endurian", "Durio resistente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's outer shell wont be so enjoyable to get through", "Atravesar su cáscara no será nada agradable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Garlic", "Ajo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Control the upcoming onslaughts with the Garlic's stench.", "Controla los ataques venideros con el hedor del Ajo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infi-nut", "Nuez infinita", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeating this one isn't so simple", "Derrotarla no es tan sencillo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potato Mine", "Patatapum", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small but potentially dangerous spud", "Una patata pequeña, pero potencialmente peligrosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cherry Bomb", "Cereza explosiva", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It may be sweet but you shouldnt underestimate it", "Puede que sea dulce, pero no la subestimes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jalapeno", "Jalapeño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I would not want to eat that", "No querría comer eso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DoomShroom", "Seta funesta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A force to be reckoned with", "Una fuerza a tener en cuenta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torchwood", "Tronco antorcha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can boost it's allies' power", "Puede aumentar el poder de sus aliados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MagnetShroom", "Seta imán", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakens the enemy to aid its allies", "Debilita al enemigo para ayudar a sus aliados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypnoshroom", "Seta hipnótica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One mans foe is another mans friend", "El enemigo de uno es el amigo de otro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Leaf", "Hoja dorada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foil your opponents' plans by turning over a new leaf", "Frustra los planes de tus rivales pasando página", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pumpkin", "Cabeza de calabaza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fortify all of your cards with this one simple trick", "Fortalece todas tus cartas con este sencillo truco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape Root", "Raíz de escape", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allows other cards the freedom of escaping to safety", "Permite que otras cartas escapen a un lugar seguro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee bean", "Grano de café", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can energise plants and unlock further potential", "Puede dar energía a las plantas y liberar más potencial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprout", "Brote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But a simple sprout, what will it grow into? nobody knows, Limitless potential", "Un simple brote, ¿en qué se convertirá? Nadie lo sabe. Su potencial es ilimitado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A common browncoat, hungry for brains", "Un zombi corriente de chaqueta marrón, hambriento de cerebros", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conehead", "Cabezacono", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A browncoat that equipped itself with road work equipment", "Un zombi de chaqueta marrón equipado con material de obras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buckethead", "Cabezacubo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To think headgear could provide so much protection", "Quién iba a pensar que algo en la cabeza pudiera proteger tanto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flag Zombie", "Zombi abanderado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A true leader, calling in allies for combat", "Un verdadero líder que llama a sus aliados al combate", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snorkel", "Buceador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dives in the deep and emerges for a munch", "Se sumerge en las profundidades y emerge para dar un bocado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screen Door", "Puerta mosquitera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I much prefer doors of sturdy wood", "Prefiero las puertas de madera resistente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jack in a box", "Caja sorpresa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one brings tension with such a simple melody", "Una melodía tan sencilla crea mucha tensión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crater", "Cráter", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a hole", "Solo un agujero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cycle of the forest", "El ciclo del bosque", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shroom Chunksr", "Trozos de seta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chunks of shrooms", "Trozos de seta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shards of shells", "Fragmentos de cáscara", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie Arm", "Brazo de zombi", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A zombie must have dropped this", "Seguro que a un zombi se le ha caído", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stray Cat", "Gato callejero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How bizarre.. i don't recognise that one", "Qué raro... No reconozco a ese", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stray Cat Requiem", "Réquiem del Gato callejero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debugger", "Depurador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debuggest", "Superdepurador", Language.Spanish);

            // Starter
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plants vs Zombies", "Plants vs. Zombies", Language.Spanish);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds plants vs zombies cards to the mix, with a custom sun currency too. Contains " + count.ToString() + " new cards.", "Añade cartas de Plants vs. Zombies y un recurso de sol personalizado. Contiene " + count.ToString() + " " + (count == 1 ? "carta nueva" : "cartas nuevas") + ".", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original seeds", "Las semillas originales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The midnight crew", "El equipo de medianoche", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Zen Garden", "El jardín zen", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Stats", "Añadir estadísticas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its health, attack, and other sigils will be added to every other non terrain card on your side of the board. Then this card will perish. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Cuando se juega [creature], su salud, ataque y otros sellos se añaden a todas las demás cartas que no sean terrenos de tu lado del tablero. Después esta carta perece. Las cartas que llevan este sello no pueden usarse para transferir sellos ni en hogueras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of teamwork", "El poder del trabajo en equipo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Stats Opponent", "Añadir estadísticas al rival", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its health, attack, and other sigils will be added to every card on the opposing side of the board. Then this card will perish. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Cuando se juega [creature], su salud, ataque y otros sellos se añaden a todas las cartas del lado rival del tablero. Después esta carta perece. Las cartas que llevan este sello no pueden usarse para transferir sellos ni en hogueras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blight your foes", "Devasta a tus enemigos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armor breaker", "Rompearmaduras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it removes all defense sigils from all of the opposing cards.", "Cuando se juega [creature], elimina todos los sellos defensivos de todas las cartas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Removing defense is a great offense", "Eliminar defensas es una gran forma de atacar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DoomBringer", "Portador de la ruina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 7 damage to all of the opponent's cards, along with 1 damage to all of the owners cards.", "Al final del turno de su propietario, [creature] explota e inflige 7 de daño a todas las cartas del rival y 1 de daño a todas las cartas de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only destruction lays in its wake", "Solo deja destrucción a su paso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fade Away", "Desvanecimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will take 1 damage.", "Al final del turno de su propietario, [creature] recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing can last forever", "Nada puede durar para siempre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hard Headed", "Cabeza dura", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is attacked, the damage taken will be reduced by 2. Then this sigil will be removed.", "Cuando [creature] recibe un ataque, el daño recibido se reduce en 2. Después se elimina este sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headwear is surprisingly good at negating wounds", "Una protección para la cabeza evita heridas sorprendentemente bien", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypnotist", "Hipnotizador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] gets defeated, its killer will move to take its place.", "Cuando [creature] es derrotada, la carta que la mató se mueve a su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To think that betrayal can happen so easily", "Quién iba a pensar que sería tan fácil traicionar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pierce", "Perforación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before attacking, [creature] attacks the given card in the opposing queue, it also nullifies the Armored sigil.", "Antes de atacar, [creature] ataca la carta correspondiente de la cola rival y también anula el sello Acorazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding in the back doesn't protect you here", "Esconderse detrás no te protege aquí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicy", "Picante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 4 damage to the opposing card and to the card on the opposing backline. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Al final del turno de su propietario, [creature] explota e inflige 4 de daño a la carta enfrentada y a la carta situada detrás en la cola rival. Las cartas que llevan este sello no pueden usarse para transferir sellos ni en hogueras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never been too fond of spice", "Nunca me ha gustado mucho el picante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Spreader", "Propagación de esporas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] defeats another card, a copy of itself will be returned to your hand.", "Si [creature] derrota a otra carta, se añade una copia de ella a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "just how much will these spores spread?", "¿Hasta dónde se extenderán estas esporas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spudow", "Patapum", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] gets defeated, it deals 4 damage to the opposing card.", "Cuando [creature] es derrotada, inflige 4 de daño a la carta enfrentada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always watch your step in a potato field", "Mira siempre dónde pisas en un campo de patatas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweet", "Dulce", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will explode and deal 3 damage to the cards in the 3 enemy slots around it, then deal 1 damage to the cards in your adjacent slots. Cards bearing this sigil cannot be used in sigil transfers or campfires.", "Al final del turno de su propietario, [creature] explota e inflige 3 de daño a las cartas de los 3 espacios enemigos a su alrededor y luego 1 de daño a las cartas de tus espacios adyacentes. Las cartas que llevan este sello no pueden usarse para transferir sellos ni en hogueras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe there's a bit more tartness than anticipated", "Quizá sea un poco más ácido de lo esperado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaredy", "Miedoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 attack but gains 1 health when against an opposing card whose attack is greater than 0, unless the opposing card retreats too.", "[creature] pierde 1 de ataque pero gana 1 de salud cuando se enfrenta a una carta rival con más de 0 de ataque, salvo que esa carta también lleve el sello Miedoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They call it a tactical retreat", "Lo llaman retirada táctica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie Caller", "Invocador de zombis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A zombie gets played on each empty adjacent space, though it may have headgear. [define:zep_pvz_zombie]", "Cuando se juega [creature], se juega un zombi en cada espacio vacío adyacente. Puede llevar algo en la cabeza. [define:zep_pvz_zombie]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A huge wave of zombies is approaching", "Se acerca una enorme oleada de zombis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrooms", "Setas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of mushrooms that the owner has on their side of the table.", "El valor representado por este sello equivale al número de setas en el lado del tablero de su propietario.", Language.Spanish);

        }
    }
    public class SmallTweakHydraMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SmallTweak_Hydra Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this Sigil hatches when drawn if 5 unique numbers are in the Health of creatures in your deck, and in their Power, and if there is a creature of 5 unique tribes in your deck. [This Excludes all cards bearing this sigil]", "Una carta que lleve este sello eclosiona al robarla si las criaturas de tu mazo tienen 5 valores de salud distintos y 5 valores de ataque distintos, y si hay criaturas de 5 tribus distintas en tu mazo. [Se excluyen todas las cartas con este sello]", Language.Spanish);


        }
    }
    public class MoreItemsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MoreItems Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Brittle", "Quebradizo para todos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Sharp", "Espinas afiladas para todos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Brittle", "Todas las cartas del tablero obtienen Quebradizo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Sharp", "Todas las cartas del tablero obtienen Espinas afiladas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Split Strike", "Golpe bifurcado para todos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards on the board gain Split Strike", "Todas las cartas del tablero obtienen Golpe bifurcado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shuffle Sigils", "Mezclar sellos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All sigils on the board are removed and added to a random card", "Se eliminan todos los sellos del tablero y se añaden a una carta aleatoria", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Waterbourne", "Sin inmersión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All my cards on the board with Submerge are revealed and the sigil removed", "Todas las cartas rivales del tablero con Inmersión se revelan y pierden ese sello", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Meat", "Carne caliente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using this item at the campfire will save your card from being destroyed for a single turn.", "Usado en la hoguera, este objeto protege tu carta de la destrucción durante esta visita a la hoguera.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Places Bait Buckets on all empty spaces. The smell is overwhelming.", "Coloca Cubos de cebo en todos los espacios vacíos. El olor es abrumador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mrs. Bomb's Remote", "Mando de la Sra. Bomba", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Places Explode Bots on all empty spaces. Pretty annoying honestly.", "Coloca Bots explosivos en todos los espacios vacíos. Es bastante molesto, la verdad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mrs. Bomb's Remote. Click that thing and Explode Bots will drop in every open space.", "El mando de la Sra. Bomba. Púlsalo y caerán Bots explosivos en todos los espacios vacíos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returns the last friendly card that perished card to your hand", "Devuelve a tu mano la última carta aliada que haya perecido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycologist Saw", "Sierra de los micólogos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combine 2 cards on your side of the board to become one.", "Combina 2 cartas de tu lado del tablero en una sola.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A temporary abomination if I ever 'saw' one.", "Una abominación temporal, de esas que no se ven ni con una sierra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survivor", "Superviviente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card on the board to have a chance to either be destroyed or buffed.", "Elige una de tus cartas del tablero: puede ser destruida o reforzada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teeth Jar", "Tarro de dientes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 10 teeth to your currency bowl. Does not get added to your scales.", "Añade 10 dientes a tu cuenco de moneda. No se añaden a la balanza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack", "Paquete de cartas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 5 random cards to your hand.", "Añade 5 cartas aleatorias a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's why my pack mules are coming back short.", "Así que por eso mis mulas de carga vuelven con menos mercancía de la debida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat Cake", "Pastel de carne", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Relights a candle if you have lost a battle. Does not work during boss battles.", "Vuelve a encender una vela si has perdido una batalla. No funciona durante las batallas contra jefes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In case you change your mind", "Por si cambias de opinión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trap", "Trampa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds a rabbit and pelts to your hand.", "Añade pieles a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pick Axe", "Pico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All my cards on the board are replaced with a gold nugget", "Todas las cartas rivales del tablero se sustituyen por pepitas de oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still sharp since the day i crafted it", "Sigue tan afilado como el día que lo fabriqué", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camera", "Cámara de bestias", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take a picture of a card on the board and add it to your deck", "Fotografía una carta del tablero y añade una copia a tu mano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My spare camera, use it wisely.", "Mi cámara de repuesto, úsala con sensatez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mystical power of that item scared the survivors away.", "El poder místico de ese objeto espantó a los supervivientes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "May you continue their legacy", "Que continúes su legado", Language.Spanish);

        }
    }
    public class DinoMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Dino Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Akainacephalus", "Akainacephalus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutish beast. The first attacks to it's shell it will completely disregard.", "Una bestia brutal. Ignora por completo los primeros ataques contra su caparazón.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgasaur", "Amalgasaur", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ever-Changing amalgasaur. It can never decide on its true stats.", "El siempre cambiante Amalgasaur. Nunca logra decidir cuáles son sus verdaderas estadísticas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber", "Ámbar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient amber..", "Un ámbar antiguo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Geck", "Geco antiguo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow.. CLap.CLap.Calp!", "Vaya... ¡Plas, plas, plas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asteroid", "Asteroide", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A full board clear, but be careful. It crashes after 1 use.", "Despeja todo el tablero, pero cuidado: se bloquea tras 1 uso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Vial", "Frasco roto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oops. You bwoke it.", "Ups. Lo has lompido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lanky Brontosaurus. It's neck streches so high up, it can catch airborne creatures in mid-air.", "El larguirucho Brontosaurus. Su cuello se estira tanto que puede atrapar criaturas aéreas en pleno vuelo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asteroid Crashsite", "Lugar del impacto del asteroide", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DJ Bronto", "DJ Bronto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil", "Fósil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dinosaur fossil long forgotten. It's slowly falling apart.", "Un fósil de dinosaurio olvidado hace mucho tiempo. Se está desmoronando lentamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen T-Rex", "T. rex congelado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's frozen. You may regret releasing it.", "Está congelado. Puede que lamentes liberarlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Dinosaurio fantasma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghost, stuck in the mortal realm, forever wadnering.", "Un fantasma atrapado en el mundo de los mortales, condenado a vagar eternamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "Indominus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Bronto", "Bronto largo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "Megalodón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even the great white shivers when confronted by this horror..", "Incluso el gran tiburón blanco tiembla ante este horror...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Mononykus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a weird looking creature..", "Qué criatura tan extraña...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lepidoptera", "Lepidóptero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feeble moth. Maybe you can find a way to power it up?", "Una polilla débil. ¿Quizá puedas encontrar una forma de potenciarla?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bronto Neck", "Cuello de Bronto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insect Neck", "Cuello de insecto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Neck", "Cuello emplumado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furry Neck", "Cuello peludo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaly Neck", "Cuello escamoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Neck", "Cuello", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Notosaurus", "Notosaurus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Notosaurus, a giant swimming beast.", "El Notosaurus, una enorme bestia nadadora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "Parasaurolophus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Parasaurolophus. This beast calls its allies to help defend itself.", "El Parasaurolophus. Esta bestia llama a sus aliados para que la ayuden a defenderse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Pterodáctilo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pterodactyl, a fearsome flying beast. It swoops down on its prey with maximum efficiency.", "El Pterodáctilo, una temible bestia voladora. Se abalanza sobre su presa con la máxima eficacia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Hatchling", "Cría de raptor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A weak dinosaur hatchling. Make sure to protect it.", "Una cría de dinosaurio débil. Asegúrate de protegerla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rox", "Rox", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a curious creature..", "Qué criatura tan curiosa...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Raptor", "Raptor no muerto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Undead Velociraptor. It manages to stay alive, but only for a while.", "El Velociraptor no muerto. Se las arregla para seguir con vida, pero solo por un tiempo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Raptor", "Raptor con púas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "Spinosaurus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spinosaurus. This beast is agile in water, and on land.", "El Spinosaurus. Esta bestia es ágil tanto en el agua como en tierra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Huevo misterioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't actually know whats in it..", "La verdad es que no sé qué hay dentro...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tessie", "Tessie", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature originating from a frozen wasteland..", "Una criatura procedente de un páramo helado...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-rex", "T. rex", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "Triceratops", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Triceratops. It turns from defense, to offense after 1 hit.", "El poderoso Triceratops. Tras 1 golpe pasa de la defensa al ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "Velociraptor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Velociraptor, a flighty, agile beast.", "El Velociraptor, una bestia inquieta y ágil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Vial", "Frasco extraño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A demonic fluid in a vile. Under the right conditions it can evolve into a horryfying beast.", "Un líquido demoníaco en un frasco. En las condiciones adecuadas puede evolucionar hasta convertirse en una bestia aterradora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Call Allies", "Llamada a los aliados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon allies adjacent of where the card is placed.", "Cuando se juega una carta que lleve este sello, invoca aliados en los espacios vacíos adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Mod Card Pack", "Paquete de cartas del mod Dino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds silly dinos and prehistoric beasts to the game!", "¡Añade al juego divertidos dinosaurios y bestias prehistóricas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatchling", "Cría desconocida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil has a chance to hatch into a random Dinosaur.", "Al final del turno, una carta que lleve este sello tiene una probabilidad de eclosionar como un dinosaurio aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crumbling", "Desmoronamiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will create 1 bone, but will lose 1 health.", "Al final del turno, una carta que lleve este sello produce 1 hueso, pero pierde 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roar of Terror", "Rugido de terror", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing the bearer of this sigil will have its damage set to 1.", "El daño de la criatura enfrentada a quien lleva este sello se fija en 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stretching", "Estiramiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will move, and stretch it's neck.", "Al final del turno de su propietario, una carta que lleve este sello se mueve en la dirección indicada por el sello y estira el cuello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Experimental Vial", "Frasco experimental", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies, it will transform into a monster.", "Cuando una carta que lleve este sello muere, se transforma en un monstruo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DinoMod", "Mod Dino", Language.Spanish);
        }
    }
