    public class InGameCardCreatorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for InGame_Card_Creator Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered the [c:bR]card creation[c:] mode.", "Has entrado en el modo de [c:bR]creación de cartas[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that you lost normally.", "Parece que has perdido de forma normal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only worthy challengers may access the Card Creator.", "Solo los aspirantes dignos pueden acceder al Creador de cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try again, but this time open the backroom door normally.", "Inténtalo de nuevo, pero esta vez abre la puerta de la trastienda de forma normal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "current card", "carta actual", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should give it a name.", "Deberías darle un nombre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please type the description.", "Introduce la descripción.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for you to return.", "Es hora de que regreses.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loading portraits.", "Cargando retratos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "previous page", "página anterior", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "next page", "página siguiente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]power[c:].", "Y otra más. Esta vez usaré su [c:bR]poder[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]complexity[c:] of card. This determines when it is unlocked in the tutorial.", "Elige la [c:bR]complejidad[c:] de la carta. Determina cuándo se desbloquea en el tutorial.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "free", "Gratis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, choose a card to draw the [c:bR]cost[c:] from.", "Elige una carta de la que obtener el [c:bR]coste[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you want to add another [c:bR]cost[c:]?", "¿Quieres añadir otro [c:bR]coste[c:]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will evolve into.", "Elige en qué carta evolucionará.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will create upon death.", "Elige qué carta creará al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How many turns[c:] should it take for this card to evolve?", "¿En [c:bR]cuántos turnos[c:] debe evolucionar esta carta?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]health[c:].", "Y otra más. Esta vez usaré su [c:bR]salud[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "regular", "Normal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "rare", "raro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hidden", "Oculto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]type[c:] of card.", "Elige el [c:bR]tipo[c:] de carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now choose some cards from which we will extract the [c:bR]sigils[c:]. Note that some may not work correctly.", "Elige ahora algunas cartas de las que extraeremos los [c:bR]sellos[c:]. Ten en cuenta que puede que algunos no funcionen correctamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, choose the hidden [c:bR]special abilities[c:] and [c:bR]traits[c:]. Again, some may not function properly.", "Por último, elige las [c:bR]habilidades especiales[c:] y los [c:bR]rasgos[c:] ocultos. De nuevo, puede que algunos no funcionen correctamente.", Language.Spanish);
