                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of [c:bR]" + value + " energy[c:].", "Coste: [c:bR]" + value + " " + (value == 1 ? "punto" : "puntos") + " de energía[c:].", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of [c:bR]" + value + " bones[c:].", "Coste: [c:bR]" + value + " " + (value == 1 ? "hueso" : "huesos") + "[c:].", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of [c:bR]" + value + " blood[c:].", "Coste: [c:bR]" + value + " " + (value == 1 ? "punto" : "puntos") + " de sangre[c:].", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]" + value + " Power[c:].", "[c:bR]" + value + " " + (value == 1 ? "punto" : "puntos") + " de poder[c:].", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]" + value + " Health[c:].", "[c:bR]" + value + " " + (value == 1 ? "punto" : "puntos") + " de salud[c:].", Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]" + value + " turns[c:].", "[c:bR]" + value + " " + (value == 1 ? "turno" : "turnos") + "[c:].", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of [c:bR]1 bone[c:].", "Un coste de [c:bR]1 hueso[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of... [c:bR]free[c:].", "Un coste de... [c:bR]gratis[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]1 turn[c:].", "[c:bR]1 turno[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 blood", "1 sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 bone", "1 hueso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 turn", "1 turno", Language.Spanish);
            Dictionary<GemType, string> gemTypesEn = new Dictionary<GemType, string>
            {
                { GemType.Orange, "orange" },
                { GemType.Blue, "blue" },
                { GemType.Green, "green" },
            };
            Dictionary<GemType, string> gemTypes = new Dictionary<GemType, string>
            {
                { GemType.Orange, "naranja" },
                { GemType.Blue, "azul" },
                { GemType.Green, "verde" },
            };
            foreach (var gemType in gemTypes.Keys)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, gemTypesEn[gemType] + " gem", "gema de color " + gemTypes[gemType], Language.Spanish);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cost of a [c:bR]" + gemTypesEn[gemType] + " gem[c:].", "Coste: una gema de color [c:bR]" + gemTypes[gemType] + "[c:].", Language.Spanish);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CardsInHand", "Cartas en mano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "lice", "Piojos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "simple", "simple", Language.Spanish);
