    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Expansión de Magnificus de Aga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "Una expansión no oficial del Mod Magnificus con [count] magos únicos y llenos de color", Language.Spanish);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "Mago de la ascensión", Language.Spanish);
            MagnificusMod.RegisterCard("Ascension Mage", "Mago de la ascensión", "Utilising the power of time they grant knowledge and experience from far beyond", "Con el poder del tiempo, transmiten conocimientos y experiencia de mucho más allá");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "Con el poder del tiempo, transmiten conocimientos y experiencia de mucho más allá", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "Mago de las cenizas", Language.Spanish);
            MagnificusMod.RegisterCard("Ash Mage", "Mago de las cenizas", "Ashes he sheds from his own body, scorching any and all who oppose him", "Las cenizas que desprende de su propio cuerpo abrasan a todos los que se le oponen");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "Las cenizas que desprende de su propio cuerpo abrasan a todos los que se le oponen", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "Huevo roto", Language.Spanish);
            MagnificusMod.RegisterCard("Broken Egg", "Huevo roto", "Only the greatest of trainers might find this treasure", "Solo los mejores entrenadores podrían encontrar este tesoro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Solo los mejores entrenadores podrían encontrar este tesoro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "Elegido", Language.Spanish);
            MagnificusMod.RegisterCard("Chosen One", "Elegido", "My selected favourite. He still clings to his elders though...", "Mi favorito elegido. Aunque sigue aferrado a sus mayores...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "Mi favorito elegido. Aunque sigue aferrado a sus mayores...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "Mago de la limpieza", Language.Spanish);
            MagnificusMod.RegisterCard("Cleanliness Mage", "Mago de la limpieza", "The proudest of all my pupils. None come close to his bath superpowers", "El más orgulloso de mis alumnos. Nadie se acerca a sus superpoderes de baño");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "El más orgulloso de mis alumnos. Nadie se acerca a sus superpoderes de baño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "Clérigo", Language.Spanish);
            MagnificusMod.RegisterCard("Cleric", "Clérigo", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Gracias a su magia divina, soporta el dolor de todos y los libra de sus heridas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Gracias a su magia divina, soporta el dolor de todos y los libra de sus heridas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "Mago de los relojes", Language.Spanish);
            MagnificusMod.RegisterCard("Clock Mage", "Mago de los relojes", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Un hechicero que domina el tiempo mismo. Cuando se acerca su fin, vuelve al pasado y regresa a la vida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Un hechicero que domina el tiempo mismo. Cuando se acerca su fin, vuelve al pasado y regresa a la vida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "Coleccionista de criaturas", Language.Spanish);
            MagnificusMod.RegisterCard("Creature Collector", "Coleccionista de criaturas", "He had searched far and wide for his little companion, you see", "Había buscado por todas partes a su pequeño compañero, ya ves");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "Había buscado por todas partes a su pequeño compañero, ya ves", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "Mago de la división", Language.Spanish);
            MagnificusMod.RegisterCard("Division Mage", "Mago de la división", "So the card says at least... I assumed those freaks were long dealth with", "Al menos eso dice la carta... Creía que se habían librado de esos chiflados hace tiempo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "Al menos eso dice la carta... Creía que se habían librado de esos chiflados hace tiempo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "Huevo", Language.Spanish);
            MagnificusMod.RegisterCard("Egg", "Huevo", "Only the greatest of trainers might find this treasure", "Solo los mejores entrenadores podrían encontrar este tesoro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Solo los mejores entrenadores podrían encontrar este tesoro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Druida", Language.Spanish);
            MagnificusMod.RegisterCard("Druid", "Druida", "Nature's primal devotee, feeding on sapped mana to cure his allies", "Un devoto primordial de la naturaleza que se alimenta del maná extraído para curar a sus aliados");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "Un devoto primordial de la naturaleza que se alimenta del maná extraído para curar a sus aliados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "Encantador", Language.Spanish);
            MagnificusMod.RegisterCard("Enchanter", "Encantador", "He spews cosmic magicks upon his demise, enchanting everything nearby", "Al morir, emana magia cósmica que encanta todo lo que le rodea");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "Al morir, emana magia cósmica que encanta todo lo que le rodea", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "Mago universal", Language.Spanish);
            MagnificusMod.RegisterCard("EveryMage", "Mago universal", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "mago", Language.Spanish);
            MagnificusMod.RegisterCard("mage", "mago", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "Evocador", Language.Spanish);
            MagnificusMod.RegisterCard("Evoker", "Evocador", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Este siniestro cretino de enseñanzas repugnantes puede invocar serpientes de lo más letales");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Este siniestro cretino de enseñanzas repugnantes puede invocar serpientes de lo más letales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "Invocación de serpiente", Language.Spanish);
            MagnificusMod.RegisterCard("Serpent Summon", "Invocación de serpiente", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "Pirómano", Language.Spanish);
            MagnificusMod.RegisterCard("Firebender", "Pirómano", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Animado en plena batalla, siempre busca la próxima víctima de sus bolas de fuego");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Animado en plena batalla, siempre busca la próxima víctima de sus bolas de fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Mago de la previsión", Language.Spanish);
            MagnificusMod.RegisterCard("Foresight Mage", "Mago de la previsión", "As he gazes upon your future, attacks that may come his way he forever predicts", "Al contemplar tu futuro, predice sin cesar los ataques que podrían dirigirse contra él");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "Al contemplar tu futuro, predice sin cesar los ataques que podrían dirigirse contra él", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Mago de la previsión", Language.Spanish);
            MagnificusMod.RegisterCard("Foresight Mage", "Mago de la previsión", "Gazing into the future, he may see any body who dares make an approach", "Al mirar al futuro, puede ver a cualquiera que se atreva a acercarse");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "Al mirar al futuro, puede ver a cualquiera que se atreva a acercarse", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Glaciar", Language.Spanish);
            MagnificusMod.RegisterCard("Glacier", "Glaciar", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.Spanish);
            MagnificusMod.RegisterCard("Gashadokuro", "Gashadokuro", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "Centinela de gemas", Language.Spanish);
            MagnificusMod.RegisterCard("Gem Sentinel", "Centinela de gemas", "the elite warrior unit enchanted with the aura of my moxen", "La unidad de guerreros de élite encantada con el aura de mis mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "La unidad de guerreros de élite encantada con el aura de mis mox", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "Gran astrólogo", Language.Spanish);
            MagnificusMod.RegisterCard("Grand Astrologer", "Gran astrólogo", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "El campo de batalla es siempre su patio de juegos y el espacio es su arma. Nada se oculta ante él.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "El campo de batalla es siempre su patio de juegos y el espacio es su arma. Nada se oculta ante él.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "Mago de la gravedad", Language.Spanish);
            MagnificusMod.RegisterCard("Gravity Mage", "Mago de la gravedad", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Un maestro de las fuerzas de la gravedad. Todos los mox se doblegan a su voluntad inquebrantable");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Un maestro de las fuerzas de la gravedad. Todos los mox se doblegan a su voluntad inquebrantable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "Ilusionista", Language.Spanish);
            MagnificusMod.RegisterCard("Illusion Mage", "Ilusionista", "Dawning his tricks and disguises, there is none scarier. At first glance", "Con sus trucos y disfraces, nadie da más miedo. A primera vista.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "Con sus trucos y disfraces, nadie da más miedo. A primera vista.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "Mago de la infestación", Language.Spanish);
            MagnificusMod.RegisterCard("Infestation Mage", "Mago de la infestación", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Supongo que un aspirante usurpador como tú podría permitirse una dosis de magia de cambio de forma");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Supongo que un aspirante usurpador como tú podría permitirse una dosis de magia de cambio de forma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "Espejo insultante", Language.Spanish);
            MagnificusMod.RegisterCard("Insulting Mirror", "Espejo insultante", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "La amenaza mágica revolotea por ahí lanzando burlas y comentarios insolentes; convierte tu ira en su propia fuerza");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "La amenaza mágica revolotea por ahí lanzando burlas y comentarios insolentes; convierte tu ira en su propia fuerza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "Doncella de hierro", Language.Spanish);
            MagnificusMod.RegisterCard("Iron Maiden", "Doncella de hierro", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "El mejor de mis paladines cumple su mejor turno. Ningún alma atraviesa su gran muro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "El mejor de mis paladines cumple su mejor turno. Ningún alma atraviesa su gran muro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "Moxeador", Language.Spanish);
            MagnificusMod.RegisterCard("Kickmoxer", "Moxeador", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Dedicó su vida al arte del combate y puede adaptarse a cualquier rival");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Dedicó su vida al arte del combate y puede adaptarse a cualquier rival", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Fosa común", Language.Spanish);
            MagnificusMod.RegisterCard("Mass Grave", "Fosa común", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "Maestro Agairan", Language.Spanish);
            MagnificusMod.RegisterCard("Master Agairan", "Maestro Agairan", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "La quimera carmesí. El maestro de alquimia inculca las toxinas más letales");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "La quimera carmesí. El maestro de alquimia inculca las toxinas más letales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "Maestro Dobleazul", Language.Spanish);
            MagnificusMod.RegisterCard("Master Bluetwo", "Maestro Dobleazul", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "La caballera de acero del zafiro. Incluso después de morir, su presencia psíquica domina a nuestros enemigos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "La caballera de acero del zafiro. Incluso después de morir, su presencia psíquica domina a nuestros enemigos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "Maestro Doublin", Language.Spanish);
            MagnificusMod.RegisterCard("Master Doublin", "Maestro Doublin", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "El mesías del señor de los huesos. El maestro de la oración ha aprendido a robar esencia con destreza.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "El mesías del señor de los huesos. El maestro de la oración ha aprendido a robar esencia con destreza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "Megahechicero", Language.Spanish);
            MagnificusMod.RegisterCard("Megawizard", "Megahechicero", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Enorme en su amenaza, amenazador incluso en su mente obtusa. Semejante poder bruto no durará eternamente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Enorme en su amenaza, amenazador incluso en su mente obtusa. Semejante poder bruto no durará eternamente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "Meteorólogo", Language.Spanish);
            MagnificusMod.RegisterCard("Meteorologist", "Meteorólogo", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Observan el universo con atención y lanzan tormentas de meteoros sobre quien consideran oportuno. ¿Son crueles? ¿O no? Solo ellos lo saben");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Observan el universo con atención y lanzan tormentas de meteoros sobre quien consideran oportuno. ¿Son crueles? ¿O no? Solo ellos lo saben", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "Minihechicero", Language.Spanish);
            MagnificusMod.RegisterCard("Miniwizard", "Minihechicero", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Un mago maldito por su diminuto tamaño. Pero no te preocupes: ha encontrado una solución.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Un mago maldito por su diminuto tamaño. Pero no te preocupes: ha encontrado una solución.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "Ladrón espectral", Language.Spanish);
            MagnificusMod.RegisterCard("Phantom Thief", "Ladrón espectral", "A billowing cloud of crime, darting in and out, and stealing his foes", "Una nube ondulante de crimen que entra y sale velozmente mientras roba a sus enemigos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "Una nube ondulante de crimen que entra y sale velozmente mientras roba a sus enemigos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "Mago del preludio", Language.Spanish);
            MagnificusMod.RegisterCard("Preformence Mage", "Mago del preludio", "Who knows to what ends his mystery rabbit has been through", "Quién sabe por todo lo que habrá pasado su misterioso conejo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "Quién sabe por todo lo que habrá pasado su misterioso conejo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "Familiar de la reina", Language.Spanish);
            MagnificusMod.RegisterCard("Queen's Familiar", "Familiar de la reina", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Una majestuosa quimera de hermosas bestias. Mantiene sus ejércitos cerca, en su interior");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Una majestuosa quimera de hermosas bestias. Mantiene sus ejércitos cerca, en su interior", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "Hambre creciente", Language.Spanish);
            MagnificusMod.RegisterCard("RisingHunger", "Hambre creciente", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "Familiar cucaracha", Language.Spanish);
            MagnificusMod.RegisterCard("Roach Familiar", "Familiar cucaracha", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Una cucaracha creada espiritualmente. ¡Su voluntad le otorga poderes de resurrección! Que al final fallan.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Una cucaracha creada espiritualmente. ¡Su voluntad le otorga poderes de resurrección! Que al final fallan.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "Hechicero de las sombras", Language.Spanish);
            MagnificusMod.RegisterCard("Shadow Wizard", "Hechicero de las sombras", "A mobster of the underseen. He calls the shadows to gang on it's foes", "Un mafioso del mundo oculto. Llama a las sombras para que se unan contra sus enemigos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "Un mafioso del mundo oculto. Llama a las sombras para que se unan contra sus enemigos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "Shinobi", Language.Spanish);
            MagnificusMod.RegisterCard("Shinobi", "Shinobi", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Guerreros de la oscuridad: atacan por sorpresa desde lugares que nadie reclama ni ve");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Guerreros de la oscuridad: atacan por sorpresa desde lugares que nadie reclama ni ve", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "Mago de la ducha", Language.Spanish);
            MagnificusMod.RegisterCard("Shower Mage", "Mago de la ducha", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "El paria de mi escuela, ¡y con razón! Su hedor solo puede describirse con magia...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "El paria de mi escuela, ¡y con razón! Su hedor solo puede describirse con magia...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "Mago del lodo", Language.Spanish);
            MagnificusMod.RegisterCard("Sludge Mage", "Mago del lodo", "An entity of unknown origins, powered off the ill spreading plague to all", "Una entidad de origen desconocido, alimentada por la enfermedad y propagadora de peste por doquier");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "Una entidad de origen desconocido, alimentada por la enfermedad y propagadora de peste por doquier", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "Sabio Sui", Language.Spanish);
            MagnificusMod.RegisterCard("Sui-Sage", "Sabio Sui", "The leader of a pack, soon to be packed away", "El líder de una manada que pronto será despachado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "El líder de una manada que pronto será despachado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Invocador", Language.Spanish);
            MagnificusMod.RegisterCard("Summoner", "Invocador", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Un loco de las artes de la vida que la crea de la nada con una sensibilidad aterradora");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Un loco de las artes de la vida que la crea de la nada con una sensibilidad aterradora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "Mago simétrico", Language.Spanish);
            MagnificusMod.RegisterCard("Symmetrical Mage", "Mago simétrico", "Everyone has two sides to them, you see. Especially once they mess with my temper", "Todo el mundo tiene dos lados, ya ves. Sobre todo cuando me hacen perder la paciencia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "Todo el mundo tiene dos lados, ya ves. Sobre todo cuando me hacen perder la paciencia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "Mago de la teletransportación", Language.Spanish);
            MagnificusMod.RegisterCard("Teleportation Mage", "Mago de la teletransportación", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Un heraldo de portales infinitos que salta sin cesar por el campo de batalla y anula los ataques entrantes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Un heraldo de portales infinitos que salta sin cesar por el campo de batalla y anula los ataques entrantes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "Mago del torrente", Language.Spanish);
            MagnificusMod.RegisterCard("Torrent Mage", "Mago del torrente", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Un aprendiz del océano que lo usa para inundar las tierras y el terreno que hay sobre ellas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Un aprendiz del océano que lo usa para inundar las tierras y el terreno que hay sobre ellas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "Dragón indómito", Language.Spanish);
            MagnificusMod.RegisterCard("Untamed Dragon", "Dragón indómito", "Legends whisper this beast, was once a companion to the mox master Goranj", "Las leyendas susurran que esta bestia fue antaño compañera del maestro de mox Verdanja");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "Las leyendas susurran que esta bestia fue antaño compañera del maestro de mox Verdanja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "Brujo", Language.Spanish);
            MagnificusMod.RegisterCard("Warlock", "Brujo", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Un hechicero ennegrecido que estudia la magia de sangre. Convierte ese sangrado en un arma terrible");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Un hechicero ennegrecido que estudia la magia de sangre. Convierte ese sangrado en un arma terrible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "Bruja malvada", Language.Spanish);
            MagnificusMod.RegisterCard("Wicked Witch", "Bruja malvada", "A flying jesting witch, laughing your sorrows and posioning your armies", "Una bruja voladora y burlona que se ríe de tus penas y envenena a tus ejércitos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "Una bruja voladora y burlona que se ríe de tus penas y envenena a tus ejércitos", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "Aura ácida", Language.Spanish);
            MagnificusMod.RegisterAbility("Acid Aura", "Aura ácida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature] inflige 1 de daño a la criatura que tiene enfrente en cada turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "Despertar", Language.Spanish);
            MagnificusMod.RegisterAbility("Awakening", "Despertar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "Cuando se juega [creature], su propietario elige una criatura aliada para que evolucione a una forma superior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "Golpe de retroceso", Language.Spanish);
            MagnificusMod.RegisterAbility("Backfire Strike", "Golpe de retroceso");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature] también inflige daño a la carta de su lado que está enfrente de cada objetivo al que ataca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Tragasangre", Language.Spanish);
            MagnificusMod.RegisterAbility("Blood Guzzler", "Tragasangre");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "Cuando [creature] inflige daño, obtiene 1 de salud por cada punto de daño infligido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "Parásito brutal", Language.Spanish);
            MagnificusMod.RegisterAbility("Brute Parasite", "Parásito brutal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "Cuando se juega [creature], se crea un Huevo en el espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "Diluvio", Language.Spanish);
            MagnificusMod.RegisterAbility("Deluge", "Diluvio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "Cuando se juega [creature], las criaturas rivales con 0 de poder se sumergen y obtienen el sello Acuático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "División", Language.Spanish);
            MagnificusMod.RegisterAbility("Division", "División");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "Tras atacar, [creature] se divide en 2 clones idénticos, cada uno con la mitad de sus estadísticas originales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "Centinela", Language.Spanish);
            MagnificusMod.RegisterAbility("Sentry", "Centinela");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Cuando una criatura se mueve al espacio frente a [creature], recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "Ah, nunca subestimes la velocidad de un Mago de la previsión.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "Aura curativa", Language.Spanish);
            MagnificusMod.RegisterAbility("Healing Aura", "Aura curativa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature] cura a las criaturas aliadas cercanas. La curación es proporcional a su poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "Ladrón de corazones", Language.Spanish);
            MagnificusMod.RegisterAbility("Heart Stealer", "Ladrón de corazones");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "Cuando [creature] mata a una criatura, la carta de la víctima se añade a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "Encantamiento de fuego", Language.Spanish);
            MagnificusMod.RegisterAbility("Ignis Incant", "Encantamiento de fuego");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "Paga 1 de sangre para que [creature] inflija 2 de daño a un espacio rival elegido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "Intimidación", Language.Spanish);
            MagnificusMod.RegisterAbility("Intimidate", "Intimidación");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "Cuando [creature] se coloca en el tablero, la criatura de enfrente huye hacia su derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "Soledad", Language.Spanish);
            MagnificusMod.RegisterAbility("Lonesome", "Soledad");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "[creature] obtiene +1 de poder por cada espacio adyacente vacío.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "Explosión mágica", Language.Spanish);
            MagnificusMod.RegisterAbility("Magic Burst", "Explosión mágica");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "Tras la muerte de [creature], las criaturas adyacentes obtienen 1 de poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "Golpe psíquico", Language.Spanish);
            MagnificusMod.RegisterAbility("Psystrike", "Golpe psíquico");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "Tras morir, [creature] manipula a la criatura de enfrente para que golpee a sus dos aliados adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "Maestro de serpientes", Language.Spanish);
            MagnificusMod.RegisterAbility("Serpent Master", "Maestro de serpientes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "Al comienzo de cada turno, [creature] genera una Invocación de serpiente en un espacio elegido por su propietario. Una Invocación de serpiente tiene 1 de poder y 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "Golpe de sombra", Language.Spanish);
            MagnificusMod.RegisterAbility("Shadow Strike", "Golpe de sombra");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature] invoca las sombras de las criaturas adyacentes a su objetivo para que también lo golpeen.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "Acoplamiento de marea", Language.Spanish);
            MagnificusMod.RegisterAbility("Tidal Lock", "Acoplamiento de marea");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "Al comienzo del turno de su propietario, [creature] atrae a su órbita a criaturas pequeñas, como las ardillas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "Corazón de hechicero", Language.Spanish);
            MagnificusMod.RegisterAbility("Wizard's Heart", "Corazón de hechicero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "Cuando [creature] muere, una carta mox correspondiente a las gemas que controlas en ese momento ocupa su lugar.", Language.Spanish);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "Defensa del castor", Language.Spanish);
            MagnificusMod.RegisterCard("Beaver's Defense", "Defensa del castor", "Curating defensive dams upon use, not bad for a dire situation.", "Crea presas defensivas al usarse; no está mal en una situación desesperada.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "Crea presas defensivas al usarse; no está mal en una situación desesperada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "Sabio de las bombas", Language.Spanish);
            MagnificusMod.RegisterCard("Bomb Sage", "Sabio de las bombas", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Cuando lo atacan, este sabio es conocido por explotar... Literal y metafóricamente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Cuando lo atacan, este sabio es conocido por explotar... Literal y metafóricamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "Campeón de boxeo", Language.Spanish);
            MagnificusMod.RegisterCard("Boxing Champ", "Campeón de boxeo", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Este campeón rechaza las varitas y prefiere resolver las cosas con los puños.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Este campeón rechaza las varitas y prefiere resolver las cosas con los puños.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontosaurus", Language.Spanish);
            MagnificusMod.RegisterCard("Brontosaurus", "Brontosaurus", "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Mago del queso", Language.Spanish);
            MagnificusMod.RegisterCard("Cheese Wizard", "Mago del queso", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Como chefs magos entrenados, los hechiceros del queso usan su intelecto y sus artes místicas para alcanzar sus objetivos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Como chefs magos entrenados, los hechiceros del queso usan su intelecto y sus artes místicas para alcanzar sus objetivos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "Quesito", Language.Spanish);
            MagnificusMod.RegisterCard("Cheezling", "Quesito", "With cheese like this, who needs friends?", "Con un queso así, ¿quién necesita amigos?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "Con un queso así, ¿quién necesita amigos?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "Telepatía", Language.Spanish);
            MagnificusMod.RegisterCard("Telepathy", "Telepatía", "A pupil can gather all the resources they need through sheer will alone.", "Un alumno puede reunir todos los recursos necesarios solo con su fuerza de voluntad.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "Un alumno puede reunir todos los recursos necesarios solo con su fuerza de voluntad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "Impacto directo", Language.Spanish);
            MagnificusMod.RegisterCard("Direct Hit", "Impacto directo", "Upon being casted, your opponent will instantly take three damage.", "Al lanzarlo, tu rival recibe inmediatamente tres de daño.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "Al lanzarlo, tu rival recibe inmediatamente tres de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Huevo misterioso", Language.Spanish);
            MagnificusMod.RegisterCard("Mysterious Egg", "Huevo misterioso", "Who knows what could hatch from this egg...", "Quién sabe qué podría salir de este huevo...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "Quién sabe qué podría salir de este huevo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "Sin rostro", Language.Spanish);
            MagnificusMod.RegisterCard("Faceless", "Sin rostro", "A hollow shell of a mage, desperately looking for something to call its own.", "La cáscara vacía de un mago que busca desesperadamente algo que pueda llamar suyo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "La cáscara vacía de un mago que busca desesperadamente algo que pueda llamar suyo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "Falsificador", Language.Spanish);
            MagnificusMod.RegisterCard("Faker", "Falsificador", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Mentir. Hacer trampas. Negarlo todo. Hasta dónde llegará el Falsificador para escapar indemne...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Mentir. Hacer trampas. Negarlo todo. Hasta dónde llegará el Falsificador para escapar indemne...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "Figletar", Language.Spanish);
            MagnificusMod.RegisterCard("Figletar", "Figletar", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Un hechicero que llevó a un rey malvado a un terrible destino; sabe un par de cosas sobre el cuadrilátero.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Un hechicero que llevó a un rey malvado a un terrible destino; sabe un par de cosas sobre el cuadrilátero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "Incendiario", Language.Spanish);
            MagnificusMod.RegisterCard("Firestarter", "Incendiario", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Cuidado al lanzar este hechizo: los alumnos dicen que el campo de duelo puede calentarse un poco.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Cuidado al lanzar este hechizo: los alumnos dicen que el campo de duelo puede calentarse un poco.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "Mago del frigorífico", Language.Spanish);
            MagnificusMod.RegisterCard("Fridge Mage", "Mago del frigorífico", "Its cold atmosphere will chill foes, weakening their offensive power.", "Su atmósfera fría enfría a los enemigos y debilita su poder ofensivo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "Su atmósfera fría enfría a los enemigos y debilita su poder ofensivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "Gemacolega", Language.Spanish);
            MagnificusMod.RegisterCard("Gembro", "Gemacolega", "The ability to tank any hit once, this pupil has high gusto.", "Este alumno puede aguantar cualquier golpe una vez y está lleno de entusiasmo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "Este alumno puede aguantar cualquier golpe una vez y está lleno de entusiasmo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "Garrapata de gema", Language.Spanish);
            MagnificusMod.RegisterCard("Gem Tick", "Garrapata de gema", "An elusive tick, which grants power to others via its mox body.", "Una garrapata escurridiza que otorga poder a otros mediante su cuerpo de mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "Una garrapata escurridiza que otorga poder a otros mediante su cuerpo de mox.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Dinosaurio fantasma", Language.Spanish);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "Dinosaurio fantasma", "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "Tercer ojo", Language.Spanish);
            MagnificusMod.RegisterCard("Third Eye", "Tercer ojo", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Gracias al poder del tercer ojo, este hechizo permite a quien lo lanza elegir una carta de su mazo restante y añadirla a su mano.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Gracias al poder del tercer ojo, este hechizo permite a quien lo lanza elegir una carta de su mazo restante y añadirla a su mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Mago del béisbol", Language.Spanish);
            MagnificusMod.RegisterCard("Baseball Mage", "Mago del béisbol", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "La varita de este mago también sirve de bate de béisbol. Es sorprendentemente resistente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "La varita de este mago también sirve de bate de béisbol. Es sorprendentemente resistente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "Gólem de hielo", Language.Spanish);
            MagnificusMod.RegisterCard("Ice Golem", "Gólem de hielo", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Procedente de una cima helada, a este bruto nunca parece preocuparle derretirse.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Procedente de una cima helada, a este bruto nunca parece preocuparle derretirse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "Bandido saqueador", Language.Spanish);
            MagnificusMod.RegisterCard("Looting Bandit", "Bandido saqueador", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Un seguidor lejano de las valquirias de Maestra Naranzul que entrena para llegar a ser como ellas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Un seguidor lejano de las valquirias de Maestra Naranzul que entrena para llegar a ser como ellas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "Mago del maná", Language.Spanish);
            MagnificusMod.RegisterCard("Mana Mage", "Mago del maná", "Brings together the energy that emits from Mana to deliver powerful strikes.", "Reúne la energía que emana del maná para asestar golpes poderosos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "Reúne la energía que emana del maná para asestar golpes poderosos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "Alumno pensativo", Language.Spanish);
            MagnificusMod.RegisterCard("Pondering Pupil", "Alumno pensativo", "It draws from your gem pile using the powers of its mind alone.", "Roba de tu pila de gemas usando únicamente el poder de su mente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "Roba de tu pila de gemas usando únicamente el poder de su mente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "Mago de los espejos", Language.Spanish);
            MagnificusMod.RegisterCard("Mirror Mage", "Mago de los espejos", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Espejito, espejito, ¿quién es el mejor escriba de todos?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Espejito, espejito, ¿quién es el mejor escriba de todos?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "Aplasta al mago", Language.Spanish);
            MagnificusMod.RegisterCard("Whack-A-Mage", "Aplasta al mago", "Always popping up to cause mischief whenever he can.", "Aparece siempre que puede para causar problemas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "Aparece siempre que puede para causar problemas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Mononykus", Language.Spanish);
            MagnificusMod.RegisterCard("Mononykus", "Mononykus", "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "PLUTÓN", Language.Spanish);
            MagnificusMod.RegisterCard("PLUTO", "PLUTÓN", "Hmph. So this is where that one went.", "Jum. Así que aquí fue a parar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "Jum. Así que aquí fue a parar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "Protección", Language.Spanish);
            MagnificusMod.RegisterCard("Protect", "Protección", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "¿En apuros? Este hechizo hace que una de tus cartas sea completamente inmune al próximo ataque que reciba.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "¿En apuros? Este hechizo hace que una de tus cartas sea completamente inmune al próximo ataque que reciba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Pterodáctilo", Language.Spanish);
            MagnificusMod.RegisterCard("Pterodactyl", "Pterodáctilo", "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "Sabio conejo loco", Language.Spanish);
            MagnificusMod.RegisterCard("Rabbid Sage", "Sabio conejo loco", "A raving magician with a field of electricity at his disposal.", "Un mago delirante que dispone de un campo eléctrico.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "Un mago delirante que dispone de un campo eléctrico.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "Esquelemox", Language.Spanish);
            MagnificusMod.RegisterCard("Skelemox", "Esquelemox", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Un pobre esqueleto controlado por un Mox verde. Casi me da pena.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Un pobre esqueleto controlado por un Mox verde. Casi me da pena.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "Hechicero del slime", Language.Spanish);
            MagnificusMod.RegisterCard("Slime Wiz", "Hechicero del slime", "It'll use the slime against the enemies, to drop their attack whence struck.", "Usa el slime contra los enemigos para reducir su ataque cuando recibe un golpe.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "Usa el slime contra los enemigos para reducir su ataque cuando recibe un golpe.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "Bruja vanidosa", Language.Spanish);
            MagnificusMod.RegisterCard("Smug Witch", "Bruja vanidosa", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "El alumno más vanidoso de todo el reino. Cuenta la leyenda que su Lanzamiento vanidoso no tiene rival.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "El alumno más vanidoso de todo el reino. Cuenta la leyenda que su Lanzamiento vanidoso no tiene rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "Lanza de invocación", Language.Spanish);
            MagnificusMod.RegisterCard("Summon Spear", "Lanza de invocación", "Roots up a spear from the ground, acting as a sturdy counter.", "Hace brotar una lanza del suelo como sólida defensa.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "Hace brotar una lanza del suelo como sólida defensa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "Mago de los pinchos", Language.Spanish);
            MagnificusMod.RegisterCard("Spike Mage", "Mago de los pinchos", "This mage learned from the best of my Pike Mage's Scarecrows.", "Este mago aprendió de los mejores espantapájaros de mi Mago lancero.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "Este mago aprendió de los mejores espantapájaros de mi Mago lancero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "T. rex", Language.Spanish);
            MagnificusMod.RegisterCard("T-Rex", "T. rex", "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "¡ME ENCANTA EL MOD DINO!!!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "Rey virtual", Language.Spanish);
            MagnificusMod.RegisterCard("Virtual King", "Rey virtual", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Gobernante autoproclamado de las tierras virtuales que no acata unas míseras «reglas de juego de cartas».");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Gobernante autoproclamado de las tierras virtuales que no acata unas míseras «reglas de juego de cartas».", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "Núcleo idiota", Language.Spanish);
            MagnificusMod.RegisterCard("Moron Core", "Núcleo idiota", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Un extraño núcleo procedente de una fábrica abandonada que odia la palabra «idiota».");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Un extraño núcleo procedente de una fábrica abandonada que odia la palabra «idiota».", Language.Spanish);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Expansión MagMod de Smughtro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "Añade al Mod Magnificus 19 cartas comunes, 7 cartas raras, 7 hechizos y 6 cartas de ficha.", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "Ayuda mortuoria", Language.Spanish);
            MagnificusMod.RegisterAbility("Death Assist", "Ayuda mortuoria");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "Cuando una carta que lleve este sello muere, inflige 3 de daño al rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "Elemental de emmental", Language.Spanish);
            MagnificusMod.RegisterAbility("Emmental Elemental", "Elemental de emmental");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "Cuando se juega una carta que lleve este sello, invoca un Quesito.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "Primer golpe", Language.Spanish);
            MagnificusMod.RegisterAbility("First Strike", "Primer golpe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "Cuando se juega una carta que lleve este sello, ataca inmediatamente el carril de enfrente. Si no hay cartas rivales, no se inflige daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "Eclosión desconocida", Language.Spanish);
            MagnificusMod.RegisterAbility("Unknown Hatching", "Eclosión desconocida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "Al comienzo del turno de su propietario, una carta que lleve este sello eclosiona como un dinosaurio aleatorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "Muerte saludable", Language.Spanish);
            MagnificusMod.RegisterAbility("Healthy Death", "Muerte saludable");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "Cuando una carta que lleve este sello muere, las cartas a su izquierda y derecha recuperan 1 de salud cada una.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "Caos de maná", Language.Spanish);
            MagnificusMod.RegisterAbility("Mana Mess", "Caos de maná");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "Cuando se juega una carta que lleve este sello, roba una carta aleatoria que no sea rara y cueste maná.", Language.Spanish);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "Flowey", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "Un líder fanático empeñado en provocar el apocalipsis resucitando al gran Cthulhu mediante intrigas entre bastidores.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "Idiota", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "¡Eres realmente idiota si crees que puedes derrotarme!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "Flowey Omega", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "Eres realmente idiota.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "Paciencia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "Paciente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "Valentía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "Valiente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "Integridad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "Íntegro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "Perseverancia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "Perseverante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "Bondad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "Amable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "Justicia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "Justicia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "¡Hola! Eh... quería decir: ¿estás listo para morir?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "¡Hola! Soy yo, Flowey, ¡Flowey la flor!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "Sabes lo que está pasando aquí, ¿verdad?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "¡Solo querías verme sufrir[c:0]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "¿Sabes que he estado observándote?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "¡Pues ahora me he apoderado de Inscryption!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "Y sé qué secretos se esconden bajo Inscryption...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "¡Ahora nada puede impedirme conquistar el mundo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "¿De qué crees que iba esta pelea?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "¡Solo la usé como tapadera para husmear en los archivos de Inscryption!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "¡Y de tu PC, claro!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "Puede que te hayas dado cuenta, ¡PERO ahora estoy conectado a Internet!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "¡Es hora de empezar a subir Inscryption!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "¡De VERDAD eres idiota!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "¡Ni siquiera necesito el poder de las almas humanas si uso los DATOS_ANTIGUOS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]¿Sabes qué consigues con esto? Nada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]¡No puedes librarte de mí! ¡Hagas lo que hagas, siempre estaré aquí!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]¿L-las almas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]¿D-dónde están mis poderes?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]¡¿QUÉ HAS HECHO?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "¡La defensa de Flowey ha bajado a [c:bR]0!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]NOOOOOO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "Qué acaba de pasar...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "Jum, parece que esta vez has ganado...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]¡NADIE VA A AYUDARTE!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "¡DEJA DE PEDIR [c:bR]AYUDA!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]¿De verdad creías que dejaría que me mataras tan fácilmente?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]¿Qué demo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]Flowey creía que podía utilizarme sin más...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]¡Ni siquiera sabía lo que soy!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]Pero ahora YO tengo el control...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]Patético: ni siquiera ajustó sus PS a infinito... Yo no cometeré ese error.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]¡Inténtalo cuanto quieras, no puedes matarme!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]Veamos qué hace esto...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]¿¿¿POR QUÉ NO PUEDO DESHACER ESTO???", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "¡VERTE MORIR UNA Y OTRA VEZ ES MUY [c:bR]DIVERTIDO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "¡NI UN SOLO PUNTO DE DAÑO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "¡ALGUIEN COMO [c:bR]TÚ NO PUEDE VENCERME!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]¡La Inanición no interrumpirá esta batalla!", Language.Spanish);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "Paquete de cartas: Undertale", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "Aaron", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "Ah, sí, Aaron el audaz, Aaron el bello. ¿Puedes apartar la mirada de sus músculos?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "Alphys", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "La Dra. Alphys es responsable de algunos de los individuos más «inquietantes» que has visto aquí... o debería decir... MULTIviduos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "Adorable y a la vez malhumorado. La dualidad de esta criatura no tiene igual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "Asgore", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "El rey de los monstruos... una fuerza bruta realmente intimidante, pero también... ¿compasión?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "Asriel Dreemurr", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "El ser más poderoso del subsuelo... Esperemos que puedas darle algún uso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "Astigmatismo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "El frustrante Astigmatismo... no consigue decidirse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "Gaster Blaster", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Bloque de hielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "Un cubo de hielo especialmente grande... Quién sabe qué habrá dentro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "Chara", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "Dogamy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "A Dogamy y su esposa Dogaressa les encanta combatir en equipo. No dejes que ninguno de los dos perezca...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "Dogaressa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "Doggo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "Ah, el ciego Doggo... Salta hacia cualquier sonido de movimiento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "Doodlebog", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "Maniquí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "El maniquí insulso... no tan carismático como su contraparte «loca».", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "Amalgama", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "Endogeny", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "nulo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "Froggit final", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "Ah, sí, el jefe definitivo de los Froggit... Sigue siendo tan fácil de engañar como sus parientes menos evolucionados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "Frisk", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "Froggit", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "Ah, sí, tímido como pocos... Froggit no quiere participar en ningún conflicto. Qué pena.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W. D. Gaster", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "Glyde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "Es tan narcisista que solo puede atacar si tiene una carta delante que lo observe.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "Perro grande", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "Verdadera y noblemente adecuado, es la forma evolutiva más alta que puede alcanzar un canino.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "Gyftrot", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "Sé amable con esta criatura, ya ha pasado por bastante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "Lobo de hielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "Ah, sí, esta criatura musculosa crea un Bloque de hielo al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "Icecap", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "Jerry", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "Déjalo atrás de una vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "Knight Knight", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "Ah, la inquietante Knight Knight... una centinela del sueño. Es implacable en su conquista...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "Pan de limón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "Perro (forma joven)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "Un canino mediocre en el mejor de los casos... al menos en su forma actual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "Loox", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "El astuto Loox EyeWalker... harías bien en no meterte con él.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "Maniquí loco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "¿Maniquí?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "Las apariencias engañan...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "Madjick", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "Menudo mago...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "Memoryhead", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "Mettaton", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "Un analizador de datos complejo, sistemático e hiperinteligente... Me recuerda a un viejo «amigo».", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "Mettaton EX", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "Migosp", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "El irritable Migosp... su ataque aumenta entre la multitud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "Migospel", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "Moldbygg", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "Moldsmal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "Este me da vibraciones de impostor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "Moldessa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "Ah, el gelatinoso Moldsmal. Probablemente nunca te has preguntado de qué está hecho.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "Muffet", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "Ah, sí, la reina de las arañas. Su juego rápido es notable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "Napstablook", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "El más melancólico de los fantasmas... No le importa la batalla, pero aun así lucha para impresionar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "Onionsan", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "No hay mucha estrategia con él... En el segundo turno se convierte en una carta de tentáculo aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "Papyrus es un bruto huesudo. Genera huesos como nadie.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "Parsnik", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "Pyrope", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "Pyrope solo quiere subir la temperatura. Veamos hasta qué punto puede ser letal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "Ave segadora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "Guardias reales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "Dos amantes de destino adverso... ¿Llegarán a centrarse en lo importante?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "Si eliges esta carta, me da la impresión de que lo voy a pasar mal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "Shyren", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "La musical Shyren... golpea sus campanas para oírla cantar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "Snowdrake", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "El risible Snowdrake... Se esfuerza por demostrar que su padre se equivoca. ¿Dejarás que lo consiga?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "Qué frío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "lo siento mucho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "lo siente mucho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "Temmie", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "Temmie, la gata inmortal... Al menos creo que es un felino. Nada que perder y todo que ganar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "Toriel", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "La guardiana de las ruinas... Protegerá tu lado del tablero lo mejor que pueda.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "Tsunderplane", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "No sabe si quiere tu atención o que te alejes... Yo aconsejo lo segundo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "Undyne", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "¿Cómo podría olvidar a Undyne? Es una auténtica guerrera, con una puntería formidable con su lanza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "Vegetoid", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "Come verduras. (No supervisado por la FDA)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "Vulkin", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "Una criatura muy apasionada. No pretende hacer daño, pero eso no lo detiene.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "Whimsalot", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "El noble Whimsalot... Reza para que considere justa tu conquista.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "Whimsun", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "El insignificante Whimsun... abandona la batalla después de atacar una sola vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "Woshua", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "Esta criatura no tiene sed de sangre. Quiere ayudar a los demás, pero luchará si la provocan.", Language.Spanish);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "Antisocial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "Una carta que lleve este sello obtiene una mejora de ataque si tienes al menos 1 carta más en tu lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "Purificador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "Al comienzo de la fase de combate de su propietario, una carta que lleve este sello cura 1 de salud a todas las demás cartas de su lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "Determinación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "Una carta que lleve este sello se mueve a un espacio libre elegido por su propietario y obtiene EXP y niveles tras una muerte causada. Pero ¿es eso lo que quieres?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "Incendiario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "Cuando una carta que lleve este sello ataca a otra carta, el objetivo obtiene el sello En llamas. Una carta en llamas pierde una salud al comienzo de la fase de combate de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "En llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "Al comienzo de la fase de combate de su propietario, una carta que lleve este sello recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "Indeciso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "Cuando una carta que lleve este sello recibe un golpe, tiene una probabilidad del 50/50 de obtener una mejora de estadísticas o morir; solo si muere se crea una copia en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "Todo el mundo conoce a Jerry. Alarga los turnos 2 segundos. Cuando matan o sacrifican a Jerry, las cartas del lado del jugador obtienen una mejora de estadísticas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "Piedad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "Una carta con Determinación recibe este sello cuando la carta enfrentada tiene poca salud, lo que lleva al jugador a tomar una decisión moral.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "Perspicacia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "¿Quieres pasarlo mal?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "Garabateador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "Cuando una carta que lleve este sello recibe un golpe, a veces invoca Doodlebogs en los espacios adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "Tímido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "Cuando una carta rival se mueve al espacio enfrente de una carta que lleve este sello, esta intenta moverse un espacio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "Has dejado atrás a Jerry.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "Vaya, sois MALÍSIMOS en esto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "El wifi de aquí es malísimo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "¡CHIST! ¡¡Estoy PENSANDO, chicos!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "Consigue el tuyo, enano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "¿Por qué hacemos esto? Qué fracaso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "Chicos, hace FRÍO. ¿A ALGUIEN le importa?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "Suspiro...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "¡PUES CLARO! ¿Quién NO lo sabe?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "Bueno... ¿TÚ puedes llevarme a casa?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "Qué incóóómodo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "O sea, ¿qué estás haciendo exactamente?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "¿Eh? ¿Me han dejado atrás...? ¡Menudos amigos!", Language.Spanish);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "Danza macabra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "Paga 2 huesos para invertir el efecto de este sello. Al final del turno de su propietario, todas las criaturas del tablero obtienen 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "Robo vital", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "Paga 1 de sangre para robar una carta de tu mazo principal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Portal de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "Paga 1 hueso para obtener 1 de energía. Al final del turno del propietario pierdes la misma cantidad de energía máxima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "Evocación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "Paga 3 de energía para devolver a tu mano la criatura aliada más antigua del cementerio que no tenga Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "Durmiente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "Paga tantos huesos como poder tenga [creature] para desactivar este sello durante 1 turno. [creature] no puede atacar normalmente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "Transmutación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "Paga 2 huesos para transformar a [creature] en su forma alternativa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "Protector", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "Las criaturas adyacentes a [creature] obtienen 1 de salud máxima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "Efusión de calamidad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "Al final del turno de su propietario, todas las criaturas del tablero pierden 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "Aura de consuelo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "Al final del turno de su propietario, las criaturas adyacentes a [creature] recuperan 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "Fiesta de cadáveres", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "Cuando una criatura del lado del propietario sin Quebradizo muere en combate, un Zombi entra en tu mano. Un Zombi tiene 1 de poder y 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "Golpe mortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "Cuando [creature] muere en combate, contraataca y después perece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "Metal de la muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "Cuando se juega [creature], las criaturas adyacentes y las criaturas rivales de la izquierda, derecha y centro enfrente de ella reciben 1 de daño. Obtiene 1 de poder por cada criatura afectada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "Profanador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "Cuando [creature] muere, roba una carta y después elige una para descartarla de tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "Invasión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "Tras 2 turnos en el tablero, [creature] crea una copia de sí misma en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "Esqueletización", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "Cuando [creature] muere, un Esqueleto con sus antiguos sellos entra en tu mano. Un Esqueleto tiene 1 de poder, 1 de salud y Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "Exorcismo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "Cuando se juega [creature], el jugador recibe tantos huesos como el coste en huesos de la criatura enfrentada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "Cadáver explosivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "Cuando [creature] muere en combate, todos los espacios vacíos del tablero se llenan con una carta Entrañas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "Coleccionista de rencores", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "[creature] obtiene 1 de poder por cada 2 veces que las criaturas rivales infligen daño directo a su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "Poder de campanillas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "El valor representado por este sello equivale al número de cartas Campana del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "Poder desenterrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "El valor representado por este sello equivale al número de sellos relacionados con huesos y excavación en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "Ignición", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "Tras cada turno en el tablero, [creature] obtiene 1 de poder a cambio de 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "Acople desenterrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "Al final del turno de su propietario, [creature] genera 1 hueso. Cuando muere, su propietario elige una criatura que obtiene el sello Desenterrador de huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "Acople desenterrador reforzado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "Al final del turno de su propietario, [creature] genera 1 hueso. Cuando muere, su propietario elige una criatura que obtiene este sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "Rejuvenecimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "Cuando [creature] muere, su propietario elige una criatura que obtiene el sello Inexperto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "Tormenta de calaveras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "Al final del turno de su propietario, este sello se sustituye por otro sello aleatorio. Cuando muere la carta que lo lleva, su propietario elige una criatura que obtiene este sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Prender fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "Cuando [creature] muere, su propietario elige una criatura que obtiene el sello Ignición.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "Pulso óseo macabro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "Cuando se juega [creature], muere inmediatamente y deja tantos huesos como el doble de criaturas haya en el lado de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "Maternal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "Las criaturas adyacentes a [creature] obtienen el sello Acuático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "Necrosis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "Tras cada turno en el tablero, [creature] pierde 1 de poder y 1 de salud máxima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "Limbo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "Cuando [creature] muere, vuelve a la parte superior de tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "Aparición implacable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Al comienzo del turno de su propietario, las criaturas adyacentes a [creature] se transforman en Apariciones. Una Aparición tiene 3 de poder, 1 de salud y Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "Retorno de la aparición", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Después de atacar, [creature] muere y se barajan 2 Apariciones con sus antiguos sellos en tu mazo secundario. Una Aparición tiene 3 de poder, 1 de salud y Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "Mal presagio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "Al final del turno de su propietario, [creature] le inflige 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "Rencor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "Cuando [creature] muere, deja una mejora permanente de 1 de poder en el espacio que ocupaba.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "Praderas reconfortantes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "Al final del turno de su propietario, todas las criaturas del tablero obtienen 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "Último trazo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "Cuando una criatura sin Quebradizo del lado del propietario muere en combate, su propietario elige una criatura que pierde todos sus sellos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "Cadáver divisible", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "Cuando [creature] muere en combate, crea una Dismorfia en cada espacio vacío adyacente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "Tórpido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature] no puede atacar normalmente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "Epitafio lúgubre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "Cuando se juega [creature], puedes elegir una carta ya puesta a descansar y devolverla a tu mano.", Language.Spanish);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "Pie Grande", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "Una criatura misteriosa que acecha en los bosques. Solo unos pocos afirman haberla visto.", Language.Spanish);
            GrimoraMod.RegisterCard("Bigfoot", "Pie Grande");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Duende", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "Una bestia bárbara y leal, una buena incorporación a tu ejército.", Language.Spanish);
            GrimoraMod.RegisterCard("Goblin", "Duende");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "Vila", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "Amor a primera vista, o al menos eso quiere que creas.", Language.Spanish);
            GrimoraMod.RegisterCard("Vila", "Vila");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "Yaramayawho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "Parece que nunca logra terminar sus comidas...", Language.Spanish);
            GrimoraMod.RegisterCard("Yaramayawho", "Yaramayawho");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "Miembros de prueba", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "Estas piezas pertenecían a alguien, o ahora a algo... (Prueba)", Language.Spanish);
            GrimoraMod.RegisterCard("Test Limbs", "Miembros de prueba");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "Allip", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "¡Los restos de los dementes! Nunca sabes qué historia se oculta tras ese rostro, pero seguro que está llena de fervor.", Language.Spanish);
            GrimoraMod.RegisterCard("Allip", "Allip");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "Conejo de Amami", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "Esconden a sus crías en madrigueras para protegerlas lo mejor posible.", Language.Spanish);
            GrimoraMod.RegisterCard("Amami Rabbit", "Conejo de Amami");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "Ankhame", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "Una reliquia atraída por tu sangre. ¡Quizá podrías probarla!", Language.Spanish);
            GrimoraMod.RegisterCard("Ankhame", "Ankhame");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "Anneta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "La tinta sigue fluyendo. ¿Sigue ella ahí? Lo único que promete la muerte es que volverás a despertar.", Language.Spanish);
            GrimoraMod.RegisterCard("Anneta", "Anneta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "Anorexia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "Te inunda de desprecio hacia ti mismo; nunca sabes qué forma adoptará después.", Language.Spanish);
            GrimoraMod.RegisterCard("Anorexia", "Anorexia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "Campana del liche", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "Parece que han encontrado una nueva forma de usar campanas.", Language.Spanish);
            GrimoraMod.RegisterCard("Lych Bell", "Campana del liche");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "El Hinchado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "Forúnculos grotescos, a punto de estallar.", Language.Spanish);
            GrimoraMod.RegisterCard("TheBloated", "El Hinchado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "Cerebro en un frasco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "Estremece imaginar qué pensamientos inhumanos alberga ese frasco...", Language.Spanish);
            GrimoraMod.RegisterCard("BrainJar", "Cerebro en un frasco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "Carcasa incendiaria", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "Dios mío, ¡qué caída desde una posición tan estimulante y elevada! Ahora solo quedan una carcasa metálica y los últimos restos de aquella sustancia vigilante...", Language.Spanish);
            GrimoraMod.RegisterCard("Combustor", "Carcasa incendiaria");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "Armiño mal jugado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "Un Armiño en descomposición cuyas estrategias tan perfectas le han fallado estrepitosamente.", Language.Spanish);
            GrimoraMod.RegisterCard("Misplayed Stoat", "Armiño mal jugado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "Dismorfia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "Dismorfia izquierda.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "Dismorfia derecha.", Language.Spanish);
            GrimoraMod.RegisterCard("Dysmorphia", "Dismorfia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "Exorcista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "Sigue creyendo que desterrar a los condenados le hará bien. ¿Sabe siquiera dónde está?", Language.Spanish);
            GrimoraMod.RegisterCard("Exorcist", "Exorcista");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "Huesos purulentos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "Espera a que juegue con su cámara web.", Language.Spanish);
            GrimoraMod.RegisterCard("Flembones", "Huesos purulentos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "Stein y Frank", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "Ni siquiera el infierno estaba lo bastante caliente para separarlos.", Language.Spanish);
            GrimoraMod.RegisterCard("Stein & Frank", "Stein y Frank");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "Craneorrayo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "Si escuchas con atención, aún puedes oír el crepitar de las llamas sobre los huesos... y también su voz.", Language.Spanish);
            GrimoraMod.RegisterCard("FulmineSkull", "Craneorrayo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "Huesos de trueno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "Nunca abandonó realmente la silla eléctrica.", Language.Spanish);
            GrimoraMod.RegisterCard("FulurOssa", "Huesos de trueno");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "Llama de Prometeo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "Una pieza única: ¡los restos del botín de un ladrón en beneficio de la humanidad! ¿Te apetece hígado?", Language.Spanish);
            GrimoraMod.RegisterCard("PrometheusFlame", "Llama de Prometeo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "Entrañas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "Entrañas molestas.", Language.Spanish);
            GrimoraMod.RegisterCard("Guts", "Entrañas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "Precursor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "Un poderoso diablo que exige un alto precio por sus servicios.", Language.Spanish);
            GrimoraMod.RegisterCard("Harbinger", "Precursor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "Hastur", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "Vino de más allá de las estrellas y entregó fragmentos de su reflejo a reyes y necios por igual. ¿Aceptarás este fragmento?", Language.Spanish);
            GrimoraMod.RegisterCard("Hastur", "Hastur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "Diablillo común", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "¡Una criatura diminuta conocida por causar problemas y caos allá donde va, con su sonrisa traviesa y su carácter juguetón!", Language.Spanish);
            GrimoraMod.RegisterCard("Common Imp", "Diablillo común");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "Orochimitama", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "Oh... Él no debería estar aquí...", Language.Spanish);
            GrimoraMod.RegisterCard("Orochimitama", "Orochimitama");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "Aliento vital", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "Una presencia reconfortante que cura a tus criaturas, la calma antes de la tormenta.", Language.Spanish);
            GrimoraMod.RegisterCard("Inochi", "Aliento vital");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "Sendero del tormento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "Miembros poseídos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "Antes unidos a una persona viva, ahora pertenecen a algo completamente distinto.", Language.Spanish);
            GrimoraMod.RegisterCard("Possessed Limbs", "Miembros poseídos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "Topo sepulturero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "El firme Topo... ¿sepulturero? Sea lo que sea...", Language.Spanish);
            GrimoraMod.RegisterCard("Mole Digger", "Topo sepulturero");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "Nekros", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "Nekros domina el tablero, aspirante. La muerte es su patio de juegos.", Language.Spanish);
            GrimoraMod.RegisterCard("Nekros", "Nekros");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "Nekros Prime", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "No encontrarás mayor poder... que el simple pensamiento de tu propio nombre... grabado en una lápida.", Language.Spanish);
            GrimoraMod.RegisterCard("NekrosPrime", "Nekros Prime");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "Nuckelavee", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "El señor de su mar. ¡Más te vale esperar que su aliento no corrompa a tus siervos!", Language.Spanish);
            GrimoraMod.RegisterCard("Nuckelavee", "Nuckelavee");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "Masa odiosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "Qué aspecto tan desagradable.", Language.Spanish);
            GrimoraMod.RegisterCard("OdiousMass", "Masa odiosa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "Orochi", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Hay que hacer sacrificios.", Language.Spanish);
            GrimoraMod.RegisterCard("Orochi", "Orochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "Maestro Ouro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "En medio de un tormento y sufrimiento interminables, encontraron la forma de ver el interior de esta pobre cosa rota... y quitarle el dolor.", Language.Spanish);
            GrimoraMod.RegisterCard("Master Ouro", "Maestro Ouro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "Un ciclo infinito de vida y muerte ha pasado factura a estos restos abandonados. El dolor era real, ¡pero la muerte nunca es definitiva!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "GanCeann", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "Innumerables leyendas hablan del dullahan, pero ninguna transmite la verdadera magnitud de su ira.", Language.Spanish);
            GrimoraMod.RegisterCard("GanCeann", "GanCeann");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "Príncipe oscuro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "El poder de los peluditos brilla en tu interior.", Language.Spanish);
            GrimoraMod.RegisterCard("Dark Prince", "Príncipe oscuro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "Cuervo mortinato", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "¡Qué bien sienta volver a ser joven!", Language.Spanish);
            GrimoraMod.RegisterCard("Stillborn Raven", "Cuervo mortinato");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "Reanimado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "CON LA GUADAÑA DE LA MUERTE, LA APARICIÓN... UN MOMENTO, ¿QUÉ?", Language.Spanish);
            GrimoraMod.RegisterCard("Reanimated", "Reanimado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "Aparición arcana", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "La fuente de la Calamidad, implacable e infalible.", Language.Spanish);
            GrimoraMod.RegisterCard("RevenantEldritch", "Aparición arcana");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "Huesos perezosos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "Un esqueleto perezoso con talento para los chistes. Me encanta.", Language.Spanish);
            GrimoraMod.RegisterCard("Lazy Bones", "Huesos perezosos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "Esqueletófono", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "Una forma de comunicarse con los muertos, a cambio de un precio.", Language.Spanish);
            GrimoraMod.RegisterCard("Skelephone", "Esqueletófono");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Portal de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "Una oportunidad de entrar en el reino de las almas, ¡qué maravilla! Espero que puedas pagar el precio.", Language.Spanish);
            GrimoraMod.RegisterCard("Soulgate", "Portal de almas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "Guerrero de picas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "Este temible guerrero te enterrará a dos metros bajo tierra, en todos los sentidos posibles.", Language.Spanish);
            GrimoraMod.RegisterCard("SpadeWarrior", "Guerrero de picas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "Civil no muerto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "Perdida en la oscuridad eterna, esta pobre alma busca desesperadamente una salida. ¿Puedes iluminarle el camino?", Language.Spanish);
            GrimoraMod.RegisterCard("UndeadCivilian", "Civil no muerto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "Aldea de los no muertos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "Abandonada y desolada, esta aldea busca nuevos habitantes para sus casas ruinosas.", Language.Spanish);
            GrimoraMod.RegisterCard("UndeadVillage", "Aldea de los no muertos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "En cada pueblo y cada ciudad alguien debe enterrar a los muertos. Con el tiempo, también ellos serán enterrados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "Dr. Huesos", Language.Spanish);
            GrimoraMod.RegisterCard("Dr.Bones", "Dr. Huesos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "Lo que no te mata solo te hace estar más cuerdo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "Wendigo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "Vuelto de lo más profundo de las tierras salvajes, me recuerda a un amigo.", Language.Spanish);
            GrimoraMod.RegisterCard("Wendigo", "Wendigo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "Señor Victoria", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "Una carta que gana. Siempre gana. Por eso se llama Señor Victoria.", Language.Spanish);
            GrimoraMod.RegisterCard("Mister Win", "Señor Victoria");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "Esa no, me temo.", Language.Spanish);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "Tú... monstruo asesino.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "Dios mío... El flujo de la Calamidad te perseguirá.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "Perpetra una matanza en la aldea donde viviste.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "Busca la pala que cava eternamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "Tráeme al perdido que lleva una chispa en la mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "Impulsado por la llamada de una antigua entidad,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "ha comenzado un ritual prohibido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "El dolor alcanza a la antigua gran serpiente de la muerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Hay que hacer sacrificios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "Oh... Aún no hay cartas muertas.", Language.Spanish);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "Paquete de cartas del mod Revenant", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "Este paquete se compone principalmente de cartas que vuelven al jugador de diversas maneras.", Language.Spanish);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "Pipis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "Pipis.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "Ayuda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "Al final del turno de su propietario, [creature] se sacrifica para curar 1 de salud a las cartas adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "Paso libre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "Cuando [creature] va a ser atacada por una carta cuyo ataque supera su salud, perece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "Llamada basura", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "Al final del turno de su propietario, los espacios vacíos dentro de un circuito completado por [creature] generan Correo basura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "Golpe NEO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature] golpea cada espacio rival ocupado y, además, ambos espacios de cada mitad rival que contenga un objetivo. Si no hay objetivos rivales, ataca directamente los dos espacios centrales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "Llamada de auxilio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "Al final del turno de su propietario, [creature] pide ayuda.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "Adelante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "Antes de que [creature] ataque, su poder se fija en al menos 1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "Cabeza voladora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "La parte más importante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "Carro de correo basura", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "Lleno de correo basura. Absorbe todo tipo de ataques.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "Correo basura", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "Contiene toda clase de ofertas inolvidables.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "Gran tirador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "Dispara grandes tiros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "Corazón encadenado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "Precioso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "Spamgel", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "El resultado de pulsar F1.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "Teléfono de mano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "¿De verdad necesitas a alguien más?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "¡¡¡EL PODER DE NEO!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "¿No quieres convertirte en alguien importante?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "Receptor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "La voz termina por apagarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "Cupón grizzly", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "Cupón grizzly.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "Carro de osos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "Lleno de osos. Absorbe todo tipo de ataques.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "Correo de osos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "Correo para osos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "Oso encadenado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "Zarpa de oso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "Bomba ardilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "Las ardillas explotan al morir y causan 10 de daño a las cartas adyacentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "Fiesta de baile", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "Tus cartas se mueven cada turno. Las que no pueden moverse mueren.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "Otra vez", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "Todas las cartas rivales atacan dos veces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "Hambriento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "Reza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "Cazón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "Cada batalla empieza con un Cubo de cebo con Guardián.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "Tótems molestos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "Empieza cada batalla con un tótem Molesto para la tribu que más usas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "Robos dolorosos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "Robar del mazo principal inflige 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "Ardillas dolorosas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "Robar del mazo secundario inflige 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "Runas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "Las cartas enemigas de la tribu dominante obtienen sellos aleatorios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "Odontología", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "Los eventos de objetos y las cartas con Portador de abalorios solo dan alicates.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "Archivado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "En cada evento de elección de cartas se oculta una opción de carta aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "Cimientos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "Todas tus cartas tienen 1 de ataque menos. Las cartas del mazo secundario tienen Líder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "Jefe final v2", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "Sustituye a Leshy como jefe final por un auténtico GRAN TIPO.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "¡Tienes que bailar! ¡¡No dejes de bailar!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "Quien deje de bailar en mi fiesta sufrirá las consecuencias.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "¿Esa mecánica es molesta?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "Perfecto. Ese es el propósito.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "¡Baila, marioneta mía! Baaaila.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "Tienes que pasar, ¿recuerdas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "ESTOY [_spamton_0,ROBANDO] TUS KROMER", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "SANTO [_spamton_0,DESMADRE], QUÉ BIEN ME SIENTO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "¡¡¡AQUÍ ESTOY!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "GRAN", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>¡¡¡GRANDE!!!</size>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,MÁS GRANDE Y MEJOR QUE NUNCA]</size>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "Y AHORA QUE ESTOY EN ESTE [_spamton_0,JUEGO DE CARTAS]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "¡¡¡NO PUEDO SER DERROTADO!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "¡¡¡PREPÁRATE PARA SER [_spamton_0,ANIQUILADO] POR [_spamton_0,EL PODER DE NEO]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "¿¿¿OTRA VEZ [_spamton_0,ESTO]???", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "¡¡¡PREPÁRATE PARA SER [_spamton_0,DESTRUIDO]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "¡¡¡NO TIENES NINGUNA OPORTUNIDAD, [_spamton_0,PEQUEÑO GUSANILLO]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "¡¡¡PREPÁRATE PARA [_spamton_0,RECIBIR UN PUÑETAZO] EN LA [_spamton_0,CARA]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "¡¡¡MÍRAME A [_spamton_0,MÍ]!!! ¡¡¡MÍRATE A [_spamton_0,TI]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,ENLACE BLOQUEADO]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "¿ACASO ESTE CUERPO NO ES [_spamton_0,CELESTIAL]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "2X LA [_spamton_0,POTENCIA DE FUEGO]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "3X LA [_spamton_0,POTENCIA DE AGUA]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "Y LO MÁS IMPORTANTE", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "¡¡¡CABEZAS VOLADORAS!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "CONVERTIREMOS A ESOS [_spamton_0,IDIOTAS] Y [_spamton_0,BOBOS]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "EN [_spamton_0,TUMBAS DE ROSAS]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "ESAS [_spamton_0,PANTALLAS CATÓDICAS]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "EN [_spamton_0,GRITOS CATÓDICOS]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "¿¡NO QUIERES SER [_spamton_0,PARTE] DE MI HERMOSO [_spamton_0,CORAZÓN]?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "O... ¿NECESITABAS UNA PEQUEÑA [_spamton_0,VISITA ESPECIAL]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "¿¡[_spamton_0,QUÉ]?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "¿HAS [_spamton_0,ROBADO] MI [_spamton_0,CORAZÓN]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "¡NO PUEDES [_spamton_0,ROBAR] MI [_spamton_0,CORAZÓN], ES MI [_spamton_0,CORAZÓN]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "DEJA DE [_spamton_0,ROBAR] MI CORAZÓN, [_spamton_0,!@#$]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "O U C [_spamton_0,HYPERLINK BLOCKED]", "A Y [_spamton_0,ENLACE BLOQUEADO]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU JUST [_spamton_0,BROKE] MY [_spamton_0,$4.99] HEART", "ACABAS DE [_spamton_0,ROMPER] MI CORAZÓN DE [_spamton_0,$4.99]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "¿¡SABES QUE [_spamton_0,DUELE] CUANDO [_spamton_0,HACES] ESO?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "¿NO QUIERES AYUDAR A TU VIEJO AMIGO SPAMTON?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THINK! WHAT ARE MY [_spamton_0,EGGS] GOING TO DO!?", "¡PIENSA! ¿¡QUÉ VAN A HACER MIS [_spamton_0,HUEVOS]?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S CALLING...", "ESTÁ LLAMANDO...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HEART]...", "MI [_spamton_0,CORAZÓN]...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HANDS]...", "MIS [_spamton_0,MANOS]...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AT THE [_spamton_0,POWER OF NEO] AND ASK YOURSELF...", "MIRA [_spamton_0,EL PODER DE NEO] Y PREGÚNTATE...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU?", "¿NO QUIERES?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE A [_spamton_0,BIG SHOT]!?", "¿¡NO QUIERES SER UN [_spamton_0,GRAN TIPO]?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY ESTEEM CUSTOMER I SEE YOU ARE ATTEMPTING TO DEPLETE MY HP!", "¡ESTIMADO CLIENTE, VEO QUE INTENTAS AGOTAR MIS PS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL ADMIT YOU'VE GOT SOME [_spamton_0,GUTS]!", "¡ADMITO QUE TIENES [_spamton_0,AGALLAS]!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IN A [_spamton_0,1 FOR 1] BATTLE, NEO NEVER LOSES!!!", "¡¡¡PERO EN UNA BATALLA [_spamton_0,1 CONTRA 1], NEO NUNCA PIERDE!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR A LITTLE [_spamton_0,BLUELIGHT SPECIL]", "ES HORA DE UNA PEQUEÑA [_spamton_0,OFERTA DE LUZ AZUL]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU [_spamton_0,SURPRISED] THAT YOU CAN'T JUST [_spamton_0,DESTROY] ME WITH YOUR [_spamton_0,PATHETIC LITTLE] [_spamton_0,CARDS]?", "¿TE [_spamton_0,SORPRENDE] NO PODER [_spamton_0,DESTRUIRME] CON TUS [_spamton_0,PATÉTICAS] [_spamton_0,CARTITAS]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIDN'T YOU KNOW [_spamton_0,NEO] IS FAMOUS FOR ITS HIGH DEFENSE!?", "¿¡NO SABÍAS QUE [_spamton_0,NEO] ES FAMOSO POR SU GRAN DEFENSA?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW... ENJ0Y THE FIR3WORKS!!!", "AHORA... ¡¡¡DISFRUTA D3 LOS FUEG0S ARTIFICIALES!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENJOY THE FIREWORKS!!!!", "¡¡¡¡DISFRUTA DE LOS FUEGOS ARTIFICIALES!!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT?", "¿QUÉ?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO] ARE YOU TRYING TO [_spamton_0,CALL]???", "¿¿¿A [_spamton_0,QUIÉN] INTENTAS [_spamton_0,LLAMAR]???", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE NO [_spamton_0,FRIENDS] IN THIS [_spamton_0,WORLD]!!!", "¡¡¡NO TIENES [_spamton_0,AMIGOS] EN ESTE [_spamton_0,MUNDO]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY'RE ALL [_spamton_0,PAPER CARDS]!!!", "¡¡¡TODOS SON [_spamton_0,CARTAS DE PAPEL]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHO'RE YOU GONNA CALL, THE [_spamton_0,POLICE]?", "¿A QUIÉN VAS A LLAMAR, A LA [_spamton_0,POLICÍA]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE [_spamton_0,PATHETIC]!!", "¡¡ERES [_spamton_0,PATÉTICO]!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,SCREAMING] FOR [_spamton_0,HELP] [_spamton_0,AT THE BOTTOM OF A DUMPSTER]!!!", "¡¡¡[_spamton_0,GRITAR] PIDIENDO [_spamton_0,AYUDA] [_spamton_0,EN EL FONDO DE UN CONTENEDOR]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO [_spamton_0,HELP] FOR YOU!!!", "¡¡¡NO HAY [_spamton_0,AYUDA] PARA TI!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,VOICE] IS GOING TO RUN OUT EVENTUALLY!!", "¡¡TU [_spamton_0,VOZ] ACABARÁ POR APAGARSE!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GIVE UP!!!", "¡¡¡RÍNDETE!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T WIN!!!", "¡¡¡NO PUEDES GANAR!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM UNSTOPPABLE!!!", "¡¡¡SOY IMPARABLE!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,FREE TRIAL OF] LIFE IS ABOUT TO [_spamton_0,EXPIRE]!!!", "¡¡¡TU [_spamton_0,PRUEBA GRATIS] DE LA VIDA ESTÁ A PUNTO DE [_spamton_0,CADUCAR]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,GOOBERT]?", "¿[_spamton_0,GOO]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS IT THAT [_spamton_0,PATHETIC] LITTLE [_spamton_0,JAR] OF [_spamton_0,GOO]?", "¿ES ESE [_spamton_0,PATÉTICO] [_spamton_0,TARRITO] DE [_spamton_0,MUGRE]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT [_spamton_0,HELP] WILL IT [_spamton_0,PROVIDE] TO [_spamton_0,YOU]???", "¿¿¿QUÉ [_spamton_0,AYUDA] PUEDE [_spamton_0,DARTE] A [_spamton_0,TI]???", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,MAGNIFICUS]??", "¿¿[_spamton_0,MAGNIFICUS]??", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT IS A [_spamton_0,MAGNIFICUS]? IS IT A KIND OF [_spamton_0,BLOWFISH]?", "¿QUÉ ES UN [_spamton_0,MAGNIFICUS]? ¿UNA ESPECIE DE [_spamton_0,PEZ GLOBO]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT'S A [_spamton_0,BLOWFISH] GONNA [_spamton_0,DO TO ME]??", "¿¿QUÉ VA A [_spamton_0,HACERME] UN [_spamton_0,PEZ GLOBO]??", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,LESHY]???", "¿¿¿[_spamton_0,LESHY]???", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS THAT THE [_spamton_0,GUY] WHO I [_spamton_0,HIT] AT THE BEGGINING OF OUR [_spamton_0,FIGHT]???", "¿¿¿ES EL [_spamton_0,TIPO] AL QUE [_spamton_0,GOLPEÉ] AL PRINCIPIO DE NUESTRA [_spamton_0,PELEA]???", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HA! I'M NOT EVEN SURE THAT HE IS [_spamton_0,ALIVE AND WELL]!!!", "¡¡¡JA! ¡NI SIQUIERA ESTOY SEGURO DE QUE ESTÉ [_spamton_0,VIVO Y BIEN]!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_1,ROYAL]?", "¿[_spamton_1,ROYAL]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROYAL [_spamton_0,WHAT]? ROYAL [_spamton_0,WHO]?", "¿ROYAL [_spamton_0,QUÉ]? ¿ROYAL [_spamton_0,QUIÉN]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO/WHAT/WHEN/WHY/HOW] IS [_spamton_0,ROYAL]?", "¿[_spamton_0,QUIÉN/QUÉ/CUÁNDO/POR QUÉ/CÓMO] ES [_spamton_0,ROYAL]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE SO PATHETIC", "ERES TAN PATÉTICO", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MUMBLING NONSENSE WORDS THROUGH A [_spamton_0,PLAYING CARD]", "MURMURAS TONTERÍAS A TRAVÉS DE UNA [_spamton_0,CARTA DE JUEGO]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU THINK YOU CAN [_spamton_0,AVOID] YOUR [_spamton_0,UNAVOIDABLE, QUICKLY APPROACHING] DEMISE?", "¿CREES QUE PUEDES [_spamton_0,EVITAR] TU FINAL [_spamton_0,INEVITABLE Y CADA VEZ MÁS CERCANO]?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THERE]", "[_spamton_0,AHÍ]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU GONNA DO WITHOUT YOUR [_spamton_0,COMMUNICATION DEVICE]???", "¿¿¿QUÉ HARÁS SIN TU [_spamton_0,DISPOSITIVO DE COMUNICACIÓN]???", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT IS IT JUST [_spamton_0,ME]", "ESPERA, ¿SOLO [_spamton_0,YO]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR DOES IT SOUND LIKE A [_spamton_0,SHIP] IS COMING [_spamton_0,OUR] WAY??", "¿O PARECE QUE UN [_spamton_0,BARCO] VIENE HACIA [_spamton_0,NOSOTROS]??", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY [_spamton_0,NOTHING] [_spamton_0,AT HALF PRICE]", "SEGURO QUE ES [_spamton_0,NADA] [_spamton_0,A MITAD DE PRECIO]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY JUST A SOUND IN MY [_spamton_0,HEAD], IN MY [_spamton_0,EARS]", "SEGURO QUE ES SOLO UN SONIDO EN MI [_spamton_0,CABEZA], EN MIS [_spamton_0,OÍDOS]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO WAY A [_spamton_0,SHIP] COULD FIT IN THIS LITTLE [_spamton_0,CABIN FOR SALE]", "UN [_spamton_0,BARCO] NO CABRÍA EN ESTA PEQUEÑA [_spamton_0,CABAÑA EN VENTA]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WILL NEVER DEFEAT-", "NUNCA ME DERROTARÁS-", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAY [_spamton_0,GOODBYE] [_spamton_0,TO YOUR FRIENDS AND FAMILY]", "DI [_spamton_0,ADIÓS] [_spamton_0,A TUS AMIGOS Y FAMILIARES]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE [_spamton_0,POWER OF NEO] WAS TOO MUCH FOR YOU", "EL [_spamton_0,PODER DE NEO] ERA DEMASIADO PARA TI", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONFIDENTIAL", "CONFIDENCIAL", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEFEATED BY A WEAKLING HUMAN...", "DERROTADO POR UN HUMANO DEBILUCHO...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOOOOOOOOOOOOOOO!!!!!!", "¡¡¡¡¡¡NOOOOOOOOOOOOOOO!!!!!!", Language.Spanish);


        }
    }
