            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the drill by now.", "el procedimiento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]God...", "[e:2] Dios...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]it reeks like death.", "[e:2] Apesta a muerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]don't tell me those", "[e:3] No me digas que esos son", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]are real dead fish.", "[e:3] peces muertos de verdad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This boss again...", "Otra vez este jefe...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]great....", "[e:2] Genial....", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you know the drill,", "Ya sabes cómo va:", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "throw a squirrel", "lanza una ardilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "or something when", "o algo así cuando", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he takes out the hook.", "saque el gancho.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]yadda yadda..,", "[e:2] Bla, bla...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you should be fine.", "Deberías estar bien.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm honestly sick of this one.", "Sinceramente, estoy harto de este.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:4] Trapper, huh? [w:2]", "[e:4] El Trampero, ¿eh? [w:2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:3]I got a bad feeling about this.", "[e:3]Tengo un mal presentimiento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "let's get this over with.", "Acabemos con esto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trapper again,", "Otra vez el Trampero,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]great...", "[e:2] genial...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:4]huh...", "[e:4] Vaya...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "these pelts might seem helpful.", "Estas pieles podrían ser útiles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]let's end this.", "[e:2] Acabemos con esto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we're finally here..", "Por fin hemos llegado...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got this, man.", "Puedes hacerlo, amigo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:1] I believe in you.", "[e:1] Creo en ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2] god I'm sick", "[e:2] Dios, estoy harto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:2]of this guy.", "[e:2] de este tipo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "please win.", "Por favor, gana.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm feeling", "Me siento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "optimistic this time.", "optimista esta vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:1] I think you got this.", "[e:1] Creo que puedes lograrlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wisp", "Fuego fatuo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a spirit of pure fire, one of which requires fuel to grow.", "Un espíritu de fuego puro que necesita combustible para crecer.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xolotl", "Xolotl", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sinister god of twilight, banished into the bodies of meager amphibians, has risen from his ancient shackles.", "El siniestro dios del crepúsculo, desterrado a los cuerpos de humildes anfibios, se ha liberado de sus antiguas cadenas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zebra", "Cebra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vitriolic zebra will stop at nothing to kill whatever is there to harm it.", "La virulenta cebra hará lo que sea para matar a todo lo que pretenda hacerle daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim zombie, a punished soul forced to wander for eternity.", "El lúgubre zombi, un alma castigada y obligada a vagar eternamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emporer Penguin", "Pingüino emperador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clouded Leopard", "Pantera nebulosa", Language.Spanish);

            //sigils
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predator", "Superdepredador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice 2 cards to boost [creature]'s attack by 1.", "Sacrifica 2 cartas para aumentar en 1 el ataque de [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonepile Strafe", "Movimiento de osamenta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move, leaving a pile of bones in it's place.", "Al final del turno de su propietario, [creature] se mueve en la dirección del sello y deja un montón de huesos en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, the sigil bearer will move, leaving a pile of bones in it's place.", "Al final del turno de su propietario, la carta que lleve este sello se mueve en la dirección indicada y deja un montón de huesos en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon placing the sigil bearer, draw an acorn. An acorn is defined as: 1 health, fledgling.", "Cuando se coloca la carta que lleve este sello, roba una Bellota. Una Bellota tiene 1 de salud e Inexperto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "at the end of the enemy's turn, the card owner's board is fully replaced with a 'the horde'.", "Al comienzo del turno del propietario de esta carta, los cuatro espacios de su lado se llenan de cartas Horda, que sustituyen su contenido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summons a cicada swarm on the owner's board, placing cicada cards on their side wherever it can.", "Invoca un enjambre de cigarras en el lado del propietario y coloca cartas de cigarra donde sea posible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo's Ambush", "Emboscada del Wendigo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wendigo will move to your board at the end of my turn.", "El Wendigo se moverá a tu lado del tablero al final de mi turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavy burden to carry all those bones.", "Cargar con todos esos huesos es una pesada carga.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor soul has awakened the beast.", "Una pobre alma ha despertado a la bestia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird of Prey", "Ave de presa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by [creature] will take 1 damage each time it declares an attack, and renders their wings useless.", "Las cartas Aéreas que reciben daño de [creature] pierden Aéreo y reciben 1 de daño cada vez que declaran un ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by the sigil bearer will take 1 damage each time it declares an attack, and renders their wings useless.", "Las cartas Aéreas que reciben daño de la carta que lleve este sello pierden Aéreo y reciben 1 de daño cada vez que declaran un ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sentry of the skies, keeping things grounded.", "Una centinela de los cielos que mantiene a los demás en tierra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dog Summon", "Invocación de perro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sigil bearer will move to an empty adjacent slot and leave a bloodhound.", "La carta que lleve este sello se mueve a un espacio vacío adyacente y deja un Sabueso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doesn't she look beautiful?", "¿No está preciosa?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So impatient....", "Qué impaciencia...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infested", "Infestado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, draw a parasite into your hand.", "Cuando [creature] recibe un golpe, roba un Parásito y añádelo a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is the host alive or merely being puppeted? Best not to know.", "¿El huésped sigue vivo o solo lo manejan como una marioneta? Mejor no saberlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrieker's call", "Llamada del chillador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the opponent's turn ends, [creature]'s board is replaced with a zombie horde.", "Al comienzo del turno de su propietario, los cuatro espacios del lado de [creature] se llenan de cartas Horda de zombis, que sustituyen su contenido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A painful screech is echoed throughout.", "Un grito doloroso resuena por todas partes.", Language.Spanish);

            //encounters
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caribou", "Caribú", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alebrije", "Alebrije", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "Oso hormiguero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caiman", "Caimán", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caribou Fawn", "Cría de caribú", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Condor", "Cóndor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lobsterzilla", "Langostazilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giraffe", "Jirafa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Pile", "Montón de oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaker", "Goteador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minotaur", "Minotauro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper", "Segador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhino", "Rinoceronte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrieker", "Chillador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it's best to take it down before it launches its cry.", "Más vale acabar con él antes de que lance su grito.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Wall", "Muro de piedra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brambles", "Zarzas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends From The Darkness: Encounters", "Leyendas de la oscuridad: Encuentros", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an Ever-expanding content pack for LFTD, meant to add battle encounters to the game.", "Un paquete de contenido en constante expansión para Leyendas de la oscuridad, pensado para añadir encuentros de combate al juego.", Language.Spanish);

        }
    }
    public class GarethMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for GarethMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gareth's Mod", "Mod de Gareth", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A part 1 booster pack created by Gareth48 and illustrated by Plutraser. Adds [count] cards and 7 sigils designed to fit right into vanilla Inscryption.", "Un paquete de cartas del acto 1 creado por Gareth48 e ilustrado por Plutraser. Añade [count] cartas y 7 sellos diseñados para encajar en el Inscryption base.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gareth48", "Gareth48", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sorry, can't do that", "Lo siento, no puedo hacerlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whats... he doing here?", "¿Qué... hace él aquí?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skinwalker", "Cambiapieles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The enigmatic skinwalker. It mimics the identity of the first creature it slays.", "El enigmático Cambiapieles. Imita la identidad de la primera criatura que mata.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounded Animal", "Animal herido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An easy target for hungry predators.", "Un objetivo fácil para depredadores hambrientos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemming", "Lemming", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The paranoid lemming. Fragile and a favorite treat among many animals.", "El lemming paranoico. Frágil y un bocado predilecto de muchos animales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treant", "Hombre árbol", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did this creature get here?", "¿Cómo ha llegado esta criatura aquí?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snag", "Obstáculo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapling", "Brote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time, even the smallest sapling becomes a massive, imposing obstacle.", "Con el tiempo, hasta el brote más pequeño se convierte en un obstáculo enorme e imponente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oxpecker", "Picabueyes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The adored Oxpecker. A bird capable of befriending even the fiercest of foes.", "El adorado Picabueyes. Un ave capaz de hacerse amiga incluso de los enemigos más feroces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy elephant. Friendly but not weak.", "El robusto elefante. Amistoso, pero no débil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cackling hyena. It always has an ally lurking in the shadows.", "La hiena carcajeante. Siempre tiene un aliado al acecho en las sombras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The aggressive panther. Never one to back down from a fight.", "La Pantera negra agresiva. Nunca rehúye una pelea.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Panther Cub", "Cría de pantera negra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young panther. Even now its caution is unwavering", "La joven pantera negra. Incluso ahora su cautela no flaquea.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tasmanian Devil", "Demonio de Tasmania", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Tasmanian devil. A fierce carnivore with a voracious appetite.", "El feroz Demonio de Tasmania. Un temible carnívoro de apetito voraz.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archerfish", "Pez arquero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish, an excellent marksman, known to shoot bugs out of the air with a blast of water.", "El pez arquero, un excelente tirador capaz de derribar insectos en el aire con un chorro de agua.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hercules Beetle", "Escarabajo hércules", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forceful Hercules beetle. It can move creatures many times its size.", "El poderoso escarabajo hércules. Puede mover criaturas varias veces mayores que él.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golem", "Gólem", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient golem. The magic that binds it is old but powerful. It will reform after death.", "Un gólem antiguo. La magia que lo une es vieja pero poderosa. Se reconstruirá tras morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The awe-inspiring lion. Sure to lead your creatures to victory.", "El impresionante león. Sin duda guiará a tus criaturas a la victoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juvenile Lion", "León joven", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lion Cub", "Cachorro de león", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The princely lion cub. Given time it will become the king of its pride.", "El principesco cachorro de león. Con el tiempo se convertirá en el rey de su manada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piranha", "Piraña", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious piranha. Schools can devour any living thing in seconds.", "La feroz piraña. Un banco puede devorar a cualquier ser vivo en segundos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stealthy leopard. Invisible to its prey until it's too late.", "El sigiloso leopardo. Invisible para su presa hasta que es demasiado tarde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Bee Swarm", "Enjambre de abejas asesinas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious killer bee. The more one fights the more will swarm.", "La feroz abeja asesina. Cuanto más se lucha, más acuden en enjambre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous pig. Its hunger is insatiable, it will eat and eat until nothing remains.", "El cerdo voraz. Su hambre es insaciable y come hasta que no queda nada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Badger", "Tejón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bothersome badger. Quick to strike and retreat back into the shadows.", "El molesto tejón. Golpea deprisa y se retira de nuevo a las sombras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "Lince rojo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wily bobcat. Unafraid to defend its territory but smart enough to know when to retreat.", "El astuto lince rojo. Defiende su territorio sin miedo, pero es lo bastante listo para saber cuándo retirarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hasty dragonfly. Few can hit an insect this fast.", "La veloz libélula. Pocos pueden alcanzar a un insecto tan rápido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allies", "Aliados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil dies, a random ally will temporarily join your hand to avenge it.", "Cuando una criatura que lleve este sello muere, un aliado aleatorio se une temporalmente a tu mano para vengarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems a creature has come to avenge the passing of its ally.", "Parece que una criatura ha venido a vengar la muerte de su aliado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Essence Steal", "Robo de esencia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil kills another, it transforms into an exact copy of it.", "Cuando una criatura que lleve este sello mata a otra, se transforma en una copia exacta de su víctima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature has slain mine, and will now become an imitation of it.", "Tu criatura ha matado a la mía y ahora se convertirá en una imitación de ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After a creature bearing this sigil attacks the user chooses a space. The creature will move to that space.", "Después de que una criatura con este sello ataque, el jugador elige un espacio vacío de su lado. La criatura se mueve allí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It retreated after it struck, perhaps it's regathering its strength for another strike.", "Se retiró después de golpear; quizá esté recuperando fuerzas para otro ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hungry", "Hambriento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil is played, choose another friendly creature to eat. The eaten creature will have its health and power added to the creature bearing this sigil.", "Cuando se juega una criatura con este sello, elige otra criatura aliada para devorarla. Su salud y poder se añaden a la criatura que lleva el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems eating another creature has caused yours to grow stronger.", "Parece que comerse a otra criatura ha hecho más fuerte a la tuya.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shove", "Empujón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil is played, it will move up to the space opposing it. Creatures that are in the way will be pushed in the same direction.", "Cuando se juega una criatura con este sello, se mueve al espacio enfrentado del lado rival si está libre o puede despejarse; cualquier carta que lo ocupe es empujada a la cola rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have such fickle allies.", "Tus aliados son muy volubles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Standoffish", "Distante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as a creature bearing this sigil is opposed by another, it has +2 attack.", "Mientras una criatura con este sello tenga otra criatura enfrente, tiene +2 de ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tasty", "Sabroso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature bearing this sigil dies, a random creature shows up to devour it.", "Cuando una criatura con este sello muere, aparece una criatura aleatoria para devorarla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creature will fight with all it has until none oppose it.", "Tu criatura luchará con todas sus fuerzas hasta que nadie se le oponga.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that another animal has come to feed. The cycle of life continues.", "Parece que otro animal ha venido a alimentarse. El ciclo de la vida continúa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curious, I don't seem to remember this creature...", "Qué curioso, no parece que recuerde a esta criatura...", Language.Spanish);

        }
    }
    public class LifeCostAPIMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Life_Cost_API Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leck", "Leck", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Lost Beast, in the shape of a tooth, showing up only in error.", "La Bestia perdida, con forma de diente, que aparece solo por error.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meck", "Meck", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teck", "Teck", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:bG]Life[c:] or [c:gray]Foils[c:] to play that. Damage your opponent to gain more [c:bG]Life[c:].", "No tienes suficiente [c:bG]vida[c:] o [c:gray]foils[c:] para jugarla. Inflige daño a tu rival para obtener más [c:bG]vida[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:bG]Life[c:] on your scales to play that. Damage your opponent to gain more [c:bG]Life[c:].", "No tienes suficiente [c:bG]vida[c:] en tu balanza para jugarla. Inflige daño a tu rival para obtener más [c:bG]vida[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough [c:gray]Foils[c:] to play that. You gain [c:gray]Foils[c:] by dealing overkill damage.", "No tienes suficientes [c:gray]foils[c:] para jugarla. Obtienes [c:gray]foils[c:] al infligir daño excedente.", Language.Spanish);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Max Energy Gamble", "Apuesta de energía máxima", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 6 energy to put 0 to 3 damage on someone's side of the scale", "Paga 6 de energía para colocar de 0 a 3 de daño en el lado de la balanza de alguien.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Die Roll", "Tirada de dados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Money for Blood", "Dinero por sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 5 Life/Foils to gain between 0 and 6 increase in stats, distributed randomly", "Paga 5 de vida o foils para obtener un aumento de estadísticas de 0 a 6, repartido al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sing it once, Sing it twice, take a chance and roll the dice!", "¡Canta una vez, canta dos, tira los dados y prueba suerte!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cash Converter", "Conversor de dinero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 foils to put 1 damage on your opponent's side of the scale", "Paga 4 foils para colocar 1 de daño en el lado rival de la balanza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Converter", "Conversor de vida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 life to gain 1 foils", "Paga 2 de vida para obtener 1 foil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vamperic Strength", "Fuerza vampírica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 life to increase the power and health of this card by 1", "Paga 3 de vida para aumentar en 1 el poder y la salud de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood for money", "Sangre por dinero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hurting oneself can lead to an increase in strength.", "Herirse a uno mismo puede aumentar la fuerza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Strength", "Fuerza codiciosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 5 currency to increase the power and health of this card by 1", "Paga 5 de moneda para aumentar en 1 el poder y la salud de esta carta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A puddle that errods all that touches it.", "Un charco que corroe todo lo que toca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One can be hired to do many tasks", "Se le puede contratar para muchas tareas.", Language.Spanish);

        }
    }
    public class EriCardExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Eri_Card_Expansion Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Young Bear", "Oso joven", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young grizzly, old enough to defend itself.", "Un grizzly joven, lo bastante mayor para defenderse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crow", "Corneja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crow, an omen of death", "La siniestra corneja, presagio de muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Eel, it will shock the creatures next to its target", "La Anguila eléctrica descarga a las criaturas junto a su objetivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elk Skeleton", "Esqueleto de uapití", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A short one? Strange", "¿Uno bajito? Qué raro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malaysian Ant", "Hormiga malasia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Malaysian Ant, it will explode to protect the nest", "La Hormiga malasia explota para proteger el nido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Heavy' Bird", "Ave «pesada»", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not sure how that one can still fly", "No sé cómo consigue seguir volando", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In cooking, always use much garlic. But one should be sufficient for our purposes.", "Al cocinar, usa siempre mucho ajo. Pero uno debería bastar para nuestros fines.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotting Garlic", "Ajo putrefacto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Leech", "Sanguijuela gigante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty vermin, it will drain the lifeforce of it's foes", "Una alimaña desagradable que drena la fuerza vital de sus enemigos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorilla", "Gorila", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The powerful gorilla, it will lead your team", "El poderoso gorila liderará tu equipo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving Hawk", "Halcón en picado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic hawk, hunting its prey", "El majestuoso halcón caza a su presa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soaring Hawk", "Halcón planeador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic hawk, soaring in the sky", "El majestuoso halcón planea en el cielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hedgehog", "Erizo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the wise hedgehog. Swift to escape danger.", "Ah, el sabio erizo. Huye rápidamente del peligro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Honey Badger, it will grows stronger when attacked", "El feroz Tejón de la miel se vuelve más fuerte al ser atacado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't underestimate the might of this scavenger", "No subestimes el poder de este Carroñero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Egg", "Huevo de mantis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time this egg will become a powerful mantis", "Con el tiempo, este huevo se convertirá en una poderosa mantis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fitting name, for one who learns its song from others.", "Un nombre apropiado para quien aprende su canto de otros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Myconid", "Micónido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The easily annoyed myconid, not quite sure what they're about", "El micónido fácilmente irritable, nadie sabe bien qué pretende", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oak Tree", "Roble", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Octopus", "Pulpo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Goat", "Cabra vieja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The apotheosized Goat. This one is long due for a sacrifice.", "La Cabra divinizada. Hace mucho que debería haber sido sacrificada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlbear", "Oso lechuza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The savage Owlbear, it will rampage through its opponents.", "El salvaje Oso lechuza arrasa a sus rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlcat", "Gato lechuza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Half cat, half owl... an aberation really.", "Mitad gato, mitad búho... una auténtica aberración.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owlslime", "Slime búho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... what happenned to that owl?", "Oh, no... ¿qué le ha pasado a ese búho?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platypus", "Ornitorrinco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's a platypus. They don't do much.", "Es un ornitorrinco. No hacen mucho.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A regrettable fate. But perhaps he may be of some use, yet.", "Un destino lamentable. Pero quizá aún pueda ser de utilidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley Raccoon", "Mapache del valle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The conniving raccoon, it will use the strenghts of his opponent against them", "El taimado mapache usa las fuerzas de su rival en su contra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Horn", "Carnero de grandes cuernos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The powerful ram will clear most things standing in your way", "El poderoso carnero despejará la mayoría de los obstáculos de tu camino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Skeleton", "Esqueleto de rata", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnant of a rat... Can't be picky when you're starving for ressources", "Los restos de una rata... No puedes ser exigente cuando te faltan recursos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Fox", "Zorro rojo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The red fox, a source of terror to the meek rabbit", "El zorro rojo, fuente de terror para el dócil conejo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive Rhinoceros, nothing will stop its charge", "El enorme rinoceronte: nada detendrá su embestida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ring-Tailed Lemur", "Lémur de cola anillada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He likes to move it.", "Le gusta moverse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Jelly", "Jalea real", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sweet jar attract both ants and bees", "Este tarro dulce atrae tanto a hormigas como a abejas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Otter", "Nutria marina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning sea otter, it will dive to kill submerged creature", "La astuta nutria marina se sumerge para matar a las criaturas sumergidas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Secretary Bird", "Secretario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This secretary bird, it will only fly away when outmatched", "Este secretario solo sale volando cuando se enfrenta a un rival superior", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sheep", "Oveja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you intend to do with a flock of sheep", "¿Qué piensas hacer con un rebaño de ovejas?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snail", "Caracol", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A snail, safe in its shell", "Un caracol, a salvo en su caparazón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Ant", "Hormiga francotiradora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sharpshooter, more dangerous than it appears", "Una pequeña tiradora certera, más peligrosa de lo que parece", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resistant thorny devil, creature fighting it should be wary", "El resistente Diablo espinoso: las criaturas que luchen contra él deben tener cuidado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truffle Hog", "Cerdo trufero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tasty beast obsessed with hidden treasures.", "Una sabrosa bestia obsesionada con los tesoros ocultos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Griffon Vulture", "Buitre leonado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Griffon Vulture will feed on your dead but will not stick around", "El Buitre leonado se alimentará de tus muertos, pero no se quedará mucho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walrus", "Morsa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive walrus, a very territorial beast", "La enorme morsa, una bestia muy territorial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthog", "Facóquero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Wolf", "Lobo blanco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The arctic white wolf, the smell of blood will strengthen the pack", "El Lobo blanco ártico: el olor de la sangre fortalece la manada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Skeleton", "Esqueleto de lobo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wolf is as dangerous in this form as it used to be", "El lobo es tan peligroso con esta forma como lo era antes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Husk", "Caparazón de hormiga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The husk of an ant, their dedication truly know no bounds", "El caparazón de una hormiga. Su dedicación no conoce límites", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nest Worker", "Obrera del nido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting ant worker, taking care of its nest", "La incansable hormiga obrera cuida de su nido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a cute little critter", "Qué criaturita tan adorable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cub", "Osezno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With time, this young one may grow into a powerful beast.", "Con el tiempo, esta cría podría convertirse en una poderosa bestia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Skeleton", "Esqueleto de oso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrible creature that shouldn't allow to be.", "Una criatura terrible que no debería existir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bell Warrior", "Guerrero de campana", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tricky little fighter.", "Un pequeño luchador tramposo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Skeleton", "Esqueleto de ave", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnant of a bird, no longer will it fly", "Los restos de un ave que ya no volverá a volar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Totem", "Tótem de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An idol dedicated to death and rebirth", "Un ídolo dedicado a la muerte y el renacimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buffalo", "Búfalo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The massive buffalo, it will tackle its opponent out of the way when played", "El enorme búfalo aparta a su rival al jugarlo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Capuchin", "Capuchino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The agile capucin, it will avoid incomming attack", "El ágil capuchino esquiva los ataques entrantes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Ant", "Hormiga carroñera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll strip a dead body clean. Or a live one.", "Dejan un cadáver limpio hasta los huesos. O uno vivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Swarm", "Enjambre carroñero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The resilient crab. It’s hard shell will lessen any damage it takes.", "El resistente cangrejo. Su duro caparazón reduce todo el daño que recibe.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gator", "Aligátor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most dangerous beast lurking the wetlands", "La bestia más peligrosa que acecha en los humedales", Language.Spanish);

        }
    }
    public class TheBeastBossBattleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for The_Beast_Boss_Battle Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come forth and be saved by his light!", "¡Ven y deja que su luz te salve!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You forgo his teachings? Disgusting!", "¿Renuncias a sus enseñanzas? ¡Repugnante!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suddenly, the sky above cracked open, and a white beam of light reached down into the Earth, smiting the Mother of Harlots asunder and setting the blood lake to a boil.", "De pronto, el cielo se abrió y un rayo de luz blanca descendió hasta la Tierra, destrozando a la Madre de las rameras y haciendo hervir el lago de sangre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, poor, ignorant heretic...you have doomed us all! I can hear their arrival at this moment...!", "Ah, pobre e ignorante hereje... ¡Nos has condenado a todos! Puedo oír su llegada en este mismo momento...!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No. I won't allow you just take God's power like that. Face it or die.", "No. No permitiré que te apropies así del poder de Dios. Enfréntate a él o muere.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fought well... But you will need more strenght... and faith... if you want to overcome the challenge. Goodbye for now.", "Has luchado bien... Pero necesitarás más fuerza... y fe... para superar el desafío. Adiós por ahora.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready to confess your sins?", "¿Estás listo para confesar tus pecados?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Behold! The apocalypse is imminent!", "¡Contemplad! ¡El apocalipsis es inminente!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So you really want this story to end this way, don't you. Right then.", "De verdad quieres que esta historia termine así, ¿verdad? Muy bien.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And the belly of the earth quivered, and so came forth Famine, bringer of strife and ruin.", "El vientre de la Tierra tembló y surgió la Hambruna, portadora de discordia y ruina.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And henceforth came Pestilence, bringer of the plagues, desecrator of the ill.", "Luego llegó la Peste, portadora de plagas y profanadora de los enfermos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "War, atop his steed, strode with wild abandon. He knew not the inevitable self-destruction his manic nature brought, just as those who meaninglessly conflict themselves.", "La Guerra avanzó sobre su corcel con salvaje desenfreno. Desconocía la inevitable autodestrucción que traía su naturaleza enloquecida, al igual que quienes luchan entre sí sin sentido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, upon his pale horse, arrived Death. The ending of endings, the bringer of salvation and damnation - the reaper of the deceased.", "Finalmente llegó la Muerte sobre su caballo pálido. El final de los finales, portadora de salvación y condena: la segadora de los difuntos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And so arrives the Mother of Harlots, as forewarned, and as preceded by the untimely deaths of her harbingers.", "Y así llega la Madre de las rameras, tal como fue anunciado y precedida por la muerte prematura de sus heraldos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repentance", "Arrepentimiento", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is replaced as the final boss of the run. Blasphemy!", "Leshy es sustituido como jefe final de la partida. ¡Blasfemia!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Strike", "Golpe infernal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the two middle slots. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature] solo ataca las cartas de los dos espacios centrales. Si un espacio objetivo está vacío, el daño se dirige al rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalactites", "Estalactitas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every second turn, a random card on the opponent's side will take 5 damage. If this effect kills that card, a Stalactite is created in its place.", "Al comienzo de cada segundo turno, una carta aleatoria del lado rival recibe 5 de daño. Si este efecto la mata, se crea una Estalactita en su lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomber", "Bombardero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card becomes active, it will deal 4 damage to a random card on the opponent's side. if there are no cards to target, it will deal damage directly", "Cuando esta carta se activa, inflige 4 de daño a una carta aleatoria del lado rival. Si no hay cartas a las que apuntar, inflige daño directo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Christian Broadcast", "Emisión cristiana", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Domga", "Dogma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fat", "grasa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "enter the gungeon hardmode", "modo difícil de Enter the Gungeon", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "starvation from inscryption", "la Inanición de Inscryption", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sabs Undersale", "Sabs Undersale", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mother of Harlots", "La Madre de las rameras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wait how did you even get this to evolve", "Espera, ¿cómo has conseguido que esto evolucione?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wait what the fuck??? wasnt beast supposed to gain +1 attack?? what????", "Espera, ¿qué coño??? ¿No se suponía que la Bestia ganaba +1 de ataque?? ¿Qué????", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this isnt going as planned", "Esto no está saliendo según lo previsto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fool. You think I will allow you to skip this battle earlier? Face your sins, you coward!", "Necio. ¿Crees que te permitiré saltarte esta batalla antes de tiempo? ¡Enfréntate a tus pecados, cobarde!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalactite", "Estalactita", Language.Spanish);

        }
    }
    public class FiveNightsAtInscryptionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FiveNightsAtInscryption Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Remnant [c:]to play that creature.", "No tienes suficiente [c:bB]remanente [c:]para jugar esa criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think you can skip this fight?", "¿Crees que puedes saltarte este combate?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think you can skip this fight? Face Me, you coward!", "¿Crees que puedes saltarte este combate? ¡Enfréntate a mí, cobarde!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Deck won't starve just yet...", "Tu mazo aún no se agotará...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome...", "Bienvenido...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry about someone interrupting us...", "No te preocupes por si alguien nos interrumpe...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fnai Achievements", "Logros de FNAI", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Restart", "Reinicio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Restart the game and get rid of the Virus inside of the Game.", "Reinicia el juego y elimina el Virus que contiene.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapfinder's Trick", "El truco del buscador de trampas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try to skip Parts of the fight against the Virus.", "Intenta saltarte partes del combate contra el Virus.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quirky at night", "Rarezas nocturnas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness Animatronics getting quirky at night.", "Presencia cómo los animatrónicos se vuelven extraños por la noche.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antivirus", "Antivirus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat The Virus plagueing the Game.", "Derrota al Virus que asola el juego.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Connection Terminated", "Conexión terminada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set your entire side ablaze.", "Prende fuego a todo tu lado del tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exotic Butters", "Mantequillas exóticas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach the maximum amount of stolen batteries and make Hand unit attack.", "Alcanza el máximo de baterías robadas y haz que ataque el Terminal portátil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Horror", "El Horror", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive the Fight against Springtrap in Fazbears Fright.", "Sobrevive al combate contra Springtrap en Fazbear's Fright.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Found Soul", "Alma encontrada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return the Soul stolen by Glitchtrap to you.", "Recupera el alma que Glitchtrap te robó.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerleech", "Sanguijuela de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain your first Stolen Battery.", "Obtén tu primera Batería robada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Classical", "Clásico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Classic Animatronics.", "Obtén todos los animatrónicos clásicos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refurbished", "Reacondicionado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Toy Animatronics.", "Obtén todos los animatrónicos Toy.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Withered Animatronics.", "Obtén todos los animatrónicos marchitos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Phantom Animatronics.", "Obtén todos los animatrónicos fantasma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nighmarish", "De pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Nightmare Animatronics.", "Obtén todos los animatrónicos de pesadilla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Robots", "Robots asesinos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Funtime Animatronics.", "Obtén todos los animatrónicos Funtime.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Last Remnants", "Los últimos remanentes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all Scrap Animatronics.", "Obtén todos los animatrónicos de chatarra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murderers Legacy", "El legado del asesino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain all of Aftons forms.", "Obtén todas las formas de Afton.", Language.Spanish);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incarnation", "Encarnación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon Death, [creature] will transform into another Card and will be added to your Hand.", "Al morir, [creature] se transforma en otra carta que se añade a tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anger Issues", "Problemas de ira", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will deal 1 damage to every opposing card.", "Al morir, [creature] inflige 1 de daño a cada carta rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby", "Baby", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...A failure to the end.", "... Un fracaso hasta el final.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballora", "Ballora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. She will move differently each time.", "Una creación familiar. Se moverá de forma distinta cada vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloon Boy", "Balloon Boy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An annoyance to the core, it takes that which it doesn't deserve.", "Una molestia hasta la médula que se lleva lo que no merece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bon Bon", "Bon Bon", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnet", "Bonnet", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Jump", "Salto de Bonnie", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to move [creature] to any free Slot on your side.", "Paga 1 de energía para mover a [creature] a cualquier espacio libre de tu lado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie the Bunny", "Bonnie el conejo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The guitarist of the Fazbear Band, constantly mistaken to be purple.", "El guitarrista de la banda Fazbear, al que siempre confunden con uno de color morado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill this abomination, please.", "Mata a esta abominación, por favor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost Soul", "Alma perdida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bucket Bob", "Bucket Bob", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You set him down and nothing happens. Then, something stirs beneath your feet. You feel the energy seep into your hands.", "Lo colocas y no ocurre nada. Entonces algo se agita bajo tus pies. Sientes cómo la energía se filtra en tus manos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will take 1 damage.", "Al final del turno, [creature] recibe 1 de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chica the Chicken", "Chica la gallina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The backup singer of the Fazbear Band, however she is not a duck.", "La corista de la banda Fazbear, aunque no es un pato.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Closeted", "Encerrado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get +2/0 after 2 turns of being unopposed.", "Tras 2 turnos sin una carta enfrente, [creature] obtiene +2/0.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghastly Body", "Cuerpo espectral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start Of Turn: [creature] will loose 1 Health.", "Al final del turno de su propietario, [creature] pierde 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damaged", "Dañado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When struck, [creature] will damage the striker with equal damage.", "Cuando [creature] recibe un golpe, inflige a la fuente del daño, si sobrevive, daño igual a su ataque actual.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo 01", "Endoesqueleto 01", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suitless skeleton. A useless, easily broken husk.", "Un esqueleto sin traje. Una carcasa inútil y frágil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo 02", "Endoesqueleto 02", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suitless skeleton. A more reliable husk.", "Un esqueleto sin traje. Una carcasa más fiable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endo Army", "Ejército de endoesqueletos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will create multiples of itself in every free slot on [creature]'s side.", "Cuando se juega [creature], crea una copia de sí misma en cada espacio libre del lado de [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Remnant", "Sin remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will not give any Remnant.", "Al morir, [creature] no proporciona ningún remanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Converter", "Conversor de remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will convert 2 Energy into 1 Remnant.", "[creature] convierte 2 de energía en 1 de remanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ennard", "Ennard", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stitched together to make one being...that sounds familiar.", "Cosidos para formar un solo ser... Eso me resulta familiar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Union", "Unión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On other Cards Death: [creature] will gain 1 Health.", "Cuando mueren otras cartas, [creature] obtiene 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malhare", "Malhare", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I always come back!", "¡Siempre vuelvo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foxys Hook", "Gancho de Foxy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will move until it reaches something, attacking every opposing slot on its way.", "[creature] se mueve hasta encontrar algo y ataca cada espacio rival a su paso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foxy the Pirate", "Foxy el pirata", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A side attraction, with a fast sprint and a rather deadly hook.", "Una atracción secundaria, con una carrera veloz y un gancho bastante letal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddle", "Freddle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. Tiny sharp-toothed faces grin up at you from the dark.", "Una creación del miedo. Diminutas caras de dientes afilados te sonríen desde la oscuridad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddles", "Freddles", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will spawn 3 Freddles and shuffles them into your side deck.", "Cuando se juega [creature], crea 3 Freddles y los baraja en tu mazo secundario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddy Fazbear", "Freddy Fazbear", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The namesake and leader of the Fazbear Band. The one, the only, Freddy Fazbear!", "El líder que da nombre a la banda Fazbear. ¡El único e inigualable Freddy Fazbear!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freddy Mask", "Máscara de Freddy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reduces all Cards Attack by 1, cannot be used on some Animatronics.", "Reduce en 1 el ataque de todas las cartas. No puede usarse con algunos animatrónicos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... The Mask, it prevents some Animatronics from attacking...", "Mmm... La máscara impide que algunos animatrónicos ataquen...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funtime Foxy", "Funtime Foxy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. Nothing can stand in their way.", "Una creación familiar. Nada puede interponerse en su camino.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funtime Freddy", "Funtime Freddy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar creation. His Companion, Bon Bon, also attacks with him.", "Una creación familiar. Su compañero Bon Bon también ataca con él.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Collector", "Recolector de remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: Gain 1 Remnant.", "Al jugar esta carta, obtienes 1 de remanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Freddy", "Golden Freddy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I don't like the look of this one.", "... No me gusta el aspecto de este.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Unit", "Terminal portátil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see what you were trying to choose and I will auto correct it for you. Thank you for choosing Hand Unit.", "Veo lo que querías elegir y lo corregiré automáticamente. Gracias por elegir el Terminal portátil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Last Will", "Última voluntad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will give you 2 Remnant.", "Al morir, [creature] te da 2 de remanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lefty", "Lefty", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A container for something far more troublesome.", "Un recipiente para algo mucho más problemático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lolbit", "Lolbit", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TECHNICAL DIFFICULTIES. PLEASE STAND BY.", "DIFICULTADES TÉCNICAS. ESPERA, POR FAVOR.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mangle Strafe", "Movimiento de Mangle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the Owners turn a [creature] will move in the Sigil Direction and leave behind a pile of Wire(0/1,Sharp Quills).", "Al final del turno de su propietario, [creature] se mueve en la dirección del sello y deja un montón de cables (0/1, Espinas afiladas).", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimic", "Imitador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minireena", "Minireena", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Molten Freddy", "Molten Freddy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mass of wires lashing out at everything in reach.", "Una masa de cables que golpea todo lo que está a su alcance.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr Can Do", "Mr Can Do", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rusted can with a vacant smile. It doesn't do much, but if you feed it enough power, it coughs up something useful. The process seems... unnatural.", "Una lata oxidada con una sonrisa vacía. No hace mucho, pero si le das suficiente energía, escupe algo útil. El proceso parece... antinatural.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mr Hugs", "Mr Hugs", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A... Vaccuum? It shuffles along, leaving a strange, lingering presence in its wake", "¿Una... aspiradora? Avanza arrastrándose y deja tras de sí una extraña presencia persistente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare", "Pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shadow of terror. It draws power from the fears you hold close to yourself.", "Una sombra de terror. Extrae poder de los miedos que guardas en tu interior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Bonnie", "Bonnie Pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He waits in silence, unmoving. You know he's there, even when you close your Eyes.", "Una creación del miedo. Espera en silencio, inmóvil. Sabes que está ahí incluso cuando cierras los ojos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Chica", "Chica Pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. Her gaping, hollow maw shouldn't be able to open that wide. The Noise she makes is neither human nor mechanical -it's something else entirely.", "Una creación del miedo. Su boca abierta y hueca no debería poder abrirse tanto. El ruido que hace no es humano ni mecánico: es algo completamente distinto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Foxy", "Foxy Pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He lurks just out of sight. The longer you ignore him, the closer he gets. When he strikes, there won't be time to react.", "Una creación del miedo. Acecha justo fuera de tu vista. Cuanto más tiempo lo ignores, más se acercará. Cuando ataque, no habrá tiempo de reaccionar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Fredbear", "Fredbear Pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of terror. It is incredibly sensitive to the sounds of ringing.", "Una creación del terror. Es extremadamente sensible al sonido de las campanas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Freddy", "Freddy Pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creation of fear. He is never alone. His little ones are already waiting for you.", "Una creación del miedo. Nunca está solo. Sus pequeños ya te están esperando.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No1 Crate", "Caja n.º 1", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crate shudders when placed. Whatever's inside shifts, lending its strength to whatever stands beside it. For a price, it does even more.", "La caja tiembla al colocarla. Algo se mueve dentro y presta su fuerza a lo que esté a su lado. Por un precio, hace aún más.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pan Stan", "Pan Stan", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sound of clanging metal echoes long after he falls apart. Yet, teh pieces still radiate something.", "El sonido del metal entrechocando resuena mucho después de que se desmonte. Sin embargo, las piezas siguen irradiando algo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Party Favors", "Regalos de fiesta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] heals cards adjacent to it equal to its Attack.", "Al final de cada turno, [creature] cura 1 a la carta a su izquierda. Si no hay espacio a la izquierda, cura en su lugar a la carta de la derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Chica", "Chica espectral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past. It can interact with this world for mere moments at a time.", "Un vestigio del pasado. Solo puede interactuar con este mundo durante breves momentos cada vez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Foxy", "Foxy espectral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past, its hook is still deadly. But it can only stay for a short time.", "Un vestigio del pasado cuyo gancho sigue siendo letal. Pero solo puede quedarse poco tiempo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Freddy", "Freddy espectral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past, loves to read fanfiction.", "Un vestigio del pasado al que le encanta leer fanfiction.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Mangle", "Mangle espectral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of the past. You can feel the seeping Energy it leaves behind.", "Un vestigio del pasado. Puedes sentir la energía que deja tras de sí filtrándose.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Puppet", "Marioneta espectral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a remnant of the past, it now no longer revives dead souls.", "Un vestigio del pasado que ya no revive a las almas muertas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pop-Pop", "Pop-Pop", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals 1 Damage to all Cards.", "Inflige 1 de daño a todas las cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... a Creature from some Game... It looks like it will blow up soon!", "Mmm... Una criatura de algún juego... ¡Parece que va a explotar pronto!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Surge", "Oleada de remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get +1 Attack for 2 Remnant.", "Consume toda tu energía: [creature] obtiene +1 de ataque por cada grupo completo de 2 puntos de energía gastados, hasta el final del turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Puppet", "La Marioneta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You hear the distant melody of a music box. A sprrpwful presence lingers, its strings pulling at the lost and forgotten... offering them one more chance.", "Oyes la lejana melodía de una caja de música. Una presencia afligida permanece, tirando de los hilos de los perdidos y olvidados... ofreciéndoles otra oportunidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeter", "Titiritero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will draw either Bon Bon or Bonnet.", "Cuando se juega [creature], roba a Bon Bon o a Bonnet.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteers Puppet", "Marioneta del titiritero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will combine with Funtime Freddy On Play.", "Al final del turno del jugador, [creature] se combina con un Funtime Freddy aliado que esté en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Other Card Death: [creature] will ressurect friendly creatures in a weaker state when they perish.", "Cuando muere otra carta, [creature] resucita a las criaturas aliadas que perecen en una forma más débil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rainbow", "Arcoíris", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape key", "Tecla Escape", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will draw a random card.", "[creature] roba una carta aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Drawn: [creature] Chooses a random Strafe Ability as part of the Choreography.", "Al robar [creature], elige al azar una habilidad de movimiento como parte de la coreografía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Drawer", "Robador de remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Play: [creature] will draw a card from your Deck (Draw an additional Card for 2 Remnant).", "Cuando se juega [creature], roba una carta de tu mazo principal. Si tienes más de 2 de remanente, se gastan automáticamente 2 para robar una carta adicional.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Sharer", "Compartir remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will allow you to gain Remnant from your own Cards.", "[creature] te permite obtener remanente de tus propias cartas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Side Drawer", "Robo secundario de remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will draw a card from your Side Deck (Draw an additional Card for 2 Remnant).", "Al morir, [creature] te hace robar una carta de tu mazo secundario. Si tienes más de 2 de remanente, se gastan automáticamente 2 para robar una carta adicional.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remnant Spawner", "Generador de remanente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Death: [creature] will draw itself in exchange for 2 Remnant.", "Al morir, [creature] se roba a sí misma a cambio de 2 de remanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Pc", "PC malo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disables the changes made to the Cabin", "Desactiva los cambios realizados en la cabaña", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scooper", "Recolectora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] has a 1/10 chance to instantly kill the opposing Card.", "Al final del turno, [creature] tiene una probabilidad de 1/10 de matar al instante a la carta de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Baby", "Baby de chatarra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " ...A freakshow. Mind her grasping claw.", "... Un espectáculo de monstruos. Cuidado con su garra prensil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Bonnie", "Bonnie de sombra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Freddy", "Freddy de sombra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Showtime", "Hora del espectáculo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Drawn: [creature] will have its energy cost randomized from 1 - 6.", "Al robar [creature], su coste de energía se convierte en un valor aleatorio de 1 a 6.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul", "Alma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a human being, now only a tool of Remnant and Agony.", "Antes humano, ahora es solo una herramienta del Remanente y la Agonía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Beasts", "escriba de las bestias", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Death", "Escriba de los muertos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Magik", "Escriba de la magia", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrybe of Technology", "escriba de la tecnología", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Springtrap", "Springtrap", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A murderer trapped in his own creation.", "Un asesino atrapado en su propia creación.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Static", "Estática", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] Irritates the Opponent, making it unable to attack.", "Si [creature] está en tu lado y tiene enfrente una carta que no es un Gigante, su propia modificación pasiva de ataque se reduce a cero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffed", "Relleno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dave", "Dave", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... How did this guy get here?", "... ¿Cómo ha llegado aquí este tipo?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Debris", "Escombros en llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Debris of Fazbears Fright", "Escombros en llamas de Fazbear's Fright", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bite", "El mordisco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Take Damage: [creature] will give 1 Remnant.", "Cuando [creature] se inflige daño a sí misma, obtienes 1 de remanente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mangle", "Mangle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He constantly falls apart, but she keeps putting herself back together.", "Él se desmorona constantemente, pero ella sigue recomponiéndose.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toy Bonnie", "Toy Bonnie", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New and Improved' Bonnie. You'll need to charge it to get any use.", "El Bonnie «nuevo y mejorado». Tienes que cargarlo para aprovecharlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ToyChica", "Toy Chica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New and Improved' Chica. It has an excess amount of energy.", "La Chica «nueva y mejorada». Tiene energía de sobra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toy Freddy", "Toy Freddy", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'New And Improved' Freddy. A true xXGamerXx with anger issues.", "El Freddy «nuevo y mejorado». Un auténtico xXGamerXx con problemas de ira.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will capture the opposing Card in itself.", "Al final del turno, [creature] captura en su interior a la carta de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wire Pile", "Montón de cables", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Bonnie", "Bonnie marchito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Bonnie. Erratic, violent, and has a mean punch.", "Una versión deteriorada de Bonnie. Errático, violento y con un golpe contundente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Chica", "Chica marchita", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Chica. Its touch is deadly, due to its exposed wirings. Just as erratic as the others.", "Una versión deteriorada de Chica. Sus cables expuestos hacen que su contacto sea letal. Es tan impredecible como los demás.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Foxy", "Foxy marchito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A broken down version of Foxy. Easily angered, but also spends a good amount of its time roaming. Mind its hook, it's still just as sharp.", "Una versión deteriorada de Foxy. Se enfada con facilidad y pasa mucho tiempo vagando. Cuidado con su gancho, sigue igual de afilado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withered Freddy", "Freddy marchito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " A broken down version of Freddy. It's erratic, and will attack anything that touches it.", " Una versión deteriorada de Freddy. Es errático y ataca todo lo que lo toca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are Number One", "Eres el número uno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Turn End: [creature] will give the Card to its left +1/0 (Additionally: If you have 1 Remnant also give the Card to its right +1/0).", "Al final de cada turno, [creature] da +1/0 a la carta de su izquierda. Si tienes al menos 1 de remanente, consume 1 y también da +1/0 a la carta de su derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Five Nights at Inscryption", "Five Nights at Inscryption", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack contains a bunch of FNAF themed Cards, from Freddy Fazbear to Springtrap.", "Este paquete contiene muchas cartas de FNAF, desde Freddy Fazbear hasta Springtrap.", Language.Spanish);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us enjoy this Fight.", "Disfrutemos de este combate.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]As it will be your last.", "[c:bR]Porque será el último.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see...", "Ya veo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seems like all your cards are turning against you!", "¡Parece que todas tus cartas se vuelven contra ti!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is taking too long.", "Esto está tardando demasiado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, another Victim...", "Por fin, otra víctima...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you seriously think id let you win that easily?", "¿De verdad crees que te dejaré ganar tan fácilmente?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "₮Ⱨł₴ ₩łⱠⱠ ₦Ø₮ ฿Ɇ ⱧØ₩ ł Đł-", "₦Ø VØɎ ₳ MØⱤłⱤ ₳₴-", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have fun being stuck here.", "Diviértete quedándote atrapado aquí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "₩-Ⱨ₳₮ Ⱨ₳-VɆ ɎØɄ ĐØ₦-Ɇ?", "¿Q-ɄÉ Ⱨ₳₴ ⱧɆ-₵ⱧØ?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really think i'd let a moron like you reach the end of the game?", "¿De verdad creías que dejaría que un idiota como tú llegara al final del juego?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha ha! Surprised?", "¡Ja, ja! ¿Sorprendido?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah, did you really think I'd let a moron like you reach the end of the game?", "Sí. ¿De verdad creías que dejaría que un idiota como tú llegara al final del juego?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pshaw!", "¡Bah!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stupid idiotic moron.", "Eres un idiota estúpido y tonto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now, if you'll excuse me, I need a few turns to charge my rainbow cannon.", "Ahora, si me disculpas, necesito unos turnos para cargar mi cañón arcoíris.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah.", "Sí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After that, it'll be game over.", "Después de eso, se acabó el juego.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So sit back and prepare to get rekt!", "¡Así que ponte cómodo y prepárate para que te destrocen!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cheated!", "¡Has hecho trampas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Besides, didn't your mommy ever tell you that you can't kill a rainbow?! ", "Además, ¿tu mami no te dijo nunca que no se puede matar a un arcoíris? ", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next time you see a rainbow in the sky that is me, comin' to your houuusssseee.... ", "La próxima vez que veas un arcoíris en el cielo, seré yo yendo a tu caaaasa.... ", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just 3 minutes left, you moron!", "¡Solo quedan 3 minutos, idiota!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just 2 minutes left, then my rainbow cannon will be ready!", "¡Solo quedan 2 minutos y mi cañón arcoíris estará listo!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 minute left, you stupid idiot!", "¡Queda 1 minuto, idiota estúpido!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare for rainbow overload!!!!", "¡¡¡¡Prepárate para la sobrecarga arcoíris!!!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awww, I'm laughing at you, not with you.", "Oh, me río de ti, no contigo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Um, learn to play?", "Eh... ¿quieres aprender a jugar?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha ha! You suck.", "¡Ja, ja! Eres malísimo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKRUB!", "¡NOOB!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noobie Boobie Noobie!!", "¡Novato, novatillo, novato!!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get some skills and call me in the morning.", "Mejora tus habilidades y llámame mañana por la mañana.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dumba**.", "Idi**a.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So sad it's hilarious.", "Es tan triste que resulta desternillante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! What a moron.", "¡Vaya! Qué idiota.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awwww! It's so cute when kids try to play games!", "¡Oh! ¡Qué mono cuando los niños intentan jugar!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excuse me, is this your first time playing a video game?", "Perdona, ¿es la primera vez que juegas a un videojuego?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello Old Sport", "Hola, viejo amigo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must be the newbie", "Tú debes de ser el novato", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets strangle some kiddens.", "Vamos a estrangular a unos peques.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "with sausages", "con salchichas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How do you like it here at Freddy's?", "¿Qué tal te va aquí en Freddy's?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "wouldn't have done that.", "Yo no habría hecho eso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep me alive.", "Mantenme con vida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...sure.", "... Claro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bullshit!", "¡Tonterías!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Will stran...", "Voy a estran...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well kid,", "Bueno, chico,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a business proposition.", "tengo una propuesta de negocios.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's me.", "Soy yo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still want", "Todavía quiero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to kill some", "matar a unos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "kiddens", "peques", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont sacrifice me!", "¡No me sacrifiques!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ow.", "Ay.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop that.", "Deja eso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouch.", "Ay.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's...", "Es...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "him...", "él...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just defeat him already", "Derrótalo de una vez", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dream big!", "¡Sueña a lo grande!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " Think of better Moss.", " Piensa en un musgo mejor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor", "Qué honor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck.", "Buena suerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck...", "Buena suerte...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck!", "¡Buena suerte!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fingers crossed", "Dedos cruzados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Forever.", "[c:bR]Para siempre.", Language.Spanish);

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Remnant [c:]to use this ability!", "¡No tienes suficiente [c:bB]remanente [c:]para usar esta habilidad!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough [c:bB]Energy [c:]to use this ability!", "¡No tienes suficiente [c:bB]energía [c:]para usar esta habilidad!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing beautiful can last.", "Nada hermoso puede durar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! I'm not ready to die yet.", "¡No! Aún no estoy listo para morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must... still...", "Debo... aún...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shake your hand...", "estrecharte la mano...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough Energy.", "No tienes suficiente energía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may make a new Card for yourself.", "Puedes crear una nueva carta para ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one of these.", "Elige uno de estos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Nothing?", "... ¿Nada?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What would you like to name your Card?", "¿Cómo quieres llamar a tu carta?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card's souls have been transfereed", "Las almas de tus cartas han sido transferidas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will let you swap the souls of 2 cards...", "Te permitiré intercambiar las almas de 2 cartas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you stand in the burning Building, a familiar Figure awaits you...", "Mientras estás en el edificio en llamas, una figura familiar te espera...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He [c:]will not let you go that easily.", "[c:bR]Él [c:]no te dejará ir tan fácilmente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Building appears to fall apart even more now!", "¡Parece que el edificio se derrumba aún más!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He [c:] appears even more angry than before!", "[c:bR]Él [c:]parece aún más enfadado que antes!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone wants to see you...", "Alguien quiere verte...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PowerSink", "Sumidero de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of stolen Batteries on your side.", "El valor representado por este sello equivale al número de Baterías robadas de tu lado.", Language.Spanish);


        }
    }
    public class HallownestExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for HallownestExpansion Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pack of [count] cards based around the broad variety of Hollow Knight enemies.", "Un paquete de [count] cartas basado en la gran variedad de enemigos de Hollow Knight.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dreamshield", "Escudo onírico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Dreamshields are created on each adjacent empty space. [define:HE_Dreamshield]", "Cuando se juega [creature], se crean Escudos oníricos en cada espacio vacío adyacente. [define:HE_Dreamshield]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukedgling", "Duelín", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will evolve into a random Fluke.", "Al final del turno de su propietario, [creature] evoluciona a una duela aleatoria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukenest", "Nido de duelas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] creates a Flukefey on a random empty space on the owner's side. [define:HE_Flukefey]", "Al final del turno de su propietario, [creature] crea una Cría de duela en un espacio vacío aleatorio de su lado. [define:HE_Flukefey]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glowing Womb", "Vientre luminoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, an Aspid Hatchling is created in your hand. An Aspid Hatchling is defined as: Strength In Numbers, 1 Health, Brittle.", "Cuando [creature] recibe un golpe, se crea una Cría de aspid en tu mano. Una Cría de aspid tiene La unión hace la fuerza, 1 de salud y Quebradizo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiveblood", "Sangre de colmena", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] creates a Hiveling on a random empty space on the owner's side. [define:HE_Hiveling]", "Al final del turno de su propietario, [creature] crea una Abejita en un espacio vacío aleatorio de su lado. [define:HE_Hiveling]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeblood Core", "Núcleo de sangre vital", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a Lifeseed is created in your hand. [define:HE_Lifeseed]", "Cuando [creature] recibe un golpe, se crea una Semilla de vida en tu mano. [define:HE_Lifeseed]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Signmaker", "Fabricante de señales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A Signpost is created in the opposing slot, if empty. [define:HE_Signpost]", "Cuando se juega [creature], se crea una Señal en el espacio de enfrente si está vacío. [define:HE_Signpost]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Vengeflies", "Invocar moscavengativas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Vengeflies are created on each adjacent empty space. [define:HE_Vengefly]", "Cuando se juega [creature], se crea una Moscavengativa en cada espacio adyacente vacío. [define:HE_Vengefly]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zoteling Spitter", "Escupidor de pequeños Zote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a random Zoteling is created in the owner's hand.", "Al final del turno de su propietario, se crea un pequeño Zote aleatorio en su mano.", Language.Spanish);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absolute Radiance", "Destello absoluto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abyss Creature", "Criatura del Abismo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this...?", "¿Qué es esto...?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aluba", "Aluba", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive glider that prefers to dwell near acid waters.", "Planeador apacible que prefiere habitar cerca de aguas ácidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambloom", "Ambloom", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple-minded crawling fungus. Its cap is covered in a layer of hardened spikes.", "Hongo reptante de mente sencilla. Su sombrero está cubierto de púas endurecidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armoured Squit", "Squit acorazado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hardened squit, bred for battle in the Colosseum of Fools. Tougher and more aggressive than its wild ancestor.", "Squit endurecido, criado para luchar en el Coliseo de los Insensatos. Es más resistente y agresivo que su antepasado salvaje.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Hatchling", "Cría de aspid", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Hunter", "Aspid cazador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cunning predator that will best its prey by spitting corrosive liquid.", "Astuto depredador que vence a sus presas escupiendo un líquido corrosivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspid Mother", "Madre aspid", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carries the eggs of its young inside its belly. Can hatch and birth its young as needed to deal with intruders.", "Lleva los huevos de sus crías en el vientre. Puede incubarlos y dar a luz cuando necesita defenderse de los intrusos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baldur", "Baldur", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although the shells of these youngsters are not thick enough to protect them from predators, they are still able to defend themselves if pressed.", "Aunque el caparazón de estas crías aún no es lo bastante grueso para protegerlas de los depredadores, saben defenderse si se ven acorraladas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Battle Obble", "Obble de combate", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raised in the Colosseum. Although trained for combat, its movements and attacks are still haphazard.", "Criado en el Coliseo. Aunque ha sido entrenado para luchar, sus movimientos y ataques siguen siendo erráticos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belfly", "Belfly", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thin wings hide a highly volatile belly. Will give its own life to protect its territory.", "Sus finas alas esconden un vientre muy explosivo. Da su vida para proteger su territorio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluggsac", "Bluggsac", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placid but putrid creature. Holds rancid eggs within its gut.", "Criatura plácida pero pútrida, que alberga huevos podridos en sus entrañas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blundering Oberlisk", "Oberlisk torpe", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This placid herbivore doesn't seem to wish harm on any of the creatures it shares a habitat with. However, its careless nature and bulky weight sometimes leads to messy accidents.", "Este apacible herbívoro no parece querer dañar a las criaturas con las que comparte hábitat. Sin embargo, su descuido y su enorme peso causan a veces aparatosos accidentes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boofly", "Boofly", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Large, docile creature that peacefully buzzes around in the caverns of Kingdom's Edge.", "Gran criatura dócil que zumba apaciblemente por las cavernas de los confines del reino.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Vessel", "Receptáculo roto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shattered corpse, reanimated by infected parasites.", "Cadáver destrozado, reanimado por parásitos infectados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brooding Mawlek", "Mawlek atormentado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ferocious but extremely social creature. Becomes aggressive if not able to mingle with its own kind.", "Criatura feroz pero muy sociable. Se vuelve agresiva si no puede relacionarse con los de su especie.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carver Hatcher", "Incubador de excavatierra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying creature that fires out dirtcarvers from its body when potential prey comes close.", "Criatura voladora que expulsa excavatierra de su cuerpo cuando se acerca una posible presa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charged Lumaflies", "Lumoscas cargadas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swarm of tiny, glowing insects. When threatened they cluster together, generating electricity.", "Un enjambre de diminutos insectos luminosos. Cuando se sienten amenazados se agrupan y generan electricidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hornhead?", "Carcasa cornuda?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Uses its horn to attack any uninfected creature it finds.", "Los restos de un insecto animados por una fuerza extraña. Usa su cuerno para atacar a toda criatura no infectada que encuentra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wandering Husk?", "Carcasa errante?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force, wandering around aimlessly.", "Los restos de un insecto animados por una fuerza extraña vagan sin rumbo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Husk", "Carcasa cobarde", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Although made aggressive by the force inside, old instincts still occasionally compel it to run from danger.", "Antiguo miembro de la alta sociedad de Hallownest. Aunque la fuerza que alberga lo vuelve agresivo, sus viejos instintos aún lo llevan a veces a huir del peligro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crawlid", "Crawlid", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid scavenger that crawls through the caverns looking for food.", "Carroñero tímido que se arrastra por las cavernas en busca de comida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Cluster", "Racimo de cristales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Crawler", "Reptador de cristal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discharges searing beams of light from the crystals on its back as it crawls around, seemingly unaware.", "Mientras se arrastra, emite haces de luz abrasadora desde los cristales de su espalda, aparentemente sin darse cuenta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Guardian", "Guardián de cristal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavyset miner of the Crystal Peak overcome by crystal growth. Can discharge blazing beams of light from its crystallised limbs.", "Robusto minero de la Cumbre de Cristal, dominado por el crecimiento de los cristales. Puede emitir haces de luz ardiente desde sus extremidades cristalizadas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Hunter", "Cazador de cristal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, airborne insect with its abdomen overgrown with crystals. Fires shards of fast-growing crystal at intruders.", "Pequeño insecto volador cuyo abdomen está cubierto de cristales. Dispara fragmentos de cristal de rápido crecimiento a los intrusos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystallised Husk", "Carcasa cristalizada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remains of a bug who died amongst the crystals. Animated by a strange force, it attacks by firing beams of light from its crystallised arms.", "Restos de un insecto que murió entre los cristales. Animado por una fuerza extraña, ataca disparando haces de luz desde sus brazos cristalizados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Loodle", "Loodle mortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loodle equipped with a helmet and taught to kill.", "Loodle equipado con un casco y adiestrado para matar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deephunter", "Cazador de las profundidades", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crawls along walls and roofs, spitting burning venom at anything that passes by.", "Se arrastra por paredes y techos y escupe veneno ardiente a todo lo que pasa cerca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deepling", "Cría de las profundidades", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infant of the Deepnest. Scuttles about in the darkness, learning the layout of its home.", "Cría de Nido Profundo. Corretea en la oscuridad mientras aprende a orientarse en su hogar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dirtcarver", "Excavatierra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swarming predator of the Deepnest. Burrows through the ground and bursts out to surprise prey.", "Depredador gregario de Nido Profundo. Excava bajo tierra y emerge de repente para sorprender a sus presas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dung Defender", "Defensor del estiércol", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled combatant living at the heart of the Waterways. Assails intruders with balls of compacted dung.", "Hábil combatiente que vive en el corazón de los Canales. Ataca a los intrusos con bolas de estiércol compactado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Duranda", "Duranda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple flying creature protected by a spikey shell.", "Sencilla criatura voladora protegida por un caparazón espinoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Durandoo", "Durandoo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simple walking creature encased in a hard shell. Often found wading in shallow pools of acidic water.", "Sencilla criatura terrestre encerrada en un caparazón duro. Suele vadear charcas poco profundas de agua ácida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Baldur", "Baldur anciano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bulky and covered in thick plating. Retracts into itself when attacked.", "Corpulento y cubierto por una gruesa armadura. Se retrae cuando lo atacan.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Hu", "Anciano Hu", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Travelled the world tending to those affected by the plague.", "Sueño persistente de un guerrero caído. Recorrió el mundo cuidando a quienes padecían la plaga.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Guardian", "Guardián enfurecido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entombed Husk", "Carcasa sepultada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummified remains, deformed and enraged by infection.", "Restos momificados, deformados y enfurecidos por la infección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Failed Champion", "Campeón fallido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "False Knight", "Falso caballero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A maggot driven mad by a strange force. Inhabits a stolen armoured shell.", "Larva de mosca enloquecida por una fuerza extraña. Habita un caparazón blindado robado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukefey", "Cría de duela", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Youngest of its species. Its body is composed of teeth, wings and stomach.", "El más joven de su especie. Su cuerpo se compone de dientes, alas y estómago.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fluke Larva", "Larva de duela", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gla gla... Grow and grow... Nice and wet...", "Gla gla... Crecer y crecer... Qué húmedo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemarm", "Madre de las duelas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An insatiable breeder. Has populated the Waterways with its kind. Its insides double as a nest for young Flukefeys.", "Progenitora insaciable que ha poblado los Canales con los de su especie. Sus entrañas también sirven de nido a las Crías de duela.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon", "Duelamón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worm-like creature that prefers damp, dark habitats.", "Criatura parecida a un gusano que prefiere los lugares húmedos y oscuros.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon's Body", "Cuerpo del Duelamón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemon's Head", "Cabeza del Duelamón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flukemunga", "Duela voraz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aged fluke, grown fat on the rich refuse found in the pipes below the capital.", "Duela anciana, engordada con los abundantes desechos de las tuberías bajo la capital.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fluke Zoteling", "Pequeño Zote duela", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Folly", "Necedad", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a highly intelligent bug, inflated by the misuse of soul.", "Antaño un insecto muy inteligente, hinchado por el mal uso del alma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fool Eater", "Devorador de insensatos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnivorous plant that snaps at any creature that comes close.", "Planta carnívora que muerde a cualquier criatura que se acerque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungified Husk", "Carcasa fúngica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, consumed by a fungus. Frequently releases clouds of thick, deadly gas.", "Restos de un insecto consumidos por un hongo. Suelen liberar nubes de gas denso y mortal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungling", "Honguito flotante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive fungal balloon. Internal gasses cause it to float.", "Globo fúngico apacible. Los gases de su interior lo mantienen a flote.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungoon", "Hongo flotante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully grown fungal balloon. Spits built up internal gas at aggressors.", "Globo fúngico adulto. Escupe el gas acumulado en su interior a sus agresores.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furious Vengefly", "Moscavengativa furiosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly whose body has been distorted by continued infection. Highly aggressive.", "Moscavengativa cuyo cuerpo ha sido deformado por una infección persistente. Muy agresiva.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Galien", "Galien", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Trained in the wilds bordering the kingdom, hoping to become a Knight.", "Sueño persistente de un guerrero caído. Entrenó en las tierras salvajes que bordean el reino con la esperanza de convertirse en caballero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Garpede", "Garpede", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant burrower covered in thick shell plates. Tirelessly travels the tunnels of the Deepnest.", "Excavador gigante cubierto de gruesas placas de caparazón. Recorre incansablemente los túneles de Nido Profundo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Cloud", "Nube de gas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Geo Deposit", "Yacimiento de Geo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glimback", "Glimback", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slow, hardy creature. The crystals that grow on its back provide extra protection from foes above.", "Criatura lenta y resistente. Los cristales que crecen en su espalda le dan protección adicional frente a enemigos situados por encima.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Husk", "Carcasa glotona", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Uses its corpulent body as a weapon.", "Antiguo miembro de la alta sociedad de Hallownest. Usa su corpulento cuerpo como arma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goam", "Goam", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thickly armoured, it bursts from the ground to seize prey in its fangs.", "Cubierto de una gruesa armadura, emerge del suelo para atrapar a sus presas con sus colmillos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Beast", "Bestia divina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Tamer", "Domadora divina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Veteran warrior of the Colosseum of Fools. Fights by the side of creatures she has trained.", "Guerrera veterana del Coliseo de los Insensatos. Lucha junto a las criaturas que ha adiestrado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorb", "Gorb", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. A mysterious life-form that claimed to contain all of the world's knowledge inside of its distended brain.", "Sueño persistente de un guerrero caído. Esta misteriosa forma de vida afirmaba contener todo el conocimiento del mundo en su cerebro hinchado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorgeous Husk", "Carcasa magnífica", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpulent Husk encrusted with a shining metal. Retains the instinct to hoard Geo.", "Carcasa corpulenta incrustada de metal brillante. Conserva el instinto de acumular Geo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Hopper", "Saltador gigante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaps around the edge of the world, trying to crush prey beneath its body.", "Salta por los confines del mundo intentando aplastar a sus presas bajo su cuerpo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Husk Sentry", "Gran centinela carcasa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a Great Sentry, the most elite of the city's guards. Wields a greatnail and shell. Its powerful attacks cause heavy damage.", "Restos animados de un gran centinela, la élite de la guardia de la ciudad. Empuña un gran clavo y un caparazón; sus poderosos ataques causan mucho daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystery Jar", "Frasco misterioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Nailsage Sly", "Gran sabio del clavo Sly", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legendary sage of the nail arts and, recently, merchant of some success.", "Sabio legendario de las artes del clavo y, desde hace poco, comerciante de cierto éxito.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grey Prince Zote", "Príncipe gris Zote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimm", "Grimm", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Master", "Maestro de la compañía Grimm", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerful and devoted member of the Grimm Troupe.", "Poderoso y devoto miembro de la compañía Grimm.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Nightmare", "Pesadilla de la compañía Grimm", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying member of the Grimm Troupe.", "Terrorífico miembro de la compañía Grimm.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimmkin Novice", "Novato de la compañía Grimm", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Young and playful member of the Grimm Troupe.", "Joven y juguetón miembro de la compañía Grimm.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub", "Larva", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little creature, separated from its family. Do you have the courage to sacrifice it?", "Pobre criaturita, separada de su familia. ¿Tienes el valor de sacrificarla?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub?", "Larva?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruz Mother", "Madre Gruz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mature gruzzer that carries its young in its belly. Attacks by hurling its huge body around.", "Gruzzer adulto que lleva a sus crías en el vientre. Ataca lanzando su enorme cuerpo de un lado a otro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruzzer", "Gruzzer", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gulka", "Gulka", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggressive plant-life that retracts protectively when danger is near and spits hard spikey balls when foes are at a distance.", "Planta agresiva que se retrae para protegerse cuando se acerca el peligro y escupe duras bolas con púas a los enemigos lejanos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Spirit", "Espíritu atormentado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of Zote", "Cabeza de Zote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Fool", "Insensato pesado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Aggressively charges down foes.", "Guerrero que lucha por la gloria en el Coliseo de los Insensatos. Carga ferozmente contra sus enemigos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Sentry", "Centinela pesado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a large Hallownest Sentry. One of few in Hallownest strong enough to wield a greatnail.", "Restos animados de un gran centinela de Hallownest. Es uno de los pocos en el reino con fuerza suficiente para empuñar un gran clavo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heavy Zoteling", "Pequeño Zote pesado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Guardian", "Guardián de la colmena", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protects the Hive by hurling its huge body at intruders.", "Protege la colmena lanzando su enorme cuerpo contra los intrusos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Knight", "Caballero de la colmena", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyal protector of the Hive's Queen. Flightless but ferocious in battle.", "Fiel protector de la reina de la colmena. No puede volar, pero es feroz en combate.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiveling", "Abejita", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hive Soldier", "Soldado de la colmena", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defends the Hive against intruders with its extendable stinger.", "Defiende la colmena de los intrusos con su aguijón extensible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Knight", "Hollow Knight", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully grown Vessel, carrying the plague's heart within its body.", "Receptáculo adulto que lleva el corazón de la plaga en su cuerpo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopper", "Saltador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaps at prey and uses its sharp proboscis to drain vital fluids.", "Salta sobre sus presas y usa su afilada probóscide para absorber sus fluidos vitales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopping Zoteling", "Pequeño Zote saltarín", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hornet", "Avispón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled protector of Hallownest's ruins. Wields a needle and thread.", "Hábil protectora de las ruinas de Hallownest. Empuña aguja e hilo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hornet Sentinel", "Avispón centinela", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Bully", "Carcasa matona", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. It aggressively attacks any uninfected creature it finds.", "Los restos de un insecto animados por una fuerza extraña. Ataca con agresividad a toda criatura no infectada que encuentra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Dandy", "Carcasa dandi", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Former member of Hallownest's high society. Limited offensive ability.", "Antiguo miembro de la alta sociedad de Hallownest. Su capacidad ofensiva es limitada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Guard", "Guardia carcasa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a great Hallownest Crossguard, animated by a strange force. Instinct still drives it to guard its post against intruders.", "Restos de un gran guardia cruzado de Hallownest animados por una fuerza extraña. El instinto aún lo impulsa a defender su puesto de los intrusos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hive", "Carcasa colmena", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly husk, its body colonised by hivelings.", "Carcasa cobarde cuyo cuerpo ha sido colonizado por Abejitas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Hornhead", "Carcasa cornuda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Uses its horn to attack any uninfected creature it finds.", "Los restos de un insecto animados por una fuerza extraña. Usa su cuerno para atacar a toda criatura no infectada que encuentra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Miner", "Minero carcasa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remains of a bug drawn to the Crystal Peak for its precious crystal. Its claw-pick now doubles as a fierce weapon.", "Restos de un insecto atraído a la Cumbre de Cristal por sus preciosos cristales. Su pico en forma de garra también sirve ahora como arma feroz.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Sentry", "Centinela carcasa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animated remains of a Hallownest Sentry. Still retains some memory of its former task.", "Restos animados de un centinela de Hallownest. Aún conserva algún recuerdo de su antigua tarea.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Husk Warrior", "Guerrero carcasa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. Wields a nail and shell.", "Los restos de un insecto animados por una fuerza extraña. Empuña un clavo y un caparazón.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hwurmp", "Hwurmp", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiny and placid but swells to enormous size when threatened.", "Diminuto y apacible, se hincha hasta alcanzar un tamaño enorme cuando se siente amenazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infected Balloon", "Globo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infected Pustule", "Pústula infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kingsmould", "Molde real", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guard construct of Hallownest's Palace and skilled wielder of the curved claw-blade. Its heavy white armour protects a fragile body.", "Constructo guardián del palacio de Hallownest, diestro con la hoja curva en forma de garra. Su pesada armadura blanca protege un cuerpo frágil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lance Sentry", "Centinela lancero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Sentry of Hallownest equipped with a nail-lance. Charges at threats or throws its lance from a distance.", "Centinela alado de Hallownest equipado con una lanza-clavo. Carga contra las amenazas o arroja su lanza desde lejos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lanky Zoteling", "Pequeño Zote larguirucho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaping Husk", "Carcasa saltarina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force. It will instinctively leap at uninfected creatures to attack them.", "Los restos de un insecto animados por una fuerza extraña. Saltan instintivamente sobre las criaturas no infectadas para atacarlas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mawlek", "Mawlek joven", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacks by spitting acid and slashing with foreclaws.", "Ataca escupiendo ácido y asestando zarpazos con sus garras delanteras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeblood Coccoon", "Capullo de sangre vital", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Contains a living core that bleeds precious lifeblood.", "Contiene un núcleo vivo que sangra la preciada sangre vital.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifeseed", "Semilla de vida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small scuttling seed filled with Lifeblood, which can be extracted and consumed for its healthful properties.", "Pequeña semilla correteadora llena de sangre vital, que se puede extraer y consumir por sus propiedades saludables.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lightseed", "Semilla luminosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A single-celled organism, completely infected. Scurries about simple-mindedly.", "Organismo unicelular completamente infectado. Corretea de un lado a otro sin pensar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little Weaver", "Pequeña tejedora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nimble spider that traverses its domain on thin strands of web. Often waits in ambush.", "Araña ágil que recorre su territorio por finos hilos de telaraña. Suele esperar en una emboscada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loodle", "Loodle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inhabits the wilds beside the Queen's Gardens. Not aggressive in nature, but its wild bouncing behaviour can be dangerous.", "Habita las tierras salvajes junto a los Jardines de la Reina. No es agresivo por naturaleza, pero sus saltos descontrolados pueden ser peligrosos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost Kin", "Pariente perdido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mace Bug", "Insecto maza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What the bug doin'?", "¿Qué hace ese bicho?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Lord", "Señor mantis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leader of the Mantis tribe and its finest warrior. Bears a thin nail-lance and attacks with blinding speed.", "Líder de la tribu de las mantis y su mejor guerrero. Porta una fina lanza-clavo y ataca a una velocidad deslumbrante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Lords", "Señores mantis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Petra", "Mantis Petra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lurks amongst foliage and attacks by flinging wind-scythes from a distance.", "Acecha entre el follaje y ataca desde lejos lanzando hoces de viento.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Traitor", "Mantis traidora", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a member of the Mantis tribe, now cast out and driven mad by infection.", "Antiguo miembro de la tribu de las mantis, ahora expulsado y enloquecido por la infección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Warrior", "Guerrero mantis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of a proud tribe, fiercely protective of its territory. Launches savage attacks with bladed forelimbs.", "Miembro de una orgullosa tribu que protege ferozmente su territorio. Lanza ataques salvajes con sus afiladas extremidades delanteras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mantis Youth", "Mantis joven", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of a proud tribe, fiercely protective of its territory. Launches stinging attacks with its needle sharp abdomen.", "Miembro de una orgullosa tribu que protege ferozmente su territorio. Ataca con su abdomen afilado como una aguja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Markoth", "Markoth", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Only member of his forgotten tribe to take up a weapon.", "Sueño persistente de un guerrero caído. Fue el único miembro de su tribu olvidada que empuñó un arma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marmu", "Marmu", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Protector of the Queen's Gardens.", "Sueño persistente de un guerrero caído. Protector de los Jardines de la Reina.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maskfly", "Mosca enmascarada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Massive Moss Charger", "Enorme emboscador musgoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Family of creatures that have learnt to bulk up with moss and live as one.", "Familia de criaturas que han aprendido a aumentar su tamaño con musgo y vivir como una sola.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawlurk", "Mawlurk", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Large, immobile creature. Wildly spits venom when intruders pass by.", "Gran criatura inmóvil. Escupe veneno con furia cuando pasan intrusos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Menderbug", "Insecto reparador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Member of an elusive guild of bugs fixated on the maintenance of Hallownest's many signs and wayposts.", "Miembro de un escurridizo gremio de insectos dedicado al mantenimiento de las numerosas señales e indicadores de Hallownest.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minigun Aspid", "Aspid ametrallador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mistake", "Error", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a highly intelligent bug, deformed by the misuse of soul.", "Antaño un insecto muy inteligente, deformado por el mal uso del alma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moss Charger", "Emboscador musgoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid creature that frightens away intruders by covering itself in huge clumps of moss.", "Criatura tímida que ahuyenta a los intrusos cubriéndose de enormes matas de musgo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosscreep", "Reptador musgoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakling that covers itself in leaves to appear larger and hides amongst the undergrowth.", "Criatura débil que se cubre de hojas para parecer más grande y se esconde entre la maleza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mossfly", "Mosca musgosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged weakling that covers itself in leaves to appear larger. Hides amongst the undergrowth, fleeing if predators draw near.", "Débil criatura alada que se cubre de hojas para parecer más grande. Se esconde entre la maleza y huye si se acercan depredadores.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosskin", "Musgoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plant-like bug that charges at foes when close.", "Insecto con aspecto de planta que carga contra los enemigos cuando se acercan.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moss Knight", "Caballero musgoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector of the Greenpath, trained in the ways of the Nail and the Shell.", "Protector del Sendero Verde, adiestrado en las artes del clavo y el caparazón.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mossy Vagabond", "Vagabundo musgoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy, portly Mosskin. Easily swayed by others.", "Musgoso perezoso y rechoncho. Los demás lo convencen con facilidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nailmaster Mato", "Maestro del clavo Mato", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nailmaster Oro", "Maestro del clavo Oro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the brothers of the nail, trained in combat by the Great Nailsage.", "Uno de los hermanos del clavo, adiestrado en combate por el gran sabio del clavo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare King Grimm", "Grimm, rey de las pesadillas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Eyes", "Sin ojos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight?", "El Caballero?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An enigmatic wanderer who descends into Hallownest carrying only a broken nail to fend off foes.", "Enigmático viajero que desciende a Hallownest con un clavo roto como única defensa contra sus enemigos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obble", "Obble", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fat, slow, flying bug. Frequently discharges the acidic liquid stored in its round body.", "Insecto volador gordo y lento. Expulsa con frecuencia el líquido ácido almacenado en su cuerpo redondo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obblobble", "Obblobble", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Larger cousin of the Obble. Pairs with a mate for life and will never leave its side.", "Pariente más grande del Obble. Se empareja de por vida y nunca se separa de su pareja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ooma", "Ooma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Passive outer being protecting an aggressive, explosive core.", "Ser exterior apacible que protege un núcleo agresivo y explosivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paintmaster Sheo", "Maestro pintor Sheo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skilled and respected master of the nail. Always eager to learn new things.", "Hábil y respetado maestro del clavo. Siempre está deseoso de aprender cosas nuevas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pale Lurker", "Acechador pálido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten champion of the Colosseum, drawn away by strange obsessions.", "Campeón olvidado del Coliseo, apartado de su camino por extrañas obsesiones.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pilflip", "Pilflip", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Odd creature that adapts to changing situations by flipping over and using the limbs on the other side of its body.", "Extraña criatura que se adapta a las situaciones cambiantes dándose la vuelta y usando las extremidades del otro lado de su cuerpo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primal Aspid", "Aspid primitivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilder, ancestral form of the Aspid. Once thought extinct, they have reappeared at the edges of the world.", "Forma ancestral y más salvaje del aspid. Se creía extinta, pero ha reaparecido en los confines del mundo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pure Vessel", "Receptáculo puro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pustulent Scholar", "Erudito pustuloso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Twister overgrown by infection...", "Tuercealmas invadido por la infección...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Radiance", "Destello", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The light, forgotten.", "La luz, olvidada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancid Egg", "Huevo podrido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revek", "Revek", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. The protector of the Spirits' Glade.", "Sueño persistente de un guerrero caído. El protector del Claro de los Espíritus.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Retainers", "Sirvientes reales", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shade", "Sombra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Creeper", "Reptador sombrío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Found only in deep, dark places. Has never been observed to eat or drink anything.", "Solo habita en lugares profundos y oscuros. Nunca se lo ha visto comer ni beber.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shardmite", "Ácaro cristalino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeds on crystal dust and uses crystallised spines to protect itself from danger.", "Se alimenta de polvo de cristal y usa sus espinas cristalizadas para protegerse del peligro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Baldur", "Baldur espinoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hardened baldur, bred for battle in the Colosseum of Fools. Tougher and more aggressive than its wild ancestor.", "Baldur endurecido, criado para luchar en el Coliseo de los Insensatos. Es más resistente y agresivo que su antepasado salvaje.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shielded Fool", "Insensato con escudo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Warily approaches opponents with shell held high.", "Guerrero que lucha por la gloria en el Coliseo de los Insensatos. Se acerca con cautela a sus rivales con el caparazón en alto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumal Ogre", "Ogro fúngico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huge fungal creature that attacks by spitting corrosive venom and slamming its body into foes.", "Enorme criatura fúngica que ataca escupiendo veneno corrosivo y embistiendo a sus enemigos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumal Warrior", "Guerrero fúngico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fungal creature that attacks intruders to protect its young.", "Criatura fúngica que ataca a los intrusos para proteger a sus crías.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shrumeling", "Honguito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siblings", "Hermanos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragments of a lingering will.", "Fragmentos de una voluntad persistente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Signpost", "Señal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sisters of Battle", "Hermanas de batalla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slobbering Husk", "Carcasa babeante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The body of a bug, completely consumed by infection. Spits corrosive liquid.", "Cuerpo de un insecto consumido por completo por la infección. Escupe líquido corrosivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Master", "Maestro de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head of the Soul Sanctum. Hoarded soul hoping to stave off Hallownest's affliction, but eventually became intoxicated by its power.", "Líder del Santuario de Almas. Acumuló alma con la esperanza de frenar la aflicción de Hallownest, pero terminó embriagado por su poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Twister", "Tuercealmas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly intelligent bug that uses arcane knowledge to twist soul into vicious spells.", "Insecto muy inteligente que usa conocimientos arcanos para convertir el alma en hechizos feroces.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Tyrant", "Tirano de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Warrior", "Guerrero de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Learned bug, wielding a refined pinblade. Enhances its combat prowess with harvested soul.", "Insecto erudito que empuña una refinada hoja de aguja. Mejora su destreza en combate con el alma recolectada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiky Trap", "Trampa de púas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinning Scythe", "Guadaña giratoria", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Husk", "Carcasa espinosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overgrown with vegetation, it attacks by firing sharp spines from its body.", "Cubierta de vegetación, ataca disparando espinas afiladas desde su cuerpo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporg", "Sporg", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A living fungus that detects nearby movement and fires out explosive spores that drift towards their target.", "Hongo vivo que detecta movimientos cercanos y dispara esporas explosivas que flotan hacia su objetivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squit", "Squit", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying bug that charges at prey with its needle-like proboscis.", "Insecto volador que carga contra sus presas con su probóscide en forma de aguja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalking Devout", "Devoto acechante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worshipper of Herrah the Beast. Shields itself with hard plated foreclaws, then lashes out suddenly to cut down prey.", "Adorador de Herrah la Bestia. Se protege con sus garras delanteras acorazadas y luego arremete de repente para abatir a su presa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sturdy Fool", "Insensato robusto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Uses crescent-shaped blades to cut down foes.", "Guerrero que lucha por la gloria en el Coliseo de los Insensatos. Abate a sus enemigos con hojas en forma de media luna.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Collector", "El Coleccionista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark figure locked inside the Tower of Love. Preserves Hallownest's creatures in glass jars with particular attention given to Grubs.", "Figura oscura encerrada en la Torre del Amor. Conserva las criaturas de Hallownest en frascos de cristal y presta especial atención a las Larvas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Collector", "El Gran Coleccionista", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Knight", "El Caballero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktik", "Tiktik", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiky, tenacious little bug that climbs all over the place using its pointed feet.", "Pequeño insecto espinoso y tenaz que trepa por todas partes con sus pies puntiagudos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traitor Lord", "Señor traidor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deposed Lord of the Mantis tribe. Embraced the infection and turned against his sisters.", "Señor depuesto de la tribu de las mantis. Abrazó la infección y se volvió contra sus hermanas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpse Creeper", "Reptador de cadáveres", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grub Mimic", "Imitador de larva", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosk", "Nosk", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuk", "Tuk", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The water brings everything you wish for... You just need to find it.", "El agua trae todo lo que deseas... Solo tienes que encontrarlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turret Zoteling", "Pequeño Zote torreta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uoma", "Uoma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smallest Jelly form. Passive and unaware, but pulsing with a dangerous electric charge.", "La forma de medusa más pequeña. Pasiva e inconsciente, pero palpitante con una peligrosa carga eléctrica.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uumuu", "Uumuu", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intelligent being that guards the inner chamber of the Teacher's Archives.", "Ser inteligente que protege la cámara interior de los Archivos de la Maestra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly", "Moscavengativa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengefly King", "Rey de las moscavengativas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patriarch of a vengefly colony. Swoops at intruders and cries out for reinforcements if threatened.", "Patriarca de una colonia de moscavengativas. Se abalanza sobre los intrusos y pide refuerzos si se siente amenazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violent Husk", "Carcasa violenta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maddened by massive infection. Charges at enemies with no thought for its own preservation.", "Enloquecida por una infección grave. Carga contra sus enemigos sin preocuparse por su propia supervivencia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Focus", "Vacío concentrado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Void... Power... Without unity...", "...Vacío... Poder... Sin unidad...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Form", "Vacío encarnado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Given Mind", "Vacío dotado de mente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Tendrils", "Tentáculos del vacío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragments of void taking the shape of sharp, thrashing tendrils.", "Fragmentos del vacío que adoptan la forma de tentáculos afilados que se agitan con violencia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Gruzzer", "Gruzzer explosivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gruzzer swollen with infection and primed to burst.", "Gruzzer hinchado por la infección y a punto de estallar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Mosskin", "Musgoso explosivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plant-like bug swollen with infection. Releases deadly gas when threatened.", "Insecto con aspecto de planta, hinchado por la infección. Libera gas letal cuando se siente amenazado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volatile Zoteling", "Pequeño Zote explosivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Volt Twister", "Tuercevoltios", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Learned bug that adapted the teachings of the Soul Sanctum into a deadly fighting art. Attacks with bursts of electricity.", "Insecto erudito que adaptó las enseñanzas del Santuario de Almas para convertirlas en un arte de combate letal. Ataca con descargas eléctricas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wandering Husk", "Carcasa errante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remains of a bug, animated by a strange force, wandering around aimlessly.", "Los restos de un insecto animados por una fuerza extraña vagan sin rumbo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watcher Knight", "Caballero vigilante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discarded shell of a Watcher Knight, re-animated by a swarm of infected flies.", "Caparazón abandonado de un caballero vigilante, reanimado por un enjambre de moscas infectadas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Defender", "Defensor blanco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Fool", "Insensato alado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior fighting for glory in the Colosseum of Fools. Flies just out of an opponent's reach then darts in for the kill.", "Guerrero que lucha por la gloria en el Coliseo de los Insensatos. Vuela justo fuera del alcance del rival y luego se lanza a rematarlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Nosk", "Nosk alado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Sentry", "Centinela alado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying sentry of Hallownest. Patrols the heights of the vast cavern in which the city was built.", "Centinela volador de Hallownest. Patrulla las alturas de la vasta caverna donde se construyó la ciudad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winged Zoteling", "Pequeño Zote alado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wingmould", "Molde alado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fly-like construct formed of white shell and a dark liquid interior.", "Constructo parecido a una mosca, formado por un caparazón blanco y un líquido oscuro en su interior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xero", "Xero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Executed for crimes against the King.", "Sueño persistente de un guerrero caído. Fue ejecutado por crímenes contra el rey.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zote's Curse", "Maldición de Zote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zote", "Zote", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A self-proclaimed Knight, of no renown. Wields a nail he carved from shellwood, named 'Life Ender.'", "Caballero autoproclamado sin fama alguna. Empuña un clavo tallado en madera de caparazón al que llamó «Fin de vidas».", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering dream of a fallen warrior. Disappeared during the plague.", "Sueño persistente de un guerrero caído. Desapareció durante la plaga.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying predator that pursues its prey relentlessly.", "Depredador volador que persigue a su presa sin descanso.", Language.Spanish);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you", "¿Por qué vienes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "bothering me for?", "a molestarme?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you want,", "¿Qué quieres,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cur?", "miserable?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another fool", "Otro insensato", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to be cut down", "que será abatido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "by Life Ender...", "por Fin de vidas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fear not, cur...", "No temas, miserable...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your death", "Tu muerte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "will be swift.", "será rápida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Umph!", "¡Uf!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pfah!", "¡Bah!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're only dulling", "¡Solo consigues embotar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "your mandibles!", "tus mandíbulas!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You almost struck me!", "¡Casi me das!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this kingdom", "¿Este reino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trying to mock me?", "pretende burlarse de mí?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.", "Hum.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being overly devoted", "Una dedicación excesiva", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to one's duties", "a los propios deberes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "is no virtue.", "no es una virtud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you doing,", "¿Qué estás haciendo,", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you clumsy", "torpe", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "little oaf?!", "pedazo de idiota?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The air is foul", "El aire es fétido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and the townsfolk", "y los habitantes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "have beady eyes.", "tienen ojos de comadreja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How miserable,", "Qué desdicha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "to be stuck here", "quedar atrapado aquí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "instead of continuing", "en lugar de continuar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my quest...", "mi misión...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How ghastly...", "Qué horror...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what do you", "¿Qué crees", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "think you're doing?!", "que estás haciendo?!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't have time", "¡No tengo tiempo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for your adulation!", "para tus adulaciones!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm a Knight.", "Soy un Caballero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not interested", "No me interesan", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in your", "tus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "childish games.", "juegos infantiles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you lost", "¿Te has perdido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "in these dark tunnels?", "en estos túneles oscuros?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, yes!", "¡Sí, sí!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All glory to me!", "¡Toda la gloria para mí!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll kill", "¡Mataré", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a thousand more!", "a otros mil!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tremble before me!", "¡Tiembla ante mí!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doing, you clumsy", "haciendo, torpe", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "little oaf?!", "pedazo de idiota?!", Language.Spanish);

        }
    }
