    public class SideDeckSelectorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Side_Deck_Selector Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a squirrel that can block fliers", "Una ardilla capaz de bloquear a las criaturas voladoras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "Zángano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For when you need just one point of damage", "Para cuando solo necesites un punto de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Drone", "Hormiga macho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "Zángano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not much, but it's an ant.", "No es gran cosa, pero es una hormiga.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppy", "Cachorro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This energetic little puppy will dig up a fresh bone every turn", "Este enérgico cachorro desentierra un hueso fresco en cada turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spare Tentacle", "Tentáculo de repuesto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen that [c:bR]thing[c:] before, but I can tell there are no bones in it.", "Nunca había visto esa [c:bR]cosa[c:], pero sé que no tiene huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One-Eyed Goat", "Cabra tuerta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This goat generates additional blood...for a price", "Esta cabra genera sangre adicional... a cambio de un precio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't realize this thing came from eggs", "No sabía que esta cosa saliera de huevos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emptier Vessel", "Receptáculo aún más vacío", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here you may replace the creatures in your [c:bR]side deck[c:]", "Aquí puedes sustituir las criaturas de tu [c:bR]mazo secundario[c:].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Second Chance", "Segunda oportunidad del mazo secundario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are given the option to change your side deck on maps two and three", "Puedes cambiar tu mazo secundario en el segundo y el tercer mapa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is ready to give us side deck options", "Leshy está listo para ofrecernos opciones de mazo secundario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable Sacrifice", "Sacrificio aceptable", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificing [creature] will count as if two creatures were sacrificed", "Sacrificar a [creature] cuenta como si se hubieran sacrificado dos criaturas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Entrance", "Entrada dolorosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal two damage to the player when it enters play.", "Cuando [creature] entra en juego, inflige dos puntos de daño al jugador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gelatinous", "Gelatinoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has no bones", "[creature] no tiene huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a Side Deck", "Elige un mazo secundario", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Player selected sidedeck card", "Carta del mazo secundario elegida por el jugador", Language.Spanish);


        }
    }
    public class TalkingPossumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Talking_Possum Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, this one. Right. You can keep it. Not much use to me, anyway.", "Ah, este. Bien. Puedes quedártelo. De todos modos no me sirve de mucho.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awesome Opossum", "Zarigüeya fenomenal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Playing dead? What a despicable creature.", "¿Hacerse el muerto? Qué criatura tan despreciable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not-So-Awesome Opossum", "Zarigüeya no tan fenomenal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Alright.[w:1]", "[e:anger]Está bien.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You must be... [w:0.4][c:#280085]confused[c:][w:1].", "[e:neutral]Debes de estar... [w:0.4][c:#280085]confundido[c:][w:1].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I get it.[w:0.2] I do.[w:0.2] It sucks.[w:0.4]", "Lo entiendo.[w:0.2] De verdad.[w:0.2] Es una mierda.[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]So, uh.[w:0.2] Hi.[w:0.2]", "[e:surprise]Bueno, eh.[w:0.2] Hola.[w:0.2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're...[w:0.6] [e:anger]stuck together, I suppose.[w:0.2]", "Estamos...[w:0.6] [e:anger]atrapados juntos, supongo.[w:0.2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It could be worse.[w:0.2]", "[e:neutral]Podría ser peor.[w:0.2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look on the [c:#280085]bright side![c:][w:0.4]", "¡Mira el [c:#280085]lado bueno![c:][w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... There's no bright side.", "... No hay ningún lado bueno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're all doomed.[leshy:Quiet now.][w:2]", "Estamos todos condenados.[leshy:Silencio ahora.][w:2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck.[w:1]", "Buena suerte.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know,[w:0.2] I was[w:0.4]", "[e:surprise]Sabes,[w:0.2] yo era[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]A [c:#280085]scrybe[c:] once.[w:1]", "[e:quiet]un [c:#280085]escriba[c:], hace tiempo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good times, good times.[w:0.6] Alas.[w:0.6]", "Qué buenos tiempos.[w:0.6] Ay.[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now I'm a fucking possum.[w:1]", "[e:surprise]Y ahora soy una maldita zarigüeya.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... This man over there?[w:0.4]", "[e:anger]... ¿Ese hombre de ahí?[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That guy?[w:0.6]", "¿Ese tipo?[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]He wasn't so bad before this.[w:1]", "[e:quiet]Antes de todo esto no era tan malo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still think he has...[w:0.6]", "Sigo pensando que tiene...[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... Some good in him.[w:0.4]", "... algo bueno dentro.[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Some.[w:1]", "[e:anger]Algo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Anyway,[w:0.4] here's my plan-[leshy:Silence.][w:3]", "[e:quiet]... En fin,[w:0.4] este es mi plan...[leshy:Silencio.][w:3]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aight. Got the memo.[w:0.6]", "Vale. Ya lo pillo.[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Good luck, traveler.[w:1]", "[e:anger]Buena suerte, viajero.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]I'm rooting for you.[w:1]", "[e:quiet]Te apoyo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[a:anger]Here we go again.[w:1]", "[a:anger]Otra vez lo mismo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isn't this FUN?[w:1] [e:surprise]Nope.[w:0.4]", "¿A que es DIVERTIDO?[w:1] [e:surprise]No.[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not fun.[w:1]", "No es divertido.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You know, I think[w:0.4]", "[e:neutral]Sabes, creo que[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]You have potential.[w:1]", "[e:quiet]tienes potencial.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm rooting for you.[w:1]", "Te apoyo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Also,[w:0.2] if you[w:0.2], uh[w:0.4]", "[e:neutral]Además,[w:0.2] si tú[w:0.2], eh[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you find an...[w:0.4] [c:#280085]odd-looking wolf...[c:][w:1]", "Si encuentras un...[w:0.4] [c:#280085]lobo de aspecto extraño...[c:][w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Tell him I-[leshy:Enough of that now.][w:2]", "[e:quiet]... Dile que yo...[leshy:Ya basta.][w:2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killjoy.[w:1]", "Aguafiestas.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This is getting old.[w:1]", "[e:anger]Esto ya cansa.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... You know...[w:0.4]", "[e:anger]... Sabes...[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That old man over there?[w:0.4]", "¿Ese viejo de ahí?[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]He has no idea[w:0.2]", "[e:neutral]No se da cuenta de que[w:0.2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's biting[w:0.2] [e:anger]way[w:0.2] more[w:0.2]", "ha querido abarcar[w:0.2] [e:anger]mucho[w:0.2] más[w:0.2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Than he can possibly chew.[w:1]", "[e:surprise]de lo que puede apretar.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Listen to me now.[w:0.6]", "[e:neutral]Escúchame ahora.[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]You have to-[leshy:Quiet, vermin.][w:2]", "[e:anger]Tienes que...[leshy:Silencio, alimaña.][w:2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Vermin?[w:0.2] Excuse me?[w:0.4]", "[e:surprise]... ¿Alimaña?[w:0.2] ¿Perdona?[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know my name.[w:0.4]", "Sabes cómo me llamo.[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's-[leshy:I said quiet.][w:2]", "Me llamo...[leshy:He dicho silencio.][w:2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#280085]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#280085]Un cordero camino al matadero.[c:][w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]NOT THE FACE!", "[e:surprise]¡EN LA CARA NO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]LEAVE ME ALONE.", "[e:surprise]DÉJAME EN PAZ.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]QUIT IT, GODDAMMIT.", "[e:surprise]PARA YA, MALDITA SEA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You're lucky I'm trapped as a marsupial.", "[e:surprise]Tienes suerte de que esté atrapado en el cuerpo de un marsupial.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Okay, I see how it is--", "[e:surprise]Vale, ya veo cómo son las cosas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN??", "[e:surprise]¿¿OTRA VEZ??", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN?? REALLY??", "[e:surprise]¿¿OTRA VEZ?? ¿¿EN SERIO??", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Odd feeling.", "[e:surprise]Qué sensación tan extraña.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Maybe skip me, perhaps?", "[e:quiet]¿Podrías dejarme pasar, quizá?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I'd rather you didn't.", "[e:surprise]Preferiría que no lo hicieras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Have you seen a strange-looking wolf?", "[e:quiet]¿Has visto un lobo de aspecto extraño?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It'd be... acceptable.", "[e:neutral]Sería... aceptable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I mean, if you insist.", "[e:surprise]Bueno, si insistes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Would it suit me?", "[e:quiet]¿Me quedaría bien?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Ah.[w:1]", "[e:surprise]... Ah.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]The board.[w:0.4] Again.[w:0.6]", "[e:anger]El tablero.[w:0.4] Otra vez.[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[c:#1e0040]Un cordero camino al matadero.[c:][w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I get it.[w:0.2]I do.[w:0.2]I do.[w:0.4]", "[e:surprise]Lo entiendo.[w:0.2]De verdad.[w:0.2]Lo entiendo.[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do as you must,[w:0.2] traveler.[w:1]", "Haz lo que debas,[w:0.2] viajero.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I'm rooting for you.[w:1]", "[e:neutral]Te apoyo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Ah.[w:0.2] The board, again.[w:0.2] I see.[w:1]", "[e:surprise]Ah.[w:0.2] El tablero, otra vez.[w:0.2] Ya veo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#1e0040]Un cordero camino al matadero.[c:][w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... I suppose.[w:1]", "[e:surprise]... Supongo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Ah, this.[w:1] [e:surprise]Once again.[w:1]", "[e:quiet]Ah, esto.[w:1] [e:surprise]Una vez más.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... I'm ready.[w:1]", "[e:anger]... Estoy listo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know what's funny?[w:0.4]", "[e:surprise]¿Sabes qué es lo gracioso?[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I really liked animals[w:0.4]", "[e:neutral]Me gustaban mucho los animales[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before all of this.[w:1]", "antes de todo esto.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now not so much.[w:1]", "[e:surprise]Ahora ya no tanto.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Cameras are ruined too.[w:2]", "[e:anger]Las cámaras también están arruinadas para mí.[w:2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Aim for their throat.[w:1]", "[e:anger]Apunta a su garganta.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]... What?[w:0.4]", "[e:neutral]... ¿Qué?[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Why are you[w:0.2]", "[e:quiet]¿Por qué me[w:0.2]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "looking at me like that?[w:0.6]", "miras así?[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... If you must.[w:1]", "[e:surprise]... Si no queda más remedio.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:surprise][c:#1e0040]Un cordero camino al matadero.[c:][w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This sounds...[w:0.6]", "[e:anger]Esto suena...[w:0.6]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... [c:#1e0040]acceptable.[c:][w:1]", "[e:surprise]... [c:#1e0040]aceptable.[c:][w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Is it...[w:0.4] gonna...[w:0.4]", "[e:quiet]¿Me va...[w:0.4] me va a...[w:0.4]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is it gonna hurt?[w:1]", "¿Me va a doler?[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]This is...[w:0.6] [e:quiet]fine.[w:1]", "[e:surprise]Esto está...[w:0.6] [e:quiet]bien.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... I suppose.[w:1]", "... Supongo.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... Why me?[w:1]", "[e:anger]... ¿Por qué yo?[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... This is weird.[w:1]", "[e:anger]... Esto es raro.[w:1]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Fate deals its cards.[w:1]", "[e:quiet]El destino reparte sus cartas.[w:1]", Language.Spanish);



        }
