    public class SireMoDeersMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Sire_MoDeers Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mitosis", "Mitosis", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the card bearing this sigil is played, it will summon two weaker copies of itself in it's adjacent slots, if possible.", "Cuando se juega una carta que lleva este sello, invoca dos copias más débiles de sí misma en los espacios adyacentes, si es posible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mo'Deers", "Más ciervos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card pack that makes sprinter enjoyable, with deers from fiction and reality, to the Polite Bowing Deer to the Preying Deerror! This Card Pack houses 70+ deers by a Community effort, have fun!", "Un paquete que hace divertido Velocista, con ciervos reales y de ficción, desde el cortés Ciervo inclinado hasta el depredador Ciervo perdido. ¡La comunidad ha creado más de 70 ciervos para este paquete!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Mo'Deers", "Más ciervos de energía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card pack that houses the Energy Deers! from the Advanced Commandeer to the Beastly Gyfrtot, this pack is for people who wants to play with electricity.", "¡Un paquete de ciervos energéticos! Desde el Ciervomandante avanzado hasta el Gyftrot bestial, está pensado para quienes disfrutan jugando con electricidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer God", "Dios de los ciervos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Deerel", "Ardiciervo conducto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the conduit deerel, this deerel has been modified with technology.", "El Ardiciervo conducto: este Ardiciervo ha sido modificado con tecnología.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerel", "Ardiciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deerel, it has adapted to it's surrounding antler-clad.", "El Ardiciervo: cubierto de astas, se ha adaptado a su entorno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Moose", "Alce de carga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's bearings can be some of use.", "Lo que lleva podría ser útil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hard working pack mule, it is carrying some creatures of use.", "La trabajadora mula de carga transporta algunas criaturas útiles.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Deern't", "Extraño Nociervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bidoof Deer", "Ciervo Bidoof", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Commandeer", "Ciervomandante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the advanced commandeer, unlike it's antler-clad brethren, it uses a more practical weapon.", "El Ciervomandante avanzado: a diferencia de sus congéneres cubiertos de astas, usa un arma más práctica.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Conduit", "Ciervo conducto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this hooved creation is useful when charged.", "Esta criatura de pezuñas es útil cuando está cargada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer-ceus", "Cierveus", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the heavenly deer-ceus, it blesses your troupe with might.", "El celestial Cierveus bendice a tu grupo con su poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engideer", "Ciervogeniero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the intellectual engideer, is now engihere.", "El intelectual Ciervogeniero ya llegó para ingeniárselas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazelle", "Gacela", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gazelle, it can run extreme speeds in a short burst.", "La gacela puede alcanzar velocidades extremas en carreras cortas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gun Deer", "Ciervo armado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deformed gundeer, it contains mighty damage, ready to be activated.", "El deformado Ciervo armado encierra un enorme daño listo para activarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gyftrot, a twisted monster made from holiday spirit.", "El Gyftrot: un monstruo retorcido creado con espíritu festivo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Cube", "Cubo mayor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the perfect cube, feast your eyes of such beauty.", "El cubo perfecto: contempla semejante belleza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect Cube", "Cubo perfecto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snipeer", "Ciervotirador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the snipeer, it's accuracy is unmatched.", "El Ciervotirador: su puntería no tiene rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Deer", "Ciervo del tiempo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the time deer, it can bend time to it's will.", "El Ciervo del tiempo puede doblegar el tiempo a su voluntad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Elk", "Uapití lúgubre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah. The Never-Dying GRIM ELK. Typically the harbinger of doom, it brings carcasses for many.", "Ah. El inmortal UAPITÍ LÚGUBRE. Normalmente presagia la perdición y trae cadáveres para muchos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stunted Deer", "Ciervo raquítico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Where did that eye go..", "¿Adónde habrá ido ese ojo...?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Augmented Deer", "Ciervo aumentado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it will like this form better than the last one...", "Quizá le guste más esta forma que la anterior...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaminskeer", "Kaminsciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaminsk-eer, my very first deer-th cards.", "Kaminsciervo, mi primera carta de ciervo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kayceer", "Kayciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems you found yourself as a Deer-th card Kaycee.", "Parece que te has convertido en una carta de ciervo, Kaycee.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loui-Stag", "Luis-Ciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Loui-Stag, converted from it's humanity.", "El Luis-Ciervo, transformado de humano en ciervo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reginelk", "Reginuapití", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reginelk, i might have repurposed some of my deathcards...", "Reginuapití: puede que haya reutilizado algunas de mis cartas de muerte...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amoedeer", "Amebaciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the consequences of forced evolution.", "Las consecuencias de una evolución forzada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspideer", "Aspiciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer hasn't reached it's primal form, may you help it evolve?", "Este ciervo aún no ha alcanzado su forma primitiva. ¿Puedes ayudarlo a evolucionar?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primal Aspideer", "Aspiciervo primitivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Deer", "Ciervo ciego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "injured after a brawl with predators, the blind deer stands no chance.", "Herido tras una pelea con depredadores, el Ciervo ciego no tiene ninguna posibilidad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowing Deer", "Ciervo inclinado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the polite bowing deer, it shows its gratitude to you.", "El cortés Ciervo inclinado te muestra su gratitud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bus", "Autobús", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the devious bus, the cause of most roadkill.", "El astuto autobús, causante de la mayoría de los atropellos de animales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armadeerlo", "Armadiciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Deer", "Ciervo muerto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a carcass, it has value to the trader.", "Un cadáver que tiene valor para la comerciante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Jackalope", "Liebrílope muerto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a carcass, it was killed in an ambush by hunters.", "Un cadáver: los cazadores lo mataron en una emboscada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerror", "Ciervo perdido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apex predator.", "El superdepredador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Ant", "Hormiga ciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer ant, providing power to it's fellow ant-lered.", "La Hormiga ciervo da fuerza a sus compañeros con astas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeratina", "Ciervatina", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the demonic deeratina, it posseses whoever it lays its sight on.", "El demoníaco Ciervatina posee a cualquiera sobre quien pose la mirada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear", "Cieroso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the rampaged dear, what had angered it has perished, this vile mix of deer and bear is an untouchable beast.", "El furioso Cieroso ha aniquilado aquello que lo enfureció. Esta vil mezcla de ciervo y oso es una bestia intocable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sky Deer", "Ciervo del cielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a shapeshifting deer, it is stuck in it's bird form.", "Un ciervo cambiante atrapado en su forma de ave.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Deer", "Ciervo del mar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a shapeshifting deer, it is stuck in it's fish form.", "Un ciervo cambiante atrapado en su forma de pez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerel Ball", "Bola de ardiciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swift deerel ball, antlered squirrels connected to each other with pure sheer-will.", "La veloz Bola de ardiciervo: ardillas con astas unidas solo por su fuerza de voluntad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerer", "Cierviante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doing tasks costs money.", "Realizar tareas cuesta dinero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerman", "Hombre ciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how much it tries to scream, It remain silent.", "Por mucho que intente gritar, permanece en silencio.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deern't", "Nociervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer is... this isn't a deer.", "Este ciervo es... Esto no es un ciervo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeroboros", "Ciervóboro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it works differently than it's sibling, it does not strengthen through death, but through progress.", "Funciona de forma distinta a su pariente: no se fortalece con la muerte, sino con el progreso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Pile", "Montón de ciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this pile of bones screams in agony, as it begs for power.", "Este montón de huesos grita de dolor mientras suplica poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Worm", "Ciervo gusano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a dangerous parasite.", "Un parásito peligroso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Findeer", "Ciervo buscahuesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the excitable bone findeer, it happily digs through the dirt for bones.", "El entusiasta Ciervo buscahuesos escarba alegremente en la tierra buscando huesos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dire Elk", "Uapití gigante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The raging Dire Elk, its antlers rip apart most prey with ease", "El furioso Uapití gigante desgarra fácilmente a la mayoría de sus presas con sus astas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calamian Deer", "Ciervo de Calamian", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the calamian deer, this endangered creature cannot afford to die.", "El Ciervo de Calamian, una criatura en peligro que no puede permitirse morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deeeeer", "Cieeeervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the chunky Deeeeer, it's size protects adjacent allies..", "El fornido Cieeeervo protege a los aliados adyacentes gracias a su tamaño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerfox", "Zorrociervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer-fox, loyal to it's companion.", "El Zorrociervo es fiel a su compañero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerfox Fawn", "Cría de zorrociervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deerfox fawn, i found this from somewhere else.", "La Cría de zorrociervo la encontré en otro lugar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frog Deer", "Cierrana", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the humble deerfrog, it hops around happily.", "La humilde Cierrana salta alegremente de un lado a otro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen Deer", "Ciervo congelado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer inside has been crystalized for far too long.", "El ciervo de su interior lleva demasiado tiempo cristalizado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Stag", "Ciervo dorado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the golden stag, searching for his sister, lured away by an impostor.", "El Ciervo dorado busca a su hermana, a quien un impostor atrajo lejos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grazing Deer", "Ciervo pastando", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer enjoys its meal even during battle.", "Este ciervo disfruta de su comida incluso en plena batalla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Deer", "Ciervo sin cabeza", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it will not stop bleeding, make use of it's situation.", "No deja de sangrar. Aprovecha su situación.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hunter", "Cazador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imposdeer", "Impostorciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this feels off...", "Algo no encaja...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tired Deer?", "Ciervo cansado?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fierce jackalope, it calls a mate to help the fight.", "El feroz liebrílope llama a un compañero para que lo ayude a luchar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long Deer", "Ciervo largo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the long deer, it might need some push to expand.", "El Ciervo largo quizá necesite un empujón para estirarse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerguin", "Ciervigüino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the quick deerguin, it pounces swiftly.", "El veloz Ciervigüino salta con rapidez.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shed Antlers", "Astas mudadas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this antlers has been shed long after.", "Estas astas se mudaron hace mucho tiempo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maze Deer", "Ciervo laberinto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it sheds continously as it's antlers rapidly grow.", "Sus astas crecen tan deprisa que las muda continuamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megaloceros", "Megalocero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the extinct megaloceros, reborn to fight another day.", "El extinto Megalocero renace para luchar otro día.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moose Fawn", "Cría de alce", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the youthful moose, even in its childhood, it is powerful.", "El joven alce es poderoso incluso siendo una cría.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Deer", "Ciervo de cristal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "made of crystal, this card can power the needy.", "Hecha de cristal, esta carta puede dar energía a quienes la necesitan.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Mage", "Mago ciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer mage, it requires a certain power to live.", "El Mago ciervo necesita cierto poder para vivir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noelle", "Noelle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the frail Noelle, it has potential to be stronger.", "La frágil Noelle tiene potencial para hacerse más fuerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerthulhu", "Ciervthulhu", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the gigantic Deerthulhu, it slashes all opponents with it's might.", "El gigantesco Ciervthulhu golpea a todos los rivales con su poder.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEER?", "¿CIERVO?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Legged Deer", "Ciervo de una pata", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "died a brutal death, it came back to find it's killer.", "Murió de forma brutal y regresó para encontrar a su asesino.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deer Knight", "Caballero ciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the loyal deer knight, it's fancy strikes can encourage others to it's calling.", "El leal Caballero ciervo anima a otros a seguirlo con sus elegantes golpes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osteocoileus", "Osteociervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this skeleton isnt hollow, infact, it is filled to the brim with souls.", "Este esqueleto no está hueco: de hecho, está lleno de almas hasta los topes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peryton", "Peritón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the peryton, the perfect mix of feathers and fur.", "El peritón, la mezcla perfecta de plumas y pelaje.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noelle Pog", "Noelle sorprendida", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prickly Deer", "Ciervo espinoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its spiny quills shoots out after death.", "Sus púas salen disparadas al morir.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongkkall", "Prongkkall", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slithering predator of the deep. It somehow learned how to grow antlers.", "Depredador reptante de las profundidades. De algún modo ha aprendido a desarrollar astas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pudu", "Pudú", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the miniscule pudu, a small deer, for a small choice.", "El diminuto pudú, un ciervo pequeño para una pequeña elección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raged Moose", "Alce enfurecido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the raged moose, it was startled whilst sleeping.", "El Alce enfurecido fue sobresaltado mientras dormía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reindeer", "Reno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, just because it's docile doesnt mean it cant lend a hand.", "El reno: que sea dócil no significa que no pueda echar una mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reindeer Fawn", "Cría de reno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the curious fawn, it's docile nature make its reluctant to fight.", "La curiosa cría es dócil por naturaleza y no quiere luchar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rudolph", "Rudolph", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer's glowing nose guide other's to a safer path.", "La nariz luminosa de este ciervo guía a los demás por un camino más seguro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short Elk", "Uapití corto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pitiful creature. This elk has been truly... scrungled.", "Pobre criatura. A este uapití lo han dejado realmente... hecho un gurruño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Deer", "Ciervo moteado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Spotted deer, don't startle this armed deer.", "El Ciervo moteado: no sobresaltes a este ciervo bien armado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Fawn", "Cervatillo moteado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the Spotted fawn, it's spots are never lost when becoming stronger.", "El Cervatillo moteado nunca pierde sus manchas al hacerse más fuerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sire", "Señor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Space Deer", "Ciervo espacial", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the space deer, it dictates where everything should go.", "El Ciervo espacial decide adónde debe ir cada cosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spi-Deer", "Araciervo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the SPI-DEER, this creature was made by a bored demigod.", "El ARACIERVO: esta criatura fue creada por un semidiós aburrido.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "i... dont know where this came from.", "Yo... no sé de dónde ha salido esto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore-galope", "Esporagalope", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deeranged spore-galope, it was never the same since the visit from the mycologists.", "El trastornado Esporagalope no volvió a ser el mismo desde la visita de los micólogos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tentakelpie", "Tentakelpie", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the shape-shifting tentakelpie, it shows its true form during hunts.", "El Tentakelpie cambiante muestra su verdadera forma durante la caza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Throwback Deer", "Ciervo ancestral", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the persistent throwback deer, how it survives through the years even confuses the scrybe of beasts.", "El persistente Ciervo ancestral: ni el escriba de las bestias entiende cómo ha sobrevivido tantos años.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tired Deer", "Ciervo cansado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this deer is sleeping, i suggest waking it up.", "Este ciervo duerme. Sugiero despertarlo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Deer", "Ciervo despierto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "now awakened, it moves around for a perfect strike.", "Ahora que ha despertado, se mueve para dar el golpe perfecto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Deer", "Ciervo de agua", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the deer that grows fangs than antlers, this is the nature of the WATER DEER.", "Un ciervo al que le crecen colmillos en lugar de astas: así es el CIERVO DE AGUA.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakened Deer", "Ciervo debilitado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weakened Fawn", "Cervatillo debilitado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Stag", "Ciervo blanco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white stag, they say it brings good luck.", "Dicen que el Ciervo blanco trae buena suerte.", Language.Spanish);



        }
    }
    public class ApellaDiseasedCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Apella_Diseased_Cards_Mod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack_Of_The_Diseased", "Paquete de los infectados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Creatures of the Woods have Befell a Disease. They have been reborn into a New Form.", "Las criaturas del bosque han contraído una enfermedad. Han renacido con una nueva forma.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "airborne dragon", "Dragón volador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex predator of the sky", "Superdepredador del cielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for all", "Un festín para todos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trapfrog", "Rana trampa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trapper is gonna be upset", "El trampero se va a enfadar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hydra dragon", "Dragón hidra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Three heads are better than one", "Tres cabezas piensan mejor que una.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mule", "Mula", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "water dragon", "Dragón de agua", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such an amazing creature", "Qué criatura tan asombrosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The prospector will be upset", "El buscador de oro se va a enfadar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "weasel", "Comadreja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe you can find some use for this worthless creature", "Quizá puedas encontrarle alguna utilidad a esta criatura inútil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased adder", "Víbora infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a horrible fate", "Qué destino tan horrible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased airborne dragon", "Dragón volador infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's become an unholy nightmare", "Se ha convertido en una pesadilla impía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased alpha", "Alfa infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor thing is about to rot", "Pobrecillo, está a punto de pudrirse.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bat", "Murciélago infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hate these things", "Odio estas cosas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bait", "Cebo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free bones to ye", "Huesos gratis para ti.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased bullfrog", "Rana toro infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it's getting ready to pop", "Parece que está a punto de estallar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased coyote", "Coyote infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a feral beast", "Qué bestia tan salvaje.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased elk", "Uapití infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hmm scary lookin", "Mmm, tiene un aspecto aterrador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "rusty trapfrog", "Rana trampa oxidada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased grizzly", "Grizzly infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has taken it", "La enfermedad se lo ha llevado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased hydra dragon", "Dragón hidra infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a shame what happened to this creature", "Qué pena lo que le ha pasado a esta criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased magpie", "Urraca infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even more wild lookin", "Tiene un aspecto aún más salvaje.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mantis", "Mantis infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh my god, it is hideous", "Dios mío, es horrible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mole", "Topo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was cute before the disease got to it", "Era adorable antes de la enfermedad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased moleman", "Hombre topo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has made this into even more of a monster", "La enfermedad lo ha convertido en un monstruo aún peor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased mule", "Mula infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what was really in there", "Así que eso era lo que había realmente dentro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased ouroboros", "Ouroboros infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle, even with the disease", "Un ciclo interminable, incluso con la enfermedad.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased packrat", "Rata de bosque infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still useful", "Sigue siendo útil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased porcupine", "Puercoespín infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It grew a tail...", "Le ha crecido una cola...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased rattler", "Crótalo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disease has given this thing poison", "La enfermedad le ha dado veneno a esta cosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased raven", "Cuervo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like it has gone mad", "Parece que se ha vuelto loco.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased ringworm", "Gusano anillado infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased skunk", "Mofeta infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This damned disease has gotten to even the smallest of critters", "Esta maldita enfermedad ha alcanzado incluso a los bichos más pequeños.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased smoke", "Humo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That thing scares me", "Esa cosa me asusta.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased urayuli", "Urayuli infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's gotten weaker", "Se ha debilitado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased vulture", "Buitre infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's grown a second head", "Le ha crecido una segunda cabeza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased water dragon", "Dragón de agua infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's such a pitiful creature now", "Ahora es una criatura tan lastimosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased weasel", "Comadreja infectada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not as worthless now I see", "Por lo que veo, ahora no es tan inútil.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolf", "Lobo infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even more rabid than it's kin", "Aún más rabioso que los de su especie.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased wolfcub", "Lobezno infectado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh god its eye!", "¡Dios mío, su ojo!", Language.Spanish);


        }
    }
    public class LethalCabinMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for LethalCabin Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lethal Cabin", "Cabaña letal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Celestial Body: Inscryption.\n Population: Sparse.\n Conditions: Unknown.\n Fauna: [count] species.", "Cuerpo celeste: Inscryption.\n Población: escasa.\n Condiciones: desconocidas.\n Fauna: [count] especies.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hygrodere", "Higrodere", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A eukaryotic organism that can multiply to millions with incredible speed.", "Organismo eucariota capaz de multiplicarse por millones a una velocidad increíble.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jester", "Bufón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know as much as I do. I just call it the Jester.", "Sabes tanto como yo. Yo simplemente lo llamo el Bufón.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kidnapper Fox", "Zorro secuestrador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal with a horizontal jaw and unique skull shape giving it a great biting strength, and a long, frog-like tongue which can reach even twice the length of its spindly body.", "Gran mamífero con mandíbula horizontal y un cráneo de forma única que le dan una gran fuerza de mordida. Su larga lengua, parecida a la de una rana, puede medir el doble que su cuerpo enjuto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Landmine", "Mina terrestre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manticoil", "Manticoil", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poses little threat and has a generally passive temperament, although it's capable of transmitting deadly diseases.", "Representa poca amenaza y tiene un temperamento generalmente pacífico, aunque puede transmitir enfermedades mortales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masked", "Enmascarado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mask Hornets", "Avispones enmascarados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious creature that takes the form of an escape door in order to lure in potential prey.", "Criatura misteriosa que adopta la forma de una puerta de emergencia para atraer posibles presas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nutcracker", "Cascanueces", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "watches with one tireless eye, which only senses movement. It remembers the last creature it noticed, whether they are moving or not.", "Vigila con un único ojo incansable que solo percibe el movimiento. Recuerda a la última criatura que detectó, se mueva o no.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Bird", "Pájaro viejo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An autonomous, offensive weapon of war with a humanoid design. Equipped with a spotlight, rocket legs, an acoustic device and a missile launcher, they are truly a sight to behold.", "Arma de guerra ofensiva autónoma de diseño humanoide. Equipada con foco, piernas propulsadas, dispositivo acústico y lanzamisiles, es todo un espectáculo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roaming Locusts", "Langostas errantes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike some species which are more prone to jump or fly, roaming locusts are almost never grounded and stay close together even when in smaller numbers.", "A diferencia de otras especies más propensas a saltar o volar, las Langostas errantes casi nunca se posan y permanecen juntas incluso cuando son pocas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry Turret", "Torreta centinela", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snare Flea", "Pulga trampa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very large arthropod that possesses the ability to tighten itself around large prey to suffocate.", "Artrópodo muy grande capaz de apretarse alrededor de presas grandes para asfixiarlas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spore Lizard", "Lagarto de esporas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bulb on its tail secretes a chemical which attracts and accelerates the growth of a fungus, which it can then shake to release spores as a defense mechanism.", "El bulbo de su cola segrega una sustancia que atrae un hongo y acelera su crecimiento. Después puede sacudirlo para liberar esporas como defensa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thumper", "Golpeador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly aggressive, carnivorous species of hunters, typically at the top of their food chain.", "Especie de cazadores carnívoros muy agresivos, normalmente en la cima de su cadena alimentaria.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tulip Snake", "Lagarto tulipán", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lifting heavy and large objects into the air has often been observed as a part of the tulip snake's mating display. They are capable of carrying rocks, plants and even other creatures at least twice their size in an effort to impress their potential mate.", "Se ha observado a menudo que el Lagarto tulipán levanta objetos grandes y pesados durante el cortejo. Puede transportar piedras, plantas e incluso criaturas de al menos el doble de su tamaño para impresionar a una posible pareja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vain Shroud", "Velo vanidoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon Hawk", "Halcón babuino", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As lone scouts, baboon hawks are generally timid and won't attack unless provoked. In greater numbers they can become a great danger.", "Cuando exploran solos, los halcones babuino suelen ser tímidos y no atacan salvo que se los provoque. En grandes grupos pueden resultar muy peligrosos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barber", "Barbero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as the Clay Surgeon, Barber is a pack-forming creature that follows a Master Barber's beat to move and attack unsuspecting prey", "El Barbero, también llamado Cirujano de arcilla, vive en grupo y sigue el ritmo de un Maestro barbero para moverse y atacar a presas desprevenidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bunker Spider", "Araña de búnker", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This enormous arachnid produces silk and lays it around its chosen nesting area, then waits for it to be tripped on.", "Este enorme arácnido produce seda y la extiende alrededor de su nido elegido, después espera a que alguien tropiece con ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butler", "Mayordomo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deformed like a deflated balloon, this humanoid smells of rotten meat and, if you listen close, you can hear a faint sound of flies buzzing inside...", "Deformado como un globo desinflado, este humanoide huele a carne podrida y, si escuchas con atención, puedes oír un leve zumbido de moscas en su interior...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Bees", "Abejas de circuito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Also known as red bees, these social insects possess the aBEElity to create a field of electrostatic charge.", "También llamados abejas rojas, estos insectos sociales tienen la abejilidad de crear un campo electrostático.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coil-Head", "Cabeza de muelle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known to combust into flames when being dissected or even deactivated, and carries dangerously high levels of radioactive particles.", "Se sabe que arde al ser diseccionado o incluso desactivado, y contiene niveles peligrosamente altos de partículas radiactivas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Company Cruiser", "Vehículo de la Compañía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeb", "Jeb", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We trust you'll be a great asset to the Company.", "Confiamos en que serás una gran incorporación para la Compañía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earth Leviathan", "Leviatán terrestre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can burrow as far as 40 meters underground, judging by the incredible excavations it can leave behind.", "A juzgar por las enormes excavaciones que deja tras de sí, puede excavar hasta 40 metros bajo tierra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eyeless Dog", "Perro sin ojos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large mammal, hunting in very large packs. They are endurance hunters and attempt to make up for their lack of sight with their sense of hearing.", "Grandes mamíferos que cazan en manadas muy numerosas. Son cazadores resistentes y tratan de compensar su falta de vista con el oído.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Keeper", "Guardián del bosque", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhibits a curious behavior similar to that of a human child the age of 5 or 6. It will eat anything it find fascinating.", "Muestra una curiosidad semejante a la de un niño humano de 5 o 6 años. Come cualquier cosa que le resulte fascinante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Girl", "Niña fantasma", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoarding Bug", "Insecto acumulador", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Given its name due to its territorial nature, they will seek out any object they can find and will protect these objects as a part of the nest.", "Su nombre se debe a su territorialidad: buscan cualquier objeto que encuentren y lo protegen como parte de su nido.", Language.Spanish);




        }
    }
    public class RemoxedBossesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Remoxed_Bosses Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Crate", "Caja mortal", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will deal 1 damage to the Scale in favor for the Player.", "Cuando muere una carta que lleva este sello, la balanza se inclina 1 punto a favor del jugador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Gem", "Gema caída", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dropped Pearl", "Perla caída", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanted Frog", "Rana encantada", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Crew", "Tripulación de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Trap", "Trampa de gemas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will kill the opposing card.", "Cuando muere una carta que lleva este sello, mata a la carta de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Nugget", "Pepita de gema", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minecart", "Vagoneta", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Seaman", "Marinero mox", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem powered Trap", "Trampa alimentada por gema", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Powder", "Polvo naranja", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil dies, it will grant the opossing card +1 Attack Power and the Orange Mox Sigil.", "Cuando muere una carta que lleva este sello, la carta de enfrente obtiene +1 de ataque y el sello Mox naranja.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overloaded", "Sobrecarga", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the inscribed direction and leave behind a Orange Mox.", "Al final del turno de su propietario, una carta que lleva este sello se mueve en la dirección indicada y deja una carta Mox naranja en su espacio anterior.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oyster", "Ostra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remoxed Bosses", "Jefes mox renovados", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Re-adds the Great White to the card pool.", "Vuelve a añadir al Gran blanco al conjunto de cartas.", Language.Spanish);

        }
    }
    public class TerrariascryptionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Terrariascryption Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hivemind", "Mente colmena", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of Crimson tribes on the board.", "El valor representado por este sello es igual al número de criaturas de la tribu Carmesí en el tablero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight?", "¿Te atreves a creer que puedes saltarte esta lucha?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare think that you can skip this fight? Face Moonlord, you coward!", "¿Te atreves a creer que puedes saltarte esta lucha? ¡Enfréntate al Señor de la Luna, cobarde!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation won't interrupt this fight!", "[c:bR]¡La Inanición no interrumpirá esta lucha!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flames", "Llamas malditas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets harmed by Acids every turn.", "[creature] recibe daño de los ácidos cada turno.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Protected", "Protegido de las llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can not be damaged by cursed flames.", "[creature] no puede recibir daño de las Llamas malditas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Flamethrower", "Lanzallamas maldito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges cursed flames to harm the opposing creature over time.", "[creature] emite llamas malditas que dañan con el tiempo a la criatura de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AngryTrapper", "Trampero furioso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Man Eater consumes enough human flesh, it undergoes a cocoon-like metamorphosis into a far deadlier form.", "Cuando una planta devoradora de hombres consume suficiente carne humana, sufre una metamorfosis similar a la de un capullo y adopta una forma mucho más letal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Crawler", "Reptador de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Most spiders operate independently, but ones touched by the Crimson hive coordinate together to consume life.", "La mayoría de las arañas actúan por separado, pero las tocadas por la colmena carmesí se coordinan para consumir la vida.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Mummy", "Momia de sangre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The blood-dripping organic matter in these mummies display far better preservation than the rest of their ilk.", "La materia orgánica que gotea sangre en estas momias está mucho mejor conservada que la de sus semejantes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Slime", "Slime azul", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A simple, gelatinous creature that swallows anything and everything whole! It takes a long time to digest anything.", "¡Una sencilla criatura gelatinosa que se traga todo entero! Tarda mucho tiempo en digerir cualquier cosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corruptor", "Corruptor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a cancer, the putrid creatures born from the Corruption mutate and grow into bigger, more deadly forms which discharge acids.", "Como un cáncer, las criaturas pútridas nacidas de la Corrupción mutan y crecen hasta adoptar formas mayores y más letales que expulsan ácidos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupt Slime", "Slime corrupto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steeped in the power of Corruption, these slimes can survive being cut apart into smaller pieces, unlike their untainted brethren.", "Impregnados del poder de la Corrupción, estos slimes sobreviven aunque los corten en trozos pequeños, a diferencia de sus semejantes no contaminados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimera", "Crimera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most common horror to be born from the Crimson, it seeks to consume pure things with unrelenting hunger.", "El horror más común nacido del Carmesí busca consumir las cosas puras con un hambre incesante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dasher", "Embistidor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will Dash in the direction inscribed on the sigil, Attacking whoever stands infront of it.", "Al final del turno de su propietario, [creature] embiste en la dirección indicada en el sello y ataca a quien esté delante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerclops", "Ciervíclope", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from a distant land, this cyclopic monstrosity lurks in cold places, wreaking havoc on those who disturb it.", "Llegada de una tierra lejana, esta monstruosidad ciclópea acecha en lugares fríos y causa estragos entre quienes la molestan.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demon", "Demonio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Demons are the infantry of the underworld. Unlike their lesser brothers, they cast shadow magic rather than hell magic.", "Los demonios son la infantería del inframundo. A diferencia de sus hermanos menores, usan magia de sombras en lugar de magia infernal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Worm-like monstrosities are the Corruption's most favored creatures, tunneling underneath unsuspecting victims.", "Las monstruosidades con forma de gusano son las criaturas predilectas de la Corrupción y excavan bajo sus víctimas desprevenidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Souls", "Devorador de almas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Birthed from the Corruption as a being of pure malice, its sole instincts are to pursue, punish, and kill.", "Nacido de la Corrupción como un ser de pura maldad, sus únicos instintos son perseguir, castigar y matar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eater of Worlds", "Devorador de mundos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conceived from the bottomless malice of the Corruption, this mighty abyssal worm tunnels wildly to devour all in its path.", "Concebido a partir de la maldad insondable de la Corrupción, este poderoso gusano abisal excava sin control para devorar todo a su paso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empress of Light", "Emperatriz de la luz", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beneath the Hallow's cleansing blanket lies a vengeful fae goddess bent on scrubbing the land of any and all impurity.", "Bajo el manto purificador de la Bendición se oculta una diosa feérica vengativa, decidida a limpiar la tierra de toda impureza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon lord", "Señor de la Luna", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Of Cthulu", "Ojo de Cthulhu", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A piece of Cthulhu ripped from his body centuries ago in a bloody war. It wanders the night seeking its host body... and revenge!", "Un fragmento de Cthulhu arrancado de su cuerpo hace siglos en una guerra sangrienta. Vaga de noche buscando su cuerpo anfitrión... ¡y venganza!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye Servant", "Ojo sirviente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Face Monster", "Monstruo cara", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would be unwise to face off with one of these unfeeling, hungry mutations. Their mouths are large enough to devour all things.", "Sería imprudente enfrentarse a estas mutaciones insensibles y hambrientas. Sus bocas son lo bastante grandes para devorarlo todo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon Awakening", "Despertar de la luna", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Creature behind the Moon has awoken...", "Una criatura detrás de la Luna ha despertado...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Tortoise", "Tortuga gigante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one takes the giant tortoises seriously. Not until they come hurtling through the air, a spinning, spiky ball of death.", "Nadie se toma en serio a las tortugas gigantes hasta que salen disparadas por el aire como bolas de muerte giratorias y espinosas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herpling", "Herpling", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These hyper, demented, slug-like fiends serve the crimson horde with an unstoppable appetite for blood and flesh.", "Estos demonios hiperactivos y dementes, semejantes a babosas, sirven a la horda carmesí con un apetito insaciable de sangre y carne.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hooked", "Ganchudo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook", "Gancho", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will summon Hooks on either side of it.", "[creature] invoca Ganchos a ambos lados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if [creature] is not surrounded by a card bearing the Hooked Sigil it will loose all attack.", "Si [creature] no está rodeada por una carta con el sello Ganchudo, pierde todo su ataque.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aggressive flying insects which swarm the jungle depths. Their venomous barbs discharge over great distances at high velocity.", "Insectos voladores agresivos que pululan en las profundidades de la jungla. Disparan sus púas venenosas a gran velocidad y distancia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Slime", "Slime de hielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes that spent too long in arctic temperatures may begin to partially freeze, developing a shifting layer of ice on their surface.", "Los slimes expuestos demasiado tiempo a temperaturas árticas pueden congelarse en parte y desarrollar una capa cambiante de hielo en la superficie.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiked Ice Slime", "Slime de hielo espinoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Ice Slime has large ice shards in its mass from excessive exposure to the cold.Somehow, it is able to launch these at its prey.", "Este Slime de hielo tiene grandes fragmentos de hielo en su masa por su larga exposición al frío. De algún modo puede lanzarlos contra sus presas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor", "Icor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gets damaged for the damage * 2.", "[creature] recibe el doble de daño.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Protected", "Protegido del icor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creatures]s defense can not be lowered by ichor.", "La defensa de [creature] no puede reducirse con icor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Discharging", "Descarga de icor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] discharges Ichor to lower the opposing creatures defenses.", "[creature] expulsa icor para reducir las defensas de las criaturas rivales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichor Sticker", "Pegatina de icor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled to the brim with powerful ichor, these squid-like abominations spew their corrosive bio-fluid at their prey.", "Llenas hasta los topes de poderoso icor, estas abominaciones similares a calamares escupen su fluido biológico corrosivo sobre sus presas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King Slime", "Rey de los slimes", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimes normally aren't intelligent, but occasionally they merge together to become a powerful force to swallow all things.", "Los slimes no suelen ser inteligentes, pero a veces se fusionan en una fuerza poderosa capaz de tragárselo todo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engulfer", "Engullidor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. Creatures in the way will be engulfed.", "Al final del turno de su propietario, [creature] se mueve en la dirección indicada en el sello. Las criaturas que encuentre a su paso serán engullidas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lavaborne", "Nacido de la lava", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will hide underneath Lava. Any card willing to attack will be damaged by the Lava", "[creature] se esconde bajo la lava. Cualquier carta que intente atacarla recibirá daño de la lava.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leap", "Salto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to choose an empty slot to move [creature] into and deal 1 damage to the opposing slot.", "Paga 2 huesos para elegir un espacio vacío al que mover a [creature] e infligir 1 punto de daño al espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lunar Spells", "Hechizos lunares", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create Spells as it strafes.", "[creature] crea hechizos al desplazarse lateralmente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LunaticCultist", "Cultista lunático", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lightning Orb", "Orbe de relámpagos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Mist", "Niebla de hielo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lord of the Moon", "Señor de la Luna", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chest", "Cofre", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talking to a chest doesn't cause craziness, but if the chest answers back, it may cause death! It still contains rare treasure, regardless!", "Hablar con un cofre no provoca locura, ¡pero si responde puede causar la muerte! ¡Aun así contiene un tesoro raro!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted Mimic", "Imitador corrupto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimics which fall to Corruption grow larger and more powerful as a result. They can be birthed from ordinary chests by force.", "Los imitadores que sucumben a la Corrupción se vuelven más grandes y poderosos. Pueden ser creados a la fuerza a partir de cofres comunes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Mimic", "Imitador carmesí", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Eye", "Ojo verdadero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phase Switcher", "Cambio de fase", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon Death, [creature] will reach its next Phase.", "Al morir, [creature] pasa a su siguiente fase.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Pillar", "Pilar de nebulosa", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Pillar", "Pilar solar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stardust Pillar", "Pilar de polvo estelar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vortex Pillar", "Pilar de vórtice", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pixie", "Duende", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A larger, more luminous form of fairy. Pixies provide the Hallow with more blessed light and aid in the cleansing of the land.", "Una forma de hada más grande y luminosa. Los duendes aportan más luz bendita a la Bendición y ayudan a purificar la tierra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plantera", "Plantera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dormant, yet powerful floral guardian awoken by the fallout of Cthulhu's destroyed machinations. Its reach spans the entire jungle.", "Poderosa guardiana floral dormida, despertada por las consecuencias de los mecanismos destruidos de Cthulhu. Su alcance abarca toda la jungla.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Planteras Hook", "Gancho de Plantera", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purple Slime", "Slime morado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will spit out a randomly chosen Rare Card upon being placed.", "Cuando se coloca a [creature], escupe una carta rara elegida al azar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Slime", "Slime rojo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who needs muscles, skin, or even eyeballs? Skeletons get by with just the bones on their back, just as deadly as more fleshy foes.", "¿Quién necesita músculos, piel o siquiera ojos? A los esqueletos les bastan sus huesos y son tan letales como los enemigos de carne y hueso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Serpent", "Serpiente de hueso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mighty serpentine dragons once ruled hell, but long ago shed their obsidian scales.A skeletal husk is all that remains.", "Poderosos dragones serpentinos gobernaron antaño el infierno, pero hace mucho mudaron sus escamas de obsidiana. Solo queda una carcasa esquelética.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimer", "Slime alado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slimer has become airborne with wings of unknown origin. The wings are easily knocked off with force, depriving it of its flight.", "El Slime alado vuela con alas de origen desconocido. Es fácil arrancárselas por la fuerza, privándolo del vuelo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Man Eater", "Devoradora de hombres", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sharp-toothed plant with a taste for human flesh. It has the ability to hide inside the mud and reach over great distances.", "Planta de dientes afilados que gusta de la carne humana. Puede esconderse en el lodo y alcanzar grandes distancias.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryad", "Dríade", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing. And well, you are not aging very gracefully.", "Las arenas del tiempo fluyen. Y, bueno, no estás envejeciendo con mucha elegancia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guide", "Guía", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They say there is a person who will tell you how to survive in this land... oh wait. That's me.", "Dicen que hay alguien que puede enseñarte a sobrevivir en estas tierras... Ah, espera. Soy yo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tree but ded.", "Un árbol, pero muerto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cool Slime", "Slime guay", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easily the coolest slime around, no question. You can tell from the backwards hat and indecipherable slang.", "Sin duda el slime más guay de por aquí. Se nota por la gorra al revés y su jerga indescifrable.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Slime", "Slime torpe", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime was a little confused when the other slimes started putting on hats and accessories. But it did its best.", "Este slime estaba algo confundido cuando los demás empezaron a ponerse sombreros y accesorios. Pero hizo todo lo posible.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nerdy Slime", "Slime empollón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just a smidge cleverer than other slimes, this slime discovered how to coexist with humans. The secret: accessorizing!", "Apenas un poco más listo que los demás, este slime descubrió cómo convivir con los humanos. ¡El secreto son los accesorios!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surly Slime", "Slime gruñón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irascible and insufferable, this grumpy slime is probably up to no good. Probably. Its the thought that counts really.", "Irascible e insoportable, este slime gruñón probablemente trama algo malo. Probablemente. Al fin y al cabo, lo que cuenta es la intención.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Slime", "Slime anciano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Older, though not necessarily wiser, the other slimes look up to the Elder Slime. If it survived this long, it must know something!", "Más viejo, aunque no necesariamente más sabio, el Slime anciano es admirado por los demás. ¡Si ha sobrevivido tanto tiempo, algo debe de saber!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diva Slime", "Slime diva", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Born of the combined energies of Shimmer and the Queen Slime, this slime is full of boundless energy and enthusiasm! And so fancy!", "¡Nacido de las energías combinadas del Destello y la Reina slime, este slime rebosa energía y entusiasmo! ¡Y qué elegante!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystic Slime", "Slime místico", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slime knows that great witches wear impressive hats, but it only found a droopy one. Might explain the backfired polymorph!", "Este slime sabe que las grandes brujas llevan sombreros impresionantes, pero solo encontró uno caído. ¡Quizá eso explique por qué salió mal el hechizo de transformación!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squire Slime", "Slime escudero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hero amongst slimes, it wields the greatest arms and armor known to its kind. It doesn't actually know how to use them, but its a start.", "Un héroe entre los slimes, equipado con las mejores armas y armaduras de su especie. En realidad no sabe usarlas, pero por algo se empieza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unicorn", "Unicornio", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These majestic single-horned equines storm angrily through the hallowed land in search of lowly intrusions needing to be cleansed away.", "Estos majestuosos equinos de un solo cuerno galopan furiosos por la tierra sagrada en busca de viles intrusos que deban ser purificados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall Creator", "Creador de muros", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will create a Wall on [creature]s Side.", "[creature] crea un muro en el lado de [creature].", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wall of Flesh", "Muro de carne", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serving as the world's core and guardian, the towering demon lord exists to keep powerful ancient spirits sealed away.", "Este imponente señor demoníaco es el núcleo y guardián del mundo y mantiene sellados a poderosos espíritus antiguos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Middle Strike", "Golpe central", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right Strike", "Golpe a la derecha", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left Strike", "Golpe a la izquierda", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its right. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature] solo ataca a las cartas del espacio a su derecha, en la misma fila. Si ese espacio está vacío, el daño se inflige al rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack only cards in the slot to its left. If a targeted slot is empty, the damage will be redirected to the opponent.", "[creature] solo ataca a las cartas del espacio a su izquierda, en la misma fila. Si ese espacio está vacío, el daño se inflige al rival.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrascryption", "Terrascryption", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack contains a bunch of awesome Terraria themed Cards!", "¡Este paquete contiene un montón de cartas geniales inspiradas en Terraria!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fortunate draw.", "Robo afortunado.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be safe", "Ten cuidado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect", "Perfecto", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time are flowing.", "Las arenas del tiempo fluyen.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope you aren't making a Mistake!", "¡Espero que no estés cometiendo un error!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You think this works?", "¿Crees que esto funciona?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh what a misplay?", "¡Vaya mala jugada!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh!", "¡Oh!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Me.", "Elígeme.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't Sacrifice me.", "No me sacrifiques.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you need to....", "Si lo necesitas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop that.", "Deja eso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Angler...", "El Pescador...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how disgusting", "Qué asco", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just defeat him already", "Véncelo de una vez", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss time, eh?", "Hora del jefe, ¿eh?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor.", "Qué honor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is great!", "¡Esto es genial!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an honor", "Qué honor", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fingers crossed", "Crucemos los dedos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nice Deck.", "Buen mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam here to help You!", "¡Estoy aquí para ayudarte!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lucky.", "Qué suerte.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't die", "No mueras", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "not the worst draw.", "No es el peor robo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good Choice!", "¡Buena elección!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iam a Guide afterall.", "Al fin y al cabo soy un guía.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OK...", "Vale...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its a Good Choice.", "Es una buena elección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total misplay.", "Una jugada completamente errónea.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yep.", "Sí.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I Hope this is right!", "¡Espero que esto sea correcto!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sure I guess?", "Supongo que sí, ¿no?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Who you want.", "Elige a quien quieras.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice me if you need to.", "Sacrifícame si lo necesitas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will still guide you!", "¡Seguiré guiándote!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector. Watch out for his Pickaxe.", "El Buscador de oro. Cuidado con su pico.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Prospector...", "El Buscador de oro...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill the Mule for Cards", "Mata a la mula para conseguir cartas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mule's key", "la mula es la clave", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you sure about this?", "¿Estás seguro de esto?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Corruption is waiting for you!", "¡La Corrupción te espera!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson is waiting for you!", "¡El Carmesí te espera!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Brain of Cthulu has awoken!", "¡El Cerebro de Cthulhu ha despertado!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a flaming celestial event known as 'solar flares', this tower holds the seal locking away a terrifying tyrant.", "Esta torre representa un ardiente fenómeno celeste llamado «fulguraciones solares» y contiene el sello que encierra a un tirano aterrador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a deep celestial void known as 'vortex', this tower holds the seal locking away a terrifying tyrant.", "Esta torre representa un profundo vacío celeste llamado «vórtice» y contiene el sello que encierra a un tirano aterrador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a stormy celestial body known as 'nebula', this tower holds the seal locking away a terrifying tyrant.", "Esta torre representa un tormentoso cuerpo celeste llamado «nebulosa» y contiene el sello que encierra a un tirano aterrador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Representing a glittering celestial remnant known as 'stardust', this tower holds the seal locking away a terrifying tyrant.", "Esta torre representa un brillante remanente celeste llamado «polvo estelar» y contiene el sello que encierra a un tirano aterrador.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And so arrives the Moonlord, harbringer of all Destruction.", "Y así llega el Señor de la Luna, heraldo de toda destrucción.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You saved us all!", "¡Nos has salvado a todos!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eater of Worlds has awoken!", "¡El Devorador de mundos ha despertado!", Language.Spanish);

        }
    }
    public class BittysRegionsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysRegions Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TIME TO FORGE METAL!", "¡HORA DE FORJAR METAL!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GO MY KNIGHTS!", "¡ADELANTE, CABALLEROS MÍOS!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah... no materials...", "Ah... no quedan materiales...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>You may claim those are your cards...</color>", "<color=#32CD32>Puedes afirmar que esas cartas son tuyas...</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>But the spiders inside them are MINE!</color>", "<color=#32CD32>¡Pero las arañas que llevan dentro son MÍAS!</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A shame... There's none of my spiders on your side...</color>", "<color=#32CD32>Qué pena... No hay ninguna de mis arañas en tu lado...</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>A spider's bite always strikes when least expected...</color>", "<color=#32CD32>La mordedura de una araña siempre llega cuando menos la esperas...</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mad laughter of a wild dog.", "La risa enloquecida de un perro salvaje.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chihuahua", "Chihuahua", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Savage and vicious, all wrapped up in a tiny package.", "Salvaje y feroz, todo concentrado en un cuerpo diminuto.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodpecker", "Pájaro carpintero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Woodpecker, it strikes endlessly.", "El persistente Pájaro carpintero golpea sin cesar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-rolling squirrel ball, a strange and bizzare phenomenon.", "La Bola de ardillas rueda sin parar: un fenómeno extraño y curioso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mighty hawk, champion of the skies.", "El poderoso halcón, campeón de los cielos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seagull", "Gaviota", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Known as rats of the skies... Or was that another bird?", "Los llaman las ratas del cielo... ¿O era otra ave?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hermit Crab", "Cangrejo ermitaño", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The humble hermit crab. Always seeking a new home.", "El humilde cangrejo ermitaño siempre busca un nuevo hogar.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rock Wall", "Muro de piedra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sheer wall of rock.", "Una pared de roca escarpada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A world on fire.", "Un mundo en llamas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Tree", "Árbol en llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Pile", "Montón de carbón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel for the flames.", "Combustible para las llamas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shackle", "Grillete", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bindings forged in flames.", "Ataduras forjadas en las llamas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight", "Caballero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creations of steel and fire.", "Creaciones de acero y fuego.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turtle Rock", "Tortuga de roca", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covered in rocks, with strength to reflect it.", "Cubierta de rocas, posee una fuerza a la altura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flamemingo", "Flamenco ardiente", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Phoenix. Always comes back.", "El majestuoso fénix. Siempre regresa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flamingo in terrible pain. Not to be mistaken with the majestic Phoenix.", "Un flamenco que sufre terriblemente. No lo confundas con el majestuoso fénix.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drake", "Dragón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dwellers of volcanos and other infernal places.", "Habitantes de volcanes y otros lugares infernales.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salamander", "Salamandra", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slippery little creature.", "Una pequeña criatura resbaladiza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flaming Salmon", "Salmón en llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Salmon scarred by searing flames. Native to lava pools.", "Un salmón marcado por llamas abrasadoras. Habita en pozas de lava.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A savage beast of the depths.", "Una bestia salvaje de las profundidades.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Ant", "Hormiga de fuego", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hundreds scurry from their anthill.", "Cientos salen corriendo de su hormiguero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Boy", "Niño de carbón", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A freakish creation. It bites.", "Una creación monstruosa. Muerde.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brood Mother", "Madre de la prole", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mother of many, stored inside her own body.", "Madre de muchas crías, guardadas en su propio cuerpo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Childlike wonder, monsterous body.", "Asombro infantil en un cuerpo monstruoso.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Spider", "Araña parásita", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infesting everything it touches.", "Infesta todo lo que toca.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sack", "Saco de huevos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sac of eggs.", "Un saco de huevos.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daddy Long Legs", "Opilión", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tall and spindly, father of none.", "Alto y larguirucho, pero padre de nadie.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pillar?", "¿Pilar?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pillar?", "¿Un pilar?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Spider", "Araña lobo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As deadly as a normal wolf, but more skittish.", "Tan letal como un lobo normal, pero más asustadiza.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night Mare", "Pesadilla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fragment of a darkened dream. It harms everything, including allies.", "Un fragmento de un sueño sombrío. Daña a todo, incluidos los aliados.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rampaging monster of many legs.", "Un monstruo desbocado de muchas patas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doom Clock", "Reloj del fin", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient calendar foretelling the end of the world.", "Un antiguo calendario que anuncia el fin del mundo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chair", "Silla", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange metal chair.", "Una extraña silla de metal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elk Mage", "Uapití mago", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ambitious Elk, making its way in the world.", "Un uapití ambicioso que se abre camino en el mundo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mus-Elk Mage", "Uapití mago musculoso", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Muscle Mage's incarnation. Muscular and beautiful.", "La encarnación del Mago musculoso. Musculosa y hermosa.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glowing Buck", "Ciervo brillante", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully fledged master of luminescence.", "Un consumado maestro de la luminiscencia.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fading light.", "Una luz que se desvanece.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack adds [count] new cards that are found in every region. (There are more cards that are region specific!)", "Este paquete añade [count] cartas nuevas que aparecen en todas las regiones. (¡Hay más cartas exclusivas de ciertas regiones!)", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The damp air of the underground...", "El aire húmedo del subsuelo...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And water dripping down stalagmites...", "Y el agua que gotea por las estalagmitas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered... [c:bG]The Infested Caves.[c:]", "Has entrado en... [c:bG]las cuevas infestadas.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Webs line the walls...", "Las telarañas cubren las paredes...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The skittering of many legs echo throughout the caverns...", "El correteo de muchas patas resuena por las cavernas...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With trepidation, you enter... [c:bG]The Infested Caves.[c:]", "Con temor, entras en... [c:bG]las cuevas infestadas.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cool air of the caverns greeted your face...", "El aire fresco de las cavernas te rozó el rostro...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you crept below...", "Mientras bajabas sigilosamente...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Into [c:bG]The Infested Caves.[c:]", "A [c:bG]las cuevas infestadas.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smell of sulfur...", "El olor a azufre...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And falling ash...", "Y las cenizas que caen...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You reach... [c:bG]The Lava Flow.[c:]", "Llegas a... [c:bG]la corriente de lava.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You see the land glowing in the distance...", "Ves la tierra brillar a lo lejos...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Molten rock, flowing in rivers...", "Roca fundida que fluye en ríos...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have reached... [c:bG]The Lava Flow.[c:]", "Has llegado a... [c:bG]la corriente de lava.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The landscape is dark with ash...", "El paisaje está oscurecido por la ceniza...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees are burning...", "Los árboles arden...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You tread through... [c:bG]The Lava Flow.[c:]", "Avanzas por... [c:bG]la corriente de lava.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time you will choose a region specific card.", "Esta vez elegirás una carta exclusiva de la región.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose wisely.", "Elige sabiamente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach a great stone forge.", "Te acercas a una gran forja de piedra.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that you aren't alone.", "Parece que no estás solo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clanging of metal reverberates around you.", "El repiqueteo del metal resuena a tu alrededor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sparks spill from the forge.", "De la forja saltan chispas.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You run into a nearby cave to escape the smell of sulfur.", "Corres a una cueva cercana para escapar del olor a azufre.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, this cave is inhabited.", "Sin embargo, esta cueva está habitada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith, [c:bG]Martel.[c:]", "Soy el herrero, [c:bG]Martel.[c:]", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The old man has given me the opportunity to face you properly...", "El anciano me ha dado la oportunidad de enfrentarme a ti como es debido...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am the blacksmith.", "Soy el herrero.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's forge you into a fine creation.", "Voy a forjarte hasta convertirte en una magnífica creación.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you... are the iron.", "Y tú... eres el hierro.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, challenger.", "Ha llegado la hora, aspirante.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for you to see the true meaning of... PERFECTION.", "Es hora de mostrarte el verdadero significado de la... PERFECCIÓN.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You approach the deepest part of the cave.", "Te acercas a la parte más profunda de la cueva.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long legs creep out of the shadows, as many smaller spiders skitter around.", "Unas largas patas salen de las sombras mientras muchas arañas pequeñas corretean alrededor.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A light hearted voice calls out to you.", "Una voz alegre te llama.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Ahuhuhu~</color>", "<color=#32CD32>Ahuhuhu~</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>My, who do we have here?</color>", "<color=#32CD32>Vaya, ¿a quién tenemos aquí?</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>It's been so long since I've seen a Challenger...</color>", "<color=#32CD32>Hace tanto que no veo a un aspirante...</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>Let's have some fun...</color>", "<color=#32CD32>Divirtámonos un poco...</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>I am the queen of the spiders,</color>", "<color=#32CD32>Soy la reina de las arañas,</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#32CD32>And You're LUNCH!</color>", "<color=#32CD32>¡Y tú eres el ALMUERZO!</color>", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this...", "¿Es este...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new map?", "¿Un mapa nuevo?", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who stands at the end of this path...", "No sé quién espera al final de este camino...", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're not meant to see this dialogue.", "No deberías ver este diálogo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something has gone wrong.", "Algo ha salido mal.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insect Swarm", "Enjambre de insectos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of insects that the owner has on their side of the table.", "El valor de este sello equivale al número de insectos en el lado del tablero de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create Terrain", "Crear terreno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random terrain is created on the opposing space.", "Cuando se juega [creature], se crea un terreno aleatorio en el espacio de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg Sacks", "Sacos de huevos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, Spiderlings are created on the owner's empty spaces.", "Cuando [creature] muere, se crean crías de araña en los espacios vacíos de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many Legs", "Muchas patas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a Leg is created in its place and a card bearing this sigil moves to the right.", "Cuando golpean a [creature], se crea una pata en su lugar y una carta con este sello se mueve a la derecha.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Stock", "Reserva de huesos", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a bone is generated for card on the owner's side of the board.", "Cuando se juega [creature], se genera un hueso por cada carta en el lado del tablero de su propietario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flip Attack", "Ataque invertido", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, swap its Power and Health.", "Cuando [creature] ataca, se intercambian su poder y su salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inflamed", "Inflamado", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, discard the oldest card in your hand.", "Cuando golpean a [creature], descarta la carta más antigua de tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recursive", "Recursivo", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes or is discarded, a copy of it is created in your deck.", "Cuando [creature] muere o es descartada, se crea una copia de esa carta en tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scuttler", "Corretero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of battle, [creature] will move in the direction inscribed in the sigil.", "Al comienzo de la batalla, [creature] se mueve en la dirección indicada en el sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Growth", "Crecimiento oscuro", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent and opposing cards gain 1 power and lose 1 health.", "Cuando [creature] muere, las cartas adyacentes del mismo lado y la carta de enfrente obtienen 1 de poder y pierden 1 de salud.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] counts down. If this sigil reaches 0, you lose.", "Al final de cada turno, [creature] cuenta hacia atrás. Si este sello llega a 0, pierdes.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muscle Milk", "Leche muscular", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on other cards. When [creature] is played on another card, it gains 1 power and loses 1 health.", "[creature] puede jugarse sobre otras cartas. Cuando se juega [creature] sobre otra carta, la carta de abajo obtiene 1 de poder y 1 de salud; después muere la criatura jugada.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoning", "Invocación", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card of the same cost tier is summoned to the right.", "Cuando se juega [creature], se invoca a su derecha una carta aleatoria del mismo nivel de coste.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain Dweller", "Habitante del terreno", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be played on terrain cards. When [creature] is played on a terrain card, the terrain gains this creature's stats and sigils.", "[creature] puede jugarse sobre cartas de terreno. Cuando se juega [creature] sobre una carta de terreno, esta obtiene las estadísticas y los sellos de la criatura.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blazing Deck", "Mazo en llamas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will draw 1 card from your deck with Fleeting.", "Al comienzo del turno de su propietario, [creature] roba 1 carta con Fugaz de tu mazo.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellows", "Fuelle", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, draw 1 card from your side deck with Fleeting.", "Cuando golpean a [creature], roba 1 carta con Fugaz de tu mazo secundario.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Swarm", "Enjambre de ardillas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and drop a Squirrel in its old space. Creatures that are in the way will be pushed in the same direction.", "Al final del turno de su propietario, [creature] se mueve en la dirección del sello y deja una ardilla en su antiguo espacio. Las criaturas en su camino son empujadas en la misma dirección.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, deal a single damage point to the opposing card.", "Cuando se juega [creature], inflige 1 de daño a la carta de enfrente.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Limit", "Límite de mano", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] is in your hand or on the board, discard your oldest card until you have 4 or less cards in your hand, or the oldest card has this sigil.", "Al final de cada turno en que [creature] esté en tu mano o en el tablero, descarta tu carta más antigua hasta que tengas 4 cartas o menos en la mano o la carta más antigua tenga este sello.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Devour", "Devorar", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing card is consumed. If this creature dies, the consumed creature is returned to the hand.", "Cuando se juega [creature], la carta de enfrente es devorada. Si esta criatura muere, la criatura devorada vuelve a la mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Discard Shield", "Escudo de descarte", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards in your hand have Fleeting removed from them. When a card is drawn, Fleeting is removed from it.", "Cuando se juega [creature], se elimina Fugaz de todas las cartas de tu mano. Cuando se roba una carta, se elimina Fugaz de ella.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anthill", "Hormiguero", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is discarded while [creature] is on the board, create a Fire Ant in your hand.", "Cuando se descarta una carta mientras [creature] está en el tablero, se crea una hormiga de fuego en tu mano.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spider's Host", "Anfitrión de arañas", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a spiderling crawls out.", "Cuando [creature] muere, sale una cría de araña.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Bite", "Mordisco parásito", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks another creature, that creature's sigils are removed and becomes host to a spiderling.", "Cuando [creature] ataca a otra criatura, se eliminan sus sellos y esta se convierte en anfitriona de una cría de araña.", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AH HA HA!", "¡JA, JA, JA!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S ME!", "¡SOY YO!", Language.Spanish);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIGHT, LIGHT!", "¡LUZ, LUZ!", Language.Spanish);
