            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, dragging christmas fun all over the world", "El reno arrastra la diversión navideña por todo el mundo.", Language.Spanish);
